INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39450, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "分離", "is_correct": true, "explanation": "くっついたものを離すことで、接合の反対の関係にある。"}, {"text": "計画", "is_correct": false, "explanation": "「計画」は前もって決めることで、接合の対義語ではない。"}, {"text": "季節", "is_correct": false, "explanation": "「季節」は一年の時期を指し、接合の対義語ではない。"}, {"text": "旅行", "is_correct": false, "explanation": "「旅行」は遠くへ出かけることで、接合の対義語ではない。"}], "correct_answer": "分離", "explanations": {"分離": "くっついたものを離すことで、接合の反対の関係にある。", "計画": "「計画」は前もって決めることで、接合の対義語ではない。", "季節": "「季節」は一年の時期を指し、接合の対義語ではない。", "旅行": "「旅行」は遠くへ出かけることで、接合の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59842fc5-799f-4d98-a8d3-278d78c2adcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39450, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "二つのものをくっつけること", "primary_collocate": null, "pronunciation": "せつごう", "ipa": "setsɯɡoː", "syllable_count": 4, "sentences": [{"text": "折れた木の板を、強い接着剤で接合しました。", "target_word": "接合", "complexity_tier": "T4", "furigana": "折[お]れた木[き]の板[いた]を、強[つよ]い接着剤[せっちゃくざい]で接合[せつごう]しました。", "sentence_source": "generated"}, {"text": "二つの管を接合すると、水が通るようになります。", "target_word": "接合", "complexity_tier": "T4", "furigana": "二[ふた]つの管[くだ]を接合[せつごう]すると、水[みず]が通[とお]るようになります。", "sentence_source": "generated"}, {"text": "医者は、切れた骨を接合する手術をしました。", "target_word": "接合", "complexity_tier": "T4", "furigana": "医者[いしゃ]は、切[き]れた骨[ほね]を接合[せつごう]する手術[しゅじゅつ]をしました。", "sentence_source": "generated"}, {"text": "この箱は、二枚の板を接合して作ってあります。", "target_word": "接合", "complexity_tier": "T3", "furigana": "この箱[はこ]は、二枚[にまい]の板[いた]を接合[せつごう]して作[つく]ってあります。", "sentence_source": "generated"}, {"text": "二つの粘土を接合して、大きな動物を作りました。", "target_word": "接合", "complexity_tier": "T3", "furigana": "二[ふた]つの粘土[ねんど]を接合[せつごう]して、大[おお]きな動物[どうぶつ]を作[つく]りました。", "sentence_source": "generated"}, {"text": "接合した部分が弱いので、すぐに外れてしまいました。", "target_word": "接合", "complexity_tier": "T4", "furigana": "接合[せつごう]した部分[ぶぶん]が弱[よわ]いので、すぐに外[はず]れてしまいました。", "sentence_source": "generated"}, {"text": "二つの板の接合には、のりが乾くまで時間がかかります。", "target_word": "接合", "complexity_tier": "T4", "furigana": "二[ふた]つの板[いた]の接合[せつごう]には、のりが乾[かわ]くまで時間[じかん]がかかります。", "sentence_source": "generated"}, {"text": "割れたお皿を接合して、もう一度使えるようにしました。", "target_word": "接合", "complexity_tier": "T3", "furigana": "割[わ]れたお皿[さら]を接合[せつごう]して、もう一度[いちど]使[つか]えるようにしました。", "sentence_source": "generated"}, {"text": "接合がうまくいかず、紙が途中ではがれました。", "target_word": "接合", "complexity_tier": "T3", "furigana": "接合[せつごう]がうまくいかず、紙[かみ]が途中[とちゅう]ではがれました。", "sentence_source": "generated"}, {"text": "切れた二本のロープを接合するには、特別な結び方があります。", "target_word": "接合", "complexity_tier": "T4", "furigana": "切[き]れた二本[にほん]のロープを接合[せつごう]するには、特別[とくべつ]な結[むす]び方[かた]があります。", "sentence_source": "generated"}], "morphological_forms": [{"form": "接合", "label": "基本形"}, {"form": "接合する", "label": "サ変動詞"}], "register": "neutral", "sense_fingerprint": "二つのものをくっつけて一つにすること（日常・医療など一般的な場面）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01e5a7c6-6233-4cdf-b902-182071ea0773') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39450, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "接合", "is_correct": true, "explanation": "「二つのものをくっつけて一つにする」の意味で、接着剤で板を結ぶ文に合う。"}, {"text": "運搬", "is_correct": false, "explanation": "「運搬」は物を運ぶことで、板をくっつける意味にはならない。"}, {"text": "測定", "is_correct": false, "explanation": "「測定」は長さや量をはかることで、くっつける行為とは違う。"}, {"text": "点検", "is_correct": false, "explanation": "「点検」は調べて確かめることで、くっつけることではない。"}], "explanations": {"接合": "「二つのものをくっつけて一つにする」の意味で、接着剤で板を結ぶ文に合う。", "運搬": "「運搬」は物を運ぶことで、板をくっつける意味にはならない。", "測定": "「測定」は長さや量をはかることで、くっつける行為とは違う。", "点検": "「点検」は調べて確かめることで、くっつけることではない。"}, "sentence_index": 0, "correct_answer": "接合"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "二つの車が接合して、ぶつかりました。", "explanation": "ここは〈接触〉の意味。接合は「くっつけて一つにする」ことで、ぶつかって触れ合う場面には使わない。"}, {"text": "機械は、部品ごとに接合して掃除しました。", "explanation": "ここは〈分解〉の意味。分解は部品を外すことで、接合は逆にくっつけること。掃除のために外す場面には合わない。"}, {"text": "ロープを切るために、二本を接合しました。", "explanation": "ここは〈切断〉の意味。切る目的の場面で、くっつける接合は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59842fc5-799f-4d98-a8d3-278d78c2adcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39450, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "接合", "is_correct": true, "explanation": "二つのものをくっつける作業の意味で、のりが乾くまでの時間の話に合う。"}, {"text": "出発", "is_correct": false, "explanation": "「出発」は出かけることで、板の作業には合わない。"}, {"text": "解説", "is_correct": false, "explanation": "「解説」は説明することで、板をくっつける作業には使わない。"}, {"text": "点呼", "is_correct": false, "explanation": "「点呼」は人数を確認する行事で、板を対象にできない。"}], "explanations": {"接合": "二つのものをくっつける作業の意味で、のりが乾くまでの時間の話に合う。", "出発": "「出発」は出かけることで、板の作業には合わない。", "解説": "「解説」は説明することで、板をくっつける作業には使わない。", "点呼": "「点呼」は人数を確認する行事で、板を対象にできない。"}, "sentence_index": 6, "correct_answer": "接合"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "古い建物を接合して、新しく建て直しました。", "explanation": "ここは〈解体〉の意味。解体は建物をばらばらにすることで、接合は逆に一つにすること。建て直す前の撤去の場面には合わない。"}, {"text": "紙を接合して捨てました。", "explanation": "ここは〈破る〉の意味。破いた紙を捨てる場面で、くっつける接合は合わない。"}, {"text": "材料を二つに接合しました。", "explanation": "ここは〈分ける〉の意味。二つに分ける場面で、一つにまとめる接合は逆になる。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59842fc5-799f-4d98-a8d3-278d78c2adcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39450, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "板の接合を、接着剤を使います。", "corrected_sentence": "板の接合に、接着剤を使います。", "error_description": "誤：接合を使います　正：接合に使います。「接合に〜を使う」で目的（何のために）を示すので「に」が必要。「接合を」とすると接合という物を使う形になり不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59842fc5-799f-4d98-a8d3-278d78c2adcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39450, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "接合を作業は、丁寧に行います。", "corrected_sentence": "接合の作業は、丁寧に行います。", "error_description": "誤：接合を作業　正：接合の作業。「接合」が「作業」を修飾するので「の」で続ける。「を」は目的語で、名詞の前に置くと文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59842fc5-799f-4d98-a8d3-278d78c2adcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39451, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「接合には」の「に」。溶接を使う用途として接合を示す格助詞で、この文に合う。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すが、ここは用途を述べる文脈。「接合がは」となり不自然。"}, {"text": "を", "is_correct": false, "explanation": "「接合を」は目的語の形だが、直後の「は」と続かず「接合をは」となる。"}, {"text": "の", "is_correct": false, "explanation": "「接合の」は名詞を修飾する形で、後ろに「は」が続くと「接合のは」となり「には」の形にならない。"}], "correct_answer": "に", "explanations": {"に": "「接合には」の「に」。溶接を使う用途として接合を示す格助詞で、この文に合う。", "が": "「が」は主語を示すが、ここは用途を述べる文脈。「接合がは」となり不自然。", "を": "「接合を」は目的語の形だが、直後の「は」と続かず「接合をは」となる。", "の": "「接合の」は名詞を修飾する形で、後ろに「は」が続くと「接合のは」となり「には」の形にならない。"}, "error_tags": {"が": "主格", "を": "対格", "の": "連体格"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "分離", "is_correct": true, "explanation": "接合の対義語。つなぎ合わせた部品を離すという意味で、つなぐ接合と反対の関係にある。"}, {"text": "製造", "is_correct": false, "explanation": "製造は材料から製品をつくること。つなぐ・離すの対立ではないため、接合の対義語ではない。"}, {"text": "点検", "is_correct": false, "explanation": "点検は状態を調べること。接合と反対の関係にはなく、対義語ではない。"}, {"text": "測定", "is_correct": false, "explanation": "測定は長さや重さを量ること。接合と対立する行為ではなく、対義語ではない。"}], "correct_answer": "分離", "explanations": {"分離": "接合の対義語。つなぎ合わせた部品を離すという意味で、つなぐ接合と反対の関係にある。", "製造": "製造は材料から製品をつくること。つなぐ・離すの対立ではないため、接合の対義語ではない。", "点検": "点検は状態を調べること。接合と反対の関係にはなく、対義語ではない。", "測定": "測定は長さや重さを量ること。接合と対立する行為ではなく、対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59842fc5-799f-4d98-a8d3-278d78c2adcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39451, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「部品の接合が悪い」の「が」。接合が悪いという状態の主語を示し、「接合が悪いと」として文に合う。"}, {"text": "を", "is_correct": false, "explanation": "「接合を悪い」は目的語の形で、形容詞「悪い」の主語にならない。ここは主語を示す「が」が入る。"}, {"text": "から", "is_correct": false, "explanation": "「接合から悪い」は起点を示す「から」で、形容詞「悪い」と結びつかず不自然。ここは主語を示す「が」が入る。"}, {"text": "で", "is_correct": false, "explanation": "「接合で悪い」は手段や場所を示す「で」で、「悪い」の主語を表せない。"}], "correct_answer": "が", "explanations": {"が": "「部品の接合が悪い」の「が」。接合が悪いという状態の主語を示し、「接合が悪いと」として文に合う。", "を": "「接合を悪い」は目的語の形で、形容詞「悪い」の主語にならない。ここは主語を示す「が」が入る。", "から": "「接合から悪い」は起点を示す「から」で、形容詞「悪い」と結びつかず不自然。ここは主語を示す「が」が入る。", "で": "「接合で悪い」は手段や場所を示す「で」で、「悪い」の主語を表せない。"}, "error_tags": {"を": "対格", "から": "起点", "で": "手段・場所"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "分離", "is_correct": true, "explanation": "接合の対義語。つなぎ合わせた部品を離すという意味で、つなぐ接合と反対の関係にある。"}, {"text": "翻訳", "is_correct": false, "explanation": "翻訳は言語を別の言語に置き換えること。接合と反対の関係にはなく、対義語ではない。"}, {"text": "採取", "is_correct": false, "explanation": "採取は必要なものを取り集めること。接合と対立する行為ではなく、対義語ではない。"}, {"text": "加熱", "is_correct": false, "explanation": "加熱は熱を加えること。つなぐ行為の反対ではなく、対義語にはならない。"}], "correct_answer": "分離", "explanations": {"分離": "接合の対義語。つなぎ合わせた部品を離すという意味で、つなぐ接合と反対の関係にある。", "翻訳": "翻訳は言語を別の言語に置き換えること。接合と反対の関係にはなく、対義語ではない。", "採取": "採取は必要なものを取り集めること。接合と対立する行為ではなく、対義語ではない。", "加熱": "加熱は熱を加えること。つなぐ行為の反対ではなく、対義語にはならない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59842fc5-799f-4d98-a8d3-278d78c2adcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39451, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "複数の部品や材料を互いにつなぎ合わせること、またはその状態", "primary_collocate": null, "pronunciation": "せつごう", "ipa": "setsɯɡoː", "syllable_count": 4, "sentences": [{"text": "工場では、鉄の部品を接合する作業をしています。", "target_word": "接合", "complexity_tier": "T4", "furigana": "工場[こうじょう]では、鉄[てつ]の部品[ぶひん]を接合[せつごう]する作業[さぎょう]をしています。", "sentence_source": "generated"}, {"text": "金属どうしの接合には、溶接という方法を使います。", "target_word": "接合", "complexity_tier": "T4", "furigana": "金属[きんぞく]どうしの接合[せつごう]には、溶接[ようせつ]という方法[ほうほう]を使[つか]います。", "sentence_source": "generated"}, {"text": "この家具は、釘を使わない接合で作られています。", "target_word": "接合", "complexity_tier": "T4", "furigana": "この家具[かぐ]は、釘[くぎ]を使[つか]わない接合[せつごう]で作[つく]られています。", "sentence_source": "generated"}, {"text": "部品をきれいに接合するため、表面をよく磨きます。", "target_word": "接合", "complexity_tier": "T4", "furigana": "部品[ぶひん]をきれいに接合[せつごう]するため、表面[ひょうめん]をよく磨[みが]きます。", "sentence_source": "generated"}, {"text": "新しい材料は、複数の部品を強く接合できます。", "target_word": "接合", "complexity_tier": "T4", "furigana": "新[あたら]しい材料[ざいりょう]は、複数[ふくすう]の部品[ぶひん]を強[つよ]く接合[せつごう]できます。", "sentence_source": "generated"}, {"text": "橋の鉄骨を接合する工事が、来月から始まります。", "target_word": "接合", "complexity_tier": "T4", "furigana": "橋[はし]の鉄骨[てっこつ]を接合[せつごう]する工事[こうじ]が、来月[らいげつ]から始[はじ]まります。", "sentence_source": "generated"}, {"text": "プラスチックと金属の接合は、技術的に難しいです。", "target_word": "接合", "complexity_tier": "T4", "furigana": "プラスチックと金属[きんぞく]の接合[せつごう]は、技術的[ぎじゅつてき]に難[むずか]しいです。", "sentence_source": "generated"}, {"text": "部品の接合が悪いと、機械は正しく動きません。", "target_word": "接合", "complexity_tier": "T4", "furigana": "部品[ぶひん]の接合[せつごう]が悪[わる]いと、機械[きかい]は正[ただ]しく動[うご]きません。", "sentence_source": "generated"}, {"text": "木材の接合には、昔から伝わる技術があります。", "target_word": "接合", "complexity_tier": "T4", "furigana": "木材[もくざい]の接合[せつごう]には、昔[むかし]から伝[つた]わる技術[ぎじゅつ]があります。", "sentence_source": "generated"}, {"text": "接合した材料の強さを、機械で調べました。", "target_word": "接合", "complexity_tier": "T4", "furigana": "接合[せつごう]した材料[ざいりょう]の強[つよ]さを、機械[きかい]で調[しら]べました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "接合", "label": "基本形"}, {"form": "接合する", "label": "サ変動詞"}], "register": "technical", "sense_fingerprint": "部品や材料をつなぎ合わせる加工・工事（溶接・組み立てなど）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01e5a7c6-6233-4cdf-b902-182071ea0773') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39451, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "接合", "is_correct": true, "explanation": "「鉄の部品を接合する作業」の「接合」。部品をつなぎ合わせる作業を指し、この空欄に入る唯一の語。"}, {"text": "点灯", "is_correct": false, "explanation": "点灯は明かりをつけること。「部品を点灯する作業」は意味をなさない。"}, {"text": "作曲", "is_correct": false, "explanation": "作曲は曲をつくること。「部品を作曲する作業」は文脈に合わない。"}, {"text": "点呼", "is_correct": false, "explanation": "点呼は人数や出欠を確かめること。部品を対象にできず、この空欄には入らない。"}], "explanations": {"接合": "「鉄の部品を接合する作業」の「接合」。部品をつなぎ合わせる作業を指し、この空欄に入る唯一の語。", "点灯": "点灯は明かりをつけること。「部品を点灯する作業」は意味をなさない。", "作曲": "作曲は曲をつくること。「部品を作曲する作業」は文脈に合わない。", "点呼": "点呼は人数や出欠を確かめること。部品を対象にできず、この空欄には入らない。"}, "sentence_index": 0, "correct_answer": "接合"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼らは意見の違いを乗り越えて、心を接合した。", "explanation": "ここは〈結合〉の意味。心や関係をひとつにする場面には結合を使う。接合は部品などを物理的に結び合わせる語なので、この文では使わない。"}, {"text": "会議室のパソコンを、社内ネットワークに接合しました。", "explanation": "ここは〈接続〉の意味。機器を回線につなぐ場面には接続を使う。接合は部品や材料を結び合わせる語なので合わない。"}, {"text": "駅の改札で、昔の友人と接合した。", "explanation": "ここは〈再会〉の意味。人と久しぶりに会う場面には再会を使う。接合は部品や材料を結び合わせる語なので、人との出会いには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59842fc5-799f-4d98-a8d3-278d78c2adcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39451, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "接合", "is_correct": true, "explanation": "「プラスチックと金属の接合」として、異なる材料をつなぎ合わせる技術を指す。この空欄に入る唯一の語。"}, {"text": "比重", "is_correct": false, "explanation": "比重は物質の密度の比。「プラスチックと金属の比重は難しい」は文として成り立たない。"}, {"text": "倉庫", "is_correct": false, "explanation": "倉庫は物を保管する建物。材料どうしの関係を表す「の〜は」には入らない。"}, {"text": "花火", "is_correct": false, "explanation": "花火は火薬による娯楽。材料どうしを対象とする文脈には入らない。"}], "explanations": {"接合": "「プラスチックと金属の接合」として、異なる材料をつなぎ合わせる技術を指す。この空欄に入る唯一の語。", "比重": "比重は物質の密度の比。「プラスチックと金属の比重は難しい」は文として成り立たない。", "倉庫": "倉庫は物を保管する建物。材料どうしの関係を表す「の〜は」には入らない。", "花火": "花火は火薬による娯楽。材料どうしを対象とする文脈には入らない。"}, "sentence_index": 6, "correct_answer": "接合"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "二つの文化が接合して、新しい芸術が生まれました。", "explanation": "ここは〈融合〉の意味。文化や思想が溶け合う場面には融合を使う。接合は物と物をつなぐ語なので、この文では使わない。"}, {"text": "二つの会社が接合して、ひとつの大きな会社になりました。", "explanation": "ここは〈統合〉の意味。組織をひとつにまとめる場面には統合を使う。接合は部品などを物理的につなぐ語なので合わない。"}, {"text": "ボールが地面に接合して、大きく跳ねました。", "explanation": "ここは〈接触〉の意味。物が触れ合うだけの場面には接触を使う。接合は部品などを結び合わせる語なので、この文では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59842fc5-799f-4d98-a8d3-278d78c2adcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39451, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "作業員は、鉄板の接合を溶接機を使います。", "corrected_sentence": "作業員は、鉄板の接合に溶接機を使います。", "error_description": "接合の直後の助詞を誤っている。「使う」は用途を「〜に使う」で表すので、正しくは「接合に」。「接合を」と書くと、接合そのものを使う対象のように読まれてしまう。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59842fc5-799f-4d98-a8d3-278d78c2adcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39451, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ねじを使わず、部品を接合しる方法を考えました。", "corrected_sentence": "ねじを使わず、部品を接合する方法を考えました。", "error_description": "正しくは「接合する」。サ変動詞「接合する」の連体形は「接合する」で、「接合しる」という形は日本語にない。「する」を「しる」と誤っている。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59842fc5-799f-4d98-a8d3-278d78c2adcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
