INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39452, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "四十七という数字のことです。", "primary_collocate": null, "pronunciation": "よんじゅうなな", "ipa": "joɲdʑɯːnana", "syllable_count": 6, "sentences": [{"text": "46の次の数は「47」です。", "target_word": "47", "complexity_tier": "T3", "furigana": "よんじゅうろくのつぎのかずは「よんじゅうなな」です。", "sentence_source": "generated"}, {"text": "日本には「47」の都道府県があります。", "target_word": "47", "complexity_tier": "T3", "furigana": "にほんには「よんじゅうなな」のとどうふけんがあります。", "sentence_source": "generated"}, {"text": "「46、47、48」と順番に数えました。", "target_word": "47", "complexity_tier": "T3", "furigana": "「よんじゅうろく、よんじゅうなな、よんじゅうはち」とじゅんばんにかぞえました。", "sentence_source": "generated"}, {"text": "私の部屋の番号は「47」です。", "target_word": "47", "complexity_tier": "T3", "furigana": "わたしのへやのばんごうは「よんじゅうなな」です。", "sentence_source": "generated"}, {"text": "兄の背番号は「47」で、いつも目立っています。", "target_word": "47", "complexity_tier": "T3", "furigana": "あにのせばんごうは「よんじゅうなな」で、いつもめだっています。", "sentence_source": "generated"}, {"text": "100から53を引くと「47」になります。", "target_word": "47", "complexity_tier": "T3", "furigana": "ひゃくからごじゅうさんをひくと「よんじゅうなな」になります。", "sentence_source": "generated"}, {"text": "テストの点数は「47」で、合格には足りませんでした。", "target_word": "47", "complexity_tier": "T3", "furigana": "テストのてんすうは「よんじゅうなな」で、ごうかくにはたりませんでした。", "sentence_source": "generated"}, {"text": "「47」は10より大きくて、50より小さい数です。", "target_word": "47", "complexity_tier": "T3", "furigana": "「よんじゅうなな」はじゅうよりおおきくて、ごじゅうよりちいさいかずです。", "sentence_source": "generated"}, {"text": "電話番号の最後が「47」の人を探しています。", "target_word": "47", "complexity_tier": "T3", "furigana": "でんわばんごうのさいごが「よんじゅうなな」のひとをさがしています。", "sentence_source": "generated"}, {"text": "40と7をたすと「47」になります。", "target_word": "47", "complexity_tier": "T3", "furigana": "よんじゅうとななをたすと「よんじゅうなな」になります。", "sentence_source": "generated"}], "morphological_forms": [{"form": "47", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "数字の47（よんじゅうなな）を表す基数", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f839c227-2f16-4265-b473-70b89a9b588c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39452, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "47", "is_correct": true, "explanation": "46の次にくる数は47なので、文の条件に合う。"}, {"text": "45", "is_correct": false, "explanation": "45は46の前の数なので、「46の次の数」には合わない。"}, {"text": "48", "is_correct": false, "explanation": "48は47の次の数で、46の次ではないので合わない。"}, {"text": "57", "is_correct": false, "explanation": "57は46の次の数ではなく、文の条件に合わない。"}], "explanations": {"47": "46の次にくる数は47なので、文の条件に合う。", "45": "45は46の前の数なので、「46の次の数」には合わない。", "48": "48は47の次の数で、46の次ではないので合わない。", "57": "57は46の次の数ではなく、文の条件に合わない。"}, "sentence_index": 0, "correct_answer": "47"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "先生は黒板に47を大声で叫んだ。", "explanation": "数字の47には別の意味がなく、「叫ぶ」の対象として不自然な使い方。"}, {"text": "この部屋の天井は47で、とても高い。", "explanation": "数字の47には別の意味がなく、天井の高さを表す単位にはならないので、この文は成り立たない。"}, {"text": "ふとんの中で47がぐっすり寝ていた。", "explanation": "数字の47には別の意味がなく、生き物ではないので寝る主語にならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d645761-a470-43e1-a068-67a54f16899d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39452, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "47", "is_correct": true, "explanation": "テストの点数が47で、合格に足りなかったという文に合う。"}, {"text": "98", "is_correct": false, "explanation": "98点は高得点で、合格に足りなかったという文と矛盾する。"}, {"text": "90", "is_correct": false, "explanation": "90点は高得点で、合格に足りなかったという文と合わない。"}, {"text": "100", "is_correct": false, "explanation": "100点は満点で、合格に足りなかったという文と矛盾する。"}], "explanations": {"47": "テストの点数が47で、合格に足りなかったという文に合う。", "98": "98点は高得点で、合格に足りなかったという文と矛盾する。", "90": "90点は高得点で、合格に足りなかったという文と合わない。", "100": "100点は満点で、合格に足りなかったという文と矛盾する。"}, "sentence_index": 6, "correct_answer": "47"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "来週、友達と47を食べに行く約束をした。", "explanation": "ここは数字の意味。47は食べ物ではないので、〈食べに行く〉の目的語にならない。"}, {"text": "昨日の晩ご飯は47でおいしかった。", "explanation": "数字の47は料理の名前ではないので、食事の説明には使えない。別の意味はない。"}, {"text": "弟は47で笑って、遊びに出かけた。", "explanation": "数字の47は人ではないので、笑って出かける主語にはならない。別の意味はない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d645761-a470-43e1-a068-67a54f16899d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39452, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "数字の47が覚えるのは難しいです。", "corrected_sentence": "数字の47を覚えるのは難しいです。", "error_description": "「覚える」の目的語は「を」で示す。「が」は主語の格で、ここでは誤り。正しくは「47を覚える」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d645761-a470-43e1-a068-67a54f16899d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
