INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39456, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "手段・材料の『で』で、『ケールでサラダを作る』と材料を示すので文に合う。"}, {"text": "が", "is_correct": false, "explanation": "主格の『が』になるとケールが作る主体になり、意味が合わない。"}, {"text": "に", "is_correct": false, "explanation": "帰着の『に』では、サラダを作る材料を示せない。"}, {"text": "へ", "is_correct": false, "explanation": "方向の『へ』では、作る材料を示せない。"}], "correct_answer": "で", "explanations": {"で": "手段・材料の『で』で、『ケールでサラダを作る』と材料を示すので文に合う。", "が": "主格の『が』になるとケールが作る主体になり、意味が合わない。", "に": "帰着の『に』では、サラダを作る材料を示せない。", "へ": "方向の『へ』では、作る材料を示せない。"}, "error_tags": {"が": "主格", "に": "帰着の格", "へ": "方向の格"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82be0cd8-928c-4b59-993b-289166961950') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
