INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39456, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "ケールは、みどりのやさいです。サラダにしてたべます。", "primary_collocate": null, "pronunciation": "けーる", "ipa": "keːɾɯ", "syllable_count": 3, "sentences": [{"text": "ケールは、緑色の野菜です。", "target_word": "ケール", "complexity_tier": "T3", "furigana": "ケールは、緑色[みどりいろ]の野菜[やさい]です。", "sentence_source": "generated"}, {"text": "母は、ケールでサラダを作ります。", "target_word": "ケール", "complexity_tier": "T3", "furigana": "母[はは]は、ケールでサラダを作[つく]ります。", "sentence_source": "generated"}, {"text": "朝ごはんに、ケールのサラダを食べました。", "target_word": "ケール", "complexity_tier": "T3", "furigana": "朝[あさ]ごはんに、ケールのサラダを食[た]べました。", "sentence_source": "generated"}, {"text": "スーパーで、緑色のケールを一束買いました。", "target_word": "ケール", "complexity_tier": "T3", "furigana": "スーパーで、緑色[みどりいろ]のケールを一束[ひとたば]買[か]いました。", "sentence_source": "generated"}, {"text": "ケールは少し苦いので、ドレッシングをかけます。", "target_word": "ケール", "complexity_tier": "T3", "furigana": "ケールは少[すこ]し苦[にが]いので、ドレッシングをかけます。", "sentence_source": "generated"}, {"text": "庭で、ケールを育てています。", "target_word": "ケール", "complexity_tier": "T3", "furigana": "庭[にわ]で、ケールを育[そだ]てています。", "sentence_source": "generated"}, {"text": "姉はケールを細かく切って、サラダに入れました。", "target_word": "ケール", "complexity_tier": "T3", "furigana": "姉[あね]はケールを細[こま]かく切[き]って、サラダに入[い]れました。", "sentence_source": "generated"}, {"text": "ケールの葉は大きくて、濃い緑色です。", "target_word": "ケール", "complexity_tier": "T3", "furigana": "ケールの葉[は]は大[おお]きくて、濃[こ]い緑色[みどりいろ]です。", "sentence_source": "generated"}, {"text": "私はケールのサラダが好きなので、よく食べます。", "target_word": "ケール", "complexity_tier": "T3", "furigana": "私[わたし]はケールのサラダが好[す]きなので、よく食[た]べます。", "sentence_source": "generated"}, {"text": "昨日の晩ごはんは、肉とケールのスープでした。", "target_word": "ケール", "complexity_tier": "T3", "furigana": "昨日[きのう]の晩[ばん]ごはんは、肉[にく]とケールのスープでした。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ケール", "label": "基本形"}], "register": "日常的（やさしい丁寧体）", "sense_fingerprint": "サラダなどにして食べる、緑色の葉の野菜", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9992a0cb-2327-4aa2-bde0-60df8cd86bf4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39456, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ケール", "is_correct": true, "explanation": "緑色の野菜の名前で、『緑色の野菜です』の主語として文が成り立つ。"}, {"text": "電車", "is_correct": false, "explanation": "乗り物で、緑色の野菜ではないので文の主語に合わない。"}, {"text": "帽子", "is_correct": false, "explanation": "身につける物で、緑色の野菜ではないので意味が通らない。"}, {"text": "扇風機", "is_correct": false, "explanation": "家電で、緑色の野菜ではないので文の主語に合わない。"}], "explanations": {"ケール": "緑色の野菜の名前で、『緑色の野菜です』の主語として文が成り立つ。", "電車": "乗り物で、緑色の野菜ではないので文の主語に合わない。", "帽子": "身につける物で、緑色の野菜ではないので意味が通らない。", "扇風機": "家電で、緑色の野菜ではないので文の主語に合わない。"}, "sentence_index": 0, "correct_answer": "ケール"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "スーパーで、台所用のケールを一本買いました。", "explanation": "ここは〈洗剤〉の意味。ケールは野菜で、台所用品には使わないので合わない。"}, {"text": "池で、ケールを泳がせました。", "explanation": "ここは〈魚〉の意味。ケールは野菜で、泳がせることはできないので合わない。"}, {"text": "図書館で、ケールを借りました。", "explanation": "ここは〈本〉の意味。ケールは食べ物で、図書館から借りるものではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82be0cd8-928c-4b59-993b-289166961950') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39456, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ケール", "is_correct": true, "explanation": "細かく切ってサラダに入れる野菜の名前で、文の対象として合う。"}, {"text": "鉛筆", "is_correct": false, "explanation": "文房具で、細かく切ってサラダに入れるものではない。"}, {"text": "座布団", "is_correct": false, "explanation": "寝具で、サラダの材料にはならない。"}, {"text": "洗濯機", "is_correct": false, "explanation": "家電で、切ってサラダに入れる対象ではない。"}], "explanations": {"ケール": "細かく切ってサラダに入れる野菜の名前で、文の対象として合う。", "鉛筆": "文房具で、細かく切ってサラダに入れるものではない。", "座布団": "寝具で、サラダの材料にはならない。", "洗濯機": "家電で、切ってサラダに入れる対象ではない。"}, "sentence_index": 6, "correct_answer": "ケール"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "家で、ケールを飼っています。", "explanation": "ここは〈猫〉の意味。ケールは野菜で、飼うことはできないので合わない。"}, {"text": "寝る前に、ケールを読みました。", "explanation": "ここは〈雑誌〉の意味。ケールは食べ物で、読むものではないので合わない。"}, {"text": "雨の日はケールをさします。", "explanation": "ここは〈傘〉の意味。ケールは野菜で、雨をよけるために使うものではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82be0cd8-928c-4b59-993b-289166961950') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
