INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39457, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "ケールを話題として示す助詞で、「ケールは見た目が似ている」という文の主題として正しい。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示す助詞で、見た目が似ているという状態を表す文には合わない。"}, {"text": "で", "is_correct": false, "explanation": "場所や手段を示す助詞で、この文の主題にはならない。"}, {"text": "から", "is_correct": false, "explanation": "起点を示す助詞で、似ているという説明とは結びつかないので合わない。"}], "correct_answer": "は", "explanations": {"は": "ケールを話題として示す助詞で、「ケールは見た目が似ている」という文の主題として正しい。", "を": "目的語を示す助詞で、見た目が似ているという状態を表す文には合わない。", "で": "場所や手段を示す助詞で、この文の主題にはならない。", "から": "起点を示す助詞で、似ているという説明とは結びつかないので合わない。"}, "error_tags": {"を": "目的語", "で": "場所・手段", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82be0cd8-928c-4b59-993b-289166961950') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39457, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "緑色の葉物野菜で、キャベツの仲間です。栄養がとても豊富で、健康に良いと言われています。", "primary_collocate": null, "pronunciation": "けーる", "ipa": "keːɾɯ", "syllable_count": 3, "sentences": [{"text": "ケールはキャベツの仲間の緑色の葉物野菜で、栄養が豊富だ。", "target_word": "ケール", "complexity_tier": "T3", "furigana": "ケールはキャベツの仲間[なかま]の緑色[みどりいろ]の葉物[はもの]野菜[やさい]で、栄養[えいよう]が豊富[ほうふ]だ。", "sentence_source": "generated"}, {"text": "健康のために、毎朝ケールのジュースを飲むようにしている。", "target_word": "ケール", "complexity_tier": "T3", "furigana": "健康[けんこう]のために、毎朝[まいあさ]ケールのジュースを飲[の]むようにしている。", "sentence_source": "generated"}, {"text": "ケールは葉が厚くてかたいので、生で食べるときは細かく切る。", "target_word": "ケール", "complexity_tier": "T3", "furigana": "ケールは葉[は]が厚[あつ]くてかたいので、生[なま]で食[た]べるときは細[こま]かく切[き]る。", "sentence_source": "generated"}, {"text": "最近は、ケールを使ったスムージーが人気だ。", "target_word": "ケール", "complexity_tier": "T3", "furigana": "最近[さいきん]は、ケールを使[つか]ったスムージーが人気[にんき]だ。", "sentence_source": "generated"}, {"text": "ケールにはビタミンが多く含まれているため、体に良いと言われる。", "target_word": "ケール", "complexity_tier": "T3", "furigana": "ケールにはビタミンが多[おお]く含[ふく]まれているため、体[からだ]に良[よ]いと言[い]われる。", "sentence_source": "generated"}, {"text": "ケールの苗を畑に植えたら、寒い冬でも元気に育った。", "target_word": "ケール", "complexity_tier": "T3", "furigana": "ケールの苗[なえ]を畑[はたけ]に植[う]えたら、寒[さむ]い冬[ふゆ]でも元気[げんき]に育[そだ]った。", "sentence_source": "generated"}, {"text": "ケールをさっといためて、にんにくで味をつけた。", "target_word": "ケール", "complexity_tier": "T3", "furigana": "ケールをさっといためて、にんにくで味[あじ]をつけた。", "sentence_source": "generated"}, {"text": "キャベツやブロッコリーと同じ仲間なので、ケールは見た目が少し似ている。", "target_word": "ケール", "complexity_tier": "T3", "furigana": "キャベツやブロッコリーと同[おな]じ仲間[なかま]なので、ケールは見[み]た目[め]が少[すこ]し似[に]ている。", "sentence_source": "generated"}, {"text": "青汁の原料として、ケールが昔からよく使われている。", "target_word": "ケール", "complexity_tier": "T3", "furigana": "青汁[あおじる]の原料[げんりょう]として、ケールが昔[むかし]からよく使[つか]われている。", "sentence_source": "generated"}, {"text": "栄養士に勧められて、サラダにケールを加えることにした。", "target_word": "ケール", "complexity_tier": "T3", "furigana": "栄養士[えいようし]に勧[すす]められて、サラダにケールを加[くわ]えることにした。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ケール", "label": "基本形"}], "register": "日常的（普通体の説明文）", "sense_fingerprint": "キャベツの仲間で、栄養が豊富な健康野菜として知られる緑色の葉物野菜", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9992a0cb-2327-4aa2-bde0-60df8cd86bf4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39457, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ケール", "is_correct": true, "explanation": "キャベツの仲間の葉物野菜を指す語で、この文の主語として正しい。"}, {"text": "ごぼう", "is_correct": false, "explanation": "根を食べる野菜で、葉物ではなくキャベツの仲間でもないので合わない。"}, {"text": "なす", "is_correct": false, "explanation": "果実を食べる野菜で、葉物ではなくキャベツの仲間でもないので合わない。"}, {"text": "とうもろこし", "is_correct": false, "explanation": "実を食べる野菜で、葉物ではなくキャベツの仲間でもないので合わない。"}], "explanations": {"ケール": "キャベツの仲間の葉物野菜を指す語で、この文の主語として正しい。", "ごぼう": "根を食べる野菜で、葉物ではなくキャベツの仲間でもないので合わない。", "なす": "果実を食べる野菜で、葉物ではなくキャベツの仲間でもないので合わない。", "とうもろこし": "実を食べる野菜で、葉物ではなくキャベツの仲間でもないので合わない。"}, "sentence_index": 0, "correct_answer": "ケール"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "朝、前髪をケールにして出かけた。", "explanation": "〈カール〉の意味。髪を巻く形を指す語で、野菜のケールとは別の語なので合わない。"}, {"text": "お祝いの夜、ケールの上のろうそくを吹き消した。", "explanation": "〈ケーキ〉の意味。ろうそくを吹き消すのはケーキの場面で、野菜のケールには合わない。"}, {"text": "壊れやすいお皿をケールに入れて運んだ。", "explanation": "〈ケース〉の意味。物を入れる容器を指す語で、野菜のケールは容器ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82be0cd8-928c-4b59-993b-289166961950') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39457, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ケール", "is_correct": true, "explanation": "いためて味をつける野菜を指す語で、この文の目的語として正しい。"}, {"text": "ヨーグルト", "is_correct": false, "explanation": "いためる料理には使わない食品で、「をさっといためて」とは合わない。"}, {"text": "ようかん", "is_correct": false, "explanation": "和菓子で、いためることはないので合わない。"}, {"text": "寒天", "is_correct": false, "explanation": "ゼリー状の材料で、いためる料理には使わないので合わない。"}], "explanations": {"ケール": "いためて味をつける野菜を指す語で、この文の目的語として正しい。", "ヨーグルト": "いためる料理には使わない食品で、「をさっといためて」とは合わない。", "ようかん": "和菓子で、いためることはないので合わない。", "寒天": "ゼリー状の材料で、いためる料理には使わないので合わない。"}, "sentence_index": 6, "correct_answer": "ケール"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "パソコンとモニターを、ケールでつないだ。", "explanation": "〈ケーブル〉の意味。電気や信号をつなぐ線を指す語で、野菜のケールはつなぐ道具ではないので合わない。"}, {"text": "ハンバーガーに、ケールを赤いボトルから絞ってかけた。", "explanation": "〈ケチャップ〉の意味。赤いボトルから絞って料理にかける調味料で、野菜のケールはそう使わないので合わない。"}, {"text": "お湯をケールで沸かして、お茶を入れた。", "explanation": "〈ケトル〉の意味。湯を沸かす道具を指す語で、野菜のケールは道具ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82be0cd8-928c-4b59-993b-289166961950') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39457, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ケールに使ったスープを作って、家族に出した。", "corrected_sentence": "ケールを使ったスープを作って、家族に出した。", "error_description": "「使う」の目的語には「を」を使う。「ケールに使った」は助詞の誤りで、正しくは「ケールを使った」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82be0cd8-928c-4b59-993b-289166961950') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39457, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "祖母は、庭でケールが育てて、毎週収穫している。", "corrected_sentence": "祖母は、庭でケールを育てて、毎週収穫している。", "error_description": "「育てる」の目的語は「を」で示す。「ケールが」にすると主語になり、「育てて」の目的語がなくなって文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82be0cd8-928c-4b59-993b-289166961950') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39458, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「動く」が通る場所を表す「を」で、「バンドの中を動きます」となる。"}, {"text": "と", "is_correct": false, "explanation": "「中と動きます」は意味が通らず、場所を表せない。"}, {"text": "しか", "is_correct": false, "explanation": "「しか」は否定と一緒に使うので、肯定の「動きます」と合わない。"}, {"text": "や", "is_correct": false, "explanation": "「中や動きます」は、並べる助詞の後が述語で、文にならない。"}], "correct_answer": "を", "explanations": {"を": "「動く」が通る場所を表す「を」で、「バンドの中を動きます」となる。", "と": "「中と動きます」は意味が通らず、場所を表せない。", "しか": "「しか」は否定と一緒に使うので、肯定の「動きます」と合わない。", "や": "「中や動きます」は、並べる助詞の後が述語で、文にならない。"}, "error_tags": {"と": "companion", "しか": "negative_polarity", "や": "listing"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ba4152e-71e4-4baf-bf6e-d4d28133816a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39458, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「バンドが違えば」は主語を表す「が」で、条件の文が成り立つ。"}, {"text": "を", "is_correct": false, "explanation": "「違う」は自動詞なので「バンドを違えば」は文法的に誤り。"}, {"text": "に", "is_correct": false, "explanation": "「バンドに違えば」は「違う」と結びつかず、文にならない。"}, {"text": "しか", "is_correct": false, "explanation": "「しか」は否定と一緒に使うので、肯定の「違えば」と合わない。"}], "correct_answer": "が", "explanations": {"が": "「バンドが違えば」は主語を表す「が」で、条件の文が成り立つ。", "を": "「違う」は自動詞なので「バンドを違えば」は文法的に誤り。", "に": "「バンドに違えば」は「違う」と結びつかず、文にならない。", "しか": "「しか」は否定と一緒に使うので、肯定の「違えば」と合わない。"}, "error_tags": {"を": "object_marker", "に": "target_marker", "しか": "negative_polarity"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ba4152e-71e4-4baf-bf6e-d4d28133816a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39458, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物質の中で、電子が持つことのできるエネルギーの範囲（エネルギー帯）。", "primary_collocate": null, "pronunciation": "ばんど", "ipa": "bando", "syllable_count": 3, "sentences": [{"text": "バンドは、電子のいる場所です。", "target_word": "バンド", "complexity_tier": "T2", "furigana": "バンドは、電子[でんし]のいる場所[ばしょ]です。", "sentence_source": "generated"}, {"text": "電子は、バンドの中を動きます。", "target_word": "バンド", "complexity_tier": "T2", "furigana": "電子[でんし]は、バンドの中[なか]を動[うご]きます。", "sentence_source": "generated"}, {"text": "上と下のバンドの間には、すきまがある。", "target_word": "バンド", "complexity_tier": "T3", "furigana": "上[うえ]と下[した]のバンドの間[あいだ]には、すきまがある。", "sentence_source": "generated"}, {"text": "バンドのすきまが大きいと、電気は流れにくい。", "target_word": "バンド", "complexity_tier": "T4", "furigana": "バンドのすきまが大[おお]きいと、電気[でんき]は流[なが]れにくい。", "sentence_source": "generated"}, {"text": "太陽の光を当てると、電子は上のバンドに移る。", "target_word": "バンド", "complexity_tier": "T4", "furigana": "太陽[たいよう]の光[ひかり]を当[あ]てると、電子[でんし]は上[うえ]のバンドに移[うつ]る。", "sentence_source": "generated"}, {"text": "光で電気をつくる研究に、バンドの知識は欠かせない。", "target_word": "バンド", "complexity_tier": "T4", "furigana": "光[ひかり]で電気[でんき]をつくる研究[けんきゅう]に、バンドの知識[ちしき]は欠[か]かせない。", "sentence_source": "generated"}, {"text": "授業で、バンドの図を初めて見た。", "target_word": "バンド", "complexity_tier": "T2", "furigana": "授業[じゅぎょう]で、バンドの図[ず]を初[はじ]めて見[み]た。", "sentence_source": "generated"}, {"text": "バンドが違えば、電気の流れ方も変わる。", "target_word": "バンド", "complexity_tier": "T4", "furigana": "バンドが違[ちが]えば、電気[でんき]の流[なが]れ方[かた]も変[か]わる。", "sentence_source": "generated"}, {"text": "半導体の研究にも、バンドの考え方が使われる。", "target_word": "バンド", "complexity_tier": "T4", "furigana": "半導体[はんどうたい]の研究[けんきゅう]にも、バンドの考[かんが]え方[かた]が使[つか]われる。", "sentence_source": "generated"}, {"text": "これは、バンドを説明する簡単な図です。", "target_word": "バンド", "complexity_tier": "T3", "furigana": "これは、バンドを説明[せつめい]する簡単[かんたん]な図[ず]です。", "sentence_source": "generated"}], "morphological_forms": [], "register": "plain", "sense_fingerprint": "名詞 | 電子のエネルギーのかたまり", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42d94e4e-9169-4547-91bc-074c7abed4e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39458, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "バンド", "is_correct": true, "explanation": "見出し語そのもので、音が一致する。"}, {"text": "バント", "is_correct": false, "explanation": "最後の「ど」が「と」に変わった別の語で、清濁の1拍だけが違う。"}, {"text": "ランド", "is_correct": false, "explanation": "最初の「ば」が「ら」に変わった別の語で、1拍だけが違う。"}, {"text": "ハンド", "is_correct": false, "explanation": "最初の「ば」が「は」に変わった別の語で、清濁の1拍だけが違う。"}], "explanations": {"バンド": "見出し語そのもので、音が一致する。", "バント": "最後の「ど」が「と」に変わった別の語で、清濁の1拍だけが違う。", "ランド": "最初の「ば」が「ら」に変わった別の語で、1拍だけが違う。", "ハンド": "最初の「ば」が「は」に変わった別の語で、清濁の1拍だけが違う。"}, "sentence_index": null, "correct_answer": "バンド"}, "level_3": {"options": [{"text": "バンド", "is_correct": true, "explanation": "電子がいる場所として、エネルギーの範囲のバンドが文に合う。"}, {"text": "ケーキ", "is_correct": false, "explanation": "形は合うが、ケーキが電子のいる場所という意味が合わない。"}, {"text": "カメラ", "is_correct": false, "explanation": "形は合うが、カメラが電子のいる場所という意味が合わない。"}, {"text": "マンガ", "is_correct": false, "explanation": "形は合うが、マンガが電子のいる場所という意味が合わない。"}], "explanations": {"バンド": "電子がいる場所として、エネルギーの範囲のバンドが文に合う。", "ケーキ": "形は合うが、ケーキが電子のいる場所という意味が合わない。", "カメラ": "形は合うが、カメラが電子のいる場所という意味が合わない。", "マンガ": "形は合うが、マンガが電子のいる場所という意味が合わない。"}, "sentence_index": 0, "correct_answer": "バンド"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "先生のバンドが、文化祭でギターを弾いて歌った。", "explanation": "「バンド」を楽器を演奏する音楽グループの意味で使っていて、電子のエネルギーの意味ではない。"}, {"text": "バンドをお茶といっしょに食べた。", "explanation": "バンドはエネルギーの範囲のことで、食べ物ではないので「食べる」と合わない。"}, {"text": "ズボンがずれないように、バンドをしめた。", "explanation": "「バンド」をベルトの意味で使っていて、この意味とは違う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ba4152e-71e4-4baf-bf6e-d4d28133816a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
