INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39460, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "二つのものの間にある、ぴったり合わないところや、あきのこと。", "primary_collocate": null, "pronunciation": "ぎゃっぷ", "ipa": "ɡjappɯ", "syllable_count": 3, "sentences": [{"text": "親と子の間には、考え方のギャップがある。", "target_word": "ギャップ", "complexity_tier": "T3", "furigana": "親[おや]と子[こ]の間[あいだ]には、考[かんが]え方[かた]のギャップがある。", "sentence_source": "generated"}, {"text": "都会と田舎のギャップに、最初は驚いた。", "target_word": "ギャップ", "complexity_tier": "T3", "furigana": "都会[とかい]と田舎[いなか]のギャップに、最初[さいしょ]は驚[おどろ]いた。", "sentence_source": "generated"}, {"text": "二人の年の差が大きく、会話にギャップを感じる。", "target_word": "ギャップ", "complexity_tier": "T3", "furigana": "二人[ふたり]の年[とし]の差[さ]が大[おお]きく、会話[かいわ]にギャップを感[かん]じる。", "sentence_source": "generated"}, {"text": "想像と実物のギャップが大きくて、がっかりした。", "target_word": "ギャップ", "complexity_tier": "T3", "furigana": "想像[そうぞう]と実物[じつぶつ]のギャップが大[おお]きくて、がっかりした。", "sentence_source": "generated"}, {"text": "昔の写真と今の姿のギャップに、友達は笑った。", "target_word": "ギャップ", "complexity_tier": "T3", "furigana": "昔[むかし]の写真[しゃしん]と今[いま]の姿[すがた]のギャップに、友達[ともだち]は笑[わら]った。", "sentence_source": "generated"}, {"text": "世代のギャップを埋めるために、よく話し合う。", "target_word": "ギャップ", "complexity_tier": "T3", "furigana": "世代[せだい]のギャップを埋[う]めるために、よく話[はな]し合[あ]う。", "sentence_source": "generated"}, {"text": "普段のおとなしさと、舞台での激しさのギャップがすごい。", "target_word": "ギャップ", "complexity_tier": "T3", "furigana": "普段[ふだん]のおとなしさと、舞台[ぶたい]での激[はげ]しさのギャップがすごい。", "sentence_source": "generated"}, {"text": "外見と中身のギャップが魅力だと言われる。", "target_word": "ギャップ", "complexity_tier": "T3", "furigana": "外見[がいけん]と中身[なかみ]のギャップが魅力[みりょく]だと言[い]われる。", "sentence_source": "generated"}, {"text": "海外で働いて、文化のギャップに悩んだ。", "target_word": "ギャップ", "complexity_tier": "T3", "furigana": "海外[かいがい]で働[はたら]いて、文化[ぶんか]のギャップに悩[なや]んだ。", "sentence_source": "generated"}, {"text": "二つの意見のギャップは、なかなか縮まらない。", "target_word": "ギャップ", "complexity_tier": "T3", "furigana": "二[ふた]つの意見[いけん]のギャップは、なかなか縮[ちぢ]まらない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ギャップ", "label": "基本形"}, {"form": "ギャップが", "label": "主格"}, {"form": "ギャップを", "label": "目的格"}], "register": "neutral", "sense_fingerprint": "二つのものの間のずれや食い違い", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3049333-685e-4b1b-9295-162778d51a11') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39460, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ギャップ", "is_correct": true, "explanation": "考え方の食い違いを表し、親子の考え方の違いを指すのに合うため正しい。"}, {"text": "カロリー", "is_correct": false, "explanation": "熱量を表す語で、考え方の隔たりを示す文には合わない。"}, {"text": "ダンス", "is_correct": false, "explanation": "踊りを表す語で、考え方の隔たりを示す文には合わない。"}, {"text": "コスト", "is_correct": false, "explanation": "費用を表す語で、考え方の違いには使えない。"}], "explanations": {"ギャップ": "考え方の食い違いを表し、親子の考え方の違いを指すのに合うため正しい。", "カロリー": "熱量を表す語で、考え方の隔たりを示す文には合わない。", "ダンス": "踊りを表す語で、考え方の隔たりを示す文には合わない。", "コスト": "費用を表す語で、考え方の違いには使えない。"}, "sentence_index": 0, "correct_answer": "ギャップ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "二つの村を、ギャップで結んだ。", "explanation": "ここは〈橋〉（つなぐもの）の意味。ギャップは二つの間のずれを指すので、村を結ぶ手段にはならない。"}, {"text": "友達からギャップをもらって、答えがわかった。", "explanation": "ここは〈ヒント〉（手がかり）の意味。ギャップは食い違いを表すので、答えを教える手がかりにはならない。"}, {"text": "友達はギャップを編んで、帽子を作った。", "explanation": "ここは〈毛糸〉（編む材料）の意味。ギャップは食い違いを指すので、編む材料にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f85d9819-83f9-481b-865a-2430605a6e4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39460, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ギャップ", "is_correct": true, "explanation": "性格の食い違いを表し、おとなしさと激しさの差を指すのに合うため正しい。"}, {"text": "サイズ", "is_correct": false, "explanation": "大きさを表す語で、性格の差を指す文脈には合わない。"}, {"text": "ドラム", "is_correct": false, "explanation": "楽器を表す語で、舞台の激しさの差を示す文脈には合わない。"}, {"text": "ボタン", "is_correct": false, "explanation": "押すための部品で、性格の差とは関係がない。"}], "explanations": {"ギャップ": "性格の食い違いを表し、おとなしさと激しさの差を指すのに合うため正しい。", "サイズ": "大きさを表す語で、性格の差を指す文脈には合わない。", "ドラム": "楽器を表す語で、舞台の激しさの差を示す文脈には合わない。", "ボタン": "押すための部品で、性格の差とは関係がない。"}, "sentence_index": 6, "correct_answer": "ギャップ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は、どんな時もギャップを守る人だ。", "explanation": "ここは〈約束〉（決めた取り決め）の意味。ギャップは食い違いを指すので、守る対象にはならない。"}, {"text": "ギャップを、みんなで祝った。", "explanation": "ここは〈祝い〉（喜びの対象）の意味。ギャップは食い違いを指すので、祝う対象にはならない。"}, {"text": "店でギャップを払って、商品を買った。", "explanation": "ここは〈代金〉（支払うお金）の意味。ギャップは食い違いを指すので、払う対象にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f85d9819-83f9-481b-865a-2430605a6e4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39460, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "親と子の間に、考え方のギャップに感じる。", "corrected_sentence": "親と子の間に、考え方のギャップを感じる。", "error_description": "「感じる」の目的語は『を』。『ギャップに』は誤りで、『ギャップを』が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f85d9819-83f9-481b-865a-2430605a6e4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39460, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "二人の意見のギャップを、なかなか縮まらない。", "corrected_sentence": "二人の意見のギャップが、なかなか縮まらない。", "error_description": "「縮まる」は自動詞で、主語に『が』を取る。『を』は誤りで、『が』が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f85d9819-83f9-481b-865a-2430605a6e4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39462, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「わかる」の対象を表す「が」で、「スケールがよくわかります」と続く。"}, {"text": "を", "is_correct": false, "explanation": "「わかる」は目的語に「を」を取らないので、「スケールをよくわかります」は成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は方向や対象を示すが、「スケールによくわかります」とは続かない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す「へ」は「わかる」の対象にならず、「スケールへよくわかります」は成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「わかる」の対象を表す「が」で、「スケールがよくわかります」と続く。", "を": "「わかる」は目的語に「を」を取らないので、「スケールをよくわかります」は成り立たない。", "に": "「に」は方向や対象を示すが、「スケールによくわかります」とは続かない。", "へ": "方向を表す「へ」は「わかる」の対象にならず、「スケールへよくわかります」は成り立たない。"}, "error_tags": {"を": "目的語", "に": "対象・場所", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f99bd40-4f88-46e8-ae62-05411a60de0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39462, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「大きい」の主語を示す「が」で、「スケールが大きい」と続く。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を示すため、「スケールと大きい」とは続かない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、「スケールへ大きい」は成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点や理由を示すため、ここでは「スケールから大きい」が成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「大きい」の主語を示す「が」で、「スケールが大きい」と続く。", "と": "「と」は並列や相手を示すため、「スケールと大きい」とは続かない。", "へ": "「へ」は方向を示すので、「スケールへ大きい」は成り立たない。", "から": "「から」は起点や理由を示すため、ここでは「スケールから大きい」が成り立たない。"}, "error_tags": {"と": "並列・相手", "へ": "方向", "から": "起点・理由"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f99bd40-4f88-46e8-ae62-05411a60de0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39462, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "大きさや広がりの度合いのことです。", "primary_collocate": null, "pronunciation": "すけーる", "ipa": "sɯkeːɾɯ", "syllable_count": 4, "sentences": [{"text": "この絵はスケールが大きくて、見ているだけで驚きました。", "target_word": "スケール", "complexity_tier": "T3", "furigana": "この絵[え]はスケールが大[おお]きくて、見[み]ているだけで驚[おどろ]きました。", "sentence_source": "generated"}, {"text": "山の上から見ると、町のスケールがよくわかります。", "target_word": "スケール", "complexity_tier": "T3", "furigana": "山[やま]の上[うえ]から見[み]ると、町[まち]のスケールがよくわかります。", "sentence_source": "generated"}, {"text": "彼の話はスケールが大きすぎて、だれも信じませんでした。", "target_word": "スケール", "complexity_tier": "T3", "furigana": "彼[かれ]の話[はなし]はスケールが大[おお]きすぎて、だれも信[しん]じませんでした。", "sentence_source": "generated"}, {"text": "この公園はスケールが小さいので、一時間で回れます。", "target_word": "スケール", "complexity_tier": "T3", "furigana": "この公園[こうえん]はスケールが小[ちい]さいので、一時間[いちじかん]で回[まわ]れます。", "sentence_source": "generated"}, {"text": "世界のスケールで考えると、この問題は小さいです。", "target_word": "スケール", "complexity_tier": "T3", "furigana": "世界[せかい]のスケールで考[かんが]えると、この問題[もんだい]は小[ちい]さいです。", "sentence_source": "generated"}, {"text": "スケールの大きい映画だったので、大きな画面で見たかったです。", "target_word": "スケール", "complexity_tier": "T3", "furigana": "スケールの大[おお]きい映画[えいが]だったので、大[おお]きな画面[がめん]で見[み]たかったです。", "sentence_source": "generated"}, {"text": "宇宙のスケールは人間には想像しにくいです。", "target_word": "スケール", "complexity_tier": "T3", "furigana": "宇宙[うちゅう]のスケールは人間[にんげん]には想像[そうぞう]しにくいです。", "sentence_source": "generated"}, {"text": "新しい橋は、スケールが大きいことで有名になりました。", "target_word": "スケール", "complexity_tier": "T3", "furigana": "新[あたら]しい橋[はし]は、スケールが大[おお]きいことで有名[ゆうめい]になりました。", "sentence_source": "generated"}, {"text": "祭りのスケールが年々大きくなって、客も増えました。", "target_word": "スケール", "complexity_tier": "T3", "furigana": "祭[まつ]りのスケールが年々[ねんねん]大[おお]きくなって、客[きゃく]も増[ふ]えました。", "sentence_source": "generated"}, {"text": "彼女の夢はスケールが大きく、いつも周りを元気にします。", "target_word": "スケール", "complexity_tier": "T3", "furigana": "彼女[かのじょ]の夢[ゆめ]はスケールが大[おお]きく、いつも周[まわ]りを元気[げんき]にします。", "sentence_source": "generated"}], "morphological_forms": [{"form": "スケール", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "物事や人の大きさ・広がりの度合い(スケールが大きい/小さい)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2b6e36a-9597-4ba4-89df-d93b59e9ae30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39462, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "スケール", "is_correct": true, "explanation": "「スケールが大きい」で絵の大きさの度合いを表し、空欄に入って文が成り立つ。"}, {"text": "ルール", "is_correct": false, "explanation": "規則の意味で、「ルールが大きくて」では絵の大きさを表せず、文が成り立たない。"}, {"text": "アドバイス", "is_correct": false, "explanation": "助言は大きさの度合いを測る対象ではなく、「アドバイスが大きくて驚いた」は絵の感想として合わない。"}, {"text": "ペース", "is_correct": false, "explanation": "進む速さや調子を表す語で、絵の広がりの大きさには使わないので合わない。"}], "explanations": {"スケール": "「スケールが大きい」で絵の大きさの度合いを表し、空欄に入って文が成り立つ。", "ルール": "規則の意味で、「ルールが大きくて」では絵の大きさを表せず、文が成り立たない。", "アドバイス": "助言は大きさの度合いを測る対象ではなく、「アドバイスが大きくて驚いた」は絵の感想として合わない。", "ペース": "進む速さや調子を表す語で、絵の広がりの大きさには使わないので合わない。"}, "sentence_index": 0, "correct_answer": "スケール"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この仕事は、スケールが速すぎて疲れます。", "explanation": "ここは〈ペース〉の意味。仕事の進む速さには「ペース」を使い、スケールは合わない。"}, {"text": "毎日ピアノのスケールを練習して、指が速く動くようになりました。", "explanation": "ここは〈音階〉の意味。楽器の練習には「音階」を使い、大きさの度合いとしては合わない。"}, {"text": "このラーメンはスケールが多くて、食べきれませんでした。", "explanation": "ここは〈ボリューム〉の意味。食べ物の分量には「多い」と組むボリュームを使うので、スケールは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f99bd40-4f88-46e8-ae62-05411a60de0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39462, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "スケール", "is_correct": true, "explanation": "宇宙の広がりの度合いを表し、人間には想像しにくいという文に合う。"}, {"text": "ボーナス", "is_correct": false, "explanation": "臨時の給与の意味で、宇宙の広がりを表すことはできないので合わない。"}, {"text": "ノルマ", "is_correct": false, "explanation": "割り当てられた仕事量の意味で、宇宙の性質を説明する文には当てはまらない。"}, {"text": "ブーム", "is_correct": false, "explanation": "一時的な流行の意味で、「宇宙のブームは想像しにくい」は文として成り立たない。"}], "explanations": {"スケール": "宇宙の広がりの度合いを表し、人間には想像しにくいという文に合う。", "ボーナス": "臨時の給与の意味で、宇宙の広がりを表すことはできないので合わない。", "ノルマ": "割り当てられた仕事量の意味で、宇宙の性質を説明する文には当てはまらない。", "ブーム": "一時的な流行の意味で、「宇宙のブームは想像しにくい」は文として成り立たない。"}, "sentence_index": 6, "correct_answer": "スケール"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "お湯のスケールが低くて、お風呂がすぐ冷めてしまいました。", "explanation": "ここは〈温度〉の意味。お湯の熱さには「温度」を使い、スケールは合わない。"}, {"text": "このコンテストはスケールが高くて、出場者の実力が上がりました。", "explanation": "ここは〈レベル〉の意味。実力の高さには「レベルが高い」と言い、スケールは合わない。"}, {"text": "このエンジンはスケールが強くて、山道も楽に登れます。", "explanation": "ここは〈パワー〉の意味。機械の力の強さには「パワーが強い」と言い、スケールは使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f99bd40-4f88-46e8-ae62-05411a60de0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39462, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この店はスケールを大きくて、驚くほど広いです。", "corrected_sentence": "この店はスケールが大きくて、驚くほど広いです。", "error_description": "誤った形は「スケールを」、正しい形は「スケールが」。「大きい」は主語を「が」で示す形容詞なので、「を」は合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f99bd40-4f88-46e8-ae62-05411a60de0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39462, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この祭りはスケールが高くて、遠くからも人が来ます。", "corrected_sentence": "この祭りはスケールが大きくて、遠くからも人が来ます。", "error_description": "誤った形は「高くて」、正しい形は「大きくて」。「スケール」は大きさの度合いを表すので、「高い」とは組まない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f99bd40-4f88-46e8-ae62-05411a60de0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39463, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「スケールの小さい店」と名詞を修飾する「の」で、文が成り立つ。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示すので、「スケールを小さい店」とは続かない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す「へ」は「小さい」とは続かず、「スケールへ小さい店」は成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点や理由を示すので、「スケールから小さい店」は意味が通らない。"}], "correct_answer": "の", "explanations": {"の": "「スケールの小さい店」と名詞を修飾する「の」で、文が成り立つ。", "を": "「を」は目的語を示すので、「スケールを小さい店」とは続かない。", "へ": "方向を表す「へ」は「小さい」とは続かず、「スケールへ小さい店」は成り立たない。", "から": "「から」は起点や理由を示すので、「スケールから小さい店」は意味が通らない。"}, "error_tags": {"を": "目的語", "へ": "方向", "から": "起点・理由"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f99bd40-4f88-46e8-ae62-05411a60de0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39463, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「小さくする」の対象を示す「を」で、「スケールを小さくして」と続く。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を示すため、「スケールと小さくして」とは続かない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は方向や対象を示すが、「小さくする」の対象には「を」を使うので、「スケールに小さくして」は不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、「スケールへ小さくして」は成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「小さくする」の対象を示す「を」で、「スケールを小さくして」と続く。", "と": "「と」は並列や相手を示すため、「スケールと小さくして」とは続かない。", "に": "「に」は方向や対象を示すが、「小さくする」の対象には「を」を使うので、「スケールに小さくして」は不自然。", "へ": "「へ」は方向を示すので、「スケールへ小さくして」は成り立たない。"}, "error_tags": {"と": "並列・相手", "に": "方向・対象", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f99bd40-4f88-46e8-ae62-05411a60de0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39463, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事の大きさや規模、程度を表す言葉。", "primary_collocate": null, "pronunciation": "すけーる", "ipa": "sɯkeːɾɯ", "syllable_count": 4, "sentences": [{"text": "この工事はスケールが大きいので、完成まで十年かかります。", "target_word": "スケール", "complexity_tier": "T3", "furigana": "この工事[こうじ]はスケールが大[おお]きいので、完成[かんせい]まで十年[じゅうねん]かかります。", "sentence_source": "generated"}, {"text": "スケールの小さい店でも、味は有名店に負けません。", "target_word": "スケール", "complexity_tier": "T3", "furigana": "スケールの小[ちい]さい店[みせ]でも、味[あじ]は有名店[ゆうめいてん]に負[ま]けません。", "sentence_source": "generated"}, {"text": "彼は計画のスケールが大きく、小さなことを気にしません。", "target_word": "スケール", "complexity_tier": "T3", "furigana": "彼[かれ]は計画[けいかく]のスケールが大[おお]きく、小[ちい]さなことを気[き]にしません。", "sentence_source": "generated"}, {"text": "大会のスケールを考えて、広い会場を借りました。", "target_word": "スケール", "complexity_tier": "T3", "furigana": "大会[たいかい]のスケールを考[かんが]えて、広[ひろ]い会場[かいじょう]を借[か]りました。", "sentence_source": "generated"}, {"text": "この町の祭りは、ほかの町とはスケールが違います。", "target_word": "スケール", "complexity_tier": "T3", "furigana": "この町[まち]の祭[まつ]りは、ほかの町[まち]とはスケールが違[ちが]います。", "sentence_source": "generated"}, {"text": "被害のスケールが大きく、多くの助けが必要です。", "target_word": "スケール", "complexity_tier": "T3", "furigana": "被害[ひがい]のスケールが大[おお]きく、多[おお]くの助[たす]けが必要[ひつよう]です。", "sentence_source": "generated"}, {"text": "スケールの大きな話ばかりで、細かい計画がありません。", "target_word": "スケール", "complexity_tier": "T3", "furigana": "スケールの大[おお]きな話[はなし]ばかりで、細[こま]かい計画[けいかく]がありません。", "sentence_source": "generated"}, {"text": "私たちの計画は、まずスケールを小さくして始めます。", "target_word": "スケール", "complexity_tier": "T3", "furigana": "私[わたし]たちの計画[けいかく]は、まずスケールを小[ちい]さくして始[はじ]めます。", "sentence_source": "generated"}, {"text": "あの建物はスケールが大きく、近くで見ると迫力があります。", "target_word": "スケール", "complexity_tier": "T3", "furigana": "あの建物[たてもの]はスケールが大[おお]きく、近[ちか]くで見[み]ると迫力[はくりょく]があります。", "sentence_source": "generated"}, {"text": "国のスケールが違うので、同じ方法は使えません。", "target_word": "スケール", "complexity_tier": "T3", "furigana": "国[くに]のスケールが違[ちが]うので、同[おな]じ方法[ほうほう]は使[つか]えません。", "sentence_source": "generated"}], "morphological_forms": [{"form": "スケール", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "事業・行事・被害などの規模や程度(スケールが違う)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2b6e36a-9597-4ba4-89df-d93b59e9ae30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39463, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "スケール", "is_correct": true, "explanation": "工事の規模の大きさを表し、「スケールが大きいので完成まで十年」と続いて文が成り立つ。"}, {"text": "ヒント", "is_correct": false, "explanation": "手がかりを表す語で、工事の規模の大きさは表せないので「ヒントが大きい」は合わない。"}, {"text": "ボーナス", "is_correct": false, "explanation": "臨時の給与の意味で、工事の大きさや完成までの期間の説明には合わない。"}, {"text": "ルール", "is_correct": false, "explanation": "決まりを表す語で、工事の規模を言う文には当てはまらないので合わない。"}], "explanations": {"スケール": "工事の規模の大きさを表し、「スケールが大きいので完成まで十年」と続いて文が成り立つ。", "ヒント": "手がかりを表す語で、工事の規模の大きさは表せないので「ヒントが大きい」は合わない。", "ボーナス": "臨時の給与の意味で、工事の大きさや完成までの期間の説明には合わない。", "ルール": "決まりを表す語で、工事の規模を言う文には当てはまらないので合わない。"}, "sentence_index": 0, "correct_answer": "スケール"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この部屋はスケールが高くて、洗濯物が乾きません。", "explanation": "ここは〈湿度〉の意味。空気の湿り具合には「湿度」を使い、スケールは合わない。"}, {"text": "この企画は、スケールが多くて準備に三か月かかりました。", "explanation": "ここは〈ボリューム〉の意味。作業量や分量には「多い」と組むボリュームを使い、スケールは合わない。"}, {"text": "この大会は進行のスケールが速くて、観客が追いつけませんでした。", "explanation": "ここは〈テンポ〉の意味。進む速さには「速い」と組むテンポを使い、スケールは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f99bd40-4f88-46e8-ae62-05411a60de0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39463, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "スケール", "is_correct": true, "explanation": "「スケールの大きな話」で規模の大きい計画を指し、細かい計画と対比される文に合う。"}, {"text": "ペース", "is_correct": false, "explanation": "進む速さを表す語で、「ペースの大きな話」とは言わないので合わない。"}, {"text": "ノルマ", "is_correct": false, "explanation": "割り当てられた仕事量の意味で、話の規模を表す語ではないので合わない。"}, {"text": "ブーム", "is_correct": false, "explanation": "一時的な流行の意味で、「ブームの大きな話」は文として成り立たない。"}], "explanations": {"スケール": "「スケールの大きな話」で規模の大きい計画を指し、細かい計画と対比される文に合う。", "ペース": "進む速さを表す語で、「ペースの大きな話」とは言わないので合わない。", "ノルマ": "割り当てられた仕事量の意味で、話の規模を表す語ではないので合わない。", "ブーム": "一時的な流行の意味で、「ブームの大きな話」は文として成り立たない。"}, "sentence_index": 6, "correct_answer": "スケール"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "このコーヒーはスケールが強くて、一杯で目が覚めます。", "explanation": "ここは〈香り〉の意味。香りの強さには「香り」を使い、スケールは合わない。"}, {"text": "この宿はスケールが高く、料金も高めです。", "explanation": "ここは〈グレード〉の意味。品質や等級には「高い」と組むグレードを使い、スケールは合わない。"}, {"text": "この車はスケールが速く、高速道路でも安心して走れます。", "explanation": "ここは〈スピード〉の意味。速さには「速い」と組むスピードを使い、スケールは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f99bd40-4f88-46e8-ae62-05411a60de0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39463, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この計画はスケールを大きく、関わる人も多くなりました。", "corrected_sentence": "この計画はスケールが大きく、関わる人も多くなりました。", "error_description": "誤った形は「スケールを」、正しい形は「スケールが」。「大きい」の主語は「が」で示すので、「を」は合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f99bd40-4f88-46e8-ae62-05411a60de0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39463, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この祭りはスケールが深くて、町の人が大勢集まります。", "corrected_sentence": "この祭りはスケールが大きくて、町の人が大勢集まります。", "error_description": "誤った形は「深くて」、正しい形は「大きくて」。「スケール」は大きさを表すので、「深い」とは組まない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f99bd40-4f88-46e8-ae62-05411a60de0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
