INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39464, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "function", "definition": "「また」という言葉。もういちど、同じことがおこるときにつかう。", "primary_collocate": null, "pronunciation": "また", "ipa": "mata", "syllable_count": 2, "sentences": [{"text": "昨日の夜も、又雨が降りました。", "target_word": "又", "complexity_tier": "T3", "furigana": "きのうのよるも、またあめがふりました。", "sentence_source": "generated"}, {"text": "明日、又ここで会いましょう。", "target_word": "又", "complexity_tier": "T3", "furigana": "あした、またここであいましょう。", "sentence_source": "generated"}, {"text": "電車が遅れて、今日も又遅刻しました。", "target_word": "又", "complexity_tier": "T3", "furigana": "でんしゃがおくれて、きょうもまたちこくしました。", "sentence_source": "generated"}, {"text": "弟が又コップを割ってしまいました。", "target_word": "又", "complexity_tier": "T3", "furigana": "おとうとがまたコップをわってしまいました。", "sentence_source": "generated"}, {"text": "財布を忘れて、又家に取りに戻りました。", "target_word": "又", "complexity_tier": "T3", "furigana": "さいふをわすれて、またいえにとりにもどりました。", "sentence_source": "generated"}, {"text": "一度失敗しても、又やってみるつもりです。", "target_word": "又", "complexity_tier": "T3", "furigana": "いちどしっぱいしても、またやってみるつもりです。", "sentence_source": "generated"}, {"text": "先生に注意されたのに、彼は又宿題を忘れました。", "target_word": "又", "complexity_tier": "T3", "furigana": "せんせいにちゅういされたのに、かれはまたしゅくだいをわすれました。", "sentence_source": "generated"}, {"text": "春になると、庭に又花が咲きます。", "target_word": "又", "complexity_tier": "T3", "furigana": "はるになると、にわにまたはながさきます。", "sentence_source": "generated"}, {"text": "電話が切れたので、五分後に又かけました。", "target_word": "又", "complexity_tier": "T3", "furigana": "でんわがきれたので、ごふんごにまたかけました。", "sentence_source": "generated"}, {"text": "次の休みに、又この海へ来たいです。", "target_word": "又", "complexity_tier": "T3", "furigana": "つぎのやすみに、またこのうみへきたいです。", "sentence_source": "generated"}], "morphological_forms": [{"form": "又", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "同じことがもう一度くり返される「再び」の意味の副詞", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f839c227-2f16-4265-b473-70b89a9b588c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39464, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "又", "is_correct": true, "explanation": "「もういちど」の意味で、同じことが再び起きたことを示す。「雨がまた降った」と合う。"}, {"text": "決して", "is_correct": false, "explanation": "「決して〜ない」と否定と結びつく副詞。肯定の「降りました」には入らない。"}, {"text": "少しも", "is_correct": false, "explanation": "「少しも〜ない」と否定を伴う。肯定の文には入らない。"}, {"text": "ぐっすり", "is_correct": false, "explanation": "眠りが深いさまを表す副詞。雨が降る文では意味が通らない。"}], "explanations": {"又": "「もういちど」の意味で、同じことが再び起きたことを示す。「雨がまた降った」と合う。", "決して": "「決して〜ない」と否定と結びつく副詞。肯定の「降りました」には入らない。", "少しも": "「少しも〜ない」と否定を伴う。肯定の文には入らない。", "ぐっすり": "眠りが深いさまを表す副詞。雨が降る文では意味が通らない。"}, "sentence_index": 0, "correct_answer": "又"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "駅までバス又は電車で行きましょう。", "explanation": "ここは「または」の意味の又は。「もういちど」の意味の又では、二つのうちどちらかを選ぶ文は作れない。"}, {"text": "彼は背が高く、又料理も上手です。", "explanation": "ここは〈その上〉と同じ「加える」の意味。「もういちど」の又では、人の長所を並べる文に合わない。"}, {"text": "これは又聞きの話なので、確かかどうか分かりません。", "explanation": "「又聞き」は人づてに聞くという別の語。「もういちど」の副詞の又とは別の言葉で、ここに入れると文が成り立たない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d645761-a470-43e1-a068-67a54f16899d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39464, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "又", "is_correct": true, "explanation": "「もういちど」の意味で、また宿題を忘れたことを示す。"}, {"text": "絶対に", "is_correct": false, "explanation": "「絶対に〜ない」と否定と結びつく。肯定の「忘れました」とは合わない。"}, {"text": "直ちに", "is_correct": false, "explanation": "「すぐに」という硬い表現で、命令や報告に使う。宿題を忘れる文には合わない。"}, {"text": "ろくに", "is_correct": false, "explanation": "「ろくに〜ない」と否定を伴う。肯定の文には入らない。"}], "explanations": {"又": "「もういちど」の意味で、また宿題を忘れたことを示す。", "絶対に": "「絶対に〜ない」と否定と結びつく。肯定の「忘れました」とは合わない。", "直ちに": "「すぐに」という硬い表現で、命令や報告に使う。宿題を忘れる文には合わない。", "ろくに": "「ろくに〜ない」と否定を伴う。肯定の文には入らない。"}, "sentence_index": 6, "correct_answer": "又"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この作家には又の名があり、ペンネームで作品を出しています。", "explanation": "「又の名」は別の呼び名を表す別の語。「もういちど」の副詞の又では、呼び名の説明にはならない。"}, {"text": "今日は無理なので、又の機会にお願いします。", "explanation": "「又の機会」は〈次の機会〉を表す固定した言い回し。「もういちど」の副詞の又とは別の用法で、ここでは意味が違う。"}, {"text": "雨が降り、又風も強くなりました。", "explanation": "ここは〈おまけに〉の意味で、風も加わるという加算を表す。「もういちど」の又では同じことの繰り返しを表すため、この文の意味にならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d645761-a470-43e1-a068-67a54f16899d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39464, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "昨日の夜、雨が又降るました。", "corrected_sentence": "昨日の夜、雨が又降りました。", "error_description": "「降るました」は誤った活用。動詞「降る」の丁寧形は「降ります」なので、正しくは「雨が又降りました」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d645761-a470-43e1-a068-67a54f16899d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39464, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "来週、又の会いましょう。", "corrected_sentence": "来週、又会いましょう。", "error_description": "副詞の又の後に「の」を置いている。又は動詞に直接かかるので「の」は不要で、正しくは「又会いましょう」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d645761-a470-43e1-a068-67a54f16899d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
