INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39465, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "function", "definition": "「又（また）」は、前に述べたことに加えて、もう一つの事柄があることを示す副詞です。", "primary_collocate": null, "pronunciation": "また", "ipa": "mata", "syllable_count": 2, "sentences": [{"text": "彼は医者であり、又作家でもあります。", "target_word": "又", "complexity_tier": "T3", "furigana": "かれはいしゃであり、またさっかでもあります。", "sentence_source": "generated"}, {"text": "兄は歌が上手で、弟も又ピアノが得意です。", "target_word": "又", "complexity_tier": "T3", "furigana": "あにはうたがじょうずで、おとうともまたピアノがとくいです。", "sentence_source": "generated"}, {"text": "この店は安い。又、店員も親切です。", "target_word": "又", "complexity_tier": "T3", "furigana": "このみせはやすい。また、てんいんもしんせつです。", "sentence_source": "generated"}, {"text": "京都は古い寺が多く、又、食べ物もおいしい町です。", "target_word": "又", "complexity_tier": "T3", "furigana": "きょうとはふるいてらがおおく、また、たべものもおいしいまちです。", "sentence_source": "generated"}, {"text": "母は料理が上手で、父も又よく台所に立ちます。", "target_word": "又", "complexity_tier": "T3", "furigana": "はははりょうりがじょうずで、ちちもまたよくだいどころにたちます。", "sentence_source": "generated"}, {"text": "この図書館は静かで、又広いので、勉強に向いています。", "target_word": "又", "complexity_tier": "T3", "furigana": "このとしょかんはしずかで、またひろいので、べんきょうにむいています。", "sentence_source": "generated"}, {"text": "山田さんは親切で、又まじめな人です。", "target_word": "又", "complexity_tier": "T3", "furigana": "やまださんはしんせつで、またまじめなひとです。", "sentence_source": "generated"}, {"text": "駅から近く、又家賃も安いので、この部屋に決めました。", "target_word": "又", "complexity_tier": "T3", "furigana": "えきからちかく、またやちんもやすいので、このへやにきめました。", "sentence_source": "generated"}, {"text": "田中さんも来ます。又、鈴木さんも来る予定です。", "target_word": "又", "complexity_tier": "T3", "furigana": "たなかさんもきます。また、すずきさんもくるよていです。", "sentence_source": "generated"}, {"text": "この町には大きな公園があり、又美しい川も流れています。", "target_word": "又", "complexity_tier": "T3", "furigana": "このまちにはおおきなこうえんがあり、またうつくしいかわもながれています。", "sentence_source": "generated"}], "morphological_forms": [{"form": "又", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "前に述べたことに別の事柄をつけ加える「その上・さらに」の意味の副詞", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f839c227-2f16-4265-b473-70b89a9b588c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39465, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "又", "is_correct": true, "explanation": "「もう一つ加える」の意味で、医者であることに作家であることを加えている。"}, {"text": "必ずしも", "is_correct": false, "explanation": "「必ずしも〜ない」と否定を伴う。肯定の「でもあります」とは合わない。"}, {"text": "一向に", "is_correct": false, "explanation": "「一向に〜ない」と否定を伴う。肯定の文には入らない。"}, {"text": "ぐっすり", "is_correct": false, "explanation": "眠りの深さを表す副詞。職業を並べる文では意味が通らない。"}], "explanations": {"又": "「もう一つ加える」の意味で、医者であることに作家であることを加えている。", "必ずしも": "「必ずしも〜ない」と否定を伴う。肯定の「でもあります」とは合わない。", "一向に": "「一向に〜ない」と否定を伴う。肯定の文には入らない。", "ぐっすり": "眠りの深さを表す副詞。職業を並べる文では意味が通らない。"}, "sentence_index": 0, "correct_answer": "又"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この小説には又の名があり、『月の影』と呼ばれています。", "explanation": "ここは〈別の呼び名〉を表す又の名。〈前に加える〉の又では、呼び名の説明にはならない。"}, {"text": "彼は雨の中、又走り出した。", "explanation": "ここは〈再び〉の意味。前のことに加えるのではなく繰り返すので、〈加える〉の又では意味が違う。"}, {"text": "ペン又は鉛筆で書いてください。", "explanation": "ここは〈または〉の意味。二つのうち一つを選ぶ文で、〈加える〉の又とは別の用法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d645761-a470-43e1-a068-67a54f16899d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39465, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "又", "is_correct": true, "explanation": "「もう一つ加える」の意味で、親切に加えてまじめな性格も加えている。"}, {"text": "少しも", "is_correct": false, "explanation": "「少しも〜ない」と否定を伴う。肯定の「まじめな人です」とは合わない。"}, {"text": "今にも", "is_correct": false, "explanation": "「今にも〜しそうだ」という切迫した表現。性格を表す文には入らない。"}, {"text": "ろくに", "is_correct": false, "explanation": "「ろくに〜ない」と否定を伴う。性格を表す文には合わない。"}], "explanations": {"又": "「もう一つ加える」の意味で、親切に加えてまじめな性格も加えている。", "少しも": "「少しも〜ない」と否定を伴う。肯定の「まじめな人です」とは合わない。", "今にも": "「今にも〜しそうだ」という切迫した表現。性格を表す文には入らない。", "ろくに": "「ろくに〜ない」と否定を伴う。性格を表す文には合わない。"}, "sentence_index": 6, "correct_answer": "又"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "これは又聞きですが、この町はとても静かだそうです。", "explanation": "「又聞き」は人づてに聞くという別の語。〈加える〉の又では、伝聞の文は成り立たない。"}, {"text": "その件は又話し合いましょう。", "explanation": "ここは〈改めて〉の意味。〈加える〉ではなく、もう一度話し合うという繰り返しを表すので、この文の意味とは違う。"}, {"text": "この件は又の日に相談しましょう。", "explanation": "「又の日」は〈別の日〉を表す言い回し。〈加える〉の又とは違う意味で、この文では別の用法として使われている。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d645761-a470-43e1-a068-67a54f16899d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39465, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は画家であり、又作家でもあるます。", "corrected_sentence": "彼は画家であり、又作家でもあります。", "error_description": "「あるます」は誤った形。「ある」の丁寧形は「あります」なので、正しくは「又作家でもあります」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d645761-a470-43e1-a068-67a54f16899d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39465, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この店は安く、又は店員も親切です。", "corrected_sentence": "この店は安く、又店員も親切です。", "error_description": "又の後に「は」が続くと「または」の意味になる。ここは加える意味の又なので「は」は不要で、正しくは「又店員も」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d645761-a470-43e1-a068-67a54f16899d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39466, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「により」の「に」で、台頭を原因として示す。"}, {"text": "が", "is_correct": false, "explanation": "主語を示すが、「台頭が」の後に「より」が続くと文が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "原因の「で」だが、「台頭で」の後に「より」は続かず、「により」の形にならない。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示すが、「台頭を」の後に「より」が続くと文が壊れる。"}], "correct_answer": "に", "explanations": {"に": "「により」の「に」で、台頭を原因として示す。", "が": "主語を示すが、「台頭が」の後に「より」が続くと文が成り立たない。", "で": "原因の「で」だが、「台頭で」の後に「より」は続かず、「により」の形にならない。", "を": "目的語を示すが、「台頭を」の後に「より」が続くと文が壊れる。"}, "error_tags": {"が": "主語", "で": "原因（より と続かない）", "を": "目的語"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'afc7ec28-a387-4bb1-bfd6-5477845bd053') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39466, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「快く思う」は対象を「を」で取るので、「彼の台頭を」が正しい。"}, {"text": "と", "is_correct": false, "explanation": "「台頭と」では並列や引用になり、「快く思う」の対象にならない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す助詞で、「快く思う」の対象を表せない。"}, {"text": "に", "is_correct": false, "explanation": "「快く思う」は対象を「に」で取らないため、文が不自然になる。"}], "correct_answer": "を", "explanations": {"を": "「快く思う」は対象を「を」で取るので、「彼の台頭を」が正しい。", "と": "「台頭と」では並列や引用になり、「快く思う」の対象にならない。", "へ": "方向を示す助詞で、「快く思う」の対象を表せない。", "に": "「快く思う」は対象を「に」で取らないため、文が不自然になる。"}, "error_tags": {"と": "並列・引用（不自然）", "へ": "方向（対象にならない）", "に": "対象（快く思うは を）"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'afc7ec28-a387-4bb1-bfd6-5477845bd053') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39466, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "何かが新しく力を持つようになること。", "primary_collocate": null, "pronunciation": "たいとう", "ipa": "taitoː", "syllable_count": 4, "sentences": [{"text": "新しい会社の台頭で、古い店は客を失った。", "target_word": "台頭", "complexity_tier": "T3", "furigana": "新(あたら)しい会社(かいしゃ)の台頭(たいとう)で、古(ふる)い店(みせ)は客(きゃく)を失(うしな)った。", "sentence_source": "generated"}, {"text": "若い選手の台頭により、チームの雰囲気が変わった。", "target_word": "台頭", "complexity_tier": "T3", "furigana": "若(わか)い選手(せんしゅ)の台頭(たいとう)により、チームの雰囲気(ふんいき)が変(か)わった。", "sentence_source": "generated"}, {"text": "中小企業の台頭が、業界の勢力図を塗り替えた。", "target_word": "台頭", "complexity_tier": "T3", "furigana": "中小企業(ちゅうしょうきぎょう)の台頭(たいとう)が、業界(ぎょうかい)の勢力図(せいりょくず)を塗(ぬ)り替(か)えた。", "sentence_source": "generated"}, {"text": "新しい国の台頭を、周りの国々は注意深く見ている。", "target_word": "台頭", "complexity_tier": "T3", "furigana": "新(あたら)しい国(くに)の台頭(たいとう)を、周(まわ)りの国々(くにぐに)は注意深(ちゅういぶか)く見(み)ている。", "sentence_source": "generated"}, {"text": "スマートフォンの台頭によって、携帯電話の市場は大きく変わった。", "target_word": "台頭", "complexity_tier": "T3", "furigana": "スマートフォンの台頭(たいとう)によって、携帯電話(けいたいでんわ)の市場(しじょう)は大(おお)きく変(か)わった。", "sentence_source": "generated"}, {"text": "若手の台頭が目立つ一方で、ベテランの出番は減っている。", "target_word": "台頭", "complexity_tier": "T3", "furigana": "若手(わかて)の台頭(たいとう)が目立(めだ)つ一方(いっぽう)で、ベテランの出番(でばん)は減(へ)っている。", "sentence_source": "generated"}, {"text": "ネット通販の台頭は、街の小さな書店に大きな打撃を与えた。", "target_word": "台頭", "complexity_tier": "T3", "furigana": "ネット通販(つうはん)の台頭(たいとう)は、街(まち)の小(ちい)さな書店(しょてん)に大(おお)きな打撃(だげき)を与(あた)えた。", "sentence_source": "generated"}, {"text": "彼の台頭を快く思わない人も、社内には少なくなかった。", "target_word": "台頭", "complexity_tier": "T3", "furigana": "彼(かれ)の台頭(たいとう)を快(こころよ)く思(おも)わない人(ひと)も、社内(しゃない)には少(すく)なくなかった。", "sentence_source": "generated"}, {"text": "新興国の台頭は、世界経済の流れを大きく変えつつある。", "target_word": "台頭", "complexity_tier": "T3", "furigana": "新興国(しんこうこく)の台頭(たいとう)は、世界経済(せかいけいざい)の流(なが)れを大(おお)きく変(か)えつつある。", "sentence_source": "generated"}, {"text": "新人作家の台頭に、文学界は活気づいている。", "target_word": "台頭", "complexity_tier": "T3", "furigana": "新人作家(しんじんさっか)の台頭(たいとう)に、文学界(ぶんがくかい)は活気(かっき)づいている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "台頭する", "label": "dictionary form (suru verb)"}, {"form": "台頭した", "label": "past"}, {"form": "台頭して", "label": "te-form"}, {"form": "台頭しない", "label": "negative"}], "register": "neutral", "sense_fingerprint": "新しい人や会社や国が力を持ち始めること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6c39368-b1a1-4be5-ad73-c3324aee30fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39466, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "台頭", "is_correct": true, "explanation": "「新しい会社が力を持ち始める」の意味で、古い店が客を失う原因として自然に入る。"}, {"text": "悲鳴", "is_correct": false, "explanation": "叫び声の意味で、会社の勢いを表す文脈には入らない。"}, {"text": "休憩", "is_correct": false, "explanation": "仕事を一時的に休む意味で、店が客を失う原因にはならない。"}, {"text": "錆", "is_correct": false, "explanation": "金属の劣化を表す語で、会社を主語にする文には使えない。"}], "explanations": {"台頭": "「新しい会社が力を持ち始める」の意味で、古い店が客を失う原因として自然に入る。", "悲鳴": "叫び声の意味で、会社の勢いを表す文脈には入らない。", "休憩": "仕事を一時的に休む意味で、店が客を失う原因にはならない。", "錆": "金属の劣化を表す語で、会社を主語にする文には使えない。"}, "sentence_index": 0, "correct_answer": "台頭"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "物価の台頭で、家計の負担が増えた。", "explanation": "ここは〈上昇〉の意味。台頭は人や勢力が新しく力を持つことに使い、物価には使わない。"}, {"text": "新しい命の台頭で、家族全員が笑顔になった。", "explanation": "ここは〈誕生〉の意味。台頭は力を持つ人や勢力に使うので、命の誕生には合わない。"}, {"text": "来客数の台頭で、店は大忙しになった。", "explanation": "ここは〈増加〉の意味。台頭は新しく力を持つことで、来客数の増加を表すには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'afc7ec28-a387-4bb1-bfd6-5477845bd053') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39466, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "台頭", "is_correct": true, "explanation": "「ネット通販が力を持ち始めた」の意味で、書店に打撃を与えた主語として自然。"}, {"text": "発熱", "is_correct": false, "explanation": "体温が上がる意味で、通販を主語にする文には入らない。"}, {"text": "眠気", "is_correct": false, "explanation": "眠くなる感覚を表し、ここでは文が成り立たない。"}, {"text": "湿気", "is_correct": false, "explanation": "空気中の水分を指し、通販の話には使えない。"}], "explanations": {"台頭": "「ネット通販が力を持ち始めた」の意味で、書店に打撃を与えた主語として自然。", "発熱": "体温が上がる意味で、通販を主語にする文には入らない。", "眠気": "眠くなる感覚を表し、ここでは文が成り立たない。", "湿気": "空気中の水分を指し、通販の話には使えない。"}, "sentence_index": 6, "correct_answer": "台頭"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大雨の台頭で、道が水びたしになった。", "explanation": "ここは〈降る〉の意味。台頭は勢力や考えが力を持つことで、雨が降る現象には使わない。"}, {"text": "新しい橋の台頭で、町の交通が便利になった。", "explanation": "ここは〈完成〉の意味。台頭は人や勢力に使い、橋の完成には合わない。"}, {"text": "新しい工事の台頭で、道は通れなくなった。", "explanation": "ここは〈工事の開始〉の意味。台頭は力を持つ人や勢力に使い、工事の始まりには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'afc7ec28-a387-4bb1-bfd6-5477845bd053') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39466, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ネット企業の台頭を、街の店は客を失った。", "corrected_sentence": "ネット企業の台頭で、街の店は客を失った。", "error_description": "原因を示す「で」が正しい。「台頭を」と「を」を使うと目的語になり、「客を失った」とつながらない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'afc7ec28-a387-4bb1-bfd6-5477845bd053') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39466, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "若手作家が台頭を始めて、文学界は活気づいている。", "corrected_sentence": "若手作家が台頭し始めて、文学界は活気づいている。", "error_description": "「台頭し始める」が正しい形。「台頭を始める」は「台頭」を目的語のように扱う誤りで、動詞の連用形「し」が必要。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'afc7ec28-a387-4bb1-bfd6-5477845bd053') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39467, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'afc7ec28-a387-4bb1-bfd6-5477845bd053') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39467, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「許す」は対象を「を」で取るので、「彼らの台頭を許した」が正しい。"}, {"text": "が", "is_correct": false, "explanation": "主語を示すが、「許す」の目的語が欠けて文が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "手段や原因を示す「で」では、「許す」の対象を表せない。"}, {"text": "に", "is_correct": false, "explanation": "「台頭に許した」では対象が結びつかず、文が不自然になる。"}], "correct_answer": "を", "explanations": {"を": "「許す」は対象を「を」で取るので、「彼らの台頭を許した」が正しい。", "が": "主語を示すが、「許す」の目的語が欠けて文が成り立たない。", "で": "手段や原因を示す「で」では、「許す」の対象を表せない。", "に": "「台頭に許した」では対象が結びつかず、文が不自然になる。"}, "error_tags": {"が": "主語（許すの目的語が欠ける）", "で": "手段・原因（対象にならない）", "に": "方向・相手（不自然）"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'afc7ec28-a387-4bb1-bfd6-5477845bd053') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39467, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ある勢力や考え方などが、それまでよりも強くなって、目立つ立場になること。", "primary_collocate": null, "pronunciation": "たいとう", "ipa": "taitoː", "syllable_count": 4, "sentences": [{"text": "十九世紀には、民主主義の考え方が台頭してきた。", "target_word": "台頭", "complexity_tier": "T3", "furigana": "十九世紀(じゅうきゅうせいき)には、民主主義(みんしゅしゅぎ)の考(かんが)え方(かた)が台頭(たいとう)してきた。", "sentence_source": "generated"}, {"text": "政治の世界で、新しい勢力が台頭した。", "target_word": "台頭", "complexity_tier": "T3", "furigana": "政治(せいじ)の世界(せかい)で、新(あたら)しい勢力(せいりょく)が台頭(たいとう)した。", "sentence_source": "generated"}, {"text": "不況が続くと、極端な意見が台頭しやすくなる。", "target_word": "台頭", "complexity_tier": "T3", "furigana": "不況(ふきょう)が続(つづ)くと、極端(きょくたん)な意見(いけん)が台頭(たいとう)しやすくなる。", "sentence_source": "generated"}, {"text": "戦国時代に、地方の武将たちが次々に台頭した。", "target_word": "台頭", "complexity_tier": "T3", "furigana": "戦国時代(せんごくじだい)に、地方(ちほう)の武将(ぶしょう)たちが次々(つぎつぎ)に台頭(たいとう)した。", "sentence_source": "generated"}, {"text": "環境を守ろうという考えが台頭し、企業の姿勢も変わった。", "target_word": "台頭", "complexity_tier": "T3", "furigana": "環境(かんきょう)を守(まも)ろうという考(かんが)えが台頭(たいとう)し、企業(きぎょう)の姿勢(しせい)も変(か)わった。", "sentence_source": "generated"}, {"text": "長い間続いた古い体制は弱まり、新しい階層が台頭した。", "target_word": "台頭", "complexity_tier": "T3", "furigana": "長(なが)い間(あいだ)続(つづ)いた古(ふる)い体制(たいせい)は弱(よわ)まり、新(あたら)しい階層(かいそう)が台頭(たいとう)した。", "sentence_source": "generated"}, {"text": "海外では、自国を優先する政党が台頭している。", "target_word": "台頭", "complexity_tier": "T3", "furigana": "海外(かいがい)では、自国(じこく)を優先(ゆうせん)する政党(せいとう)が台頭(たいとう)している。", "sentence_source": "generated"}, {"text": "彼らの台頭を許したのは、政府の対応の遅れだった。", "target_word": "台頭", "complexity_tier": "T3", "furigana": "彼(かれ)らの台頭(たいとう)を許(ゆる)したのは、政府(せいふ)の対応(たいおう)の遅(おく)れだった。", "sentence_source": "generated"}, {"text": "平安時代の終わりごろ、武士が台頭して政治の中心に立った。", "target_word": "台頭", "complexity_tier": "T3", "furigana": "平安時代(へいあんじだい)の終(お)わりごろ、武士(ぶし)が台頭(たいとう)して政治(せいじ)の中心(ちゅうしん)に立(た)った。", "sentence_source": "generated"}, {"text": "若い世代の価値観が台頭して、職場のルールも見直された。", "target_word": "台頭", "complexity_tier": "T3", "furigana": "若(わか)い世代(せだい)の価値観(かちかん)が台頭(たいとう)して、職場(しょくば)のルールも見直(みなお)された。", "sentence_source": "generated"}], "morphological_forms": [{"form": "台頭する", "label": "dictionary form (suru verb)"}, {"form": "台頭した", "label": "past"}, {"form": "台頭して", "label": "te-form"}, {"form": "台頭しやすい", "label": "tai-type adjective (easy to)"}], "register": "formal", "sense_fingerprint": "勢力や思想が強まって表に出てくること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6c39368-b1a1-4be5-ad73-c3324aee30fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39467, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "台頭", "is_correct": true, "explanation": "考えが強まって表に現れてくる意味で、「してきた」に合う。"}, {"text": "送付", "is_correct": false, "explanation": "書類などを送る意味で、考え方を主語にはできない。"}, {"text": "出荷", "is_correct": false, "explanation": "商品を送り出す意味で、考え方には使えない。"}, {"text": "配達", "is_correct": false, "explanation": "物を届ける意味で、考え方が届くという文は成り立たない。"}], "explanations": {"台頭": "考えが強まって表に現れてくる意味で、「してきた」に合う。", "送付": "書類などを送る意味で、考え方を主語にはできない。", "出荷": "商品を送り出す意味で、考え方には使えない。", "配達": "物を届ける意味で、考え方が届くという文は成り立たない。"}, "sentence_index": 0, "correct_answer": "台頭"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "新しい機械が工場に台頭して、作業が楽になった。", "explanation": "ここは〈導入〉の意味。台頭は勢力や思想が表に出てくることで、機械の導入には合わない。"}, {"text": "地震が台頭して、町の人々は避難した。", "explanation": "ここは〈発生〉の意味。台頭は勢力や考えに使い、地震の発生には使わない。"}, {"text": "新しいビルが台頭して、通りは夜も明るい。", "explanation": "ここは〈完成〉の意味。台頭は勢力や思想に使い、建物の完成には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'afc7ec28-a387-4bb1-bfd6-5477845bd053') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39467, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "台頭", "is_correct": true, "explanation": "政党が勢力を強めて表に出てくる意味で、「している」に合う。"}, {"text": "散歩", "is_correct": false, "explanation": "歩いて出かける意味で、政党を主語にする文には入らない。"}, {"text": "採掘", "is_correct": false, "explanation": "地下の資源を掘り出す意味で、政党の話には使えない。"}, {"text": "洗濯", "is_correct": false, "explanation": "衣類を洗う意味で、政党を主語にすると文が成り立たない。"}], "explanations": {"台頭": "政党が勢力を強めて表に出てくる意味で、「している」に合う。", "散歩": "歩いて出かける意味で、政党を主語にする文には入らない。", "採掘": "地下の資源を掘り出す意味で、政党の話には使えない。", "洗濯": "衣類を洗う意味で、政党を主語にすると文が成り立たない。"}, "sentence_index": 6, "correct_answer": "台頭"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大会が台頭して、多くの選手が集まった。", "explanation": "ここは〈開催〉の意味。台頭は勢力や思想に使い、大会を開く意味では使わない。"}, {"text": "大量の燃料が台頭して、資源が減った。", "explanation": "ここは〈消費〉の意味。台頭は人や勢力が力を持つことで、燃料の消費とは合わない。"}, {"text": "熱が台頭して、子どもは寝込んだ。", "explanation": "ここは〈上がる〉の意味。台頭は勢力や思想が目立つ立場になることで、熱が上がる意味には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'afc7ec28-a387-4bb1-bfd6-5477845bd053') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39467, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "地方の新しい勢力の台頭を、政府は手を焼いた。", "corrected_sentence": "地方の新しい勢力の台頭に、政府は手を焼いた。", "error_description": "「手を焼く」の原因は「に」で示す。「台頭を」では目的語になり、「手を焼いた」と結びつかない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'afc7ec28-a387-4bb1-bfd6-5477845bd053') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39467, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "新しい勢力が台頭て、政府は慌てた。", "corrected_sentence": "新しい勢力が台頭して、政府は慌てた。", "error_description": "て形は「台頭して」。「台頭て」は連用形の「し」が抜けた誤りで、「して」の形が必要。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'afc7ec28-a387-4bb1-bfd6-5477845bd053') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39470, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「置く」の場所を示す「に」。中央がテーブルを置く先になる。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す。「中央がテーブルを置きました」となり、文の主語として合わない。"}, {"text": "と", "is_correct": false, "explanation": "並列や相手を示す。「中央とテーブルを置いた」では文が成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示す。すでに「テーブルを」があるので、ここに「を」は重なって入らない。"}], "correct_answer": "に", "explanations": {"に": "「置く」の場所を示す「に」。中央がテーブルを置く先になる。", "が": "主語を示す。「中央がテーブルを置きました」となり、文の主語として合わない。", "と": "並列や相手を示す。「中央とテーブルを置いた」では文が成り立たない。", "を": "目的語を示す。すでに「テーブルを」があるので、ここに「を」は重なって入らない。"}, "error_tags": {"が": "主語", "と": "並列", "を": "目的語"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d645761-a470-43e1-a068-67a54f16899d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39470, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「のせる」の着点を示す「に」。中央にいちごを置く意味になる。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す。「ケーキの中央がいちごをのせて」では中央が動作の主体になり、文が成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "比較を示す。置く場所を表す文には入らない。"}, {"text": "の", "is_correct": false, "explanation": "名詞をつなぐ。「中央のいちご」となり、置く場所を示せない。"}], "correct_answer": "に", "explanations": {"に": "「のせる」の着点を示す「に」。中央にいちごを置く意味になる。", "が": "主語を示す。「ケーキの中央がいちごをのせて」では中央が動作の主体になり、文が成り立たない。", "より": "比較を示す。置く場所を表す文には入らない。", "の": "名詞をつなぐ。「中央のいちご」となり、置く場所を示せない。"}, "error_tags": {"が": "主語", "より": "比較", "の": "修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d645761-a470-43e1-a068-67a54f16899d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39470, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "まんなかのこと。", "primary_collocate": null, "pronunciation": "ちゅうおう", "ipa": "tɕɯːoː", "syllable_count": 4, "sentences": [{"text": "広場の中央に、大きな木が立っています。", "target_word": "中央", "complexity_tier": "T3", "furigana": "ひろばのちゅうおうに、おおきなきがたっています。", "sentence_source": "generated"}, {"text": "部屋の中央にテーブルを置きました。", "target_word": "中央", "complexity_tier": "T3", "furigana": "へやのちゅうおうにテーブルをおきました。", "sentence_source": "generated"}, {"text": "地図の中央に赤い印がついています。", "target_word": "中央", "complexity_tier": "T3", "furigana": "ちずのちゅうおうにあかいしるしがついています。", "sentence_source": "generated"}, {"text": "町の中央には駅があり、人が多いです。", "target_word": "中央", "complexity_tier": "T3", "furigana": "まちのちゅうおうにはえきがあり、ひとがおおいです。", "sentence_source": "generated"}, {"text": "池の中央で、白い鳥が泳いでいます。", "target_word": "中央", "complexity_tier": "T3", "furigana": "いけのちゅうおうで、しろいとりがおよいでいます。", "sentence_source": "generated"}, {"text": "舞台の中央に立つと、緊張で声が出ませんでした。", "target_word": "中央", "complexity_tier": "T3", "furigana": "ぶたいのちゅうおうにたつと、きんちょうでこえがでませんでした。", "sentence_source": "generated"}, {"text": "道路の中央に線が引いてあるので、車は左を走ります。", "target_word": "中央", "complexity_tier": "T3", "furigana": "どうろのちゅうおうにせんがひいてあるので、くるまはひだりをはしります。", "sentence_source": "generated"}, {"text": "ケーキの中央にいちごをのせてください。", "target_word": "中央", "complexity_tier": "T3", "furigana": "ケーキのちゅうおうにいちごをのせてください。", "sentence_source": "generated"}, {"text": "日本の中央にある山々は、冬に雪が積もります。", "target_word": "中央", "complexity_tier": "T3", "furigana": "にほんのちゅうおうにあるやまやまは、ふゆにゆきがつもります。", "sentence_source": "generated"}, {"text": "国の中央を流れる川が、この地方を豊かにしています。", "target_word": "中央", "complexity_tier": "T3", "furigana": "くにのちゅうおうをながれるかわが、このちほうをゆたかにしています。", "sentence_source": "generated"}], "morphological_forms": [{"form": "中央", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "場所や物の真ん中にあたる位置", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f839c227-2f16-4265-b473-70b89a9b588c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39470, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "中央", "is_correct": true, "explanation": "「広場の真ん中」を表し、大きな木が立つ位置として合う。"}, {"text": "天井", "is_correct": false, "explanation": "建物の内側の上面を表す。屋外の広場には合わない。"}, {"text": "屋根", "is_correct": false, "explanation": "建物を覆うものを表す。広場の木の位置としては不自然。"}, {"text": "床", "is_correct": false, "explanation": "建物の底面を表す。屋外の広場には合わない。"}], "explanations": {"中央": "「広場の真ん中」を表し、大きな木が立つ位置として合う。", "天井": "建物の内側の上面を表す。屋外の広場には合わない。", "屋根": "建物を覆うものを表す。広場の木の位置としては不自然。", "床": "建物の底面を表す。屋外の広場には合わない。"}, "sentence_index": 0, "correct_answer": "中央"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は仕事で中央に出ることが多いです。", "explanation": "ここは〈首都・中央政府〉の意味。場所のまんなかを表す中央ではなく、都市や政府の中心機関を指すので、この文の意味とは違う。"}, {"text": "会議の中央は予算の話でした。", "explanation": "ここは〈中心〉の意味。話題の核は中心と言い、場所のまんなかを表す中央は使わない。"}, {"text": "中央線で新宿へ行きました。", "explanation": "「中央線」は鉄道路線の名前。場所のまんなかを表す中央とは別の語で、ここでは意味が違う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d645761-a470-43e1-a068-67a54f16899d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39470, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "中央", "is_correct": true, "explanation": "道路のまんなかに線が引かれているという意味に合う。"}, {"text": "玄関", "is_correct": false, "explanation": "建物の出入口を表す。道路に線が引かれる文には入らない。"}, {"text": "台所", "is_correct": false, "explanation": "料理をする場所を表す。道路の文には合わない。"}, {"text": "表紙", "is_correct": false, "explanation": "本や冊子の外側の面を表す。道路の文には合わない。"}], "explanations": {"中央": "道路のまんなかに線が引かれているという意味に合う。", "玄関": "建物の出入口を表す。道路に線が引かれる文には入らない。", "台所": "料理をする場所を表す。道路の文には合わない。", "表紙": "本や冊子の外側の面を表す。道路の文には合わない。"}, "sentence_index": 6, "correct_answer": "中央"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "データの中央値を求めます。", "explanation": "「中央値」は統計で数値の中間を表す語。場所のまんなかを表す中央とは別の意味で、ここでの使い方は違う。"}, {"text": "試合は中央に入りました。", "explanation": "ここは〈中盤〉の意味。試合の段階や時間の途中を示すので、場所のまんなかを表す中央は合わない。"}, {"text": "私は中央区に住んでいます。", "explanation": "「中央区」は東京などの区の名前。まんなかを表す中央とは別の固有名詞で、ここでは意味が違う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d645761-a470-43e1-a068-67a54f16899d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39470, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "公園の中央を、大きな木が立っています。", "corrected_sentence": "公園の中央に、大きな木が立っています。", "error_description": "「立っています」は場所を示す「に」を取る。「中央を」の「を」は誤りで、「に」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d645761-a470-43e1-a068-67a54f16899d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39470, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "テーブルの中央を花瓶を置いてください。", "corrected_sentence": "テーブルの中央に花瓶を置いてください。", "error_description": "「置く」の置き場所は「に」で示す。「中央を」の「を」は、続く「花瓶を」と目的語が二つ並んで不自然。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d645761-a470-43e1-a068-67a54f16899d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39473, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「集権が進む」で、集権そのものが主語として進むという意味になる。"}, {"text": "を", "is_correct": false, "explanation": "「進む」は自動詞で目的語を取らないので、「集権を進むと」は続かない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を表すので、「集権と進むと」は意味が通らない。"}, {"text": "の", "is_correct": false, "explanation": "「集権の進むと」では述語として成り立たず、文が通らない。"}], "correct_answer": "が", "explanations": {"が": "「集権が進む」で、集権そのものが主語として進むという意味になる。", "を": "「進む」は自動詞で目的語を取らないので、「集権を進むと」は続かない。", "と": "「と」は並列や相手を表すので、「集権と進むと」は意味が通らない。", "の": "「集権の進むと」では述語として成り立たず、文が通らない。"}, "error_tags": {"を": "対象", "と": "並列・相手", "の": "連体修飾"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "分権", "is_correct": true, "explanation": "集権の対義語で、決定権を各地へ分ける意味。"}, {"text": "海岸", "is_correct": false, "explanation": "陸と海の境目の意味で、対義語ではない。"}, {"text": "天気", "is_correct": false, "explanation": "空模様の意味で、対義語ではない。"}, {"text": "書類", "is_correct": false, "explanation": "文字で書いた紙の意味で、対義語ではない。"}], "correct_answer": "分権", "explanations": {"分権": "集権の対義語で、決定権を各地へ分ける意味。", "海岸": "陸と海の境目の意味で、対義語ではない。", "天気": "空模様の意味で、対義語ではない。", "書類": "文字で書いた紙の意味で、対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c2077fb-5805-427c-b931-fa45bdbd5b4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39473, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「首都への」の「の」で、首都へ向かう集権という意味になる。"}, {"text": "に", "is_correct": false, "explanation": "「首都へに」は「へ」と重なり、文として成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「首都へで」は「へ」と重なり、手段や場所の意味にもならない。"}, {"text": "から", "is_correct": false, "explanation": "「首都へから」は「へ」と重なり、文として成り立たない。"}], "correct_answer": "の", "explanations": {"の": "「首都への」の「の」で、首都へ向かう集権という意味になる。", "に": "「首都へに」は「へ」と重なり、文として成り立たない。", "で": "「首都へで」は「へ」と重なり、手段や場所の意味にもならない。", "から": "「首都へから」は「へ」と重なり、文として成り立たない。"}, "error_tags": {"に": "場所・相手", "で": "手段・場所", "から": "起点"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "分権", "is_correct": true, "explanation": "集権の対義語で、決定権を各地へ分ける意味。"}, {"text": "独裁", "is_correct": false, "explanation": "一人が支配する意味で、集権に近いが対義語ではない。"}, {"text": "中央", "is_correct": false, "explanation": "真ん中や政府の本部の意味で、対義語ではない。"}, {"text": "集中", "is_correct": false, "explanation": "一か所に集まる意味で、対義語ではない。"}], "correct_answer": "分権", "explanations": {"分権": "集権の対義語で、決定権を各地へ分ける意味。", "独裁": "一人が支配する意味で、集権に近いが対義語ではない。", "中央": "真ん中や政府の本部の意味で、対義語ではない。", "集中": "一か所に集まる意味で、対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c2077fb-5805-427c-b931-fa45bdbd5b4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39473, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "政治や組織において、決定権限を一つの場所に集中させること。", "primary_collocate": null, "pronunciation": "しゅうけん", "ipa": "ɕɯːkeɴ", "syllable_count": 4, "sentences": [{"text": "国は地方の力を弱め、集権を進めようとしている。", "target_word": "集権", "complexity_tier": "T3", "furigana": "国[くに]は地方[ちほう]の力[ちから]を弱[よわ]め、集権[しゅうけん]を進[すす]めようとしている。", "sentence_source": "generated"}, {"text": "集権が進むと、地方は自分で予算を決められなくなる。", "target_word": "集権", "complexity_tier": "T3", "furigana": "集権[しゅうけん]が進[すす]むと、地方[ちほう]は自分[じぶん]で予算[よさん]を決[き]められなくなる。", "sentence_source": "generated"}, {"text": "大きな企業は、本社への集権を見直して支社に権限を渡した。", "target_word": "集権", "complexity_tier": "T3", "furigana": "大[おお]きな企業[きぎょう]は、本社[ほんしゃ]への集権[しゅうけん]を見直[みなお]して支社[ししゃ]に権限[けんげん]を渡[わた]した。", "sentence_source": "generated"}, {"text": "歴史の授業で、集権と分権のちがいを学んだ。", "target_word": "集権", "complexity_tier": "T3", "furigana": "歴史[れきし]の授業[じゅぎょう]で、集権[しゅうけん]と分権[ぶんけん]のちがいを学[まな]んだ。", "sentence_source": "generated"}, {"text": "政府は災害に早く対応するため、一時的に集権を強めた。", "target_word": "集権", "complexity_tier": "T3", "furigana": "政府[せいふ]は災害[さいがい]に早[はや]く対応[たいおう]するため、一時的[いちじてき]に集権[しゅうけん]を強[つよ]めた。", "sentence_source": "generated"}, {"text": "集権を批判する市長は、町に決定権を戻すよう求めた。", "target_word": "集権", "complexity_tier": "T3", "furigana": "集権[しゅうけん]を批判[ひはん]する市長[しちょう]は、町[まち]に決定権[けっていけん]を戻[もど]すよう求[もと]めた。", "sentence_source": "generated"}, {"text": "組織の集権が行き過ぎると、現場の声が届かなくなる。", "target_word": "集権", "complexity_tier": "T3", "furigana": "組織[そしき]の集権[しゅうけん]が行[い]き過[す]ぎると、現場[げんば]の声[こえ]が届[とど]かなくなる。", "sentence_source": "generated"}, {"text": "この国では長い間、首都への集権が続いてきた。", "target_word": "集権", "complexity_tier": "T3", "furigana": "この国[くに]では長[なが]い間[あいだ]、首都[しゅと]への集権[しゅうけん]が続[つづ]いてきた。", "sentence_source": "generated"}, {"text": "集権の利点は、全国で同じルールを素早く決められることだ。", "target_word": "集権", "complexity_tier": "T3", "furigana": "集権[しゅうけん]の利点[りてん]は、全国[ぜんこく]で同[おな]じルールを素早[すばや]く決[き]められることだ。", "sentence_source": "generated"}, {"text": "市民団体は、国への集権に反対する署名を集めた。", "target_word": "集権", "complexity_tier": "T3", "furigana": "市民[しみん]団体[だんたい]は、国[くに]への集権[しゅうけん]に反対[はんたい]する署名[しょめい]を集[あつ]めた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "集権", "label": "辞書形"}], "register": "formal", "sense_fingerprint": "政治・組織で決定権限を一か所(中央・本部)に集めること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b545744d-41a4-491d-95fb-e6974ddf9eae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39473, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "集権", "is_correct": true, "explanation": "「集権を進める」で、権限を中央に集める政策を進めるという意味になり、文脈に合う。"}, {"text": "切符", "is_correct": false, "explanation": "乗車券の意味で、政策を進める対象にはならない。"}, {"text": "天井", "is_correct": false, "explanation": "部屋の上の面の意味で、政策の対象として文が通らない。"}, {"text": "寝具", "is_correct": false, "explanation": "布団などの意味で、政策を進めるという文脈には入らない。"}], "explanations": {"集権": "「集権を進める」で、権限を中央に集める政策を進めるという意味になり、文脈に合う。", "切符": "乗車券の意味で、政策を進める対象にはならない。", "天井": "部屋の上の面の意味で、政策の対象として文が通らない。", "寝具": "布団などの意味で、政策を進めるという文脈には入らない。"}, "sentence_index": 0, "correct_answer": "集権"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "倉庫の在庫を毎日集権して、数が合っているか確かめた。", "explanation": "ここは〈管理〉の意味。集権は決定権限を一か所に集める語で、在庫の数を見て保つ意味では使わないので合わない。"}, {"text": "彼は仕事に集権して、昼ごはんも忘れた。", "explanation": "ここは〈集中〉の意味。集権は権限を一か所に集める語で、注意を一つのことに向ける意味では使わない。"}, {"text": "庭の花を集権して、花束を作った。", "explanation": "ここは〈収集〉の意味。集権は決定権限を一か所に集める語で、花を摘んで集める意味では使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c2077fb-5805-427c-b931-fa45bdbd5b4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39473, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "集権", "is_correct": true, "explanation": "「組織の集権が行き過ぎる」で、決定権の集中が過剰になるという意味になり、文脈に合う。"}, {"text": "郵便", "is_correct": false, "explanation": "手紙を送る仕組みの意味で、組織の行き過ぎとは結びつかない。"}, {"text": "黒板", "is_correct": false, "explanation": "教室の板の意味で、組織の行き過ぎとは結びつかない。"}, {"text": "砂糖", "is_correct": false, "explanation": "甘味料の意味で、組織の行き過ぎとは結びつかない。"}], "explanations": {"集権": "「組織の集権が行き過ぎる」で、決定権の集中が過剰になるという意味になり、文脈に合う。", "郵便": "手紙を送る仕組みの意味で、組織の行き過ぎとは結びつかない。", "黒板": "教室の板の意味で、組織の行き過ぎとは結びつかない。", "砂糖": "甘味料の意味で、組織の行き過ぎとは結びつかない。"}, "sentence_index": 6, "correct_answer": "集権"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夏休みの宿題を一日に集権して、まとめて終わらせた。", "explanation": "ここは〈集中〉の意味。集権は決定権限の集まりを表す語で、作業を一日に集める意味では使わない。"}, {"text": "災害の支援物資を各地の倉庫に集権して、被害を減らした。", "explanation": "ここは〈分散〉の意味。集権は権限を一か所に集める語で、物資を広く置く意味では使わない。"}, {"text": "家事を家族で集権して、みんなが休めるようにした。", "explanation": "ここは〈分担〉の意味。集権は決定権の集中を表し、役割を分けて受け持つ意味ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c2077fb-5805-427c-b931-fa45bdbd5b4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39473, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "本部は決定権限を一か所を集権した。", "corrected_sentence": "本部は決定権限を一か所に集権した。", "error_description": "「一か所に集権する」の「に」が「を」になっている。集権は集める先を「に」で示すので、「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c2077fb-5805-427c-b931-fa45bdbd5b4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39473, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "本部が決定を一か所に集権ているので、支社は動けない。", "corrected_sentence": "本部が決定を一か所に集権しているので、支社は動けない。", "error_description": "「集権する」の「し」が抜けている。「集権ている」は活用として誤りで、「集権している」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c2077fb-5805-427c-b931-fa45bdbd5b4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39474, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「電力を節約する」で、電力を節約の対象とする正しい形になる。"}, {"text": "が", "is_correct": false, "explanation": "「電力が節約する」では電力が主語になり、節約の主体として文が通らない。"}, {"text": "に", "is_correct": false, "explanation": "「電力に節約する」は節約の対象を示せず、不自然。"}, {"text": "より", "is_correct": false, "explanation": "「電力より節約する」は比較の形になり、意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "「電力を節約する」で、電力を節約の対象とする正しい形になる。", "が": "「電力が節約する」では電力が主語になり、節約の主体として文が通らない。", "に": "「電力に節約する」は節約の対象を示せず、不自然。", "より": "「電力より節約する」は比較の形になり、意味が通らない。"}, "error_tags": {"が": "主語", "に": "場所・相手", "より": "比較"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c2077fb-5805-427c-b931-fa45bdbd5b4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39474, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「電力を作る」で、作る対象として電力を目的語にする正しい形になる。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列を表し、「電力と作る」は作るものの示し方として不自然。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を表し、「電力から作る」は作る元の示し方として合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表し、「電力へ作る」は意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "「電力を作る」で、作る対象として電力を目的語にする正しい形になる。", "と": "「と」は並列を表し、「電力と作る」は作るものの示し方として不自然。", "から": "「から」は起点を表し、「電力から作る」は作る元の示し方として合わない。", "へ": "「へ」は方向を表し、「電力へ作る」は意味が通らない。"}, "error_tags": {"と": "並列", "から": "起点", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c2077fb-5805-427c-b931-fa45bdbd5b4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39474, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "電気を使うための力のこと。電気を動かすためのエネルギーです。", "primary_collocate": null, "pronunciation": "でんりょく", "ipa": "deɴɾʲokɯ", "syllable_count": 4, "sentences": [{"text": "夏はエアコンを使う人が多く、電力がたくさん必要になる。", "target_word": "電力", "complexity_tier": "T3", "furigana": "夏[なつ]はエアコンを使[つか]う人[ひと]が多[おお]く、電力[でんりょく]がたくさん必要[ひつよう]になる。", "sentence_source": "generated"}, {"text": "家の電力を節約するために、使わない部屋の電気を消した。", "target_word": "電力", "complexity_tier": "T3", "furigana": "家[いえ]の電力[でんりょく]を節約[せつやく]するために、使[つか]わない部屋[へや]の電気[でんき]を消[け]した。", "sentence_source": "generated"}, {"text": "台風で電力が止まり、夜は真っ暗になった。", "target_word": "電力", "complexity_tier": "T3", "furigana": "台風[たいふう]で電力[でんりょく]が止[と]まり、夜[よる]は真[ま]っ暗[くら]になった。", "sentence_source": "generated"}, {"text": "この電気ケトルは電力が大きいので、すぐにお湯がわく。", "target_word": "電力", "complexity_tier": "T3", "furigana": "この電気[でんき]ケトルは電力[でんりょく]が大[おお]きいので、すぐにお湯[ゆ]がわく。", "sentence_source": "generated"}, {"text": "電力が足りないときは、工場が仕事の時間を変える。", "target_word": "電力", "complexity_tier": "T3", "furigana": "電力[でんりょく]が足[た]りないときは、工場[こうじょう]が仕事[しごと]の時間[じかん]を変[か]える。", "sentence_source": "generated"}, {"text": "新しい冷蔵庫は電力をあまり使わず、電気代が安くなった。", "target_word": "電力", "complexity_tier": "T3", "furigana": "新[あたら]しい冷蔵庫[れいぞうこ]は電力[でんりょく]をあまり使[つか]わず、電気代[でんきだい]が安[やす]くなった。", "sentence_source": "generated"}, {"text": "電力の使いすぎで、ブレーカーが落ちてしまった。", "target_word": "電力", "complexity_tier": "T3", "furigana": "電力[でんりょく]の使[つか]いすぎで、ブレーカーが落[お]ちてしまった。", "sentence_source": "generated"}, {"text": "太陽の光で電力を作る家が増えている。", "target_word": "電力", "complexity_tier": "T3", "furigana": "太陽[たいよう]の光[ひかり]で電力[でんりょく]を作[つく]る家[いえ]が増[ふ]えている。", "sentence_source": "generated"}, {"text": "電力を大切に使うよう、駅にポスターがはってある。", "target_word": "電力", "complexity_tier": "T3", "furigana": "電力[でんりょく]を大切[たいせつ]に使[つか]うよう、駅[えき]にポスターがはってある。", "sentence_source": "generated"}, {"text": "会社は電力の使用量を毎月記録している。", "target_word": "電力", "complexity_tier": "T3", "furigana": "会社[かいしゃ]は電力[でんりょく]の使用量[しようりょう]を毎月[まいつき]記録[きろく]している。", "sentence_source": "generated"}], "morphological_forms": [{"form": "電力", "label": "辞書形"}], "register": "neutral", "sense_fingerprint": "電気器具を動かすために使う電気のエネルギー(使う量・大きさ)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b545744d-41a4-491d-95fb-e6974ddf9eae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39474, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "電力", "is_correct": true, "explanation": "電気を使うための力の意味で、エアコンを使う夏に必要になるという文脈に合う。"}, {"text": "湿度", "is_correct": false, "explanation": "空気中の水分の度合いの意味で、必要になるという文脈に合わない。"}, {"text": "座布団", "is_correct": false, "explanation": "敷く布の意味で、必要になるという文脈に合わない。"}, {"text": "渋滞", "is_correct": false, "explanation": "車が詰まる状態の意味で、必要になるという文脈に合わない。"}], "explanations": {"電力": "電気を使うための力の意味で、エアコンを使う夏に必要になるという文脈に合う。", "湿度": "空気中の水分の度合いの意味で、必要になるという文脈に合わない。", "座布団": "敷く布の意味で、必要になるという文脈に合わない。", "渋滞": "車が詰まる状態の意味で、必要になるという文脈に合わない。"}, "sentence_index": 0, "correct_answer": "電力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この電力は長持ちするので、旅行でも安心だ。", "explanation": "ここは〈電池〉の意味。電力は電気を使う力や供給の量を指し、持ち運んで長持ちする物ではないので合わない。"}, {"text": "この電力は暗くなると自動で点く。", "explanation": "ここは〈電灯〉の意味。電力は物ではないので、点いたり消えたりする器具の説明には使えない。"}, {"text": "この電力は、一晩でスマホをフルに充電する。", "explanation": "ここは〈充電器〉の意味。電力は充電する機械ではないので、機器が行う動作の主語にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c2077fb-5805-427c-b931-fa45bdbd5b4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39474, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "電力", "is_correct": true, "explanation": "電力の使いすぎで、ブレーカーが落ちるという因果関係として自然。"}, {"text": "天井", "is_correct": false, "explanation": "部屋の上の面の意味で、使いすぎるという語とは合わない。"}, {"text": "靴下", "is_correct": false, "explanation": "足を覆う衣類の意味で、使いすぎるという語とは合わない。"}, {"text": "黒板", "is_correct": false, "explanation": "文字を書く板の意味で、使いすぎるという語とは合わない。"}], "explanations": {"電力": "電力の使いすぎで、ブレーカーが落ちるという因果関係として自然。", "天井": "部屋の上の面の意味で、使いすぎるという語とは合わない。", "靴下": "足を覆う衣類の意味で、使いすぎるという語とは合わない。", "黒板": "文字を書く板の意味で、使いすぎるという語とは合わない。"}, "sentence_index": 6, "correct_answer": "電力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この電力は大きな音を出すので、夜は使えない。", "explanation": "ここは〈発電機〉の意味。電力は電気を使う力を指し、音を出す機械ではないので合わない。"}, {"text": "この電力は屋根に並べて使う。", "explanation": "ここは〈太陽光パネル〉の意味。電力は設備ではないので、屋根に並べるという用途には合わない。"}, {"text": "電力は夏の暑い部屋で風を送る。", "explanation": "ここは〈扇風機〉の意味。電力は風を送る機械ではなく、電気を使う力なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c2077fb-5805-427c-b931-fa45bdbd5b4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39474, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夏は電力を足りなくなるおそれがある。", "corrected_sentence": "夏は電力が足りなくなるおそれがある。", "error_description": "「足りる」は「が」を取るので「電力が足りない」が正しい。「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c2077fb-5805-427c-b931-fa45bdbd5b4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39474, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "電力を使いすぎるたら、ブレーカーが落ちることがある。", "corrected_sentence": "電力を使いすぎたら、ブレーカーが落ちることがある。", "error_description": "「使いすぎる」に「たら」を付けるときは「使いすぎたら」にする。「使いすぎるたら」は活用の形が誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c2077fb-5805-427c-b931-fa45bdbd5b4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39475, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「電力の供給」で、電力に属する供給を表す正しい形になる。"}, {"text": "を", "is_correct": false, "explanation": "「電力を供給が安定」では目的語の形が成り立たず、文が通らない。"}, {"text": "に", "is_correct": false, "explanation": "「電力に供給が安定」は「に」が相手を示すが、安定の主語として成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「電力へ供給が安定」は方向を示すが、意味が通らない。"}], "correct_answer": "の", "explanations": {"の": "「電力の供給」で、電力に属する供給を表す正しい形になる。", "を": "「電力を供給が安定」では目的語の形が成り立たず、文が通らない。", "に": "「電力に供給が安定」は「に」が相手を示すが、安定の主語として成り立たない。", "へ": "「電力へ供給が安定」は方向を示すが、意味が通らない。"}, "error_tags": {"を": "対象", "に": "場所・相手", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c2077fb-5805-427c-b931-fa45bdbd5b4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39475, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「電力の供給」で、供給の内容を電力に限定する正しい形になる。"}, {"text": "で", "is_correct": false, "explanation": "「電力で供給に使う」は手段の意味になり、燃料の用途として通らない。"}, {"text": "から", "is_correct": false, "explanation": "「電力から供給に使う」は起点の意味になり、用途として不自然。"}, {"text": "より", "is_correct": false, "explanation": "「電力より供給に使う」は比較の形になり、意味が通らない。"}], "correct_answer": "の", "explanations": {"の": "「電力の供給」で、供給の内容を電力に限定する正しい形になる。", "で": "「電力で供給に使う」は手段の意味になり、燃料の用途として通らない。", "から": "「電力から供給に使う」は起点の意味になり、用途として不自然。", "より": "「電力より供給に使う」は比較の形になり、意味が通らない。"}, "error_tags": {"で": "手段", "から": "起点", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c2077fb-5805-427c-b931-fa45bdbd5b4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39475, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "電気エネルギーを供給したり消費したりするための能力や、そのシステムのこと。電気を起こしたり、送ったり、使ったりするしくみ全体を指します。", "primary_collocate": null, "pronunciation": "でんりょく", "ipa": "deɴɾʲokɯ", "syllable_count": 4, "sentences": [{"text": "国の電力は、発電所と送電線が合わさって成り立っている。", "target_word": "電力", "complexity_tier": "T3", "furigana": "国[くに]の電力[でんりょく]は、発電所[はつでんしょ]と送電線[そうでんせん]が合[あ]わさって成[な]り立[た]っている。", "sentence_source": "generated"}, {"text": "電力の供給が安定しているので、停電はめったに起きない。", "target_word": "電力", "complexity_tier": "T3", "furigana": "電力[でんりょく]の供給[きょうきゅう]が安定[あんてい]しているので、停電[ていでん]はめったに起[お]きない。", "sentence_source": "generated"}, {"text": "日本では、地域ごとに電力のしくみが少しちがう。", "target_word": "電力", "complexity_tier": "T3", "furigana": "日本[にほん]では、地域[ちいき]ごとに電力[でんりょく]のしくみが少[すこ]しちがう。", "sentence_source": "generated"}, {"text": "電力の自由化で、家庭が電気の買い先を選べるようになった。", "target_word": "電力", "complexity_tier": "T3", "furigana": "電力[でんりょく]の自由化[じゆうか]で、家庭[かてい]が電気[でんき]の買[か]い先[さき]を選[えら]べるようになった。", "sentence_source": "generated"}, {"text": "災害に強い電力をめざして、政府は新しい計画を発表した。", "target_word": "電力", "complexity_tier": "T3", "furigana": "災害[さいがい]に強[つよ]い電力[でんりょく]をめざして、政府[せいふ]は新[あたら]しい計画[けいかく]を発表[はっぴょう]した。", "sentence_source": "generated"}, {"text": "発電から送電、使う側まで、電力全体をつなぐ研究が進んでいる。", "target_word": "電力", "complexity_tier": "T3", "furigana": "発電[はつでん]から送電[そうでん]、使[つか]う側[がわ]まで、電力[でんりょく]全体[ぜんたい]をつなぐ研究[けんきゅう]が進[すす]んでいる。", "sentence_source": "generated"}, {"text": "冬は暖房の利用が増え、電力の供給が厳しくなる。", "target_word": "電力", "complexity_tier": "T3", "furigana": "冬[ふゆ]は暖房[だんぼう]の利用[りよう]が増[ふ]え、電力[でんりょく]の供給[きょうきゅう]が厳[きび]しくなる。", "sentence_source": "generated"}, {"text": "島では電力の供給に使う燃料を船で運んでいる。", "target_word": "電力", "complexity_tier": "T3", "furigana": "島[しま]では電力[でんりょく]の供給[きょうきゅう]に使[つか]う燃料[ねんりょう]を船[ふね]で運[はこ]んでいる。", "sentence_source": "generated"}, {"text": "電力は社会を支える大切なしくみだと言われる。", "target_word": "電力", "complexity_tier": "T3", "furigana": "電力[でんりょく]は社会[しゃかい]を支[ささ]える大切[たいせつ]なしくみだと言[い]われる。", "sentence_source": "generated"}, {"text": "電力の需要を予測して、発電量を調整している。", "target_word": "電力", "complexity_tier": "T3", "furigana": "電力[でんりょく]の需要[じゅよう]を予測[よそく]して、発電量[はつでんりょう]を調整[ちょうせい]している。", "sentence_source": "generated"}], "morphological_forms": [{"form": "電力", "label": "辞書形"}], "register": "formal", "sense_fingerprint": "発電・送電・消費をふくむ電気供給のしくみ全体と供給能力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b545744d-41a4-491d-95fb-e6974ddf9eae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39475, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "電力", "is_correct": true, "explanation": "電気を送る仕組み全体を指し、発電所と送電線が合わさって成り立つという説明と合う。"}, {"text": "郵便", "is_correct": false, "explanation": "手紙を届ける仕組みの意味で、発電所と送電線の話には合わない。"}, {"text": "天気", "is_correct": false, "explanation": "空模様のことで、発電所と送電線で成り立つ仕組みには合わない。"}, {"text": "教室", "is_correct": false, "explanation": "授業をする部屋の意味で、成り立つ仕組みには合わない。"}], "explanations": {"電力": "電気を送る仕組み全体を指し、発電所と送電線が合わさって成り立つという説明と合う。", "郵便": "手紙を届ける仕組みの意味で、発電所と送電線の話には合わない。", "天気": "空模様のことで、発電所と送電線で成り立つ仕組みには合わない。", "教室": "授業をする部屋の意味で、成り立つ仕組みには合わない。"}, "sentence_index": 0, "correct_answer": "電力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この電力は古くなったので、台風で切れやすい。", "explanation": "ここは〈送電線〉の意味。電力は供給のしくみや能力を指す語で、切れる設備ではないので合わない。"}, {"text": "この電力は汚れを落とすのが得意だ。", "explanation": "ここは〈洗濯機〉の意味。電力は洗う機械ではないので、汚れを落とす性能の説明には使えない。"}, {"text": "この電力は計算を素早く行う。", "explanation": "ここは〈電卓〉の意味。電力は計算する機械ではないので、計算をする主語にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c2077fb-5805-427c-b931-fa45bdbd5b4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39475, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "電力", "is_correct": true, "explanation": "暖房が増えると電力の供給が厳しくなるという流れに合う。"}, {"text": "挨拶", "is_correct": false, "explanation": "人に言葉をかける動作の意味で、供給とは結びつかない。"}, {"text": "年齢", "is_correct": false, "explanation": "生まれてからの年数の意味で、供給とは結びつかない。"}, {"text": "思い出", "is_correct": false, "explanation": "過去の記憶の意味で、供給とは結びつかない。"}], "explanations": {"電力": "暖房が増えると電力の供給が厳しくなるという流れに合う。", "挨拶": "人に言葉をかける動作の意味で、供給とは結びつかない。", "年齢": "生まれてからの年数の意味で、供給とは結びつかない。", "思い出": "過去の記憶の意味で、供給とは結びつかない。"}, "sentence_index": 6, "correct_answer": "電力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この電力は家まで水を送る。", "explanation": "ここは〈水道〉の意味。電力は水を送る設備ではなく、電気を送る仕組みなので合わない。"}, {"text": "電力は手紙を届ける。", "explanation": "ここは〈郵便局〉の意味。電力は手紙を届ける機関ではないので、届ける主語にはならない。"}, {"text": "電力は車を通す。", "explanation": "ここは〈道路〉の意味。電力は車を通す設備ではないので、通行の用途には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c2077fb-5805-427c-b931-fa45bdbd5b4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39475, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この地域では電力に供給が途切れたことがない。", "corrected_sentence": "この地域では電力の供給が途切れたことがない。", "error_description": "「電力の供給」の「の」が「に」になっている。「供給」は「電力の」で修飾する名詞なので、「に」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c2077fb-5805-427c-b931-fa45bdbd5b4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39475, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "電力を供給ている会社は、災害の復旧を急いでいる。", "corrected_sentence": "電力を供給している会社は、災害の復旧を急いでいる。", "error_description": "「供給している」の「し」が抜けている。「供給ている」は「供給する」の活用として誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c2077fb-5805-427c-b931-fa45bdbd5b4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39476, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "大型", "is_correct": true, "explanation": "大きさが大きいという意味で、「小型」の対義語として辞書にも載る。"}, {"text": "中型", "is_correct": false, "explanation": "中型は大きさの中くらいを指すので、「小型」の対義語ではない。"}, {"text": "巨大", "is_correct": false, "explanation": "巨大は非常に大きいことを表すが、「小型」の対義語としては扱われない。"}, {"text": "高級", "is_correct": false, "explanation": "高級は品質や値段が高いことを表すので、大きさの対義語ではない。"}], "correct_answer": "大型", "explanations": {"大型": "大きさが大きいという意味で、「小型」の対義語として辞書にも載る。", "中型": "中型は大きさの中くらいを指すので、「小型」の対義語ではない。", "巨大": "巨大は非常に大きいことを表すが、「小型」の対義語としては扱われない。", "高級": "高級は品質や値段が高いことを表すので、大きさの対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '034c4210-ad68-4bb4-ae2e-8d82f9a50de0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
