INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39476, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "「小型」は、大きさが小さいことを言います。", "primary_collocate": null, "pronunciation": "こがた", "ipa": "koɡata", "syllable_count": 3, "sentences": [{"text": "小型の犬なので、小さなアパートでも飼えます。", "target_word": "小型", "complexity_tier": "T3", "furigana": "小型[こがた]の犬[いぬ]なので、小[ちい]さなアパートでも飼[か]えます。", "sentence_source": "generated"}, {"text": "このカメラは小型で、ポケットに入ります。", "target_word": "小型", "complexity_tier": "T3", "furigana": "このカメラは小型[こがた]で、ポケットに入[はい]ります。", "sentence_source": "generated"}, {"text": "小型の船は、大きな波に弱い。", "target_word": "小型", "complexity_tier": "T3", "furigana": "小型[こがた]の船[ふね]は、大[おお]きな波[なみ]に弱[よわ]い。", "sentence_source": "generated"}, {"text": "駐車場が狭いので、小型の車を買った。", "target_word": "小型", "complexity_tier": "T3", "furigana": "駐車場[ちゅうしゃじょう]が狭[せま]いので、小型[こがた]の車[くるま]を買[か]った。", "sentence_source": "generated"}, {"text": "小型のラジオを持って、山へ出かけた。", "target_word": "小型", "complexity_tier": "T3", "furigana": "小型[こがた]のラジオを持[も]って、山[やま]へ出[で]かけた。", "sentence_source": "generated"}, {"text": "弟は小型の望遠鏡で、夜空の星を見た。", "target_word": "小型", "complexity_tier": "T3", "furigana": "弟[おとうと]は小型[こがた]の望遠鏡[ぼうえんきょう]で、夜空[よぞら]の星[ほし]を見[み]た。", "sentence_source": "generated"}, {"text": "小型のバスなら、この細い道も通れる。", "target_word": "小型", "complexity_tier": "T3", "furigana": "小型[こがた]のバスなら、この細[ほそ]い道[みち]も通[とお]れる。", "sentence_source": "generated"}, {"text": "荷物が多いので、小型の冷蔵庫では足りない。", "target_word": "小型", "complexity_tier": "T3", "furigana": "荷物[にもつ]が多[おお]いので、小型[こがた]の冷蔵庫[れいぞうこ]では足[た]りない。", "sentence_source": "generated"}, {"text": "小型のドローンが、庭の上をゆっくり飛んでいた。", "target_word": "小型", "complexity_tier": "T3", "furigana": "小型[こがた]のドローンが、庭[にわ]の上[うえ]をゆっくり飛[と]んでいた。", "sentence_source": "generated"}, {"text": "小型のトラックが、荷物を店に運んできた。", "target_word": "小型", "complexity_tier": "T3", "furigana": "小型[こがた]のトラックが、荷物[にもつ]を店[みせ]に運[はこ]んできた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "小型", "label": "base"}, {"form": "小型の", "label": "attributive"}, {"form": "小型で", "label": "te-form"}], "register": "neutral", "sense_fingerprint": "小型: 大きさが小さいこと（乗り物・機械・動物など）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcd0e261-a606-4c8b-a65c-77d92cef559f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39476, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "小型", "is_correct": true, "explanation": "「小型の犬」で、体の大きさが小さいことを表す。小さなアパートで飼えるという文に合う。"}, {"text": "大判", "is_correct": false, "explanation": "大判は紙や本の大きさを指すので、犬には使えず文の流れにも合わない。"}, {"text": "高所", "is_correct": false, "explanation": "高所は高い場所を指すので、犬の大きさの説明としては合わない。"}, {"text": "深夜", "is_correct": false, "explanation": "深夜は時間を指すので、犬の種類や大きさを示す語として合わない。"}], "explanations": {"小型": "「小型の犬」で、体の大きさが小さいことを表す。小さなアパートで飼えるという文に合う。", "大判": "大判は紙や本の大きさを指すので、犬には使えず文の流れにも合わない。", "高所": "高所は高い場所を指すので、犬の大きさの説明としては合わない。", "深夜": "深夜は時間を指すので、犬の種類や大きさを示す語として合わない。"}, "sentence_index": 0, "correct_answer": "小型"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は背が低いが、小型の人だ。", "explanation": "人の体格を表すなら「小柄」を使う。「小型」は機械や乗り物などの大きさに使う語。"}, {"text": "彼女は小型で、制服がよく似合う。", "explanation": "「小柄で」と言うのが自然。「小型」は人には使わず、体格の意味で使うのは不自然。"}, {"text": "彼は小型の声で、やさしく答えた。", "explanation": "声の大きさには「小さい」を使う。「小型」は機械や乗り物に使う語なので、声には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '034c4210-ad68-4bb4-ae2e-8d82f9a50de0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39476, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "小型", "is_correct": true, "explanation": "「小型のバス」で、小さいバスは細い道も通れるという文に合う。"}, {"text": "深海", "is_correct": false, "explanation": "深海は海の深い場所を指すので、バスの大きさを表す語として合わない。"}, {"text": "夜間", "is_correct": false, "explanation": "夜間は時間を指すので、バスの大きさを示す語として合わない。"}, {"text": "砂漠", "is_correct": false, "explanation": "砂漠は場所を指すので、バスの大きさを表す語としては合わない。"}], "explanations": {"小型": "「小型のバス」で、小さいバスは細い道も通れるという文に合う。", "深海": "深海は海の深い場所を指すので、バスの大きさを表す語として合わない。", "夜間": "夜間は時間を指すので、バスの大きさを示す語として合わない。", "砂漠": "砂漠は場所を指すので、バスの大きさを表す語としては合わない。"}, "sentence_index": 6, "correct_answer": "小型"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この林檎は小型で、甘くておいしい。", "explanation": "果物の大きさには「小ぶり」を使う。「小型」は機械や乗り物などに使う語なので、果物には合わない。"}, {"text": "まだ小型の子どもなので、字が書けない。", "explanation": "子どもの年齢や成長を表すなら「幼い」や「小さい」を使う。「小型」は年齢には使わない。"}, {"text": "その映画は小型の時間で終わった。", "explanation": "時間の長さを言うなら〈短い〉を使う。〈小型〉は物の大きさを表す語なので、時間の長さには合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '034c4210-ad68-4bb4-ae2e-8d82f9a50de0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39476, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "小型を船で、荷物を港へ運んだ。", "corrected_sentence": "小型の船で、荷物を港へ運んだ。", "error_description": "「小型の船」のように、名詞を修飾するには「の」が必要。「を」は目的語を示すので、ここでは合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '034c4210-ad68-4bb4-ae2e-8d82f9a50de0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39476, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "小型に軽いカメラを、旅行に持って行った。", "corrected_sentence": "小型で軽いカメラを、旅行に持って行った。", "error_description": "「小型で」と状態を表す「で」が自然。「に」は合わず、この形では不自然になる。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '034c4210-ad68-4bb4-ae2e-8d82f9a50de0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39477, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "大型", "is_correct": true, "explanation": "「小型」の対義語。普通より規模が大きいことを表す。"}, {"text": "中型", "is_correct": false, "explanation": "大小の中間を表す語で、対義語ではない。"}, {"text": "寸法", "is_correct": false, "explanation": "大きさを測る基準を表す語で、対義語ではない。"}, {"text": "体積", "is_correct": false, "explanation": "空間の大きさを表す語で、対義語ではない。"}], "correct_answer": "大型", "explanations": {"大型": "「小型」の対義語。普通より規模が大きいことを表す。", "中型": "大小の中間を表す語で、対義語ではない。", "寸法": "大きさを測る基準を表す語で、対義語ではない。", "体積": "空間の大きさを表す語で、対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '034c4210-ad68-4bb4-ae2e-8d82f9a50de0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39477, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "大型", "is_correct": true, "explanation": "「小型」の対義語で、普通より大きいことを表す。"}, {"text": "機密", "is_correct": false, "explanation": "秘密のことで、大きさの対義語ではない。"}, {"text": "試運転", "is_correct": false, "explanation": "動作の確認を指す語で、対義語ではない。"}, {"text": "重量", "is_correct": false, "explanation": "目方を表す語で、大きさの対義語ではない。"}], "correct_answer": "大型", "explanations": {"大型": "「小型」の対義語で、普通より大きいことを表す。", "機密": "秘密のことで、大きさの対義語ではない。", "試運転": "動作の確認を指す語で、対義語ではない。", "重量": "目方を表す語で、大きさの対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '034c4210-ad68-4bb4-ae2e-8d82f9a50de0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39477, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "物の形や規模が普通より小さいこと。", "primary_collocate": null, "pronunciation": "こがた", "ipa": "koɡata", "syllable_count": 3, "sentences": [{"text": "このスーツケースは小型で、機内に持ち込める。", "target_word": "小型", "complexity_tier": "T3", "furigana": "このスーツケースは小型[こがた]で、機内[きない]に持[も]ち込[こ]める。", "sentence_source": "generated"}, {"text": "小型の台風だったが、強い風が吹いた。", "target_word": "小型", "complexity_tier": "T3", "furigana": "小型[こがた]の台風[たいふう]だったが、強[つよ]い風[かぜ]が吹[ふ]いた。", "sentence_source": "generated"}, {"text": "小型の工場がいくつも集まって、町を支えている。", "target_word": "小型", "complexity_tier": "T3", "furigana": "小型[こがた]の工場[こうじょう]がいくつも集[あつ]まって、町[まち]を支[ささ]えている。", "sentence_source": "generated"}, {"text": "この掃除機は小型で、狭い部屋でも使いやすい。", "target_word": "小型", "complexity_tier": "T3", "furigana": "この掃除機[そうじき]は小型[こがた]で、狭[せま]い部屋[へや]でも使[つか]いやすい。", "sentence_source": "generated"}, {"text": "小型のなべは、一人分の料理を作るのに便利だ。", "target_word": "小型", "complexity_tier": "T3", "furigana": "小型[こがた]のなべは、一人分[ひとりぶん]の料理[りょうり]を作[つく]るのに便利[べんり]だ。", "sentence_source": "generated"}, {"text": "小型の扇風機を机の上に置いた。", "target_word": "小型", "complexity_tier": "T3", "furigana": "小型[こがた]の扇風機[せんぷうき]を机[つくえ]の上[うえ]に置[お]いた。", "sentence_source": "generated"}, {"text": "この会社は小型のロボットを専門に作っている。", "target_word": "小型", "complexity_tier": "T3", "furigana": "この会社[かいしゃ]は小型[こがた]のロボットを専門[せんもん]に作[つく]っている。", "sentence_source": "generated"}, {"text": "小型の電気自動車は、街の中で使いやすい。", "target_word": "小型", "complexity_tier": "T3", "furigana": "小型[こがた]の電気自動車[でんきじどうしゃ]は、街[まち]の中[なか]で使[つか]いやすい。", "sentence_source": "generated"}, {"text": "小型のテレビしかないので、映画は迫力がない。", "target_word": "小型", "complexity_tier": "T3", "furigana": "小型[こがた]のテレビしかないので、映画[えいが]は迫力[はくりょく]がない。", "sentence_source": "generated"}, {"text": "普通の機械より小型にしたので、持ち運びが楽になった。", "target_word": "小型", "complexity_tier": "T3", "furigana": "普通[ふつう]の機械[きかい]より小型[こがた]にしたので、持[も]ち運[はこ]びが楽[らく]になった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "小型", "label": "base"}, {"form": "小型の", "label": "attributive"}, {"form": "小型で", "label": "te-form"}], "register": "neutral", "sense_fingerprint": "小型: 形や規模が普通より小さいこと（標準サイズとの比較）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcd0e261-a606-4c8b-a65c-77d92cef559f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39477, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "小型", "is_correct": true, "explanation": "スーツケースの大きさを表し、機内に持ち込める条件に合う。"}, {"text": "大型", "is_correct": false, "explanation": "大型だと機内に持ち込めないので、文の内容と合わない。"}, {"text": "寸法", "is_correct": false, "explanation": "寸法は長さなどの測り方を指し、「寸法で持ち込める」は意味をなさない。"}, {"text": "体積", "is_correct": false, "explanation": "体積は空間の大きさを指す語で、「体積で持ち込める」は文に入らない。"}], "explanations": {"小型": "スーツケースの大きさを表し、機内に持ち込める条件に合う。", "大型": "大型だと機内に持ち込めないので、文の内容と合わない。", "寸法": "寸法は長さなどの測り方を指し、「寸法で持ち込める」は意味をなさない。", "体積": "体積は空間の大きさを指す語で、「体積で持ち込める」は文に入らない。"}, "sentence_index": 0, "correct_answer": "小型"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼女は小型で、ダンスの大会で優勝した。", "explanation": "ここは〈小柄〉の意味。人の体格には小柄を使い、小型は物や機械に使うので合わない。"}, {"text": "彼は小型の声で話したので、後ろの席の人には聞こえなかった。", "explanation": "ここは〈小声〉の意味。声の小ささには小声を使い、小型は物の大きさに使うので合わない。"}, {"text": "この店は小型の経営で、従業員は二人しかいない。", "explanation": "ここは〈小規模〉の意味。事業の規模には小規模を使い、小型は物の大きさに使うので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '034c4210-ad68-4bb4-ae2e-8d82f9a50de0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39477, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "小型", "is_correct": true, "explanation": "ロボットの大きさを表し、「小型のロボット」と続いて文意に合う。"}, {"text": "深夜", "is_correct": false, "explanation": "深夜は時間を指すので、ロボットの大きさを表す語として合わない。"}, {"text": "機密", "is_correct": false, "explanation": "機密は秘密のことで、「機密のロボット」は意味が合わない。"}, {"text": "試運転", "is_correct": false, "explanation": "試運転は動作の確認を指し、ロボットの大きさを表さない。"}], "explanations": {"小型": "ロボットの大きさを表し、「小型のロボット」と続いて文意に合う。", "深夜": "深夜は時間を指すので、ロボットの大きさを表す語として合わない。", "機密": "機密は秘密のことで、「機密のロボット」は意味が合わない。", "試運転": "試運転は動作の確認を指し、ロボットの大きさを表さない。"}, "sentence_index": 6, "correct_answer": "小型"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この会議は小型で、五人だけが参加する。", "explanation": "ここは〈少人数〉の意味。人数の少なさには少人数を使い、小型は物の大きさに使うので合わない。"}, {"text": "この米は小型で、粒の大きさがそろっていて炊きやすい。", "explanation": "ここは〈小粒〉の意味。粒状の米の小ささには小粒を使い、小型は合わないので誤り。"}, {"text": "この銀行は小型の融資を専門にしている。", "explanation": "ここは〈小口〉の意味。少額の取引には小口を使い、小型は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '034c4210-ad68-4bb4-ae2e-8d82f9a50de0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39477, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "小型な電池を買うと、軽くて持ち運びが楽だ。", "corrected_sentence": "小型の電池を買うと、軽くて持ち運びが楽だ。", "error_description": "「小型」は名詞なので、名詞を修飾するときは「の」を使う。「な」は誤りで、正しくは「小型の電池」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '034c4210-ad68-4bb4-ae2e-8d82f9a50de0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39477, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "会社は製品を小型するため、新しい部品を開発した。", "corrected_sentence": "会社は製品を小型化するため、新しい部品を開発した。", "error_description": "「小型」を動詞にするには「化する」が必要。「小型する」は言えないので、正しくは「小型化する」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '034c4210-ad68-4bb4-ae2e-8d82f9a50de0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39478, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "マクロ", "is_correct": true, "explanation": "〈ミクロ（マイクロ）〉の対義語。全体や大きな規模を見る視点を表し、小さなものと対になる。"}, {"text": "ナノ", "is_correct": false, "explanation": "ナノはマイクロよりさらに小さい単位で、対義語ではない。"}, {"text": "電車", "is_correct": false, "explanation": "電車は乗り物の名詞で、大きさの対義語ではない。"}, {"text": "夕焼け", "is_correct": false, "explanation": "夕焼けは空の現象で、マイクロの反対の意味を持たない。"}], "correct_answer": "マクロ", "explanations": {"マクロ": "〈ミクロ（マイクロ）〉の対義語。全体や大きな規模を見る視点を表し、小さなものと対になる。", "ナノ": "ナノはマイクロよりさらに小さい単位で、対義語ではない。", "電車": "電車は乗り物の名詞で、大きさの対義語ではない。", "夕焼け": "夕焼けは空の現象で、マイクロの反対の意味を持たない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ff88f66-a23a-43b4-812c-c0d92e99400c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
