INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39478, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "とても小さい「ミクロ」という意味の言葉です。", "primary_collocate": null, "pronunciation": "まいくろ", "ipa": "maikɯɾo", "syllable_count": 4, "sentences": [{"text": "マイクロの世界では、水の一滴も大きな海に見える。", "target_word": "マイクロ", "complexity_tier": "T3", "furigana": "マイクロの世界[せかい]では、水[みず]の一滴[いってき]も大[おお]きな海[うみ]に見[み]える。", "sentence_source": "generated"}, {"text": "マイクロとマクロでは、見る大きさがまったく違います。", "target_word": "マイクロ", "complexity_tier": "T3", "furigana": "マイクロとマクロでは、見[み]る大[おお]きさがまったく違[ちが]います。", "sentence_source": "generated"}, {"text": "この研究は、マイクロの視点で細胞を調べている。", "target_word": "マイクロ", "complexity_tier": "T3", "furigana": "この研究[けんきゅう]は、マイクロの視点[してん]で細胞[さいぼう]を調[しら]べている。", "sentence_source": "generated"}, {"text": "目に見えない小さなものを、マイクロと言うこともあります。", "target_word": "マイクロ", "complexity_tier": "T3", "furigana": "目[め]に見[み]えない小[ちい]さなものを、マイクロと言[い]うこともあります。", "sentence_source": "generated"}, {"text": "「ミクロ」と同じ意味で、「マイクロ」を使う人もいる。", "target_word": "マイクロ", "complexity_tier": "T3", "furigana": "「ミクロ」と同[おな]じ意味[いみ]で、「マイクロ」を使[つか]う人[ひと]もいる。", "sentence_source": "generated"}, {"text": "髪の毛より細い線は、マイクロの世界の大きさです。", "target_word": "マイクロ", "complexity_tier": "T3", "furigana": "髪[かみ]の毛[け]より細[ほそ]い線[せん]は、マイクロの世界[せかい]の大[おお]きさです。", "sentence_source": "generated"}, {"text": "科学者は、マクロだけでなくマイクロの変化にも注目する。", "target_word": "マイクロ", "complexity_tier": "T3", "furigana": "科学者[かがくしゃ]は、マクロだけでなくマイクロの変化[へんか]にも注目[ちゅうもく]する。", "sentence_source": "generated"}, {"text": "小さな虫の体も、マイクロの世界ではとても複雑だ。", "target_word": "マイクロ", "complexity_tier": "T3", "furigana": "小[ちい]さな虫[むし]の体[からだ]も、マイクロの世界[せかい]ではとても複雑[ふくざつ]だ。", "sentence_source": "generated"}, {"text": "全体の動きより、マイクロの違いを見分けることが大切な実験です。", "target_word": "マイクロ", "complexity_tier": "T3", "furigana": "全体[ぜんたい]の動[うご]きより、マイクロ[まいくろ]の違[ちが]いを見分[みわ]けることが大切[たいせつ]な実験[じっけん]です。", "sentence_source": "generated"}, {"text": "子どもたちは、顕微鏡でマイクロの世界を初めて見て、おどろいた。", "target_word": "マイクロ", "complexity_tier": "T3", "furigana": "子[こ]どもたちは、顕微鏡[けんびきょう]でマイクロの世界[せかい]を初[はじ]めて見[み]て、おどろいた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "マイクロ", "label": "基本形"}], "register": "一般・科学の説明", "sense_fingerprint": "ミクロと同じ、とても小さいことを表す語（マクロの対）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa11b1da-6a01-497b-ba17-85963d2f0c23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39478, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "マイクロ", "is_correct": true, "explanation": "「マイクロの世界」は、水の一滴が海に見えるほど小さな世界を指す。空欄に入るのはこの語だけ。"}, {"text": "電車", "is_correct": false, "explanation": "「電車の世界」では、小さな水の一滴が海に見えるという話の流れに合わない。"}, {"text": "ガラス", "is_correct": false, "explanation": "「ガラスの世界」は意味が通らず、大きさの尺度を表す語ではない。"}, {"text": "夕焼け", "is_correct": false, "explanation": "「夕焼けの世界」は空の景色の話になり、小さいものを見る文脈に合わない。"}], "explanations": {"マイクロ": "「マイクロの世界」は、水の一滴が海に見えるほど小さな世界を指す。空欄に入るのはこの語だけ。", "電車": "「電車の世界」では、小さな水の一滴が海に見えるという話の流れに合わない。", "ガラス": "「ガラスの世界」は意味が通らず、大きさの尺度を表す語ではない。", "夕焼け": "「夕焼けの世界」は空の景色の話になり、小さいものを見る文脈に合わない。"}, "sentence_index": 0, "correct_answer": "マイクロ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "歌手は、マイクロに向かって大きな声で歌った。", "explanation": "ここは〈マイク〉（声を音にする機械）の意味。マイクロ（とても小さい）は機械の名前ではないので、マイクの代わりには合わない。"}, {"text": "車の重さは、マイクロの単位で表す。", "explanation": "ここは〈キロ〉（千倍）の単位が合う。マイクロは小さいものの単位に使う語で、車の重さには使わない。"}, {"text": "原子ひとつの大きさは、マイクロの単位で測る。", "explanation": "原子はマイクロ（百万分の一）より桁違いに小さいので、ここは〈ナノ〉の単位が合う。マイクロでは大きすぎる。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ff88f66-a23a-43b4-812c-c0d92e99400c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39478, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ギター", "is_correct": false, "explanation": "「ギターの変化」では、顕微鏡で見る細かな変化の話に合わない。"}, {"text": "マイクロ", "is_correct": true, "explanation": "マクロと対になる、小さな世界の変化を表す語。空欄に入るのはこの語だけ。"}, {"text": "カレー", "is_correct": false, "explanation": "「カレーの変化」は科学の文脈では意味が通らない。"}, {"text": "ヨット", "is_correct": false, "explanation": "「ヨットの変化」は、マクロと対比して注目する話題として成り立たない。"}], "explanations": {"ギター": "「ギターの変化」では、顕微鏡で見る細かな変化の話に合わない。", "マイクロ": "マクロと対になる、小さな世界の変化を表す語。空欄に入るのはこの語だけ。", "カレー": "「カレーの変化」は科学の文脈では意味が通らない。", "ヨット": "「ヨットの変化」は、マクロと対比して注目する話題として成り立たない。"}, "sentence_index": 6, "correct_answer": "マイクロ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "古いマイクロで、簡単なプログラムを組んだ。", "explanation": "ここは〈マイコン〉（マイクロコンピュータ）の意味。マイクロ（とても小さい）は機械の名前ではないので、マイコンの代わりには合わない。"}, {"text": "池の水には、マイクロがたくさんいる。", "explanation": "ここは〈微生物〉の意味。マイクロは生き物を指す名詞ではないので、微生物の代わりにはならない。"}, {"text": "マイクロの水が、ダムからいっきに流れ出した。", "explanation": "ここは〈大量〉の意味（量が多い）。マイクロは大きさを表す語で、量の多さは示せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ff88f66-a23a-43b4-812c-c0d92e99400c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39478, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "マイクロを視点で、細胞の中の動きを確かめた。", "corrected_sentence": "マイクロの視点で、細胞の中の動きを確かめた。", "error_description": "「マイクロ」に続けるのは「の」（マイクロの視点）。「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ff88f66-a23a-43b4-812c-c0d92e99400c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39478, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "顕微鏡を使えば、マイクロ変化をはっきり見分けられる。", "corrected_sentence": "顕微鏡を使えば、マイクロの変化をはっきり見分けられる。", "error_description": "「マイクロ」が名詞を修飾するには「の」（マイクロの変化）が必要。「の」が抜けている。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ff88f66-a23a-43b4-812c-c0d92e99400c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
