INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39479, 3, 'prompt1_core', '{"pos": "接頭辞", "semantic_class": "function", "definition": "「マイクロ」は、非常に小さい、あるいは100万分の1を表す接頭語です。", "primary_collocate": null, "pronunciation": "まいくろ", "ipa": "maikɯɾo", "syllable_count": 4, "sentences": [{"text": "「マイクロ」は、百万分の一を表す言葉です。", "target_word": "マイクロ", "complexity_tier": "T3", "furigana": "「マイクロ」は、百万[ひゃくまん]分[ぶん]の一[いち]を表[あらわ]す言葉[ことば]です。", "sentence_source": "generated"}, {"text": "単位の前に「マイクロ」をつけると、百万分の一の大きさを表します。", "target_word": "マイクロ", "complexity_tier": "T3", "furigana": "単位[たんい]の前[まえ]に「マイクロ[まいくろ]」をつけると、百万分[ひゃくまんぶん]の一[いち]の大[おお]きさを表[あらわ]します。", "sentence_source": "generated"}, {"text": "「マイクロ」は、単位の前につく接頭語です。", "target_word": "マイクロ", "complexity_tier": "T3", "furigana": "「マイクロ[まいくろ]」は、単位[たんい]の前[まえ]につく接頭語[せっとうご]です。", "sentence_source": "generated"}, {"text": "「マイクロ」は、とても小さいものの大きさを表す接頭語です。", "target_word": "マイクロ", "complexity_tier": "T3", "furigana": "「マイクロ[まいくろ]」は、とても小[ちい]さいものの大[おお]きさを表[あらわ]す接頭語[せっとうご]です。", "sentence_source": "generated"}, {"text": "「マイクロ」の付いた単位は、ミリより小さい量をはかるときに使われます。", "target_word": "マイクロ", "complexity_tier": "T3", "furigana": "「マイクロ[まいくろ]」の付[つ]いた単位[たんい]は、ミリより小[ちい]さい量[りょう]をはかるときに使[つか]われます。", "sentence_source": "generated"}, {"text": "「マイクロ」は、千分の一の千分の一を表す接頭語です。", "target_word": "マイクロ", "complexity_tier": "T3", "furigana": "「マイクロ[まいくろ]」は、千分[せんぶん]の一[いち]の千分[せんぶん]の一[いち]を表[あらわ]す接頭語[せっとうご]です。", "sentence_source": "generated"}, {"text": "「マイクロ」は、百万分の一グラムを表すときにも使われます。", "target_word": "マイクロ", "complexity_tier": "T3", "furigana": "「マイクロ[まいくろ]」は、百万分[ひゃくまんぶん]の一[いち]グラムを表[あらわ]すときにも使[つか]われます。", "sentence_source": "generated"}, {"text": "「マイクロ」は、接頭語なので、単独では単位になりません。", "target_word": "マイクロ", "complexity_tier": "T3", "furigana": "「マイクロ[まいくろ]」は、接頭語[せっとうご]なので、単独[たんどく]では単位[たんい]になりません。", "sentence_source": "generated"}, {"text": "「マイクロ」は、「ミクロ」と同じ使い方をされることもある接頭語です。", "target_word": "マイクロ", "complexity_tier": "T3", "furigana": "「マイクロ[まいくろ]」は、「ミクロ」と同[おな]じ使[つか]い方[かた]をされることもある接頭語[せっとうご]です。", "sentence_source": "generated"}, {"text": "「マイクロ」は、「ミリ」より小さく「ナノ」より大きい単位を作る接頭語です。", "target_word": "マイクロ", "complexity_tier": "T3", "furigana": "「マイクロ[まいくろ]」は、「ミリ」より小[ちい]さく「ナノ」より大[おお]きい単位[たんい]を作[つく]る接頭語[せっとうご]です。", "sentence_source": "generated"}], "morphological_forms": [{"form": "マイクロ", "label": "基本形"}], "register": "科学・技術の説明文", "sense_fingerprint": "単位や名詞の前に付いて、非常に小さい・百万分の一を表す接頭語", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa11b1da-6a01-497b-ba17-85963d2f0c23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39479, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ミリ", "is_correct": false, "explanation": "ミリは千分の一を表す接頭語で、百万分の一の説明には合わない。"}, {"text": "マイクロ", "is_correct": true, "explanation": "百万分の一を表す接頭語はマイクロ。空欄に入るのはこの語だけ。"}, {"text": "キロ", "is_correct": false, "explanation": "キロは千倍を表す接頭語で、百万分の一とは逆の意味。"}, {"text": "センチ", "is_correct": false, "explanation": "センチは百分の一を表す接頭語で、百万分の一とは桁が違う。"}], "explanations": {"ミリ": "ミリは千分の一を表す接頭語で、百万分の一の説明には合わない。", "マイクロ": "百万分の一を表す接頭語はマイクロ。空欄に入るのはこの語だけ。", "キロ": "キロは千倍を表す接頭語で、百万分の一とは逆の意味。", "センチ": "センチは百分の一を表す接頭語で、百万分の一とは桁が違う。"}, "sentence_index": 0, "correct_answer": "マイクロ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "「マイクロ」は、千分の一を表す接頭語です。", "explanation": "ここは〈ミリ〉（千分の一）の意味。マイクロは百万分の一を表すので合わない。"}, {"text": "「マイクロ」は、十億分の一を表す接頭語です。", "explanation": "ここは〈ナノ〉の意味（十億分の一）。マイクロは百万分の一なので合わない。"}, {"text": "「マイクロ」は、千倍の大きさを表す接頭語です。", "explanation": "ここは〈キロ〉の意味（千倍）。マイクロは小さい方の単位なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ff88f66-a23a-43b4-812c-c0d92e99400c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39479, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "デシ", "is_correct": false, "explanation": "デシは十分の一を表す接頭語で、百万分の一グラムの説明には合わない。"}, {"text": "ヘクト", "is_correct": false, "explanation": "ヘクトは百倍を表す接頭語で、小さい方の単位には合わない。"}, {"text": "マイクロ", "is_correct": true, "explanation": "百万分の一グラムを表すときに使われる接頭語はマイクロ。ここに入るのはこの語だけ。"}, {"text": "メガ", "is_correct": false, "explanation": "メガは百万倍を表す接頭語で、百万分の一とは逆の意味。"}], "explanations": {"デシ": "デシは十分の一を表す接頭語で、百万分の一グラムの説明には合わない。", "ヘクト": "ヘクトは百倍を表す接頭語で、小さい方の単位には合わない。", "マイクロ": "百万分の一グラムを表すときに使われる接頭語はマイクロ。ここに入るのはこの語だけ。", "メガ": "メガは百万倍を表す接頭語で、百万分の一とは逆の意味。"}, "sentence_index": 6, "correct_answer": "マイクロ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "「マイクロ」は、十分の一を表す接頭語です。", "explanation": "ここは〈デシ〉の意味（十分の一）。マイクロは百万分の一なので合わない。"}, {"text": "「マイクロ」は、十億倍を表す接頭語です。", "explanation": "ここは〈ギガ〉の意味（十億倍）。マイクロは小さい側の接頭語なので逆になる。"}, {"text": "「マイクロ」は、単独で単位として使われる言葉です。", "explanation": "ここは〈メートル〉や〈グラム〉のように単独で単位になる語の意味。マイクロは接頭語なので、単独では単位にならず合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ff88f66-a23a-43b4-812c-c0d92e99400c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39479, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "マイクロに単位で、細胞の大きさをはかる。", "corrected_sentence": "マイクロの単位で、細胞の大きさをはかる。", "error_description": "「マイクロ」に続けるのは「の」（マイクロの単位）。「に」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ff88f66-a23a-43b4-812c-c0d92e99400c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39479, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "マイクロ分は、一秒の百万分の一です。", "corrected_sentence": "マイクロ秒は、一秒の百万分の一です。", "error_description": "「マイクロ」は「秒」と組んで「マイクロ秒」になる。「分」では単位が合わず、一秒の百万分の一という説明とも矛盾する。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ff88f66-a23a-43b4-812c-c0d92e99400c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39480, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「出す」の対象を示す「を」で、「グリッドを出す」と続く。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞どうしをつなぐため、「グリッドの出すと」は動詞に続かず成り立たない。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すが、「出す」は「を」を目的語に取るので、「グリッドが出す」は成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を示すため、「グリッドと出す」とは続かない。"}], "correct_answer": "を", "explanations": {"を": "「出す」の対象を示す「を」で、「グリッドを出す」と続く。", "の": "「の」は名詞どうしをつなぐため、「グリッドの出すと」は動詞に続かず成り立たない。", "が": "「が」は主語を示すが、「出す」は「を」を目的語に取るので、「グリッドが出す」は成り立たない。", "と": "「と」は並列や相手を示すため、「グリッドと出す」とは続かない。"}, "error_tags": {"の": "修飾・所属", "が": "主語", "と": "並列・相手"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f99bd40-4f88-46e8-ae62-05411a60de0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39480, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「グリッドの線」と名詞をつなぐ「の」で、文が成り立つ。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示すので、「グリッドを線」のように名詞の間には入らない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示すため、「グリッドで線」とは続かない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、「グリッドへ線」は成り立たない。"}], "correct_answer": "の", "explanations": {"の": "「グリッドの線」と名詞をつなぐ「の」で、文が成り立つ。", "を": "「を」は目的語を示すので、「グリッドを線」のように名詞の間には入らない。", "で": "「で」は手段や場所を示すため、「グリッドで線」とは続かない。", "へ": "「へ」は方向を示すので、「グリッドへ線」は成り立たない。"}, "error_tags": {"を": "目的語", "で": "手段・場所", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f99bd40-4f88-46e8-ae62-05411a60de0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39480, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "ものをまっすぐに区切った線のことです。", "primary_collocate": null, "pronunciation": "ぐりっど", "ipa": "ɡɯɾiddo", "syllable_count": 4, "sentences": [{"text": "紙に鉛筆でグリッドを引いてから、絵を描きます。", "target_word": "グリッド", "complexity_tier": "T3", "furigana": "紙[かみ]に鉛筆[えんぴつ]でグリッドを引[ひ]いてから、絵[え]を描[か]きます。", "sentence_source": "generated"}, {"text": "写真にグリッドを出すと、まっすぐ撮れたか確認できます。", "target_word": "グリッド", "complexity_tier": "T3", "furigana": "写真[しゃしん]にグリッドを出[だ]すと、まっすぐ撮[と]れたか確認[かくにん]できます。", "sentence_source": "generated"}, {"text": "このノートは小さなグリッドがあって、図を書きやすいです。", "target_word": "グリッド", "complexity_tier": "T3", "furigana": "このノートは小[ちい]さなグリッドがあって、図[ず]を書[か]きやすいです。", "sentence_source": "generated"}, {"text": "グリッドに合わせて文字を並べると、きれいに見えます。", "target_word": "グリッド", "complexity_tier": "T3", "furigana": "グリッドに合[あ]わせて文字[もじ]を並[なら]べると、きれいに見[み]えます。", "sentence_source": "generated"}, {"text": "カメラの画面にグリッドが出ていて、水平がわかります。", "target_word": "グリッド", "complexity_tier": "T3", "furigana": "カメラの画面[がめん]にグリッドが出[で]ていて、水平[すいへい]がわかります。", "sentence_source": "generated"}, {"text": "地図にグリッドを引いて、場所を番号で調べました。", "target_word": "グリッド", "complexity_tier": "T3", "furigana": "地図[ちず]にグリッドを引[ひ]いて、場所[ばしょ]を番号[ばんごう]で調[しら]べました。", "sentence_source": "generated"}, {"text": "デザインの時は、まずグリッドを決めます。", "target_word": "グリッド", "complexity_tier": "T3", "furigana": "デザインの時[とき]は、まずグリッドを決[き]めます。", "sentence_source": "generated"}, {"text": "グリッドの線が細すぎて、印刷すると見えませんでした。", "target_word": "グリッド", "complexity_tier": "T3", "furigana": "グリッドの線[せん]が細[ほそ]すぎて、印刷[いんさつ]すると見[み]えませんでした。", "sentence_source": "generated"}, {"text": "先生は黒板にグリッドを書いて、点の場所を教えました。", "target_word": "グリッド", "complexity_tier": "T3", "furigana": "先生[せんせい]は黒板[こくばん]にグリッドを書[か]いて、点[てん]の場所[ばしょ]を教[おし]えました。", "sentence_source": "generated"}, {"text": "画面のグリッドを消すと、すっきり見えます。", "target_word": "グリッド", "complexity_tier": "T3", "furigana": "画面[がめん]のグリッドを消[け]すと、すっきり見[み]えます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "グリッド", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "紙や画面に引く、位置をそろえるための区切り線", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2b6e36a-9597-4ba4-89df-d93b59e9ae30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39480, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "グリッド", "is_correct": true, "explanation": "紙に引く規則正しい区切り線の集まりを指し、「鉛筆でグリッドを引く」と自然に続く。"}, {"text": "ルーラー", "is_correct": false, "explanation": "定規のことで、線を引く道具であって引かれる線の集まりではないので合わない。"}, {"text": "シール", "is_correct": false, "explanation": "貼り付けるものなので、鉛筆で引く対象にはならないので合わない。"}, {"text": "インク", "is_correct": false, "explanation": "色を付ける液体で、「インクを引く」は線を引く対象として成り立たない。"}], "explanations": {"グリッド": "紙に引く規則正しい区切り線の集まりを指し、「鉛筆でグリッドを引く」と自然に続く。", "ルーラー": "定規のことで、線を引く道具であって引かれる線の集まりではないので合わない。", "シール": "貼り付けるものなので、鉛筆で引く対象にはならないので合わない。", "インク": "色を付ける液体で、「インクを引く」は線を引く対象として成り立たない。"}, "sentence_index": 0, "correct_answer": "グリッド"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "玄関のグリッドを閉めて、外に出ました。", "explanation": "ここは〈ドア〉の意味。戸を閉める対象はドアで、区切り線のグリッドは閉められないので合わない。"}, {"text": "レンガのグリッドを積んで、小さな花壇を作りました。", "explanation": "ここは〈ブロック〉の意味。積み上げる部品を指す語で、区切り線の集まりであるグリッドは積めないので合わない。"}, {"text": "週末にグリッドを磨いて、部屋が明るくなりました。", "explanation": "ここは〈窓〉の意味。磨く対象は窓ガラスで、区切り線のグリッドは磨けないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f99bd40-4f88-46e8-ae62-05411a60de0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39480, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "グリッド", "is_correct": true, "explanation": "デザインで最初に決める区切り線の基準を指し、「まずグリッドを決めます」と自然に続く。"}, {"text": "にじみ", "is_correct": false, "explanation": "インクが広がる現象で、決めるものではないので「にじみを決める」は成り立たない。"}, {"text": "かすれ", "is_correct": false, "explanation": "線や文字が薄く途切れる状態で、決める対象にはならないので合わない。"}, {"text": "ゆがみ", "is_correct": false, "explanation": "形がくずれる状態で、決める対象にはならないので合わない。"}], "explanations": {"グリッド": "デザインで最初に決める区切り線の基準を指し、「まずグリッドを決めます」と自然に続く。", "にじみ": "インクが広がる現象で、決めるものではないので「にじみを決める」は成り立たない。", "かすれ": "線や文字が薄く途切れる状態で、決める対象にはならないので合わない。", "ゆがみ": "形がくずれる状態で、決める対象にはならないので合わない。"}, "sentence_index": 6, "correct_answer": "グリッド"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "カメラのグリッドを押すと、写真が撮れます。", "explanation": "ここは〈ボタン〉の意味。押す対象はボタンで、区切り線のグリッドは押せないので合わない。"}, {"text": "メールのグリッドを開くと、本文が読めます。", "explanation": "ここは〈ページ〉の意味。開くものは画面のページで、区切り線のグリッドは開けないので合わない。"}, {"text": "写真のグリッドを拭いて、きれいにしました。", "explanation": "ここは〈汚れ〉の意味。拭き取るのは汚れで、区切り線のグリッドは拭けないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f99bd40-4f88-46e8-ae62-05411a60de0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39480, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この表はグリッドを細かく、文字が読みにくいです。", "corrected_sentence": "この表はグリッドが細かく、文字が読みにくいです。", "error_description": "誤った形は「グリッドを」、正しい形は「グリッドが」。「細かい」の主語は「が」で示すので、「を」は合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f99bd40-4f88-46e8-ae62-05411a60de0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39480, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "このシートのグリッドは深くて、文字が見えにくいです。", "corrected_sentence": "このシートのグリッドは細かくて、文字が見えにくいです。", "error_description": "誤った形は「深くて」、正しい形は「細かくて」。線の間隔を表すには「細かい」と組むので、「深い」は合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f99bd40-4f88-46e8-ae62-05411a60de0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39481, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "場所や範囲を示す「に」で、「方眼紙のグリッドに色をぬる」と続く。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示すが、後ろに「色を」があるため二重になり不自然。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を示すため、「グリッドと、一マスずつ」は文として続かない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞どうしをつなぐが、ここでは後ろの動詞に続かないので合わない。"}], "correct_answer": "に", "explanations": {"に": "場所や範囲を示す「に」で、「方眼紙のグリッドに色をぬる」と続く。", "を": "「を」は目的語を示すが、後ろに「色を」があるため二重になり不自然。", "と": "「と」は並列や相手を示すため、「グリッドと、一マスずつ」は文として続かない。", "の": "「の」は名詞どうしをつなぐが、ここでは後ろの動詞に続かないので合わない。"}, "error_tags": {"を": "目的語", "と": "並列・相手", "の": "修飾・所属"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f99bd40-4f88-46e8-ae62-05411a60de0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39481, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「使う」の対象を示す「を」で、「グリッドを使って」と続く。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を示すため、「グリッドと使って」は文として続かない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すため、「グリッドへ使って」とは続かない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点や理由を示すため、「グリッドから使って」は意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "「使う」の対象を示す「を」で、「グリッドを使って」と続く。", "と": "「と」は並列や相手を示すため、「グリッドと使って」は文として続かない。", "へ": "「へ」は方向を示すため、「グリッドへ使って」とは続かない。", "から": "「から」は起点や理由を示すため、「グリッドから使って」は意味が通らない。"}, "error_tags": {"と": "並列・相手", "へ": "方向", "から": "起点・理由"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f99bd40-4f88-46e8-ae62-05411a60de0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39481, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "物や場所を規則正しく区切るための、縦と横の線の集まり。", "primary_collocate": null, "pronunciation": "ぐりっど", "ipa": "ɡɯɾiddo", "syllable_count": 4, "sentences": [{"text": "この町は道がグリッドのように、縦と横に並んでいます。", "target_word": "グリッド", "complexity_tier": "T3", "furigana": "この町[まち]は道[みち]がグリッドのように、縦[たて]と横[よこ]に並[なら]んでいます。", "sentence_source": "generated"}, {"text": "方眼紙のグリッドに、一マスずつ色をぬりました。", "target_word": "グリッド", "complexity_tier": "T3", "furigana": "方眼紙[ほうがんし]のグリッドに、一[ひと]マスずつ色[いろ]をぬりました。", "sentence_source": "generated"}, {"text": "ゲームの盤はグリッドになっていて、駒は一マスずつ動きます。", "target_word": "グリッド", "complexity_tier": "T3", "furigana": "ゲームの盤[ばん]はグリッドになっていて、駒[こま]は一[ひと]マスずつ動[うご]きます。", "sentence_source": "generated"}, {"text": "グリッドの交わる所に、小さな点を打ちました。", "target_word": "グリッド", "complexity_tier": "T3", "furigana": "グリッドの交[まじ]わる所[ところ]に、小[ちい]さな点[てん]を打[う]ちました。", "sentence_source": "generated"}, {"text": "ビルの窓がグリッドのように並んでいて、きれいです。", "target_word": "グリッド", "complexity_tier": "T3", "furigana": "ビルの窓[まど]がグリッドのように並[なら]んでいて、きれいです。", "sentence_source": "generated"}, {"text": "表のグリッドを大きくして、文字を入れやすくしました。", "target_word": "グリッド", "complexity_tier": "T3", "furigana": "表[ひょう]のグリッドを大[おお]きくして、文字[もじ]を入[い]れやすくしました。", "sentence_source": "generated"}, {"text": "都市計画では、道をグリッドにすると、迷いにくくなります。", "target_word": "グリッド", "complexity_tier": "T3", "furigana": "都市計画[としけいかく]では、道[みち]をグリッドにすると、迷[まよ]いにくくなります。", "sentence_source": "generated"}, {"text": "グリッドを使って、部屋の家具の場所を決めました。", "target_word": "グリッド", "complexity_tier": "T3", "furigana": "グリッドを使[つか]って、部屋[へや]の家具[かぐ]の場所[ばしょ]を決[き]めました。", "sentence_source": "generated"}, {"text": "この地図はグリッドごとに番号が付いています。", "target_word": "グリッド", "complexity_tier": "T3", "furigana": "この地図[ちず]はグリッドごとに番号[ばんごう]が付[つ]いています。", "sentence_source": "generated"}, {"text": "画面をグリッドに分けて、写真を九枚並べました。", "target_word": "グリッド", "complexity_tier": "T3", "furigana": "画面[がめん]をグリッドに分[わ]けて、写真[しゃしん]を九枚[きゅうまい]並[なら]べました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "グリッド", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "縦横の線でできた碁盤目状の区切り(道・盤・方眼)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2b6e36a-9597-4ba4-89df-d93b59e9ae30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39481, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "グリッド", "is_correct": true, "explanation": "縦と横に規則正しく並ぶ碁盤目状の配置を指し、「道がグリッドのように並んでいる」と自然に続く。"}, {"text": "ピラミッド", "is_correct": false, "explanation": "三角形に積んだ形で、縦と横に規則的に並ぶ配置とは合わないので不適切。"}, {"text": "らせん", "is_correct": false, "explanation": "渦を巻く形で、縦と横に並ぶ配置を表さないので合わない。"}, {"text": "ドーナツ", "is_correct": false, "explanation": "輪の形で、道が縦と横に並ぶ様子には当てはまらない。"}], "explanations": {"グリッド": "縦と横に規則正しく並ぶ碁盤目状の配置を指し、「道がグリッドのように並んでいる」と自然に続く。", "ピラミッド": "三角形に積んだ形で、縦と横に規則的に並ぶ配置とは合わないので不適切。", "らせん": "渦を巻く形で、縦と横に並ぶ配置を表さないので合わない。", "ドーナツ": "輪の形で、道が縦と横に並ぶ様子には当てはまらない。"}, "sentence_index": 0, "correct_answer": "グリッド"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "懐中電灯のグリッドが切れて、部屋が真っ暗になりました。", "explanation": "ここは〈電池〉の意味。電気を蓄える電池は切れるが、区切り線のグリッドには合わない。"}, {"text": "ゲーム機のグリッドを押すと、キャラクターが跳びます。", "explanation": "ここは〈ボタン〉の意味。押す対象はボタンで、碁盤目状の配置を表すグリッドは押せないので合わない。"}, {"text": "辞書のグリッドを開くと、言葉の意味がわかります。", "explanation": "ここは〈ページ〉の意味。開くのは本のページで、碁盤目状の配置を表すグリッドは開けないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f99bd40-4f88-46e8-ae62-05411a60de0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39481, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "グリッド", "is_correct": true, "explanation": "道を縦と横に規則正しく並べる配置を表し、迷いにくくするという文脈に合う。"}, {"text": "ドーム", "is_correct": false, "explanation": "丸い屋根の形で、道の配置を言う文には合わないので不適切。"}, {"text": "パズル", "is_correct": false, "explanation": "ピースをはめる遊びで、道の並べ方を表す語ではないので合わない。"}, {"text": "ハート", "is_correct": false, "explanation": "心の形で、道を迷いにくくするという理屈には合わない。"}], "explanations": {"グリッド": "道を縦と横に規則正しく並べる配置を表し、迷いにくくするという文脈に合う。", "ドーム": "丸い屋根の形で、道の配置を言う文には合わないので不適切。", "パズル": "ピースをはめる遊びで、道の並べ方を表す語ではないので合わない。", "ハート": "心の形で、道を迷いにくくするという理屈には合わない。"}, "sentence_index": 6, "correct_answer": "グリッド"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "グリッドに向かって、ゆっくり話しました。", "explanation": "ここは〈マイク〉の意味。話しかける対象はマイクや人で、区切り線のグリッドには話しかけられないので合わない。"}, {"text": "グリッドを右に切ると、車が曲がります。", "explanation": "ここは〈ハンドル〉の意味。車を曲げるのはハンドルで、区切り線のグリッドは切れないので合わない。"}, {"text": "グリッドを上げると、音が大きくなります。", "explanation": "ここは〈ボリューム〉の意味。音の大きさを変える語で、区切り線のグリッドは音量にならないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f99bd40-4f88-46e8-ae62-05411a60de0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39481, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "表をグリッドを分けて、文字を入れました。", "corrected_sentence": "表をグリッドに分けて、文字を入れました。", "error_description": "誤った形は「グリッドを」、正しい形は「グリッドに」。「分ける」の場所は「に」で示すので、「を」が二重になり誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f99bd40-4f88-46e8-ae62-05411a60de0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39481, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "庭の敷石がグリッドにように並んでいて、歩きやすいです。", "corrected_sentence": "庭の敷石がグリッドのように並んでいて、歩きやすいです。", "error_description": "誤った形は「グリッドにように」、正しい形は「グリッドのように」。比喩の「〜のように」は「の」で名詞につなぐ。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f99bd40-4f88-46e8-ae62-05411a60de0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
