INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39482, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "平らで、でこぼこがないこと。", "primary_collocate": null, "pronunciation": "ふらっと", "ipa": "ɸɯɾatto", "syllable_count": 4, "sentences": [{"text": "この道はフラットなので、自転車でも走りやすいです。", "target_word": "フラット", "complexity_tier": "T3", "furigana": "この道[みち]はフラットなので、自転車[じてんしゃ]でも走[はし]りやすいです。", "sentence_source": "generated"}, {"text": "フラットな床だから、ロボットが止まらずに動けます。", "target_word": "フラット", "complexity_tier": "T3", "furigana": "フラットな床[ゆか]だから、ロボットが止[と]まらずに動[うご]けます。", "sentence_source": "generated"}, {"text": "山の上に、フラットな広場がありました。", "target_word": "フラット", "complexity_tier": "T3", "furigana": "山[やま]の上[うえ]に、フラットな広場[ひろば]がありました。", "sentence_source": "generated"}, {"text": "フラットな場所を探して、テントを立てました。", "target_word": "フラット", "complexity_tier": "T3", "furigana": "フラットな場所[ばしょ]を探[さが]して、テントを立[た]てました。", "sentence_source": "generated"}, {"text": "机の上がフラットでないと、ボールが転がってしまいます。", "target_word": "フラット", "complexity_tier": "T3", "furigana": "机[つくえ]の上[うえ]がフラットでないと、ボールが転[ころ]がってしまいます。", "sentence_source": "generated"}, {"text": "雪をふんで、地面をフラットにしました。", "target_word": "フラット", "complexity_tier": "T3", "furigana": "雪[ゆき]をふんで、地面[じめん]をフラットにしました。", "sentence_source": "generated"}, {"text": "このコースは坂がなく、ほとんどフラットです。", "target_word": "フラット", "complexity_tier": "T3", "furigana": "このコースは坂[さか]がなく、ほとんどフラットです。", "sentence_source": "generated"}, {"text": "フラットな屋根には、雨がたまりやすいです。", "target_word": "フラット", "complexity_tier": "T3", "furigana": "フラットな屋根[やね]には、雨[あめ]がたまりやすいです。", "sentence_source": "generated"}, {"text": "ベッドの下がフラットなので、箱をしまえます。", "target_word": "フラット", "complexity_tier": "T3", "furigana": "ベッドの下[した]がフラットなので、箱[はこ]をしまえます。", "sentence_source": "generated"}, {"text": "工事のあとで、庭がフラットになりました。", "target_word": "フラット", "complexity_tier": "T3", "furigana": "工事[こうじ]のあとで、庭[にわ]がフラットになりました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "フラットな", "label": "連体形"}, {"form": "フラットに", "label": "連用形"}, {"form": "フラットで", "label": "中止形"}], "register": "neutral", "sense_fingerprint": "地面・床・面が平らででこぼこしていない様子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2b6e36a-9597-4ba4-89df-d93b59e9ae30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39482, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "フラット", "is_correct": true, "explanation": "「平らで走りやすい道」の意味にあい、文脈に合う。"}, {"text": "ゴツゴツ", "is_correct": false, "explanation": "表面が荒く凸凹した様子を表し、「走りやすい」と矛盾する。"}, {"text": "でこぼこ", "is_correct": false, "explanation": "凹凸がある意味で、平らな道を言う文には入らない。"}, {"text": "急勾配", "is_correct": false, "explanation": "坂が急なことを表し、「坂がなく平ら」という文脈と逆になる。"}], "explanations": {"フラット": "「平らで走りやすい道」の意味にあい、文脈に合う。", "ゴツゴツ": "表面が荒く凸凹した様子を表し、「走りやすい」と矛盾する。", "でこぼこ": "凹凸がある意味で、平らな道を言う文には入らない。", "急勾配": "坂が急なことを表し、「坂がなく平ら」という文脈と逆になる。"}, "sentence_index": 0, "correct_answer": "フラット"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ごはんがフラットに炊けて、とてもおいしかったです。", "explanation": "ここは〈ふっくら（ふくらんでやわらかい）〉の意味。炊き上がりの食感には〈ふっくら〉を使い、〈フラット〉は面が平らなことを指すので合わない。"}, {"text": "ポテトがフラットに揚がって、カリッとしていました。", "explanation": "ここは〈カリッと（表面が硬く香ばしい）〉の意味。揚げ物の食感には〈カリッと〉を使い、〈フラット〉は面の平らさを表す語なので合わない。"}, {"text": "石けんの泡がフラットで、肌にやさしいです。", "explanation": "ここは〈なめらか・きめ細かい〉の意味。泡や肌の感触には〈なめらか〉を使い、フラットは面の平らさを指す。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f99bd40-4f88-46e8-ae62-05411a60de0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39482, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "フラット", "is_correct": true, "explanation": "「ほとんど平ら」という文脈に合う。"}, {"text": "ボコボコ", "is_correct": false, "explanation": "凸凹が多い様子で、「ほとんどフラット」と矛盾する。"}, {"text": "がたがた", "is_correct": false, "explanation": "揺れてがたつく様子で、坂がなく平らという文脈と合わない。"}, {"text": "起伏だらけ", "is_correct": false, "explanation": "高低差が多いことを表し、「坂がなく」と逆になる。"}], "explanations": {"フラット": "「ほとんど平ら」という文脈に合う。", "ボコボコ": "凸凹が多い様子で、「ほとんどフラット」と矛盾する。", "がたがた": "揺れてがたつく様子で、坂がなく平らという文脈と合わない。", "起伏だらけ": "高低差が多いことを表し、「坂がなく」と逆になる。"}, "sentence_index": 6, "correct_answer": "フラット"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "寝ぐせで髪がフラットになってしまい、直すのに時間がかかりました。", "explanation": "ここは〈ぺたんこ（髪がつぶれて立たない）〉の意味。つぶれた髪には〈ぺたんこ〉を使い、〈フラット〉は面が平らなことを表す語なので合わない。"}, {"text": "マスクのゴムが、フラットに伸びてしまいました。", "explanation": "ここは〈伸びる（伸縮する）〉の意味。ゴムの伸び縮みは〈伸びる〉で言い、〈フラット〉は面の平らさを表す語なので合わない。"}, {"text": "ひざのけががフラットに治って、もう痛くありません。", "explanation": "ここは〈治る（回復する）〉の意味。傷の回復は〈治る〉で言い、〈フラット〉は面の平らさを表す語なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f99bd40-4f88-46e8-ae62-05411a60de0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39482, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この公園の地面はフラットに、子どもが遊びやすいです。", "corrected_sentence": "この公園の地面はフラットで、子どもが遊びやすいです。", "error_description": "「フラットで」（中止形）が正しいのに「フラットに」（連用形）を使っており、後ろに続く文の形が成り立たない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "フラット", "is_correct": true, "explanation": "文中の「フラットな」の語幹となる基本の形。"}, {"text": "フラットに", "is_correct": false, "explanation": "連用形で、名詞「床」を修飾する形ではない。"}, {"text": "フラットで", "is_correct": false, "explanation": "中止形で、名詞の前に置いて「床」を修飾できない。"}, {"text": "フラットだ", "is_correct": false, "explanation": "断定形で、「床」を直接修飾する位置には入らない。"}], "correct_form": "フラット", "base_form": "フラット", "form_label": "語幹", "sentence_index": 1, "explanations": {"フラット": "文中の「フラットな」の語幹となる基本の形。", "フラットに": "連用形で、名詞「床」を修飾する形ではない。", "フラットで": "中止形で、名詞の前に置いて「床」を修飾できない。", "フラットだ": "断定形で、「床」を直接修飾する位置には入らない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f99bd40-4f88-46e8-ae62-05411a60de0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39482, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この広場の地面はフラットを、ボールを投げやすいです。", "corrected_sentence": "この広場の地面はフラットで、ボールを投げやすいです。", "error_description": "「フラット」は状態を述べる語なので、目的語の「を」ではなく「で」（中止形）で続けるのが正しい。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "フラット", "is_correct": true, "explanation": "文中の「フラットな」の語幹となる基本の形。"}, {"text": "フラットさ", "is_correct": false, "explanation": "名詞化した形で、「屋根」を直接修飾する位置には入らない。"}, {"text": "フラットだった", "is_correct": false, "explanation": "過去の断定形で、名詞「屋根」を直接修飾する位置には入らない。"}, {"text": "フラットでした", "is_correct": false, "explanation": "丁寧な過去形で、名詞「屋根」を修飾する位置には入らない。"}], "correct_form": "フラット", "base_form": "フラット", "form_label": "語幹", "sentence_index": 7, "explanations": {"フラット": "文中の「フラットな」の語幹となる基本の形。", "フラットさ": "名詞化した形で、「屋根」を直接修飾する位置には入らない。", "フラットだった": "過去の断定形で、名詞「屋根」を直接修飾する位置には入らない。", "フラットでした": "丁寧な過去形で、名詞「屋根」を修飾する位置には入らない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f99bd40-4f88-46e8-ae62-05411a60de0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
