INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39483, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "平らで、凹凸がない状態。また、変化や差がなく、均一な様子。", "primary_collocate": null, "pronunciation": "ふらっと", "ipa": "ɸɯɾatto", "syllable_count": 4, "sentences": [{"text": "この会社は上下関係がフラットで、だれでも意見を言えます。", "target_word": "フラット", "complexity_tier": "T3", "furigana": "この会社[かいしゃ]は上下関係[じょうげかんけい]がフラットで、だれでも意見[いけん]を言[い]えます。", "sentence_source": "generated"}, {"text": "来月から、料金がフラットになって、だれでも同じ額を払います。", "target_word": "フラット", "complexity_tier": "T3", "furigana": "来月[らいげつ]から、料金[りょうきん]がフラットになって、だれでも同じ額[がく]を払[はら]います。", "sentence_source": "generated"}, {"text": "グラフを見ると、売り上げはずっとフラットです。", "target_word": "フラット", "complexity_tier": "T3", "furigana": "グラフを見[み]ると、売[う]り上[あ]げはずっとフラットです。", "sentence_source": "generated"}, {"text": "フラットな関係の友だちとは、気軽に話せます。", "target_word": "フラット", "complexity_tier": "T3", "furigana": "フラットな関係[かんけい]の友[とも]だちとは、気軽[きがる]に話[はな]せます。", "sentence_source": "generated"}, {"text": "この学年は点数がフラットで、クラスの中に目立つ成績の子がいません。", "target_word": "フラット", "complexity_tier": "T3", "furigana": "この学年[がくねん]は点数[てんすう]がフラットで、クラスの中[なか]に目立[めだ]つ成績[せいせき]の子[こ]がいません。", "sentence_source": "generated"}, {"text": "彼は怒っても笑っても、声がフラットで気持ちがわかりません。", "target_word": "フラット", "complexity_tier": "T3", "furigana": "彼[かれ]は怒[おこ]っても笑[わら]っても、声[こえ]がフラットで気持[きも]ちがわかりません。", "sentence_source": "generated"}, {"text": "この店はどの席も料金がフラットで、前でも後ろでも同じです。", "target_word": "フラット", "complexity_tier": "T3", "furigana": "この店[みせ]はどの席[せき]も料金[りょうきん]がフラットで、前[まえ]でも後[うし]ろでも同[おな]じです。", "sentence_source": "generated"}, {"text": "先生と生徒がフラットに話す授業は、人気があります。", "target_word": "フラット", "complexity_tier": "T3", "furigana": "先生[せんせい]と生徒[せいと]がフラットに話[はな]す授業[じゅぎょう]は、人気[にんき]があります。", "sentence_source": "generated"}, {"text": "物価がフラットな状態が続いていて、値段もほとんど変わりません。", "target_word": "フラット", "complexity_tier": "T3", "furigana": "物価[ぶっか]がフラットな状態[じょうたい]が続[つづ]いていて、値段[ねだん]もほとんど変[か]わりません。", "sentence_source": "generated"}, {"text": "テーブルをフラットにすると、広く使えます。", "target_word": "フラット", "complexity_tier": "T3", "furigana": "テーブルをフラットにすると、広[ひろ]く使[つか]えます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "フラットな", "label": "連体形"}, {"form": "フラットに", "label": "連用形"}, {"form": "フラットで", "label": "中止形"}], "register": "neutral", "sense_fingerprint": "平らな状態、または変化・差・上下がなく均一な様子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2b6e36a-9597-4ba4-89df-d93b59e9ae30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39483, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "フラット", "is_correct": true, "explanation": "「上下関係に差がない」の意味にあい、文脈に合う。"}, {"text": "厳格", "is_correct": false, "explanation": "規則が厳しい意味で、だれでも意見を言える状況と逆になる。"}, {"text": "不規則", "is_correct": false, "explanation": "決まりがばらばらな意味で、「だれでも意見を言える」と矛盾する。"}, {"text": "固定的", "is_correct": false, "explanation": "変わらず決まっている意味で、上下関係の差がないという文脈と合わない。"}], "explanations": {"フラット": "「上下関係に差がない」の意味にあい、文脈に合う。", "厳格": "規則が厳しい意味で、だれでも意見を言える状況と逆になる。", "不規則": "決まりがばらばらな意味で、「だれでも意見を言える」と矛盾する。", "固定的": "変わらず決まっている意味で、上下関係の差がないという文脈と合わない。"}, "sentence_index": 0, "correct_answer": "フラット"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は走るのがフラットで、いつも一番遅いです。", "explanation": "ここは〈遅い〉の意味（別の語義）。走る速さは〈速い／遅い〉で言い、〈フラット〉は差がなく均一な様子を表すので合わない。"}, {"text": "このパンはフラットにふくらんで、ふわふわです。", "explanation": "ここは〈ふくらむ〉の意味。パンのふくらみには〈ふくらむ〉を使い、〈フラット〉は差がなく均一な様子を表すので合わない。"}, {"text": "お湯がフラットにわいて、湯気が出ました。", "explanation": "ここは〈わく〉の意味。お湯のわき方には〈わく〉を使い、〈フラット〉は均一な様子を表す語なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f99bd40-4f88-46e8-ae62-05411a60de0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39483, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "フラット", "is_correct": true, "explanation": "「どの席も料金が同じ」の意味に合う。"}, {"text": "差別的", "is_correct": false, "explanation": "差をつける意味で、「前でも後ろでも同じ」と矛盾する。"}, {"text": "変動的", "is_correct": false, "explanation": "変わる意味で、同じ料金という文脈と逆になる。"}, {"text": "不平等", "is_correct": false, "explanation": "差がある状態を表し、どの席も同じという文脈と合わない。"}], "explanations": {"フラット": "「どの席も料金が同じ」の意味に合う。", "差別的": "差をつける意味で、「前でも後ろでも同じ」と矛盾する。", "変動的": "変わる意味で、同じ料金という文脈と逆になる。", "不平等": "差がある状態を表し、どの席も同じという文脈と合わない。"}, "sentence_index": 6, "correct_answer": "フラット"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "パンを三つに、フラットに切りました。", "explanation": "ここは〈均等に切る〉の意味で、近い語は〈均等〉。〈フラット〉は差がない状態を言い、「切る」の仕方には使わない。"}, {"text": "新しい靴のかかとが、フラットに減って、歩きにくいです。", "explanation": "ここは〈すり減る〉の意味で、近い語は〈すり減る〉。〈フラット〉は均一な状態を言い、すり減り方には使わない。"}, {"text": "ラーメンのどんぶりがフラットに割れて、大変でした。", "explanation": "ここは〈割れる〉の意味で、近い語は〈割れる〉。〈フラット〉は均一な様子を言い、割れ方には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f99bd40-4f88-46e8-ae62-05411a60de0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39483, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この部署は上下関係がフラットに、新人も提案しやすいです。", "corrected_sentence": "この部署は上下関係がフラットで、新人も提案しやすいです。", "error_description": "「フラットで」（中止形）が正しいのに「フラットに」（連用形）を使った誤り。「〜で、〜」の形で続ける。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "フラット", "is_correct": true, "explanation": "文中の「フラットに」の語幹となる基本の形。"}, {"text": "フラットで", "is_correct": false, "explanation": "中止形で、「料金が」の述語として「なって」に続けられない。"}, {"text": "フラットだ", "is_correct": false, "explanation": "断定形で、「なって」に続ける形として合わない。"}, {"text": "フラットではない", "is_correct": false, "explanation": "否定形で、「料金がなって」の流れに合わない。"}], "correct_form": "フラット", "base_form": "フラット", "form_label": "語幹", "sentence_index": 1, "explanations": {"フラット": "文中の「フラットに」の語幹となる基本の形。", "フラットで": "中止形で、「料金が」の述語として「なって」に続けられない。", "フラットだ": "断定形で、「なって」に続ける形として合わない。", "フラットではない": "否定形で、「料金がなって」の流れに合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f99bd40-4f88-46e8-ae62-05411a60de0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39483, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この会員プランは料金がフラットを、利用回数に関係なく同じです。", "corrected_sentence": "この会員プランは料金がフラットで、利用回数に関係なく同じです。", "error_description": "「フラット」は状態を述べる語なので、「を」ではなく「で」（中止形）で続けるのが正しい。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "フラット", "is_correct": true, "explanation": "文中の「フラットに」の語幹となる基本の形。"}, {"text": "フラットだった", "is_correct": false, "explanation": "過去の断定形で、「話す」の修飾として合わない。"}, {"text": "フラットであった", "is_correct": false, "explanation": "文語的な過去形で、「話す」に続く形として不自然。"}, {"text": "フラットな", "is_correct": false, "explanation": "連体形で、「話す」を修飾する位置には「フラットに」の形が必要。"}], "correct_form": "フラット", "base_form": "フラット", "form_label": "語幹", "sentence_index": 7, "explanations": {"フラット": "文中の「フラットに」の語幹となる基本の形。", "フラットだった": "過去の断定形で、「話す」の修飾として合わない。", "フラットであった": "文語的な過去形で、「話す」に続く形として不自然。", "フラットな": "連体形で、「話す」を修飾する位置には「フラットに」の形が必要。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f99bd40-4f88-46e8-ae62-05411a60de0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39484, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「主権を尊重する」の目的語を表す「を」。"}, {"text": "に", "is_correct": false, "explanation": "「主権に尊重する」は文の関係が成り立たず、不自然。"}, {"text": "で", "is_correct": false, "explanation": "「主権で尊重する」は手段の関係が合わず、意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "「主権へ尊重する」は方向の関係が成り立たず、不自然。"}], "correct_answer": "を", "explanations": {"を": "「主権を尊重する」の目的語を表す「を」。", "に": "「主権に尊重する」は文の関係が成り立たず、不自然。", "で": "「主権で尊重する」は手段の関係が合わず、意味が通らない。", "へ": "「主権へ尊重する」は方向の関係が成り立たず、不自然。"}, "error_tags": {"を": "目的語", "に": "相手", "で": "手段", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3098aba-6f6f-4241-b083-88432432dfb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39484, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「主権を大切にします」の目的語を表す「を」。"}, {"text": "が", "is_correct": false, "explanation": "「主権が大切にします」では主語と動詞の関係が成り立たず、不自然。"}, {"text": "から", "is_correct": false, "explanation": "起点を表す「から」で、「主権から大切にします」は意味が合わない。"}, {"text": "と", "is_correct": false, "explanation": "「主権と大切にします」は文の関係が成り立たず、不自然。"}], "correct_answer": "を", "explanations": {"を": "「主権を大切にします」の目的語を表す「を」。", "が": "「主権が大切にします」では主語と動詞の関係が成り立たず、不自然。", "から": "起点を表す「から」で、「主権から大切にします」は意味が合わない。", "と": "「主権と大切にします」は文の関係が成り立たず、不自然。"}, "error_tags": {"を": "目的語", "が": "主語", "から": "起点", "と": "相手"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3098aba-6f6f-4241-b083-88432432dfb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39484, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "国や人が自分で決める力のこと。", "primary_collocate": null, "pronunciation": "しゅけん", "ipa": "ɕɯkeɴ", "syllable_count": 3, "sentences": [{"text": "この国では、国民が主権を持っています。", "target_word": "主権", "complexity_tier": "T3", "furigana": "この国[くに]では、国民[こくみん]が主権[しゅけん]を持[も]っています。", "sentence_source": "generated"}, {"text": "他の国は、この国の主権を尊重しなければなりません。", "target_word": "主権", "complexity_tier": "T3", "furigana": "他[ほか]の国[くに]は、この国[くに]の主権[しゅけん]を尊重[そんちょう]しなければなりません。", "sentence_source": "generated"}, {"text": "主権があるので、国は自分でルールを決められます。", "target_word": "主権", "complexity_tier": "T3", "furigana": "主権[しゅけん]があるので、国[くに]は自分[じぶん]でルールを決[き]められます。", "sentence_source": "generated"}, {"text": "国民に主権があるから、みんなが選挙に行きます。", "target_word": "主権", "complexity_tier": "T3", "furigana": "国民[こくみん]に主権[しゅけん]があるから、みんなが選挙[せんきょ]に行[い]きます。", "sentence_source": "generated"}, {"text": "昔、その国は主権がなくて、自由に決められませんでした。", "target_word": "主権", "complexity_tier": "T3", "furigana": "昔[むかし]、その国[くに]は主権[しゅけん]がなくて、自由[じゆう]に決[き]められませんでした。", "sentence_source": "generated"}, {"text": "学校の授業で、主権の意味を先生に教えてもらいました。", "target_word": "主権", "complexity_tier": "T3", "furigana": "学校[がっこう]の授業[じゅぎょう]で、主権[しゅけん]の意味[いみ]を先生[せんせい]に教[おし]えてもらいました。", "sentence_source": "generated"}, {"text": "他の国に命令されると、主権がなくなってしまいます。", "target_word": "主権", "complexity_tier": "T3", "furigana": "他[ほか]の国[くに]に命令[めいれい]されると、主権[しゅけん]がなくなってしまいます。", "sentence_source": "generated"}, {"text": "独立した国は、自分の主権を大切にします。", "target_word": "主権", "complexity_tier": "T3", "furigana": "独立[どくりつ]した国[くに]は、自分[じぶん]の主権[しゅけん]を大切[たいせつ]にします。", "sentence_source": "generated"}, {"text": "子どもにも自分のことを決める主権があると、先生は話しました。", "target_word": "主権", "complexity_tier": "T3", "furigana": "子[こ]どもにも自分[じぶん]のことを決[き]める主権[しゅけん]があると、先生[せんせい]は話[はな]しました。", "sentence_source": "generated"}, {"text": "国どうしは、おたがいの主権を認め合っています。", "target_word": "主権", "complexity_tier": "T3", "furigana": "国[くに]どうしは、おたがいの主権[しゅけん]を認[みと]め合[あ]っています。", "sentence_source": "generated"}], "morphological_forms": [{"form": "主権", "label": "基本形"}], "register": "polite", "sense_fingerprint": "国や人が自分で決める力(やさしい説明)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3dad2fff-697e-44cf-a119-02d31c5b4414') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39484, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "主権", "is_correct": true, "explanation": "空欄には「主権」が入り、国民が主権を持つという文になる。"}, {"text": "窓", "is_correct": false, "explanation": "「国民が窓を持っています」は意味が通らず、文に合わない。"}, {"text": "砂糖", "is_correct": false, "explanation": "「国民が砂糖を持っています」では国の決定の文脈に合わない。"}, {"text": "石", "is_correct": false, "explanation": "「国民が石を持っています」は意味が合わず、不自然。"}], "explanations": {"主権": "空欄には「主権」が入り、国民が主権を持つという文になる。", "窓": "「国民が窓を持っています」は意味が通らず、文に合わない。", "砂糖": "「国民が砂糖を持っています」では国の決定の文脈に合わない。", "石": "「国民が石を持っています」は意味が合わず、不自然。"}, "sentence_index": 0, "correct_answer": "主権"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この本の主権は、友情と裏切りです。", "explanation": "ここは〈主題〉の意味。本のテーマを表す場面で、主権とは言わない。"}, {"text": "映画の主権は、新人の女優が務めます。", "explanation": "ここは〈主役〉の意味。主役を務める場面で、主権の語は使わない。"}, {"text": "彼の話は主権が強すぎます。", "explanation": "ここは〈主観〉の意味。考えの偏りを表す場面で、主権とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3098aba-6f6f-4241-b083-88432432dfb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39484, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "主権", "is_correct": true, "explanation": "空欄には「主権」が入り、命令されると主権がなくなるという文になる。"}, {"text": "雪", "is_correct": false, "explanation": "「雪がなくなってしまいます」は国の命令の文脈に合わない。"}, {"text": "梅", "is_correct": false, "explanation": "「梅がなくなってしまいます」は命令の文脈と合わず、不自然。"}, {"text": "鍋", "is_correct": false, "explanation": "「鍋がなくなってしまいます」は国の主権の文脈に合わない。"}], "explanations": {"主権": "空欄には「主権」が入り、命令されると主権がなくなるという文になる。", "雪": "「雪がなくなってしまいます」は国の命令の文脈に合わない。", "梅": "「梅がなくなってしまいます」は命令の文脈と合わず、不自然。", "鍋": "「鍋がなくなってしまいます」は国の主権の文脈に合わない。"}, "sentence_index": 6, "correct_answer": "主権"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "主権を測って、記録しました。", "explanation": "ここは〈身長〉の意味。身長は測って記録するものだが、主権は測れないので合わない。"}, {"text": "今夜の番組で、彼は主権を務めます。", "explanation": "ここは〈司会〉の意味。番組を進める司会を務める場面で、主権とは言わない。"}, {"text": "この考えが今の主権です。", "explanation": "ここは〈主流〉の意味。大勢の考えを表す場面で、主権は国家の権利を指すので使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3098aba-6f6f-4241-b083-88432432dfb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39484, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他の国は、この国の主権に尊重するべきです。", "corrected_sentence": "他の国は、この国の主権を尊重するべきです。", "error_description": "「主権を尊重する」の目的語を表す「を」を「に」にしている。正しくは「を」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3098aba-6f6f-4241-b083-88432432dfb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39484, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "主権を大切にす国は、他の国と仲良くできます。", "corrected_sentence": "主権を大切にする国は、他の国と仲良くできます。", "error_description": "「大切にする国」の連体形「する」を「す」にしている。正しくは「する」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3098aba-6f6f-4241-b083-88432432dfb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39485, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「主権を持つ」の目的語を表す「を」。"}, {"text": "に", "is_correct": false, "explanation": "「主権に持つ」では文が成り立たず、不自然。"}, {"text": "で", "is_correct": false, "explanation": "「主権で持つ」は意味が通らず、手段の関係も合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「主権へ持つ」は方向の関係が成り立たず、不自然。"}], "correct_answer": "を", "explanations": {"を": "「主権を持つ」の目的語を表す「を」。", "に": "「主権に持つ」では文が成り立たず、不自然。", "で": "「主権で持つ」は意味が通らず、手段の関係も合わない。", "へ": "「主権へ持つ」は方向の関係が成り立たず、不自然。"}, "error_tags": {"を": "目的語", "に": "相手", "で": "手段", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3098aba-6f6f-4241-b083-88432432dfb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39485, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「主権があると」の主語を表す「が」。"}, {"text": "を", "is_correct": false, "explanation": "「主権をあると」では文が成り立たず、不自然。"}, {"text": "から", "is_correct": false, "explanation": "起点を表す「から」で、「主権からあると」は意味が合わない。"}, {"text": "と", "is_correct": false, "explanation": "並列や引用の「と」で、「主権とあると」は文の関係が合わない。"}], "correct_answer": "が", "explanations": {"が": "「主権があると」の主語を表す「が」。", "を": "「主権をあると」では文が成り立たず、不自然。", "から": "起点を表す「から」で、「主権からあると」は意味が合わない。", "と": "並列や引用の「と」で、「主権とあると」は文の関係が合わない。"}, "error_tags": {"が": "主語", "を": "目的語", "から": "起点", "と": "並列"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3098aba-6f6f-4241-b083-88432432dfb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39485, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "他からの干渉を受けずに、国家や個人が自らの意志で決定し行動する権利や状態。", "primary_collocate": null, "pronunciation": "しゅけん", "ipa": "ɕɯkeɴ", "syllable_count": 3, "sentences": [{"text": "他国の干渉を受けずに、国が主権を守っています。", "target_word": "主権", "complexity_tier": "T3", "furigana": "他国[たこく]の干渉[かんしょう]を受[う]けずに、国[くに]が主権[しゅけん]を守[まも]っています。", "sentence_source": "generated"}, {"text": "国民が主権を持つ国では、選挙で代表を選びます。", "target_word": "主権", "complexity_tier": "T3", "furigana": "国民[こくみん]が主権[しゅけん]を持[も]つ国[くに]では、選挙[せんきょ]で代表[だいひょう]を選[えら]びます。", "sentence_source": "generated"}, {"text": "その島は主権を認められておらず、独立を求めて交渉を続けています。", "target_word": "主権", "complexity_tier": "T3", "furigana": "その島[しま]は主権[しゅけん]を認[みと]められておらず、独立[どくりつ]を求[もと]めて交渉[こうしょう]を続[つづ]けています。", "sentence_source": "generated"}, {"text": "他の国が軍隊を送ることは、この国の主権を侵すことになります。", "target_word": "主権", "complexity_tier": "T3", "furigana": "他[ほか]の国[くに]が軍隊[ぐんたい]を送[おく]ることは、この国[くに]の主権[しゅけん]を侵[おか]すことになります。", "sentence_source": "generated"}, {"text": "主権を守るために、政府は国境の警備を強めました。", "target_word": "主権", "complexity_tier": "T3", "furigana": "主権[しゅけん]を守[まも]るために、政府[せいふ]は国境[こっきょう]の警備[けいび]を強[つよ]めました。", "sentence_source": "generated"}, {"text": "憲法には、主権は国民にあると書かれています。", "target_word": "主権", "complexity_tier": "T3", "furigana": "憲法[けんぽう]には、主権[しゅけん]は国民[こくみん]にあると書[か]かれています。", "sentence_source": "generated"}, {"text": "植民地だった国が主権を取り戻したのは、戦争が終わった後でした。", "target_word": "主権", "complexity_tier": "T3", "furigana": "植民地[しょくみんち]だった国[くに]が主権[しゅけん]を取[と]り戻[もど]したのは、戦争[せんそう]が終[お]わった後[あと]でした。", "sentence_source": "generated"}, {"text": "自分の体のことは自分で決める主権があると、彼女は主張しました。", "target_word": "主権", "complexity_tier": "T3", "furigana": "自分[じぶん]の体[からだ]のことは自分[じぶん]で決[き]める主権[しゅけん]があると、彼女[かのじょ]は主張[しゅちょう]しました。", "sentence_source": "generated"}, {"text": "二つの国は、互いの主権を尊重するという条約に署名しました。", "target_word": "主権", "complexity_tier": "T3", "furigana": "二[ふた]つの国[くに]は、互[たが]いの主権[しゅけん]を尊重[そんちょう]するという条約[じょうやく]に署名[しょめい]しました。", "sentence_source": "generated"}, {"text": "主権を失った小さな国は、大国の命令に従うしかありませんでした。", "target_word": "主権", "complexity_tier": "T3", "furigana": "主権[しゅけん]を失[うしな]った小[ちい]さな国[くに]は、大国[たいこく]の命令[めいれい]に従[したが]うしかありませんでした。", "sentence_source": "generated"}], "morphological_forms": [{"form": "主権", "label": "基本形"}], "register": "polite", "sense_fingerprint": "干渉を受けず自ら決定する権利としての主権", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3dad2fff-697e-44cf-a119-02d31c5b4414') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39485, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "主権", "is_correct": true, "explanation": "空欄には「主権」が入り、国が主権を守るという文になる。"}, {"text": "雨", "is_correct": false, "explanation": "「国が窓を守っています」は意味が通らず、文に合わない。"}, {"text": "霧", "is_correct": false, "explanation": "「国が砂糖を守っています」は文脈に合わず、意味が通らない。"}, {"text": "雷", "is_correct": false, "explanation": "「国が石を守っています」は意味が合わず、不自然。"}], "explanations": {"主権": "空欄には「主権」が入り、国が主権を守るという文になる。", "雨": "「国が窓を守っています」は意味が通らず、文に合わない。", "霧": "「国が砂糖を守っています」は文脈に合わず、意味が通らない。", "雷": "「国が石を守っています」は意味が合わず、不自然。"}, "sentence_index": 0, "correct_answer": "主権"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼はクラスの主権で、いつも話し合いを仕切ります。", "explanation": "ここは〈主役・リーダー〉の意味。国家や人が自ら決める権利の意味ではない。"}, {"text": "この役所の主権は、市長に限られています。", "explanation": "ここは〈権限〉の意味。役所の仕事の範囲を指すので、主権とは言わない。"}, {"text": "映画の主権は、友情と裏切りです。", "explanation": "ここは〈主題〉の意味。作品のテーマを表す場面で、主権は使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3098aba-6f6f-4241-b083-88432432dfb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39485, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "主権", "is_correct": true, "explanation": "空欄には「主権」が入り、主権を取り戻したという文になる。"}, {"text": "砂糖", "is_correct": false, "explanation": "「砂糖を取り戻した」は国家の文脈に合わず、意味が通らない。"}, {"text": "窓", "is_correct": false, "explanation": "「窓を取り戻した」は国家の文脈に合わない。"}, {"text": "鏡", "is_correct": false, "explanation": "「鏡を取り戻した」は植民地の文脈と合わず、不自然。"}], "explanations": {"主権": "空欄には「主権」が入り、主権を取り戻したという文になる。", "砂糖": "「砂糖を取り戻した」は国家の文脈に合わず、意味が通らない。", "窓": "「窓を取り戻した」は国家の文脈に合わない。", "鏡": "「鏡を取り戻した」は植民地の文脈と合わず、不自然。"}, "sentence_index": 6, "correct_answer": "主権"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "主権を聞かれて、正直に答えました。", "explanation": "ここは〈年齢〉の意味（年齢を聞かれる）。主権は年齢を表さないので、ここでは合わない。"}, {"text": "次の映画で、彼は主権を務めます。", "explanation": "ここは〈主演〉の意味。主演を務める場面で、主権とは言わない。"}, {"text": "うちの主権は、毎朝早く起きます。", "explanation": "ここは〈主人〉の意味。主権は人を指さないので、家の主人の文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3098aba-6f6f-4241-b083-88432432dfb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39485, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "国民が主権に持つ権利を大切にします。", "corrected_sentence": "国民が主権を持つ権利を大切にします。", "error_description": "「主権を持つ」の目的語を表す「を」を「に」にしている。正しくは「を」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3098aba-6f6f-4241-b083-88432432dfb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39485, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "主権を奪わられた国は、自由を取り戻せませんでした。", "corrected_sentence": "主権を奪われた国は、自由を取り戻せませんでした。", "error_description": "「奪われた」の受身を重ねて「奪わられた」にしている。正しくは「奪われた」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3098aba-6f6f-4241-b083-88432432dfb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
