INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39486, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "元に戻る力のこと。", "primary_collocate": null, "pronunciation": "れじりえんす", "ipa": "ɾedʑiɾieɴsɯ", "syllable_count": 6, "sentences": [{"text": "このゴムはレジリエンスが高いので、強く押しても元の形に戻る。", "target_word": "レジリエンス", "complexity_tier": "T3", "furigana": "このゴムはレジリエンスが高[たか]いので、強[つよ]く押[お]しても元[もと]の形[かたち]に戻[もど]る。", "sentence_source": "generated"}, {"text": "スポンジのレジリエンスが低いと、へこんだまま戻らなくなる。", "target_word": "レジリエンス", "complexity_tier": "T3", "furigana": "スポンジのレジリエンスが低[ひく]いと、へこんだまま戻[もど]らなくなる。", "sentence_source": "generated"}, {"text": "靴底のレジリエンスが優れているため、長く歩いても疲れにくい。", "target_word": "レジリエンス", "complexity_tier": "T3", "furigana": "靴底[くつぞこ]のレジリエンスが優[すぐ]れているため、長[なが]く歩[ある]いても疲[つか]れにくい。", "sentence_source": "generated"}, {"text": "新しいマットレスはレジリエンスが高く、寝たあともすぐに膨らむ。", "target_word": "レジリエンス", "complexity_tier": "T3", "furigana": "新[あたら]しいマットレスはレジリエンスが高[たか]く、寝[ね]たあともすぐに膨[ふく]らむ。", "sentence_source": "generated"}, {"text": "素材のレジリエンスを調べるために、実験で何度も押して離した。", "target_word": "レジリエンス", "complexity_tier": "T3", "furigana": "素材[そざい]のレジリエンスを調[しら]べるために、実験[じっけん]で何度[なんど]も押[お]して離[はな]した。", "sentence_source": "generated"}, {"text": "この枕はレジリエンスが弱く、数か月で平らになってしまった。", "target_word": "レジリエンス", "complexity_tier": "T3", "furigana": "この枕[まくら]はレジリエンスが弱[よわ]く、数[すう]か月[げつ]で平[たい]らになってしまった。", "sentence_source": "generated"}, {"text": "ボールのレジリエンスが高いほど、床に落としたときによく跳ねる。", "target_word": "レジリエンス", "complexity_tier": "T3", "furigana": "ボールのレジリエンスが高[たか]いほど、床[ゆか]に落[お]としたときによく跳[は]ねる。", "sentence_source": "generated"}, {"text": "金属のばねはレジリエンスがあるので、縮めても手を離せば戻る。", "target_word": "レジリエンス", "complexity_tier": "T3", "furigana": "金属[きんぞく]のばねはレジリエンスがあるので、縮[ちぢ]めても手[て]を離[はな]せば戻[もど]る。", "sentence_source": "generated"}, {"text": "テニスラケットのガットはレジリエンスが大切で、ボールを強く打ち返せる。", "target_word": "レジリエンス", "complexity_tier": "T3", "furigana": "テニスラケットのガットはレジリエンスが大切[たいせつ]で、ボールを強[つよ]く打[う]ち返[かえ]せる。", "sentence_source": "generated"}, {"text": "ソファのクッションはレジリエンスが高く、座ってもすぐに元の厚みに戻る。", "target_word": "レジリエンス", "complexity_tier": "T3", "furigana": "ソファのクッションはレジリエンスが高[たか]く、座[すわ]ってもすぐに元[もと]の厚[あつ]みに戻[もど]る。", "sentence_source": "generated"}], "morphological_forms": [{"form": "レジリエンス", "label": "基本形"}], "register": "中立", "sense_fingerprint": "物が押されたり曲げられたりしたあとで元の形に戻る性質（弾力・復元力）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '989c883e-1f67-4ecd-80a7-ae7c0f0d1e3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39486, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "レジリエンス", "is_correct": true, "explanation": "元に戻る力を指す語で、「このゴムは___が高い」に入る。正解。"}, {"text": "静けさ", "is_correct": false, "explanation": "「静けさが高い」は成り立たず、ゴムが元に戻る性質の説明にならない。"}, {"text": "寂しさ", "is_correct": false, "explanation": "「寂しさが高い」は不自然で、ゴムの弾力の話として意味が通らない。"}, {"text": "眠気", "is_correct": false, "explanation": "「眠気が高い」は言わず、物が押されたあと戻るかどうかの話にならない。"}], "explanations": {"レジリエンス": "元に戻る力を指す語で、「このゴムは___が高い」に入る。正解。", "静けさ": "「静けさが高い」は成り立たず、ゴムが元に戻る性質の説明にならない。", "寂しさ": "「寂しさが高い」は不自然で、ゴムの弾力の話として意味が通らない。", "眠気": "「眠気が高い」は言わず、物が押されたあと戻るかどうかの話にならない。"}, "sentence_index": 0, "correct_answer": "レジリエンス"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このシャツはレジリエンスが高く、何度洗っても色落ちしない。", "explanation": "ここは〈色落ちしにくさ（堅牢度）〉の意味。レジリエンスは形が元に戻る力で、染料が落ちにくいことを表さないので合わない。"}, {"text": "このマットはレジリエンスが高いので、部屋の湿気をよく吸う。", "explanation": "ここは〈吸湿性〉の意味。レジリエンスは押されたあとに形が戻る力で、湿気を吸う性質ではないので合わない。"}, {"text": "このドアはレジリエンスが高いので、外の音をほとんど通さない。", "explanation": "ここは〈遮音性〉の意味。レジリエンスは元の形に戻る力で、音を通さない性質ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca5920d4-ba89-425c-8b4e-47cfa4b9d998') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39486, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "レジリエンス", "is_correct": true, "explanation": "ボールが床で跳ねる性質を表す語で、「ボールの___が高いほど」に入る。正解。"}, {"text": "懐かしさ", "is_correct": false, "explanation": "「懐かしさが高いほど」は成り立たず、ボールが跳ねる話にならない。"}, {"text": "大人しさ", "is_correct": false, "explanation": "「大人しさが高い」は不自然で、ボールの性質として意味が通らない。"}, {"text": "几帳面さ", "is_correct": false, "explanation": "人の性格を表す語で、ボールが跳ねる程度の説明にはならない。"}], "explanations": {"レジリエンス": "ボールが床で跳ねる性質を表す語で、「ボールの___が高いほど」に入る。正解。", "懐かしさ": "「懐かしさが高いほど」は成り立たず、ボールが跳ねる話にならない。", "大人しさ": "「大人しさが高い」は不自然で、ボールの性質として意味が通らない。", "几帳面さ": "人の性格を表す語で、ボールが跳ねる程度の説明にはならない。"}, "sentence_index": 6, "correct_answer": "レジリエンス"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "このジャケットはレジリエンスが高いので、雨の日も濡れない。", "explanation": "ここは〈防水性〉の意味。レジリエンスは曲げたあとに元へ戻る力で、水を通さない性質ではないので合わない。"}, {"text": "このスニーカーはレジリエンスが高いので、一年履いてもほとんど破れない。", "explanation": "ここは〈耐久性〉の意味。レジリエンスは形が戻る力で、長く使っても破れにくいことを表さないので合わない。"}, {"text": "この毛布はレジリエンスが高いので、冬の夜も暖かい。", "explanation": "ここは〈保温性〉の意味。レジリエンスは元の形に戻る力で、熱を逃がさない性質を表さないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca5920d4-ba89-425c-8b4e-47cfa4b9d998') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39486, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この古いゴムは、レジリエンスを低いので、引っ張ると戻らなくなる。", "corrected_sentence": "この古いゴムは、レジリエンスが低いので、引っ張ると戻らなくなる。", "error_description": "形容詞「低い」の主語には「が」が要る。「を」は他動詞の目的語を示すので、ここでは誤り。正しくは「レジリエンスが低い」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca5920d4-ba89-425c-8b4e-47cfa4b9d998') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39486, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "このマットは、レジリエンスが高くので、寝ても形がへたりにくい。", "corrected_sentence": "このマットは、レジリエンスが高いので、寝ても形がへたりにくい。", "error_description": "「ので」は終止形（高い）に続く。「高くので」は活用が誤りで、正しくは「高いので」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca5920d4-ba89-425c-8b4e-47cfa4b9d998') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39487, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「育てる」は目的語に「を」を取り、「レジリエンスを育てる」で文意が通る。正解。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すが、目的語が入るべき位置に置くと「レジリエンスが育てる」となり不自然。"}, {"text": "と", "is_correct": false, "explanation": "「と」は相手や並列を示すので、「レジリエンスと育てる」では目的語にならず不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、「レジリエンスへ育てる」は文として成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「育てる」は目的語に「を」を取り、「レジリエンスを育てる」で文意が通る。正解。", "が": "「が」は主語を示すが、目的語が入るべき位置に置くと「レジリエンスが育てる」となり不自然。", "と": "「と」は相手や並列を示すので、「レジリエンスと育てる」では目的語にならず不自然。", "へ": "「へ」は方向を示すので、「レジリエンスへ育てる」は文として成り立たない。"}, "error_tags": {"が": "主語", "と": "相手・並列", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca5920d4-ba89-425c-8b4e-47cfa4b9d998') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39487, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「強い」は主語に「が」を取り、「レジリエンスが強い」で文意が通る。正解。"}, {"text": "を", "is_correct": false, "explanation": "「を」は動作の目的語を示すため、形容詞「強い」の主語にはならず不自然。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所・手段を示すので、「レジリエンスで強い」は文として成立しない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を示すが、状態の主語にはならず「レジリエンスから強い」は不自然。"}], "correct_answer": "が", "explanations": {"が": "「強い」は主語に「が」を取り、「レジリエンスが強い」で文意が通る。正解。", "を": "「を」は動作の目的語を示すため、形容詞「強い」の主語にはならず不自然。", "で": "「で」は場所・手段を示すので、「レジリエンスで強い」は文として成立しない。", "から": "「から」は起点を示すが、状態の主語にはならず「レジリエンスから強い」は不自然。"}, "error_tags": {"を": "目的語", "で": "手段・場所", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca5920d4-ba89-425c-8b4e-47cfa4b9d998') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39487, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "困難な状況から立ち直り、適応する能力。", "primary_collocate": null, "pronunciation": "れじりえんす", "ipa": "ɾedʑiɾieɴsɯ", "syllable_count": 6, "sentences": [{"text": "失敗しても立ち直れる人は、レジリエンスが高いと言われる。", "target_word": "レジリエンス", "complexity_tier": "T3", "furigana": "失敗[しっぱい]しても立[た]ち直[なお]れる人[ひと]は、レジリエンスが高[たか]いと言[い]われる。", "sentence_source": "generated"}, {"text": "子どもの頃の経験が、大人になってからのレジリエンスを育てる。", "target_word": "レジリエンス", "complexity_tier": "T3", "furigana": "子[こ]どもの頃[ころ]の経験[けいけん]が、大人[おとな]になってからのレジリエンスを育[そだ]てる。", "sentence_source": "generated"}, {"text": "会社は社員のレジリエンスを高めるため、研修を始めた。", "target_word": "レジリエンス", "complexity_tier": "T3", "furigana": "会社[かいしゃ]は社員[しゃいん]のレジリエンスを高[たか]めるため、研修[けんしゅう]を始[はじ]めた。", "sentence_source": "generated"}, {"text": "災害のあとの町の復興には、住民のレジリエンスが欠かせない。", "target_word": "レジリエンス", "complexity_tier": "T3", "furigana": "災害[さいがい]のあとの町[まち]の復興[ふっこう]には、住民[じゅうみん]のレジリエンスが欠[か]かせない。", "sentence_source": "generated"}, {"text": "仕事で大きな失敗をしたが、彼女はレジリエンスのおかげで早く前向きになれた。", "target_word": "レジリエンス", "complexity_tier": "T3", "furigana": "仕事[しごと]で大[おお]きな失敗[しっぱい]をしたが、彼女[かのじょ]はレジリエンスのおかげで早[はや]く前向[まえむ]きになれた。", "sentence_source": "generated"}, {"text": "友人の支えは、つらい時期を乗り越えるレジリエンスにつながった。", "target_word": "レジリエンス", "complexity_tier": "T3", "furigana": "友人[ゆうじん]の支[ささ]えは、つらい時期[じき]を乗[の]り越[こ]えるレジリエンスにつながった。", "sentence_source": "generated"}, {"text": "レジリエンスが弱いと、小さな失敗でも長く落ち込んでしまう。", "target_word": "レジリエンス", "complexity_tier": "T3", "furigana": "レジリエンスが弱[よわ]いと、小[ちい]さな失敗[しっぱい]でも長[なが]く落[お]ち込[こ]んでしまう。", "sentence_source": "generated"}, {"text": "転職を何度も経験した彼は、変化に対するレジリエンスが強い。", "target_word": "レジリエンス", "complexity_tier": "T3", "furigana": "転職[てんしょく]を何度[なんど]も経験[けいけん]した彼[かれ]は、変化[へんか]に対[たい]するレジリエンスが強[つよ]い。", "sentence_source": "generated"}, {"text": "心理学では、ストレスに負けないレジリエンスの研究が進んでいる。", "target_word": "レジリエンス", "complexity_tier": "T3", "furigana": "心理学[しんりがく]では、ストレスに負[ま]けないレジリエンスの研究[けんきゅう]が進[すす]んでいる。", "sentence_source": "generated"}, {"text": "日記を書くことは、気持ちを整えてレジリエンスを養う方法の一つだ。", "target_word": "レジリエンス", "complexity_tier": "T3", "furigana": "日記[にっき]を書[か]くことは、気持[きも]ちを整[ととの]えてレジリエンスを養[やしな]う方法[ほうほう]の一[ひと]つだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "レジリエンス", "label": "基本形"}], "register": "中立", "sense_fingerprint": "失敗や災害などの困難から心や社会が立ち直り、変化に適応する力（心理学・組織論の用法）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '989c883e-1f67-4ecd-80a7-ae7c0f0d1e3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39487, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "レジリエンス", "is_correct": true, "explanation": "困難から立ち直る力を指す語で、「___が高いと言われる」に入る。正解。"}, {"text": "気まずさ", "is_correct": false, "explanation": "「気まずさが高い」は言わず、立ち直る力の高さを表せない。"}, {"text": "物悲しさ", "is_correct": false, "explanation": "情緒を表す語で、「高い」と組み合わせて立ち直る力を評価する文にはならない。"}, {"text": "寒さ", "is_correct": false, "explanation": "「寒さが高い」は不自然で、人が失敗から立ち直る話として意味が通らない。"}], "explanations": {"レジリエンス": "困難から立ち直る力を指す語で、「___が高いと言われる」に入る。正解。", "気まずさ": "「気まずさが高い」は言わず、立ち直る力の高さを表せない。", "物悲しさ": "情緒を表す語で、「高い」と組み合わせて立ち直る力を評価する文にはならない。", "寒さ": "「寒さが高い」は不自然で、人が失敗から立ち直る話として意味が通らない。"}, "sentence_index": 0, "correct_answer": "レジリエンス"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このパンはレジリエンスが高く、一週間たっても焼きたてのように柔らかい。", "explanation": "ここは〈日持ち（鮮度）〉の意味。レジリエンスは困難から立ち直る力で、食品が日持ちすることを表さないので合わない。"}, {"text": "母はレジリエンスが高く、ぜいたくな買い物はほとんどしない。", "explanation": "ここは〈倹約〉の意味。レジリエンスは困難から立ち直る力で、お金を節約する性格を表さないので合わない。"}, {"text": "この時計はレジリエンスが高く、一日の時間のずれがほとんどない。", "explanation": "ここは〈正確さ（精度）〉の意味。レジリエンスは立ち直る力で、時間のずれが少ないことを表さないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca5920d4-ba89-425c-8b4e-47cfa4b9d998') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39487, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "レジリエンス", "is_correct": true, "explanation": "失敗から立ち直る力を指す語で、「___が弱いと」に入る。正解。"}, {"text": "行儀", "is_correct": false, "explanation": "「行儀が弱いと、小さな失敗でも長く落ち込む」は意味が通らず、立ち直る力の話にならない。"}, {"text": "大胆さ", "is_correct": false, "explanation": "「大胆さが弱い」は不自然で、失敗後に落ち込むかどうかの説明にならない。"}, {"text": "手際", "is_correct": false, "explanation": "「手際が弱い」は言わず（「悪い」と言う）、立ち直りの強さを表せない。"}], "explanations": {"レジリエンス": "失敗から立ち直る力を指す語で、「___が弱いと」に入る。正解。", "行儀": "「行儀が弱いと、小さな失敗でも長く落ち込む」は意味が通らず、立ち直る力の話にならない。", "大胆さ": "「大胆さが弱い」は不自然で、失敗後に落ち込むかどうかの説明にならない。", "手際": "「手際が弱い」は言わず（「悪い」と言う）、立ち直りの強さを表せない。"}, "sentence_index": 6, "correct_answer": "レジリエンス"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この果物はレジリエンスが高く、とても甘い。", "explanation": "ここは〈甘さ〉の意味。レジリエンスは困難から立ち直る力で、味の甘さを表す語ではないので合わない。"}, {"text": "この歌手はレジリエンスが高く、ホールの一番後ろまで声が届く。", "explanation": "ここは〈声量〉の意味。レジリエンスは困難から立ち直る力で、声の大きさを表さないので合わない。"}, {"text": "この湖はレジリエンスが高く、底まで透けて見える。", "explanation": "ここは〈透明度〉の意味。レジリエンスは立ち直る力で、水の透き通りを表さないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca5920d4-ba89-425c-8b4e-47cfa4b9d998') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39487, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "このチームはレジリエンスを高く、厳しい納期も乗り越えた。", "corrected_sentence": "このチームはレジリエンスが高く、厳しい納期も乗り越えた。", "error_description": "形容詞「高い」は主語に「が」を取る。「を」は動作の目的語を示すので、ここでは誤り。正しくは「レジリエンスが高く」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca5920d4-ba89-425c-8b4e-47cfa4b9d998') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39487, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼女は失敗しても、レジリエンスが高くので、すぐに前を向ける。", "corrected_sentence": "彼女は失敗しても、レジリエンスが高いので、すぐに前を向ける。", "error_description": "「ので」は終止形（高い）に続く。「高くので」は活用が誤りで、正しくは「高いので」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca5920d4-ba89-425c-8b4e-47cfa4b9d998') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39488, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "放電", "is_correct": true, "explanation": "電気を外へ出すことで、ためておく蓄電の反対の意味を持つ。"}, {"text": "発電", "is_correct": false, "explanation": "電気を作ることで、ためることの反対ではなく、作る方向の語。"}, {"text": "送電", "is_correct": false, "explanation": "電気を送ることで、ためることの反対にはならない。"}, {"text": "停電", "is_correct": false, "explanation": "電気が止まることで、ためることの反対の語ではない。"}], "correct_answer": "放電", "explanations": {"放電": "電気を外へ出すことで、ためておく蓄電の反対の意味を持つ。", "発電": "電気を作ることで、ためることの反対ではなく、作る方向の語。", "送電": "電気を送ることで、ためることの反対にはならない。", "停電": "電気が止まることで、ためることの反対の語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c2077fb-5805-427c-b931-fa45bdbd5b4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39488, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "放電", "is_correct": true, "explanation": "電気を外へ出すことで、ためておく蓄電の反対の意味を持つ。"}, {"text": "変電", "is_correct": false, "explanation": "電圧を変えることで、ためることの反対の語ではない。"}, {"text": "配電", "is_correct": false, "explanation": "電気を各所へ配ることで、ためることの反対にはならない。"}, {"text": "節電", "is_correct": false, "explanation": "電気の使用を減らすことで、ためることの反対の語として並ばない。"}], "correct_answer": "放電", "explanations": {"放電": "電気を外へ出すことで、ためておく蓄電の反対の意味を持つ。", "変電": "電圧を変えることで、ためることの反対の語ではない。", "配電": "電気を各所へ配ることで、ためることの反対にはならない。", "節電": "電気の使用を減らすことで、ためることの反対の語として並ばない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c2077fb-5805-427c-b931-fa45bdbd5b4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39488, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "電気をためておくこと。", "primary_collocate": null, "pronunciation": "ちくでん", "ipa": "tɕikɯdeɴ", "syllable_count": 4, "sentences": [{"text": "太陽の光で作った電気を、蓄電して夜に使う。", "target_word": "蓄電", "complexity_tier": "T3", "furigana": "太陽[たいよう]の光[ひかり]で作[つく]った電気[でんき]を、蓄電[ちくでん]して夜[よる]に使[つか]う。", "sentence_source": "generated"}, {"text": "大型の設備は、夜間の電気を蓄電するのに一晩かかる。", "target_word": "蓄電", "complexity_tier": "T3", "furigana": "大型[おおがた]の設備[せつび]は、夜間[やかん]の電気[でんき]を蓄電[ちくでん]するのに一晩[ひとばん]かかる。", "sentence_source": "generated"}, {"text": "蓄電ができれば、停電の夜も安心だ。", "target_word": "蓄電", "complexity_tier": "T3", "furigana": "蓄電[ちくでん]ができれば、停電[ていでん]の夜[よる]も安心[あんしん]だ。", "sentence_source": "generated"}, {"text": "蓄電の量が少なくなると、ランプが赤く光る。", "target_word": "蓄電", "complexity_tier": "T3", "furigana": "蓄電[ちくでん]の量[りょう]が少[すく]なくなると、ランプが赤[あか]く光[ひか]る。", "sentence_source": "generated"}, {"text": "昼のうちに蓄電しておけば、夜の電気代が安くなる。", "target_word": "蓄電", "complexity_tier": "T3", "furigana": "昼[ひる]のうちに蓄電[ちくでん]しておけば、夜[よる]の電気代[でんきだい]が安[やす]くなる。", "sentence_source": "generated"}, {"text": "蓄電のための大きな電池を、学校の屋上に置いた。", "target_word": "蓄電", "complexity_tier": "T3", "furigana": "蓄電[ちくでん]のための大[おお]きな電池[でんち]を、学校[がっこう]の屋上[おくじょう]に置[お]いた。", "sentence_source": "generated"}, {"text": "風が強い日に蓄電して、風のない日に使う。", "target_word": "蓄電", "complexity_tier": "T3", "furigana": "風[かぜ]が強[つよ]い日[ひ]に蓄電[ちくでん]して、風[かぜ]のない日[ひ]に使[つか]う。", "sentence_source": "generated"}, {"text": "停電に備えて、家の電気を蓄電しておく装置を買った。", "target_word": "蓄電", "complexity_tier": "T3", "furigana": "停電[ていでん]に備[そな]えて、家[いえ]の電気[でんき]を蓄電[ちくでん]しておく装置[そうち]を買[か]った。", "sentence_source": "generated"}, {"text": "蓄電が足りず、ライトがすぐに消えてしまった。", "target_word": "蓄電", "complexity_tier": "T3", "furigana": "蓄電[ちくでん]が足[た]りず、ライトがすぐに消[き]えてしまった。", "sentence_source": "generated"}, {"text": "兄は蓄電のしくみを調べて、自由研究にまとめた。", "target_word": "蓄電", "complexity_tier": "T3", "furigana": "兄[あに]は蓄電[ちくでん]のしくみを調[しら]べて、自由[じゆう]研究[けんきゅう]にまとめた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "蓄電", "label": "辞書形"}, {"form": "蓄電する", "label": "サ変動詞"}, {"form": "蓄電した", "label": "過去形"}, {"form": "蓄電して", "label": "て形"}], "register": "neutral", "sense_fingerprint": "電池などに電気をためておくこと(身近な電池・バッテリー)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b545744d-41a4-491d-95fb-e6974ddf9eae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39488, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "蓄電", "is_correct": true, "explanation": "電気をためておく意味で、太陽の光で作った電気を夜に使うという文脈に合う。"}, {"text": "停電", "is_correct": false, "explanation": "電気の供給が止まることで、電気をためておく動作ではない。"}, {"text": "消灯", "is_correct": false, "explanation": "明かりを消すことで、電気をためる意味にはならない。"}, {"text": "切断", "is_correct": false, "explanation": "つないだものを切り離すことで、電気をためる文脈には合わない。"}], "explanations": {"蓄電": "電気をためておく意味で、太陽の光で作った電気を夜に使うという文脈に合う。", "停電": "電気の供給が止まることで、電気をためておく動作ではない。", "消灯": "明かりを消すことで、電気をためる意味にはならない。", "切断": "つないだものを切り離すことで、電気をためる文脈には合わない。"}, "sentence_index": 0, "correct_answer": "蓄電"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ダムは川の水を一日中蓄電して、夏の田んぼに流している。", "explanation": "ここは〈貯水〉の意味。蓄電は電気をためることに限り、水をためる場合には使わない。"}, {"text": "祖母は梅干しを毎年蓄電して、冬に備えている。", "explanation": "ここは〈貯蔵〉の意味。蓄電は電気に使う語で、梅干しのような食べ物には使わない。"}, {"text": "週末は家でしっかり蓄電して、気力を取り戻す。", "explanation": "ここは〈充電〉の意味。蓄電は電気エネルギーに使う語で、人の気力には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c2077fb-5805-427c-b931-fa45bdbd5b4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39488, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "蓄電", "is_correct": true, "explanation": "風が強い日に電気をためて、風のない日に使うという意味に合う。"}, {"text": "点灯", "is_correct": false, "explanation": "明かりをつけることで、電気をためて使い分ける文脈には合わない。"}, {"text": "断線", "is_correct": false, "explanation": "電線が切れることで、電気をためる動作ではない。"}, {"text": "漏電", "is_correct": false, "explanation": "電気が本来の経路から漏れることで、ためる意味にはならない。"}], "explanations": {"蓄電": "風が強い日に電気をためて、風のない日に使うという意味に合う。", "点灯": "明かりをつけることで、電気をためて使い分ける文脈には合わない。", "断線": "電線が切れることで、電気をためる動作ではない。", "漏電": "電気が本来の経路から漏れることで、ためる意味にはならない。"}, "sentence_index": 6, "correct_answer": "蓄電"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工場の廃液が蓄電して、川が汚れた。", "explanation": "ここは〈蓄積〉の意味。蓄電は電気をためることに限る語で、廃液のような物質がたまる場合は蓄積を使う。"}, {"text": "冬は床に熱を蓄電しておくと、夜も暖かい。", "explanation": "ここは〈蓄熱〉の意味。蓄電は電気に限る語で、熱をためる場合は蓄熱を使う。"}, {"text": "このアプリは写真を蓄電して、あとで見返せるようにする。", "explanation": "ここは〈保存〉の意味。蓄電は電気エネルギーに使う語で、写真のデータには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c2077fb-5805-427c-b931-fa45bdbd5b4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39488, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "蓄電に量が増えると、夜もランプが明るく光る。", "corrected_sentence": "蓄電の量が増えると、夜もランプが明るく光る。", "error_description": "「蓄電の量」の「の」が正しい。「蓄電に」では後ろの名詞「量」を修飾できず、文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c2077fb-5805-427c-b931-fa45bdbd5b4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39488, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "電池に電気を蓄電られて、停電に備える。", "corrected_sentence": "電池に電気を蓄電して、停電に備える。", "error_description": "「蓄電して」が正しい。「蓄電られて」は動詞の形として成り立たず、サ変動詞「蓄電する」の連用形「して」を使う必要がある。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c2077fb-5805-427c-b931-fa45bdbd5b4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39489, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "放電", "is_correct": true, "explanation": "電気を外へ出すことで、ためておく蓄電の反対の意味を持つ。"}, {"text": "発電", "is_correct": false, "explanation": "電気を作ることで、ためることの反対ではなく、作る方向の語。"}, {"text": "送電", "is_correct": false, "explanation": "電気を送ることで、ためることの反対にはならない。"}, {"text": "停電", "is_correct": false, "explanation": "電気が止まることで、ためることの反対の語ではない。"}], "correct_answer": "放電", "explanations": {"放電": "電気を外へ出すことで、ためておく蓄電の反対の意味を持つ。", "発電": "電気を作ることで、ためることの反対ではなく、作る方向の語。", "送電": "電気を送ることで、ためることの反対にはならない。", "停電": "電気が止まることで、ためることの反対の語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c2077fb-5805-427c-b931-fa45bdbd5b4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39489, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "放電", "is_correct": true, "explanation": "電気を外へ出すことで、ためておく蓄電の反対の意味を持つ。"}, {"text": "変電", "is_correct": false, "explanation": "電圧を変えることで、ためることの反対の語ではない。"}, {"text": "配電", "is_correct": false, "explanation": "電気を各所へ配ることで、ためることの反対にはならない。"}, {"text": "節電", "is_correct": false, "explanation": "電気の使用を減らすことで、ためることの反対の語として並ばない。"}], "correct_answer": "放電", "explanations": {"放電": "電気を外へ出すことで、ためておく蓄電の反対の意味を持つ。", "変電": "電圧を変えることで、ためることの反対の語ではない。", "配電": "電気を各所へ配ることで、ためることの反対にはならない。", "節電": "電気の使用を減らすことで、ためることの反対の語として並ばない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c2077fb-5805-427c-b931-fa45bdbd5b4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39489, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "電気エネルギーを蓄えて、必要なときに使えるようにすること。", "primary_collocate": null, "pronunciation": "ちくでん", "ipa": "tɕikɯdeɴ", "syllable_count": 4, "sentences": [{"text": "発電所の電気が余った時間に蓄電し、足りない時間に使う。", "target_word": "蓄電", "complexity_tier": "T3", "furigana": "発電所[はつでんしょ]の電気[でんき]が余[あま]った時間[じかん]に蓄電[ちくでん]し、足[た]りない時間[じかん]に使[つか]う。", "sentence_source": "generated"}, {"text": "家庭用の蓄電システムが、災害への備えとして人気だ。", "target_word": "蓄電", "complexity_tier": "T3", "furigana": "家庭用[かていよう]の蓄電[ちくでん]システムが、災害[さいがい]への備[そな]えとして人気[にんき]だ。", "sentence_source": "generated"}, {"text": "蓄電のおかげで、再生可能エネルギーを安定して使える。", "target_word": "蓄電", "complexity_tier": "T3", "furigana": "蓄電[ちくでん]のおかげで、再生可能[さいせいかのう]エネルギーを安定[あんてい]して使[つか]える。", "sentence_source": "generated"}, {"text": "会社は工場の屋根で作った電気を蓄電して、必要な時間に使っている。", "target_word": "蓄電", "complexity_tier": "T3", "furigana": "会社[かいしゃ]は工場[こうじょう]の屋根[やね]で作[つく]った電気[でんき]を蓄電[ちくでん]して、必要[ひつよう]な時間[じかん]に使[つか]っている。", "sentence_source": "generated"}, {"text": "電気自動車は蓄電した電気を、家に送ることもできる。", "target_word": "蓄電", "complexity_tier": "T3", "furigana": "電気[でんき]自動車[じどうしゃ]は蓄電[ちくでん]した電気[でんき]を、家[いえ]に送[おく]ることもできる。", "sentence_source": "generated"}, {"text": "蓄電の技術が進むと、天気に左右されずに電気を使える。", "target_word": "蓄電", "complexity_tier": "T3", "furigana": "蓄電[ちくでん]の技術[ぎじゅつ]が進[すす]むと、天気[てんき]に左右[さゆう]されずに電気[でんき]を使[つか]える。", "sentence_source": "generated"}, {"text": "夜の安い電気で蓄電し、昼の高い時間は使わないようにする。", "target_word": "蓄電", "complexity_tier": "T3", "furigana": "夜[よる]の安[やす]い電気[でんき]で蓄電[ちくでん]し、昼[ひる]の高[たか]い時間[じかん]は使[つか]わないようにする。", "sentence_source": "generated"}, {"text": "町では、非常時のために蓄電の設備を増やしている。", "target_word": "蓄電", "complexity_tier": "T3", "furigana": "町[まち]では、非常時[ひじょうじ]のために蓄電[ちくでん]の設備[せつび]を増[ふ]やしている。", "sentence_source": "generated"}, {"text": "蓄電できる量が大きいほど、停電が長くても安心だ。", "target_word": "蓄電", "complexity_tier": "T3", "furigana": "蓄電[ちくでん]できる量[りょう]が大[おお]きいほど、停電[ていでん]が長[なが]くても安心[あんしん]だ。", "sentence_source": "generated"}, {"text": "研究者は、長く蓄電できる新しい電池を開発している。", "target_word": "蓄電", "complexity_tier": "T3", "furigana": "研究者[けんきゅうしゃ]は、長[なが]く蓄電[ちくでん]できる新[あたら]しい電池[でんち]を開発[かいはつ]している。", "sentence_source": "generated"}], "morphological_forms": [{"form": "蓄電", "label": "辞書形"}, {"form": "蓄電する", "label": "サ変動詞"}, {"form": "蓄電した", "label": "過去形"}, {"form": "蓄電できる", "label": "可能形"}], "register": "formal", "sense_fingerprint": "余った電気エネルギーを設備にためて、必要な時に使えるようにすること(電力の需給調整)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b545744d-41a4-491d-95fb-e6974ddf9eae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39489, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "蓄電", "is_correct": true, "explanation": "余った電気を設備にためておくという意味で、足りない時間に使う文脈に合う。"}, {"text": "停電", "is_correct": false, "explanation": "電気が止まることで、余った時間に電気をためる意味にはならない。"}, {"text": "消灯", "is_correct": false, "explanation": "明かりを消すことで、電気をためる動作ではない。"}, {"text": "点灯", "is_correct": false, "explanation": "明かりをつけることで、余った時間にためるという意味にならない。"}], "explanations": {"蓄電": "余った電気を設備にためておくという意味で、足りない時間に使う文脈に合う。", "停電": "電気が止まることで、余った時間に電気をためる意味にはならない。", "消灯": "明かりを消すことで、電気をためる動作ではない。", "点灯": "明かりをつけることで、余った時間にためるという意味にならない。"}, "sentence_index": 0, "correct_answer": "蓄電"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会社は工場の屋根で、太陽の熱を蓄電している。", "explanation": "ここは〈蓄熱〉の意味。蓄電は電気に限る語で、熱をためる場合は蓄熱を使う。"}, {"text": "休日は家で蓄電して、また仕事に向かう。", "explanation": "ここは〈充電〉の意味。蓄電は電気エネルギーに使う語で、人の活力を取り戻す場合は充電を使う。"}, {"text": "会社は毎年、利益を蓄電して、工場を増やしている。", "explanation": "ここは〈蓄積〉の意味。蓄電は電気に限る語で、利益やお金をためる場合には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c2077fb-5805-427c-b931-fa45bdbd5b4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39489, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "蓄電", "is_correct": true, "explanation": "夜の安い電気をためて、昼の高い時間に使わないという文脈に合う。"}, {"text": "断線", "is_correct": false, "explanation": "電線が切れることで、夜の電気をためる意味にはならない。"}, {"text": "漏電", "is_correct": false, "explanation": "電気が本来の経路から漏れることで、ためる動作ではない。"}, {"text": "切断", "is_correct": false, "explanation": "つないだものを切り離すことで、夜の電気をためる文脈には合わない。"}], "explanations": {"蓄電": "夜の安い電気をためて、昼の高い時間に使わないという文脈に合う。", "断線": "電線が切れることで、夜の電気をためる意味にはならない。", "漏電": "電気が本来の経路から漏れることで、ためる動作ではない。", "切断": "つないだものを切り離すことで、夜の電気をためる文脈には合わない。"}, "sentence_index": 6, "correct_answer": "蓄電"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "畑で採れた野菜を、冬に備えて蓄電しておく。", "explanation": "ここは〈貯蔵〉の意味。蓄電は電気に使う語で、野菜のような食べ物には使わない。"}, {"text": "発電所から家庭へ蓄電している。", "explanation": "ここは〈送電〉の意味。蓄電は電気をためることで、電気を届ける場合は送電を使う。"}, {"text": "このビルは照明を消して、電気の使用量を蓄電している。", "explanation": "ここは〈節約〉の意味。蓄電は電気をためることで、使う量を減らす場合は節約を使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c2077fb-5805-427c-b931-fa45bdbd5b4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39489, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "蓄電に設備が増えて、停電の時も町は明るい。", "corrected_sentence": "蓄電の設備が増えて、停電の時も町は明るい。", "error_description": "「蓄電の設備」の「の」が正しい。「蓄電に」では後ろの名詞「設備」を修飾できず、文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c2077fb-5805-427c-b931-fa45bdbd5b4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39489, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "晴れた日に電気を蓄電で、雨の日に備える。", "corrected_sentence": "晴れた日に電気を蓄電して、雨の日に備える。", "error_description": "「蓄電して」の「して」が必要。「蓄電で」では動詞の形にならず、文が続かない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c2077fb-5805-427c-b931-fa45bdbd5b4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39492, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "連続的に", "is_correct": true, "explanation": "途切れずに続くことで、途切れ途切れの断続的の反対の意味を持つ。"}, {"text": "一時的に", "is_correct": false, "explanation": "一定の時間だけという意味で、途切れ途切れの反対とは言えない。"}, {"text": "定期的に", "is_correct": false, "explanation": "決まった間隔で繰り返す意味で、途切れと続きの反対ではない。"}, {"text": "頻繁に", "is_correct": false, "explanation": "回数が多いことを表す語で、続きと途切れの反対の軸ではない。"}], "correct_answer": "連続的に", "explanations": {"連続的に": "途切れずに続くことで、途切れ途切れの断続的の反対の意味を持つ。", "一時的に": "一定の時間だけという意味で、途切れ途切れの反対とは言えない。", "定期的に": "決まった間隔で繰り返す意味で、途切れと続きの反対ではない。", "頻繁に": "回数が多いことを表す語で、続きと途切れの反対の軸ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c2077fb-5805-427c-b931-fa45bdbd5b4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39492, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "連続的に", "is_correct": true, "explanation": "途切れずに続くことで、途切れ途切れの断続的の反対の意味を持つ。"}, {"text": "瞬間的に", "is_correct": false, "explanation": "ごく短い時間に起こる意味で、続き方の反対とは言えない。"}, {"text": "即座に", "is_correct": false, "explanation": "すぐにという意味で、途切れと続きの反対の語ではない。"}, {"text": "大量に", "is_correct": false, "explanation": "数量が多いことを表し、続きと途切れの反対の軸ではない。"}], "correct_answer": "連続的に", "explanations": {"連続的に": "途切れずに続くことで、途切れ途切れの断続的の反対の意味を持つ。", "瞬間的に": "ごく短い時間に起こる意味で、続き方の反対とは言えない。", "即座に": "すぐにという意味で、途切れと続きの反対の語ではない。", "大量に": "数量が多いことを表し、続きと途切れの反対の軸ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c2077fb-5805-427c-b931-fa45bdbd5b4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39492, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "何かが、とまったり、また動いたりすること。", "primary_collocate": null, "pronunciation": "だんぞく", "ipa": "dandzokɯ", "syllable_count": 4, "sentences": [{"text": "古い機械が断続的に動いたり止まったりして、作業が進まなかった。", "target_word": "断続的に", "complexity_tier": "T3", "furigana": "古[ふる]い機械[きかい]が断続的[だんぞくてき]に動[うご]いたり止[と]まったりして、作業[さぎょう]が進[すす]まなかった。", "sentence_source": "generated"}, {"text": "蛇口の水が断続的に出るので、水道管を調べてもらった。", "target_word": "断続的に", "complexity_tier": "T3", "furigana": "蛇口[じゃぐち]の水[みず]が断続的[だんぞくてき]に出[で]るので、水道管[すいどうかん]を調[しら]べてもらった。", "sentence_source": "generated"}, {"text": "渋滞のせいで、バスは断続的に止まりながらゆっくり進んだ。", "target_word": "断続的に", "complexity_tier": "T3", "furigana": "渋滞[じゅうたい]のせいで、バスは断続的[だんぞくてき]に止[と]まりながらゆっくり進[すす]んだ。", "sentence_source": "generated"}, {"text": "風が弱く、風車は断続的に回るだけで電気がほとんど作れなかった。", "target_word": "断続的に", "complexity_tier": "T3", "furigana": "風[かぜ]が弱[よわ]く、風車[ふうしゃ]は断続的[だんぞくてき]に回[まわ]るだけで電気[でんき]がほとんど作[つく]れなかった。", "sentence_source": "generated"}, {"text": "エレベーターが断続的に動くため、階段を使う人が増えた。", "target_word": "断続的に", "complexity_tier": "T3", "furigana": "エレベーターが断続的[だんぞくてき]に動[うご]くため、階段[かいだん]を使[つか]う人[ひと]が増[ふ]えた。", "sentence_source": "generated"}, {"text": "信号の故障で、車の流れが断続的になっていた。", "target_word": "断続的", "complexity_tier": "T3", "furigana": "信号[しんごう]の故障[こしょう]で、車[くるま]の流[なが]れが断続的[だんぞくてき]になっていた。", "sentence_source": "generated"}, {"text": "動画が断続的に止まるので、ネットの回線を替えた。", "target_word": "断続的に", "complexity_tier": "T3", "furigana": "動画[どうが]が断続的[だんぞくてき]に止[と]まるので、ネットの回線[かいせん]を替[か]えた。", "sentence_source": "generated"}, {"text": "ベルトコンベアーが断続的に動くせいで、荷物が山のようにたまった。", "target_word": "断続的に", "complexity_tier": "T3", "furigana": "ベルトコンベアーが断続的[だんぞくてき]に動[うご]くせいで、荷物[にもつ]が山[やま]のようにたまった。", "sentence_source": "generated"}, {"text": "雪のため、電車は断続的に走っては止まるのを繰り返した。", "target_word": "断続的に", "complexity_tier": "T3", "furigana": "雪[ゆき]のため、電車[でんしゃ]は断続的[だんぞくてき]に走[はし]っては止[と]まるのを繰[く]り返[かえ]した。", "sentence_source": "generated"}, {"text": "壊れかけた扇風機は断続的に回り、部屋はなかなか涼しくならなかった。", "target_word": "断続的に", "complexity_tier": "T3", "furigana": "壊[こわ]れかけた扇風機[せんぷうき]は断続的[だんぞくてき]に回[まわ]り、部屋[へや]はなかなか涼[すず]しくならなかった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "断続的", "label": "語幹"}, {"form": "断続的に", "label": "連用形（副詞的）"}, {"form": "断続的な", "label": "連体形"}], "register": "neutral", "sense_fingerprint": "機械・水・乗り物などの動きが止まっては動くことを繰り返すこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b545744d-41a4-491d-95fb-e6974ddf9eae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39492, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "断続的に", "is_correct": true, "explanation": "途切れ途切れに動いたり止まったりする様子を表し、機械の動きに合う。"}, {"text": "永遠に", "is_correct": false, "explanation": "いつまでも続くという意味で、動いたり止まったりを繰り返す様子とは合わない。"}, {"text": "大急ぎで", "is_correct": false, "explanation": "非常に急ぐという意味で、動いたり止まったりする様子には合わない。"}, {"text": "完全に", "is_correct": false, "explanation": "すっかりという意味で、途切れ途切れに動く様子を表せない。"}], "explanations": {"断続的に": "途切れ途切れに動いたり止まったりする様子を表し、機械の動きに合う。", "永遠に": "いつまでも続くという意味で、動いたり止まったりを繰り返す様子とは合わない。", "大急ぎで": "非常に急ぐという意味で、動いたり止まったりする様子には合わない。", "完全に": "すっかりという意味で、途切れ途切れに動く様子を表せない。"}, "sentence_index": 0, "correct_answer": "断続的に"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "バスは断続的に、毎朝七時きっかりに出発する。", "explanation": "ここは〈定期的に〉の意味。断続的は途切れ途切れの意味で、決まった間隔で出る場合は定期的を使う。"}, {"text": "モーターは断続的に、一晩中一定の速さで回り続けた。", "explanation": "ここは〈連続的に〉の意味。断続的は途切れることを表し、ずっと続く動きには合わない。"}, {"text": "機械は断続的に止まったまま、二度と動かなかった。", "explanation": "ここは〈永続的に〉の意味。断続的は動いたり止まったりを繰り返すことで、ずっと止まる場合には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c2077fb-5805-427c-b931-fa45bdbd5b4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39492, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "断続的に", "is_correct": true, "explanation": "動画が途切れ途切れに止まる様子を表し、回線を替えた理由として合う。"}, {"text": "大声で", "is_correct": false, "explanation": "声を大きくする意味で、動画が止まる様子には合わない。"}, {"text": "丁寧に", "is_correct": false, "explanation": "注意深く行う意味で、動画が止まる様子には合わない。"}, {"text": "大幅に", "is_correct": false, "explanation": "変化の大きさを表す語で、止まる仕方を表さない。"}], "explanations": {"断続的に": "動画が途切れ途切れに止まる様子を表し、回線を替えた理由として合う。", "大声で": "声を大きくする意味で、動画が止まる様子には合わない。", "丁寧に": "注意深く行う意味で、動画が止まる様子には合わない。", "大幅に": "変化の大きさを表す語で、止まる仕方を表さない。"}, "sentence_index": 6, "correct_answer": "断続的に"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "扇風機は一瞬だけ断続的に回り、すぐに止まった。", "explanation": "ここは〈一瞬〉の意味。断続的は途切れてまた続くことを何度も繰り返すので、一回だけの動きには使えない。"}, {"text": "子どもたちは断続的に一斉に手を挙げた。", "explanation": "ここは〈一斉に〉の意味。断続的は途切れ途切れのことで、みんなが同時に動く場面には合わない。"}, {"text": "地震で建物が断続的に一度だけ揺れた。", "explanation": "ここは〈一度〉の意味。断続的は同じ動きが途切れて何度も起こることで、一度だけの揺れには使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c2077fb-5805-427c-b931-fa45bdbd5b4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39492, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "雨は断続的を降り、夕方には止んだ。", "corrected_sentence": "雨は断続的に降り、夕方には止んだ。", "error_description": "「断続的に」の「に」が正しい。「断続的を」の「を」は目的語を示すため、副詞として「降り」を修飾できない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c2077fb-5805-427c-b931-fa45bdbd5b4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39492, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "電車は断続的だ止まり、駅は混乱した。", "corrected_sentence": "電車は断続的に止まり、駅は混乱した。", "error_description": "「断続的に」の「に」が正しい。「断続的だ」は断定の形で、動詞「止まり」を修飾できない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c2077fb-5805-427c-b931-fa45bdbd5b4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39493, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "連続的に", "is_correct": true, "explanation": "途切れずに続くことで、途切れ途切れの断続的の反対の意味を持つ。"}, {"text": "一時的に", "is_correct": false, "explanation": "一定の時間だけという意味で、途切れ途切れの反対とは言えない。"}, {"text": "定期的に", "is_correct": false, "explanation": "決まった間隔で繰り返す意味で、途切れと続きの反対ではない。"}, {"text": "頻繁に", "is_correct": false, "explanation": "回数が多いことを表す語で、続きと途切れの反対の軸ではない。"}], "correct_answer": "連続的に", "explanations": {"連続的に": "途切れずに続くことで、途切れ途切れの断続的の反対の意味を持つ。", "一時的に": "一定の時間だけという意味で、途切れ途切れの反対とは言えない。", "定期的に": "決まった間隔で繰り返す意味で、途切れと続きの反対ではない。", "頻繁に": "回数が多いことを表す語で、続きと途切れの反対の軸ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c2077fb-5805-427c-b931-fa45bdbd5b4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39493, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "連続的に", "is_correct": true, "explanation": "途切れずに続くことで、途切れ途切れの断続的の反対の意味を持つ。"}, {"text": "瞬間的に", "is_correct": false, "explanation": "ごく短い時間に起こる意味で、続き方の反対とは言えない。"}, {"text": "即座に", "is_correct": false, "explanation": "すぐにという意味で、途切れと続きの反対の語ではない。"}, {"text": "大量に", "is_correct": false, "explanation": "数量が多いことを表す語で、続きと途切れの反対の軸ではない。"}], "correct_answer": "連続的に", "explanations": {"連続的に": "途切れずに続くことで、途切れ途切れの断続的の反対の意味を持つ。", "瞬間的に": "ごく短い時間に起こる意味で、続き方の反対とは言えない。", "即座に": "すぐにという意味で、途切れと続きの反対の語ではない。", "大量に": "数量が多いことを表す語で、続きと途切れの反対の軸ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c2077fb-5805-427c-b931-fa45bdbd5b4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39493, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事が途切れ途切れに続くこと。連続しないこと。", "primary_collocate": null, "pronunciation": "だんぞく", "ipa": "dandzokɯ", "syllable_count": 4, "sentences": [{"text": "昼から夜まで、雨が断続的に降り続いた。", "target_word": "断続的に", "complexity_tier": "T3", "furigana": "昼[ひる]から夜[よる]まで、雨[あめ]が断続的[だんぞくてき]に降[ふ]り続[つづ]いた。", "sentence_source": "generated"}, {"text": "夜中、頭の痛みが断続的に続いて、ほとんど眠れなかった。", "target_word": "断続的に", "complexity_tier": "T3", "furigana": "夜中[よなか]、頭[あたま]の痛[いた]みが断続的[だんぞくてき]に続[つづ]いて、ほとんど眠[ねむ]れなかった。", "sentence_source": "generated"}, {"text": "工事の音が断続的に聞こえて、勉強に集中できない。", "target_word": "断続的に", "complexity_tier": "T3", "furigana": "工事[こうじ]の音[おと]が断続的[だんぞくてき]に聞[き]こえて、勉強[べんきょう]に集中[しゅうちゅう]できない。", "sentence_source": "generated"}, {"text": "両国の話し合いは断続的に行われ、三年かかってやっと合意した。", "target_word": "断続的に", "complexity_tier": "T3", "furigana": "両国[りょうこく]の話[はな]し合[あ]いは断続的[だんぞくてき]に行[おこな]われ、三年[さんねん]かかってやっと合意[ごうい]した。", "sentence_source": "generated"}, {"text": "地震のあと、小さな揺れが断続的に起こった。", "target_word": "断続的に", "complexity_tier": "T3", "furigana": "地震[じしん]のあと、小[ちい]さな揺[ゆ]れが断続的[だんぞくてき]に起[お]こった。", "sentence_source": "generated"}, {"text": "彼とは断続的に連絡を取っているが、毎週話すわけではない。", "target_word": "断続的に", "complexity_tier": "T3", "furigana": "彼[かれ]とは断続的[だんぞくてき]に連絡[れんらく]を取[と]っているが、毎週[まいしゅう]話[はな]すわけではない。", "sentence_source": "generated"}, {"text": "遠くで花火の音が断続的に響いていた。", "target_word": "断続的に", "complexity_tier": "T3", "furigana": "遠[とお]くで花火[はなび]の音[おと]が断続的[だんぞくてき]に響[ひび]いていた。", "sentence_source": "generated"}, {"text": "山の中では電波が断続的にしか入らず、電話が何度も切れた。", "target_word": "断続的に", "complexity_tier": "T3", "furigana": "山[やま]の中[なか]では電波[でんぱ]が断続的[だんぞくてき]にしか入[はい]らず、電話[でんわ]が何度[なんど]も切[き]れた。", "sentence_source": "generated"}, {"text": "彼女は断続的に日記をつけていて、まだ一冊も書き終えていない。", "target_word": "断続的に", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は断続的[だんぞくてき]に日記[にっき]をつけていて、まだ一冊[いっさつ]も書[か]き終[お]えていない。", "sentence_source": "generated"}, {"text": "咳が断続的に出るので、病院で診てもらった。", "target_word": "断続的に", "complexity_tier": "T3", "furigana": "咳[せき]が断続的[だんぞくてき]に出[で]るので、病院[びょういん]で診[み]てもらった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "断続的", "label": "語幹"}, {"form": "断続的に", "label": "連用形（副詞的）"}, {"form": "断続的な", "label": "連体形"}], "register": "neutral", "sense_fingerprint": "雨・音・痛み・連絡などが間を置きながら途切れ途切れに続くこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b545744d-41a4-491d-95fb-e6974ddf9eae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39493, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "断続的に", "is_correct": true, "explanation": "途切れ途切れに続く様子を表し、雨の降り方として合う。"}, {"text": "大声で", "is_correct": false, "explanation": "声を大きくする意味で、雨が降り続く様子には合わない。"}, {"text": "丁寧に", "is_correct": false, "explanation": "注意深く行う意味で、雨の降り方には合わない。"}, {"text": "大急ぎで", "is_correct": false, "explanation": "急ぐという意味で、雨が降り続く様子には合わない。"}], "explanations": {"断続的に": "途切れ途切れに続く様子を表し、雨の降り方として合う。", "大声で": "声を大きくする意味で、雨が降り続く様子には合わない。", "丁寧に": "注意深く行う意味で、雨の降り方には合わない。", "大急ぎで": "急ぐという意味で、雨が降り続く様子には合わない。"}, "sentence_index": 0, "correct_answer": "断続的に"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工事は断続的に、一日中休まず続いた。", "explanation": "ここは〈連続的に〉の意味。断続的は途切れ途切れなので、休まず続く場合には使えない。"}, {"text": "雨が断続的に一度だけ降り、昼にはやんだ。", "explanation": "ここは〈一度〉の意味。断続的は途切れてまた続くことを何度も繰り返すので、一度だけの雨には使えない。"}, {"text": "工場の機械が断続的に、常に動いていた。", "explanation": "ここは〈常に〉の意味。断続的は途切れることを表すので、いつも動いている場面には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c2077fb-5805-427c-b931-fa45bdbd5b4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39493, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "断続的に", "is_correct": true, "explanation": "途切れ途切れに響く様子を表し、花火の音として合う。"}, {"text": "大幅に", "is_correct": false, "explanation": "変化の大きさを表す語で、音が響く様子には合わない。"}, {"text": "大量に", "is_correct": false, "explanation": "数量が多いことを表す語で、音が響く様子とは合わない。"}, {"text": "大規模に", "is_correct": false, "explanation": "規模の大きさを表す語で、音が途切れて響く様子には合わない。"}], "explanations": {"断続的に": "途切れ途切れに響く様子を表し、花火の音として合う。", "大幅に": "変化の大きさを表す語で、音が響く様子には合わない。", "大量に": "数量が多いことを表す語で、音が響く様子とは合わない。", "大規模に": "規模の大きさを表す語で、音が途切れて響く様子には合わない。"}, "sentence_index": 6, "correct_answer": "断続的に"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "咳が断続的に一気に出たので、病院で診てもらった。", "explanation": "ここは〈一気に〉の意味。断続的は途切れ途切れなので、一度にまとめて出る咳には合わない。"}, {"text": "咳が断続的に絶え間なく出るので、病院で診てもらった。", "explanation": "ここは〈絶え間なく〉の意味。断続的は途切れることを表し、途切れずに続く咳には使えない。"}, {"text": "咳が断続的に一斉に出たので、病院で診てもらった。", "explanation": "ここは〈一斉に〉の意味。断続的は途切れ途切れのことで、みんなが同時に出る場面には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c2077fb-5805-427c-b931-fa45bdbd5b4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39493, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夜中、咳が断続的から続き、眠れない。", "corrected_sentence": "夜中、咳が断続的に続き、眠れない。", "error_description": "「断続的に」の「に」が正しい。「断続的から」は起点を表す「から」になり、動詞「続き」を修飾できない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c2077fb-5805-427c-b931-fa45bdbd5b4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39493, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工事の音が断続的の聞こえ、夜も眠れない。", "corrected_sentence": "工事の音が断続的に聞こえ、夜も眠れない。", "error_description": "「断続的に」の「に」が正しい。「断続的の」は連体修飾にならず、動詞「聞こえ」を修飾できない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c2077fb-5805-427c-b931-fa45bdbd5b4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39494, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「体力のなさ」を克服の対象として示す目的語の「を」。"}, {"text": "に", "is_correct": false, "explanation": "「体力のなさに克服した」は対象を示せず、不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「体力のなさへ克服した」は方向の意味にならない。"}, {"text": "と", "is_correct": false, "explanation": "「体力のなさと克服した」は動作の相手にならず、文が成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「体力のなさ」を克服の対象として示す目的語の「を」。", "に": "「体力のなさに克服した」は対象を示せず、不自然。", "へ": "「体力のなさへ克服した」は方向の意味にならない。", "と": "「体力のなさと克服した」は動作の相手にならず、文が成り立たない。"}, "error_tags": {"に": "着点・相手", "へ": "方向", "と": "相手・並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c2077fb-5805-427c-b931-fa45bdbd5b4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39494, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「克服」を主題にして「簡単ではない」と述べる「は」。"}, {"text": "を", "is_correct": false, "explanation": "「克服を簡単ではない」は文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「克服に簡単ではない」は不自然で、主題を示せない。"}, {"text": "で", "is_correct": false, "explanation": "「克服で簡単ではない」は手段の意味にならない。"}], "correct_answer": "は", "explanations": {"は": "「克服」を主題にして「簡単ではない」と述べる「は」。", "を": "「克服を簡単ではない」は文が成り立たない。", "に": "「克服に簡単ではない」は不自然で、主題を示せない。", "で": "「克服で簡単ではない」は手段の意味にならない。"}, "error_tags": {"を": "目的語", "に": "着点", "で": "手段"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c2077fb-5805-427c-b931-fa45bdbd5b4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39494, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "難しいことをのりこえること。", "primary_collocate": null, "pronunciation": "こくふく", "ipa": "kokɯɸɯkɯ", "syllable_count": 4, "sentences": [{"text": "高いところが苦手だったが、練習して克服した。", "target_word": "克服", "complexity_tier": "T3", "furigana": "高[たか]いところが苦手[にがて]だったが、練習[れんしゅう]して克服[こくふく]した。", "sentence_source": "generated"}, {"text": "兄は毎日走って、体力のなさを克服した。", "target_word": "克服", "complexity_tier": "T3", "furigana": "兄[あに]は毎日[まいにち]走[はし]って、体力[たいりょく]のなさを克服[こくふく]した。", "sentence_source": "generated"}, {"text": "人前で話す緊張を克服するために、鏡の前で何度も練習した。", "target_word": "克服", "complexity_tier": "T3", "furigana": "人前[ひとまえ]で話[はな]す緊張[きんちょう]を克服[こくふく]するために、鏡[かがみ]の前[まえ]で何度[なんど]も練習[れんしゅう]した。", "sentence_source": "generated"}, {"text": "私は苦手な野菜を克服して、サラダが好きになった。", "target_word": "克服", "complexity_tier": "T3", "furigana": "私[わたし]は苦手[にがて]な野菜[やさい]を克服[こくふく]して、サラダが好[す]きになった。", "sentence_source": "generated"}, {"text": "泳げなかった彼女は、水への恐怖を克服して海で泳いだ。", "target_word": "克服", "complexity_tier": "T3", "furigana": "泳[およ]げなかった彼女[かのじょ]は、水[みず]への恐怖[きょうふ]を克服[こくふく]して海[うみ]で泳[およ]いだ。", "sentence_source": "generated"}, {"text": "英語の発音の弱点を克服するには、毎日声に出して読むのがいい。", "target_word": "克服", "complexity_tier": "T3", "furigana": "英語[えいご]の発音[はつおん]の弱点[じゃくてん]を克服[こくふく]するには、毎日[まいにち]声[こえ]に出[だ]して読[よ]むのがいい。", "sentence_source": "generated"}, {"text": "犬が怖かった弟は、克服できて今は子犬を飼っている。", "target_word": "克服", "complexity_tier": "T3", "furigana": "犬[いぬ]が怖[こわ]かった弟[おとうと]は、克服[こくふく]できて今[いま]は子犬[こいぬ]を飼[か]っている。", "sentence_source": "generated"}, {"text": "悪い癖の克服は簡単ではないが、少しずつ変えていきたい。", "target_word": "克服", "complexity_tier": "T3", "furigana": "悪[わる]い癖[くせ]の克服[こくふく]は簡単[かんたん]ではないが、少[すこ]しずつ変[か]えていきたい。", "sentence_source": "generated"}, {"text": "本番で失敗しないよう、あがり症を克服したいと思っている。", "target_word": "克服", "complexity_tier": "T3", "furigana": "本番[ほんばん]で失敗[しっぱい]しないよう、あがり症[しょう]を克服[こくふく]したいと思[おも]っている。", "sentence_source": "generated"}, {"text": "彼は漢字が苦手だったが、毎晩の勉強で克服できた。", "target_word": "克服", "complexity_tier": "T3", "furigana": "彼[かれ]は漢字[かんじ]が苦手[にがて]だったが、毎晩[まいばん]の勉強[べんきょう]で克服[こくふく]できた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "克服する", "label": "辞書形"}, {"form": "克服した", "label": "過去形"}, {"form": "克服して", "label": "て形"}, {"form": "克服できる", "label": "可能形"}], "register": "neutral", "sense_fingerprint": "苦手・弱点・恐怖・癖など身近な難しさをのりこえること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b545744d-41a4-491d-95fb-e6974ddf9eae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39494, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "克服", "is_correct": true, "explanation": "「練習して克服した」となり、苦手を乗りこえたという文脈に合う。"}, {"text": "無視", "is_correct": false, "explanation": "「練習して無視した」では苦手を乗りこえた意味にならず、文脈に合わない。"}, {"text": "注文", "is_correct": false, "explanation": "「練習して注文した」は文として意味が通らない。"}, {"text": "減速", "is_correct": false, "explanation": "「練習して減速した」は苦手の克服の話と結びつかない。"}], "explanations": {"克服": "「練習して克服した」となり、苦手を乗りこえたという文脈に合う。", "無視": "「練習して無視した」では苦手を乗りこえた意味にならず、文脈に合わない。", "注文": "「練習して注文した」は文として意味が通らない。", "減速": "「練習して減速した」は苦手の克服の話と結びつかない。"}, "sentence_index": 0, "correct_answer": "克服"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は三日で長い本を克服した。", "explanation": "ここは〈読了〉の意味。本は読み終えるもので、克服は困難に打ち勝つことを指さない。"}, {"text": "彼は一年かけて、大作の小説を克服した。", "explanation": "ここは〈完成〉の意味。小説は書き上げるもので、克服は困難に打ち勝つことを指さない。"}, {"text": "警察は事件の真相を克服した。", "explanation": "ここは〈解明〉の意味。真相は突き止めるもので、克服は困難に打ち勝つことには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c2077fb-5805-427c-b931-fa45bdbd5b4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39494, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "克服", "is_correct": true, "explanation": "「克服できて」となり、犬への怖さを乗りこえた状況に合う。"}, {"text": "出発", "is_correct": false, "explanation": "「出発できて」では犬を怖がっていた弟の状況と結びつかない。"}, {"text": "謝罪", "is_correct": false, "explanation": "「謝罪できて」は犬への怖さとつながらず、文意が通らない。"}, {"text": "報告", "is_correct": false, "explanation": "「報告できて」は子犬を飼うまでの経緯として意味が通らない。"}], "explanations": {"克服": "「克服できて」となり、犬への怖さを乗りこえた状況に合う。", "出発": "「出発できて」では犬を怖がっていた弟の状況と結びつかない。", "謝罪": "「謝罪できて」は犬への怖さとつながらず、文意が通らない。", "報告": "「報告できて」は子犬を飼うまでの経緯として意味が通らない。"}, "sentence_index": 6, "correct_answer": "克服"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は新しい資格を克服した。", "explanation": "ここは〈獲得〉の意味。資格は取得するもので、克服は困難や弱点に打ち勝つことに使う。"}, {"text": "店は一週間で在庫を克服した。", "explanation": "ここは〈解消〉の意味。余った在庫は取り除くもので、克服は困難に打ち勝つことを指さない。"}, {"text": "週末、彼は祖父の家を克服して、みんなで食事をした。", "explanation": "ここは〈訪問〉の意味。家は訪ねるもので、克服は困難に打ち勝つことを指さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c2077fb-5805-427c-b931-fa45bdbd5b4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39494, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "新しい環境に慣れるまで、不安を克服で一歩ずつ進んだ。", "corrected_sentence": "新しい環境に慣れるまで、不安を克服して一歩ずつ進んだ。", "error_description": "「克服で」は誤り。後ろの文へつなぐには「克服して」（て形）が必要。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c2077fb-5805-427c-b931-fa45bdbd5b4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39494, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "長く続いた体調不良を克服、ようやく仕事に戻れた。", "corrected_sentence": "長く続いた体調不良を克服して、ようやく仕事に戻れた。", "error_description": "「克服して」の「して」が抜けている。「克服、ようやく」では文が続かない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c2077fb-5805-427c-b931-fa45bdbd5b4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39495, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「不況を」は克服の目的語を示す「を」。"}, {"text": "に", "is_correct": false, "explanation": "「不況に克服するために」は対象を示せず、不自然。"}, {"text": "で", "is_correct": false, "explanation": "「不況で克服するために」は手段の意味にならない。"}, {"text": "へ", "is_correct": false, "explanation": "「不況へ克服するために」は方向の意味にならない。"}], "correct_answer": "を", "explanations": {"を": "「不況を」は克服の目的語を示す「を」。", "に": "「不況に克服するために」は対象を示せず、不自然。", "で": "「不況で克服するために」は手段の意味にならない。", "へ": "「不況へ克服するために」は方向の意味にならない。"}, "error_tags": {"に": "着点・相手", "で": "手段", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c2077fb-5805-427c-b931-fa45bdbd5b4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39495, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「克服に」は「には」の形で、克服を主題として示す「に」。"}, {"text": "を", "is_correct": false, "explanation": "「克服を」は後続の述語と結びつかず、文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「克服へ」は方向の意味にならず、不自然。"}, {"text": "と", "is_correct": false, "explanation": "「克服とは」は定義の形になり、「欠かせなかった」と続かず不自然。"}], "correct_answer": "に", "explanations": {"に": "「克服に」は「には」の形で、克服を主題として示す「に」。", "を": "「克服を」は後続の述語と結びつかず、文が成り立たない。", "へ": "「克服へ」は方向の意味にならず、不自然。", "と": "「克服とは」は定義の形になり、「欠かせなかった」と続かず不自然。"}, "error_tags": {"を": "目的語", "へ": "方向", "と": "相手・並列"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c2077fb-5805-427c-b931-fa45bdbd5b4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39495, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "困難や障害に打ち勝ち、乗り越えること。", "primary_collocate": null, "pronunciation": "こくふく", "ipa": "kokɯɸɯkɯ", "syllable_count": 4, "sentences": [{"text": "彼は大きな病気を克服し、再びマラソンを走った。", "target_word": "克服", "complexity_tier": "T3", "furigana": "彼[かれ]は大[おお]きな病気[びょうき]を克服[こくふく]し、再[ふたた]びマラソンを走[はし]った。", "sentence_source": "generated"}, {"text": "会社は不況を克服するために、新しい商品を作った。", "target_word": "克服", "complexity_tier": "T3", "furigana": "会社[かいしゃ]は不況[ふきょう]を克服[こくふく]するために、新[あたら]しい商品[しょうひん]を作[つく]った。", "sentence_source": "generated"}, {"text": "貧しさを克服した彼女は、のちに有名な医者になった。", "target_word": "克服", "complexity_tier": "T3", "furigana": "貧[まず]しさを克服[こくふく]した彼女[かのじょ]は、のちに有名[ゆうめい]な医者[いしゃ]になった。", "sentence_source": "generated"}, {"text": "選手はけがを克服して、四年後の大会で金メダルを取った。", "target_word": "克服", "complexity_tier": "T3", "furigana": "選手[せんしゅ]はけがを克服[こくふく]して、四年後[よねんご]の大会[たいかい]で金[きん]メダルを取[と]った。", "sentence_source": "generated"}, {"text": "町の人々は津波の被害を克服しようと、力を合わせて働いた。", "target_word": "克服", "complexity_tier": "T3", "furigana": "町[まち]の人々[ひとびと]は津波[つなみ]の被害[ひがい]を克服[こくふく]しようと、力[ちから]を合[あ]わせて働[はたら]いた。", "sentence_source": "generated"}, {"text": "言葉の壁を克服した移民たちが、この町で店を開いた。", "target_word": "克服", "complexity_tier": "T3", "furigana": "言葉[ことば]の壁[かべ]を克服[こくふく]した移民[いみん]たちが、この町[まち]で店[みせ]を開[ひら]いた。", "sentence_source": "generated"}, {"text": "科学者たちはその病気を克服する薬を長い間研究している。", "target_word": "克服", "complexity_tier": "T3", "furigana": "科学者[かがくしゃ]たちはその病気[びょうき]を克服[こくふく]する薬[くすり]を長[なが]い間[あいだ]研究[けんきゅう]している。", "sentence_source": "generated"}, {"text": "困難の克服には、仲間の支えが欠かせなかった。", "target_word": "克服", "complexity_tier": "T3", "furigana": "困難[こんなん]の克服[こくふく]には、仲間[なかま]の支[ささ]えが欠[か]かせなかった。", "sentence_source": "generated"}, {"text": "国は食料不足を克服し、輸出ができるまでになった。", "target_word": "克服", "complexity_tier": "T3", "furigana": "国[くに]は食料[しょくりょう]不足[ぶそく]を克服[こくふく]し、輸出[ゆしゅつ]ができるまでになった。", "sentence_source": "generated"}, {"text": "彼は厳しい環境を克服して、会社を大きくした。", "target_word": "克服", "complexity_tier": "T3", "furigana": "彼[かれ]は厳[きび]しい環境[かんきょう]を克服[こくふく]して、会社[かいしゃ]を大[おお]きくした。", "sentence_source": "generated"}], "morphological_forms": [{"form": "克服する", "label": "辞書形"}, {"form": "克服した", "label": "過去形"}, {"form": "克服して", "label": "て形"}, {"form": "克服できる", "label": "可能形"}], "register": "neutral", "sense_fingerprint": "病気・けが・不況・貧困など大きな困難や障害に打ち勝つこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b545744d-41a4-491d-95fb-e6974ddf9eae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39495, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "克服", "is_correct": true, "explanation": "「病気を克服し」で、病気に打ち勝って再び走ったという流れに合う。"}, {"text": "注文", "is_correct": false, "explanation": "「病気を注文し」は文意が通らない。"}, {"text": "出発", "is_correct": false, "explanation": "「病気を出発し」は病気との文脈に合わない。"}, {"text": "減速", "is_correct": false, "explanation": "「病気を減速し」は病気を乗りこえた文脈と合わない。"}], "explanations": {"克服": "「病気を克服し」で、病気に打ち勝って再び走ったという流れに合う。", "注文": "「病気を注文し」は文意が通らない。", "出発": "「病気を出発し」は病気との文脈に合わない。", "減速": "「病気を減速し」は病気を乗りこえた文脈と合わない。"}, "sentence_index": 0, "correct_answer": "克服"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は運転免許を克服した。", "explanation": "ここは〈取得〉の意味。免許は取るもので、克服は困難や障害に打ち勝つことに使う。"}, {"text": "研究者は長年の謎を克服した。", "explanation": "ここは〈解明〉の意味。謎は解き明かすもので、克服は困難に打ち勝つことには使わない。"}, {"text": "店は一週間で在庫を克服した。", "explanation": "ここは〈解消〉の意味。余った在庫は取り除くもので、克服は困難に打ち勝つことを指さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c2077fb-5805-427c-b931-fa45bdbd5b4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39495, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "克服", "is_correct": true, "explanation": "「病気を克服する薬」で、病気に打ち勝つための薬という文脈に合う。"}, {"text": "購入", "is_correct": false, "explanation": "「病気を購入する薬」は文意が通らない。"}, {"text": "撮影", "is_correct": false, "explanation": "「病気を撮影する薬」は意味をなさない。"}, {"text": "更新", "is_correct": false, "explanation": "「病気を更新する薬」は病気の研究の文脈と合わない。"}], "explanations": {"克服": "「病気を克服する薬」で、病気に打ち勝つための薬という文脈に合う。", "購入": "「病気を購入する薬」は文意が通らない。", "撮影": "「病気を撮影する薬」は意味をなさない。", "更新": "「病気を更新する薬」は病気の研究の文脈と合わない。"}, "sentence_index": 6, "correct_answer": "克服"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女は半年かけて古い辞書を克服した。", "explanation": "ここは〈読破〉の意味。辞書は読み通すもので、克服は困難に打ち勝つことを指さない。"}, {"text": "彼女は一年かけて、大きな絵画を克服した。", "explanation": "ここは〈完成〉の意味。絵画は仕上げるもので、克服は困難に打ち勝つことを指さない。"}, {"text": "新しい服を克服して、パーティーに出かけた。", "explanation": "ここは〈着用〉の意味。服は身につけるもので、克服は困難に打ち勝つことを指さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c2077fb-5805-427c-b931-fa45bdbd5b4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39495, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "長年の赤字を克服に、店は再び黒字になった。", "corrected_sentence": "長年の赤字を克服して、店は再び黒字になった。", "error_description": "「克服して」（て形）が正しい。「克服に」では文の形が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c2077fb-5805-427c-b931-fa45bdbd5b4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39495, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "厳しい寒さを克服をため、農家は温室を建てた。", "corrected_sentence": "厳しい寒さを克服するため、農家は温室を建てた。", "error_description": "「克服する」の「する」が「を」になっている。動詞の終止形＋「ため」（目的）が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c2077fb-5805-427c-b931-fa45bdbd5b4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39496, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「入っている」の主語は「が」で示すので、リチウムに続けるのは「が」。"}, {"text": "を", "is_correct": false, "explanation": "「入る」は目的語に「を」をとらず、入るものは主語になるので不自然。"}, {"text": "に", "is_correct": false, "explanation": "「に」は場所や相手を示すので、入っているものの主語にはならない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、入っている状態を表す文には合わない。"}], "correct_answer": "が", "explanations": {"が": "「入っている」の主語は「が」で示すので、リチウムに続けるのは「が」。", "を": "「入る」は目的語に「を」をとらず、入るものは主語になるので不自然。", "に": "「に」は場所や相手を示すので、入っているものの主語にはならない。", "へ": "「へ」は方向を示すので、入っている状態を表す文には合わない。"}, "error_tags": {"を": "目的語", "に": "場所・相手", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40f14b35-1271-4760-b951-b1670908809b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39496, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「欠かせない」の主語は「が」で示すので、リチウムに続けるのは「が」。"}, {"text": "を", "is_correct": false, "explanation": "「欠かせない」は「が」で主語を示す文なので、「を」は不自然。"}, {"text": "の", "is_correct": false, "explanation": "「の」では所属を示すだけで、「欠かせない」の主語にはならない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、「欠かせない」の主語にはならない。"}], "correct_answer": "が", "explanations": {"が": "「欠かせない」の主語は「が」で示すので、リチウムに続けるのは「が」。", "を": "「欠かせない」は「が」で主語を示す文なので、「を」は不自然。", "の": "「の」では所属を示すだけで、「欠かせない」の主語にはならない。", "へ": "「へ」は方向を示すので、「欠かせない」の主語にはならない。"}, "error_tags": {"を": "目的語", "の": "所属・修飾", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40f14b35-1271-4760-b951-b1670908809b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39496, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "リチウムは、とても軽い金属で、電池に使われることが多いです。", "primary_collocate": null, "pronunciation": "りちうむ", "ipa": "ɾitɕiɯmɯ", "syllable_count": 4, "sentences": [{"text": "リチウムは軽い金属で、電池によく使われる。", "target_word": "リチウム", "complexity_tier": "T3", "furigana": "リチウムは軽[かる]い金属[きんぞく]で、電池[でんち]によく使[つか]われる。", "sentence_source": "generated"}, {"text": "スマートフォンの電池には、リチウムが入っている。", "target_word": "リチウム", "complexity_tier": "T3", "furigana": "スマートフォンの電池[でんち]には、リチウムが入[はい]っている。", "sentence_source": "generated"}, {"text": "リチウムはとても軽いので、水に浮かぶ。", "target_word": "リチウム", "complexity_tier": "T3", "furigana": "リチウムはとても軽[かる]いので、水[みず]に浮[う]かぶ。", "sentence_source": "generated"}, {"text": "この会社は、電池に使うリチウムを外国から買っている。", "target_word": "リチウム", "complexity_tier": "T3", "furigana": "この会社[かいしゃ]は、電池[でんち]に使[つか]うリチウムを外国[がいこく]から買[か]っている。", "sentence_source": "generated"}, {"text": "リチウムを使った電池は、小さいのに長く使える。", "target_word": "リチウム", "complexity_tier": "T3", "furigana": "リチウムを使[つか]った電池[でんち]は、小[ちい]さいのに長[なが]く使[つか]える。", "sentence_source": "generated"}, {"text": "弟は理科の授業で、リチウムという金属の名前を習った。", "target_word": "リチウム", "complexity_tier": "T3", "furigana": "弟[おとうと]は理科[りか]の授業[じゅぎょう]で、リチウムという金属[きんぞく]の名前[なまえ]を習[なら]った。", "sentence_source": "generated"}, {"text": "リチウムは貴重な資源なので、使い終わった電池から集める試みもある。", "target_word": "リチウム", "complexity_tier": "T3", "furigana": "リチウムは貴重[きちょう]な資源[しげん]なので、使[つか]い終[お]わった電池[でんち]から集[あつ]める試[こころ]みもある。", "sentence_source": "generated"}, {"text": "電気自動車の電池にも、リチウムが欠かせない。", "target_word": "リチウム", "complexity_tier": "T3", "furigana": "電気自動車[でんきじどうしゃ]の電池[でんち]にも、リチウムが欠[か]かせない。", "sentence_source": "generated"}, {"text": "軽い金属のなかでも、リチウムは特に軽い。", "target_word": "リチウム", "complexity_tier": "T3", "furigana": "軽[かる]い金属[きんぞく]のなかでも、リチウムは特[とく]に軽[かる]い。", "sentence_source": "generated"}, {"text": "工場では、リチウムが空気にふれないように気をつけて扱う。", "target_word": "リチウム", "complexity_tier": "T3", "furigana": "工場[こうじょう]では、リチウムが空気[くうき]にふれないように気[き]をつけて扱[あつか]う。", "sentence_source": "generated"}], "morphological_forms": [{"form": "リチウム", "label": "基本形"}], "register": "中立", "sense_fingerprint": "とても軽くて、電池によく使われる金属", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f06b4680-4fa3-4940-ae92-665bd01dff19') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39496, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "リチウム", "is_correct": true, "explanation": "「軽い金属で電池によく使われる」に当たる元素名。"}, {"text": "鉄", "is_correct": false, "explanation": "鉄は重い金属で、「軽い金属」とは合わない。"}, {"text": "酸素", "is_correct": false, "explanation": "酸素は気体で、金属ではないので合わない。"}, {"text": "電池", "is_correct": false, "explanation": "電池は金属ではないので、「軽い金属で」の主語にならない。"}], "explanations": {"リチウム": "「軽い金属で電池によく使われる」に当たる元素名。", "鉄": "鉄は重い金属で、「軽い金属」とは合わない。", "酸素": "酸素は気体で、金属ではないので合わない。", "電池": "電池は金属ではないので、「軽い金属で」の主語にならない。"}, "sentence_index": 0, "correct_answer": "リチウム"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "リチウムは軽い気体なので、風船を浮かせるのに使われる。", "explanation": "ここは〈ヘリウム〉の性質。リチウムは金属で、気体の風船には使わない。"}, {"text": "リチウムは重くて硬いので、建物の骨組みに使われる。", "explanation": "ここは〈鉄〉の用途。リチウムは軽い金属なので、重さが必要な骨組みには合わない。"}, {"text": "リチウムは食塩の主成分で、料理の味つけに欠かせない。", "explanation": "ここは〈ナトリウム〉の話。食塩の主成分はナトリウムで、リチウムではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40f14b35-1271-4760-b951-b1670908809b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39496, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "リチウム", "is_correct": true, "explanation": "「貴重な資源で、電池から集める試みがある」に当たる元素名。"}, {"text": "風船", "is_correct": false, "explanation": "風船は資源ではなく、電池から集める対象にもならない。"}, {"text": "煙", "is_correct": false, "explanation": "煙は資源として集める対象ではなく、文の主語としても合わない。"}, {"text": "花火", "is_correct": false, "explanation": "花火は資源ではなく、電池から集めるものでもない。"}], "explanations": {"リチウム": "「貴重な資源で、電池から集める試みがある」に当たる元素名。", "風船": "風船は資源ではなく、電池から集める対象にもならない。", "煙": "煙は資源として集める対象ではなく、文の主語としても合わない。", "花火": "花火は資源ではなく、電池から集めるものでもない。"}, "sentence_index": 6, "correct_answer": "リチウム"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "リチウムは体に必要なミネラルで、野菜や果物に多く含まれる。", "explanation": "ここは〈カリウム〉の話。野菜や果物に多い必須ミネラルはカリウムで、リチウムには当てはまらない。"}, {"text": "リチウムは軽くて加工しやすく、飲み物の缶によく使われる。", "explanation": "ここは〈アルミニウム〉の用途。飲み物の缶に使われる軽金属はアルミニウムで、リチウムの用途ではない。"}, {"text": "リチウムは骨をつくる成分で、牛乳に多く含まれる。", "explanation": "ここは〈カルシウム〉の話。骨や牛乳の成分はカルシウムで、リチウムの性質ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40f14b35-1271-4760-b951-b1670908809b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39496, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "電池にはリチウムに使われている。", "corrected_sentence": "電池にはリチウムが使われている。", "error_description": "助詞の誤り。「使われる」は受け身で、使われるものが主語になるので「が」をとる。「に」は不自然で、正しくは「リチウムが」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40f14b35-1271-4760-b951-b1670908809b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39496, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "リチウムが含む電池は、軽くて長持ちする。", "corrected_sentence": "リチウムを含む電池は、軽くて長持ちする。", "error_description": "助詞の誤り。「含む」は目的語に「を」をとる。「が」だと主語のように読まれて不自然で、正しくは「リチウムを」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40f14b35-1271-4760-b951-b1670908809b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39497, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "話題として取り上げる「は」で、リチウムに続けると文の主題になる。"}, {"text": "を", "is_correct": false, "explanation": "「反応性が高い」は主語と形容詞の文なので、目的語の「を」は不要で不自然。"}, {"text": "に", "is_correct": false, "explanation": "「に」は場所や相手を示すので、文の主題にはならない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、「リチウムへ反応性が高い」という状態の文には合わない。"}], "correct_answer": "は", "explanations": {"は": "話題として取り上げる「は」で、リチウムに続けると文の主題になる。", "を": "「反応性が高い」は主語と形容詞の文なので、目的語の「を」は不要で不自然。", "に": "「に」は場所や相手を示すので、文の主題にはならない。", "へ": "「へ」は方向を示すので、「リチウムへ反応性が高い」という状態の文には合わない。"}, "error_tags": {"を": "目的語", "に": "場所・相手", "で": "手段・原因"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40f14b35-1271-4760-b951-b1670908809b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39497, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「採掘」を修飾する所属の「の」で、リチウムに続けると「リチウムの採掘」になる。"}, {"text": "を", "is_correct": false, "explanation": "「リチウムを採掘」は動詞の目的語を取る形で、名詞「採掘」に続く主題の文では「を」は成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は場所や相手を示すので、「採掘」に続く形としては合わない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を示すので、「リチウムからの採掘」は採掘の対象を表せず不自然。"}], "correct_answer": "の", "explanations": {"の": "「採掘」を修飾する所属の「の」で、リチウムに続けると「リチウムの採掘」になる。", "を": "「リチウムを採掘」は動詞の目的語を取る形で、名詞「採掘」に続く主題の文では「を」は成り立たない。", "に": "「に」は場所や相手を示すので、「採掘」に続く形としては合わない。", "から": "「から」は起点を示すので、「リチウムからの採掘」は採掘の対象を表せず不自然。"}, "error_tags": {"を": "目的語", "に": "場所・相手", "から": "起点（採掘の対象にならない）"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40f14b35-1271-4760-b951-b1670908809b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39497, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "リチウムは、原子番号3のアルカリ金属元素で、軽量で反応性が高く、主にリチウムイオン電池の材料として利用されます。", "primary_collocate": null, "pronunciation": "りちうむ", "ipa": "ɾitɕiɯmɯ", "syllable_count": 4, "sentences": [{"text": "リチウムは原子番号3のアルカリ金属で、周期表の第2周期に属する。", "target_word": "リチウム", "complexity_tier": "T3", "furigana": "リチウムは原子番号[げんしばんごう]3のアルカリ金属[きんぞく]で、周期表[しゅうきひょう]の第[だい]2周期[しゅうき]に属[ぞく]する。", "sentence_source": "generated"}, {"text": "リチウムは反応性が高いため、水に入れると激しく反応する。", "target_word": "リチウム", "complexity_tier": "T3", "furigana": "リチウムは反応性[はんのうせい]が高[たか]いため、水[みず]に入[い]れると激[はげ]しく反応[はんのう]する。", "sentence_source": "generated"}, {"text": "電池の材料としてのリチウムの需要が、年々増えている。", "target_word": "リチウム", "complexity_tier": "T3", "furigana": "電池[でんち]の材料[ざいりょう]としてのリチウムの需要[じゅよう]が、年々[ねんねん]増[ふ]えている。", "sentence_source": "generated"}, {"text": "南米の塩湖は、リチウムの主要な産地として知られている。", "target_word": "リチウム", "complexity_tier": "T3", "furigana": "南米[なんべい]の塩湖[えんこ]は、リチウムの主要[しゅよう]な産地[さんち]として知[し]られている。", "sentence_source": "generated"}, {"text": "リチウムは軽量で、エネルギーを多くためられる点が評価されている。", "target_word": "リチウム", "complexity_tier": "T3", "furigana": "リチウムは軽量[けいりょう]で、エネルギーを多[おお]くためられる点[てん]が評価[ひょうか]されている。", "sentence_source": "generated"}, {"text": "研究者は、リチウムの代わりになる安価な材料を探している。", "target_word": "リチウム", "complexity_tier": "T3", "furigana": "研究者[けんきゅうしゃ]は、リチウムの代[か]わりになる安価[あんか]な材料[ざいりょう]を探[さが]している。", "sentence_source": "generated"}, {"text": "純粋なリチウムは銀白色で、ナイフで切れるほどやわらかい。", "target_word": "リチウム", "complexity_tier": "T3", "furigana": "純粋[じゅんすい]なリチウムは銀白色[ぎんはくしょく]で、ナイフで切[き]れるほどやわらかい。", "sentence_source": "generated"}, {"text": "リチウムの採掘は環境への影響が大きいと指摘されている。", "target_word": "リチウム", "complexity_tier": "T3", "furigana": "リチウムの採掘[さいくつ]は環境[かんきょう]への影響[えいきょう]が大[おお]きいと指摘[してき]されている。", "sentence_source": "generated"}, {"text": "実験室では、リチウムを石油の中に保管して酸化を防ぐ。", "target_word": "リチウム", "complexity_tier": "T3", "furigana": "実験室[じっけんしつ]では、リチウムを石油[せきゆ]の中[なか]に保管[ほかん]して酸化[さんか]を防[ふせ]ぐ。", "sentence_source": "generated"}, {"text": "リチウムの価格が上がり、電池メーカーは調達先を増やした。", "target_word": "リチウム", "complexity_tier": "T3", "furigana": "リチウムの価格[かかく]が上[あ]がり、電池[でんち]メーカーは調達先[ちょうたつさき]を増[ふ]やした。", "sentence_source": "generated"}], "morphological_forms": [{"form": "リチウム", "label": "基本形"}], "register": "硬い(専門的)", "sense_fingerprint": "原子番号3のアルカリ金属元素で、軽く反応性が高く、電池の材料になる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f06b4680-4fa3-4940-ae92-665bd01dff19') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39497, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "リチウム", "is_correct": true, "explanation": "「原子番号3のアルカリ金属で周期表の第2周期」に当たる元素名。"}, {"text": "水素", "is_correct": false, "explanation": "水素は原子番号1の気体で、アルカリ金属ではないので合わない。"}, {"text": "酸素", "is_correct": false, "explanation": "酸素は非金属の気体で、アルカリ金属ではないので合わない。"}, {"text": "銅", "is_correct": false, "explanation": "銅は遷移金属で、アルカリ金属ではないので合わない。"}], "explanations": {"リチウム": "「原子番号3のアルカリ金属で周期表の第2周期」に当たる元素名。", "水素": "水素は原子番号1の気体で、アルカリ金属ではないので合わない。", "酸素": "酸素は非金属の気体で、アルカリ金属ではないので合わない。", "銅": "銅は遷移金属で、アルカリ金属ではないので合わない。"}, "sentence_index": 0, "correct_answer": "リチウム"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "リチウムは気体で、燃料電池の燃料として使われている。", "explanation": "ここは〈水素〉の性質。リチウムは固体の金属で、気体の燃料には当たらない。"}, {"text": "リチウムは電気をよく通すので、家庭の電線に多く使われている。", "explanation": "ここは〈銅〉の用途。家庭の電線に使われるのは銅で、リチウムの用途ではない。"}, {"text": "リチウムは炎色反応で黄色く光るので、花火の色づけに使われる。", "explanation": "ここは〈ナトリウム〉の性質。黄色い炎色反応を示すのはナトリウムで、リチウムではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40f14b35-1271-4760-b951-b1670908809b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39497, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "リチウム", "is_correct": true, "explanation": "「銀白色で、ナイフで切れるほどやわらかい」に当たる元素名。"}, {"text": "鉄", "is_correct": false, "explanation": "鉄は硬く、ナイフで切れるほどやわらかくはないので合わない。"}, {"text": "炭素", "is_correct": false, "explanation": "炭素は黒っぽく、銀白色ではないので合わない。"}, {"text": "窒素", "is_correct": false, "explanation": "窒素は無色の気体で、金属ではないので合わない。"}], "explanations": {"リチウム": "「銀白色で、ナイフで切れるほどやわらかい」に当たる元素名。", "鉄": "鉄は硬く、ナイフで切れるほどやわらかくはないので合わない。", "炭素": "炭素は黒っぽく、銀白色ではないので合わない。", "窒素": "窒素は無色の気体で、金属ではないので合わない。"}, "sentence_index": 6, "correct_answer": "リチウム"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "リチウムは炎の色を紫に変えるので、炎色反応の検査に使われる。", "explanation": "ここは〈カリウム〉の性質。炎色反応で紫色を示すのはカリウムで、リチウムの性質ではない。"}, {"text": "リチウムは地殻に最も多い金属で、橋の材料によく使われる。", "explanation": "ここは〈アルミニウム〉の話。地殻に最も多い金属はアルミニウムで、リチウムには当てはまらない。"}, {"text": "リチウムは黄色い固体で、火山のまわりに多く見られる。", "explanation": "ここは〈硫黄〉の話。黄色い固体で火山付近に多いのは硫黄で、リチウムは銀白色の金属。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40f14b35-1271-4760-b951-b1670908809b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
