INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39498, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "イオンは、電気を帯びた小さなつぶのことです。", "primary_collocate": null, "pronunciation": "いおん", "ipa": "ioɴ", "syllable_count": 3, "sentences": [{"text": "イオンは、とても小さいつぶです。", "target_word": "イオン", "complexity_tier": "T2", "furigana": "", "sentence_source": "generated"}, {"text": "イオンには、プラスやマイナスの電気があります。", "target_word": "イオン", "complexity_tier": "T2", "furigana": "", "sentence_source": "generated"}, {"text": "水の中に、イオンがあります。", "target_word": "イオン", "complexity_tier": "T2", "furigana": "", "sentence_source": "generated"}, {"text": "先生がイオンの話をしました。", "target_word": "イオン", "complexity_tier": "T2", "furigana": "", "sentence_source": "generated"}, {"text": "イオンは目に見えません。", "target_word": "イオン", "complexity_tier": "T2", "furigana": "", "sentence_source": "generated"}, {"text": "この水にはイオンが入っています。", "target_word": "イオン", "complexity_tier": "T2", "furigana": "", "sentence_source": "generated"}, {"text": "イオンを調べる実験をしました。", "target_word": "イオン", "complexity_tier": "T2", "furigana": "", "sentence_source": "generated"}, {"text": "電気を帯びたつぶを、イオンと呼ぶ。", "target_word": "イオン", "complexity_tier": "T3", "furigana": "", "sentence_source": "generated"}, {"text": "イオンの本を図書館で借りた。", "target_word": "イオン", "complexity_tier": "T2", "furigana": "", "sentence_source": "generated"}, {"text": "プラスのイオンとマイナスのイオンがある。", "target_word": "イオン", "complexity_tier": "T3", "furigana": "", "sentence_source": "generated"}], "morphological_forms": [], "register": "plain", "sense_fingerprint": "名詞 | 電気を帯びた小さなつぶ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '706f6503-4810-49ec-aa3e-5da3ec8990bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39498, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "イオン", "is_correct": true, "explanation": "イオンはとても小さいつぶ、という文意に合う。"}, {"text": "山", "is_correct": false, "explanation": "形は合うが、山は小さいつぶではなく意味が合わない。"}, {"text": "象", "is_correct": false, "explanation": "形は合うが、象は大きな動物で「小さいつぶ」と合わない。"}, {"text": "空", "is_correct": false, "explanation": "形は合うが、空は小さいつぶではなく意味が合わない。"}], "explanations": {"イオン": "イオンはとても小さいつぶ、という文意に合う。", "山": "形は合うが、山は小さいつぶではなく意味が合わない。", "象": "形は合うが、象は大きな動物で「小さいつぶ」と合わない。", "空": "形は合うが、空は小さいつぶではなく意味が合わない。"}, "sentence_index": 0, "correct_answer": "イオン"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "イオンは大きな動物なので、動物園で見られます。", "explanation": "イオンは小さいつぶであり、動物ではないので意味が誤り。"}, {"text": "イオンの電気を、ごはんにかけて食べました。", "explanation": "イオンや電気は食べ物にかけるものではなく、使い方が誤り。"}, {"text": "昨日、イオンに乗って学校へ行きました。", "explanation": "イオンは乗り物ではないので、「乗る」の対象にするのは誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63e7f52c-280f-4c6b-b3bb-5d30c4ee1874') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39498, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "イオン", "is_correct": true, "explanation": "イオンを調べる実験は自然で意味が合う。"}, {"text": "約束", "is_correct": false, "explanation": "形は合うが、約束を調べる実験は意味が合わない。"}, {"text": "誕生日", "is_correct": false, "explanation": "形は合うが、誕生日を調べる実験は意味が合わない。"}, {"text": "朝", "is_correct": false, "explanation": "形は合うが、朝を調べる実験は意味が合わない。"}], "explanations": {"イオン": "イオンを調べる実験は自然で意味が合う。", "約束": "形は合うが、約束を調べる実験は意味が合わない。", "誕生日": "形は合うが、誕生日を調べる実験は意味が合わない。", "朝": "形は合うが、朝を調べる実験は意味が合わない。"}, "sentence_index": 6, "correct_answer": "イオン"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大きなイオンを、手でつかんで持ち上げた。", "explanation": "イオンは目に見えない小さなつぶで、手でつかめないので誤り。"}, {"text": "イオンは、朝になると鳴き始める。", "explanation": "イオンは生き物ではないので「鳴く」の主語にならず誤り。"}, {"text": "私はイオンを着て出かけた。", "explanation": "イオンは衣服ではないので、「着る」の対象にするのは誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63e7f52c-280f-4c6b-b3bb-5d30c4ee1874') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39498, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "水の中に、イオンがいます。", "corrected_sentence": "水の中に、イオンがあります。", "error_description": "イオンは生き物ではないので「いる」ではなく「ある」を使う。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63e7f52c-280f-4c6b-b3bb-5d30c4ee1874') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39498, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この水にはイオンが話しています。", "corrected_sentence": "この水にはイオンが入っています。", "error_description": "イオンは話さない。水の中に「入っている」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63e7f52c-280f-4c6b-b3bb-5d30c4ee1874') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39499, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「イオンになる」で変化の結果を表す。"}, {"text": "を", "is_correct": false, "explanation": "「なる」は「を」を取らないので不適切。"}, {"text": "が", "is_correct": false, "explanation": "「イオンがなる」では変化の結果を表せず不適切。"}, {"text": "の", "is_correct": false, "explanation": "「イオンのなる」は文として成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「イオンになる」で変化の結果を表す。", "を": "「なる」は「を」を取らないので不適切。", "が": "「イオンがなる」では変化の結果を表せず不適切。", "の": "「イオンのなる」は文として成り立たない。"}, "error_tags": {"を": "object_marker", "が": "subject_marker", "の": "possessive"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63e7f52c-280f-4c6b-b3bb-5d30c4ee1874') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39499, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "イオンが運ぶ主体なので「が」。"}, {"text": "を", "is_correct": false, "explanation": "後ろにも「を」があり、「を」が二つ続いて不適切。"}, {"text": "な", "is_correct": false, "explanation": "「イオンな」は名詞に「な」が付いた形で、文法的に誤り。"}, {"text": "ば", "is_correct": false, "explanation": "名詞に「ば」は直接付かず、文法的に誤り。"}], "correct_answer": "が", "explanations": {"が": "イオンが運ぶ主体なので「が」。", "を": "後ろにも「を」があり、「を」が二つ続いて不適切。", "な": "「イオンな」は名詞に「な」が付いた形で、文法的に誤り。", "ば": "名詞に「ば」は直接付かず、文法的に誤り。"}, "error_tags": {"を": "object_marker", "な": "adjectival_na", "ば": "conditional_particle"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63e7f52c-280f-4c6b-b3bb-5d30c4ee1874') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39499, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "原子や分子が電子を失ったり得たりして、電気を帯びた状態のものをイオンと呼びます。", "primary_collocate": null, "pronunciation": "いおん", "ipa": "ioɴ", "syllable_count": 3, "sentences": [{"text": "金属イオンとの錯体形成を通じて、色は初めてその真の輝きを帯び、生地へと不可逆的に定着するのだ。", "target_word": "イオン", "complexity_tier": "T6", "furigana": "", "sentence_source": "mined"}, {"text": "水に溶けると、塩はイオンになる。", "target_word": "イオン", "complexity_tier": "T2", "furigana": "", "sentence_source": "generated"}, {"text": "原子が電子を失うと、イオンができる。", "target_word": "イオン", "complexity_tier": "T3", "furigana": "", "sentence_source": "generated"}, {"text": "イオンは電気を帯びた粒子だ。", "target_word": "イオン", "complexity_tier": "T2", "furigana": "", "sentence_source": "generated"}, {"text": "この実験では、イオンの動きを調べる。", "target_word": "イオン", "complexity_tier": "T3", "furigana": "", "sentence_source": "generated"}, {"text": "イオンが多い水は、電気を通しやすい。", "target_word": "イオン", "complexity_tier": "T3", "furigana": "", "sentence_source": "generated"}, {"text": "電子を得た原子は、マイナスのイオンになる。", "target_word": "イオン", "complexity_tier": "T3", "furigana": "", "sentence_source": "generated"}, {"text": "体の中では、イオンが神経の信号を運ぶ。", "target_word": "イオン", "complexity_tier": "T3", "furigana": "", "sentence_source": "generated"}, {"text": "先生はイオンの性質を黒板に書いた。", "target_word": "イオン", "complexity_tier": "T3", "furigana": "", "sentence_source": "generated"}, {"text": "電池の中でも、イオンが移動している。", "target_word": "イオン", "complexity_tier": "T3", "furigana": "", "sentence_source": "generated"}], "morphological_forms": [], "register": "plain", "sense_fingerprint": "名詞 | 電気を帯びた原子や分子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T2: contains vocabulary far above tier T2: 錯体 (Zipf 2.39)']::text[], '706f6503-4810-49ec-aa3e-5da3ec8990bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39499, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "イオン", "is_correct": true, "explanation": "金属イオンとの錯体形成は、文脈に合う正しい語。"}, {"text": "価格", "is_correct": false, "explanation": "形は合うが、金属価格と錯体形成は結びつかず意味が合わない。"}, {"text": "光沢", "is_correct": false, "explanation": "形は合うが、光沢と錯体を作ることはないので意味が合わない。"}, {"text": "重量", "is_correct": false, "explanation": "形は合うが、重量と錯体を形成するとは言えず意味が合わない。"}], "explanations": {"イオン": "金属イオンとの錯体形成は、文脈に合う正しい語。", "価格": "形は合うが、金属価格と錯体形成は結びつかず意味が合わない。", "光沢": "形は合うが、光沢と錯体を作ることはないので意味が合わない。", "重量": "形は合うが、重量と錯体を形成するとは言えず意味が合わない。"}, "sentence_index": 0, "correct_answer": "イオン"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "イオンは電気を帯びていない、中性の粒子だ。", "explanation": "イオンは電気を帯びた粒子なので、「電気を帯びていない」という使い方は意味が逆で誤り。"}, {"text": "昨日の夕食に、イオンを箸で食べた。", "explanation": "イオンは食べ物ではなく粒子なので、「食べる」の対象にするのは誤り。"}, {"text": "イオンは黒板に字を書くための白い道具だ。", "explanation": "イオンを筆記用具(チョーク)の意味で使っており、語の意味が違う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63e7f52c-280f-4c6b-b3bb-5d30c4ee1874') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39499, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "イオン", "is_correct": true, "explanation": "電子を得た原子はマイナスのイオンになる。"}, {"text": "道具", "is_correct": false, "explanation": "形は合うが、原子が「マイナスの道具」になるのは意味が合わない。"}, {"text": "言葉", "is_correct": false, "explanation": "形は合うが、原子が言葉になるのは意味が合わない。"}, {"text": "建物", "is_correct": false, "explanation": "形は合うが、原子が建物になるのは意味が合わない。"}], "explanations": {"イオン": "電子を得た原子はマイナスのイオンになる。", "道具": "形は合うが、原子が「マイナスの道具」になるのは意味が合わない。", "言葉": "形は合うが、原子が言葉になるのは意味が合わない。", "建物": "形は合うが、原子が建物になるのは意味が合わない。"}, "sentence_index": 6, "correct_answer": "イオン"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "イオンは、教室の窓から入る光のことだ。", "explanation": "イオンを「光」の意味で使っており、電気を帯びた粒子という意味とずれている。"}, {"text": "電池の中で、イオンが笑っている。", "explanation": "イオンは粒子なので「笑う」の主語にならず、使い方が誤り。"}, {"text": "イオンを帽子のようにかぶって、学校へ行った。", "explanation": "イオンは身につける物ではないので、「かぶる」の対象にするのは誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63e7f52c-280f-4c6b-b3bb-5d30c4ee1874') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39499, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "原子が電子を失うと、イオンが歩く。", "corrected_sentence": "原子が電子を失うと、イオンができる。", "error_description": "イオンは歩くものではない。電子を失った結果として「できる」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63e7f52c-280f-4c6b-b3bb-5d30c4ee1874') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39499, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "体の中では、イオンが神経の信号を食べる。", "corrected_sentence": "体の中では、イオンが神経の信号を運ぶ。", "error_description": "イオンは信号を「食べる」のではなく「運ぶ」。動詞の選択が誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63e7f52c-280f-4c6b-b3bb-5d30c4ee1874') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39500, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「固体の氷」と名詞を修飾し、固体の状態の氷という意味になる。正解。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示すが、「固体を氷になる」は動詞「なる」と噛み合わず不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、「固体へ氷になる」は文として成立しない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示すが、「固体で氷になる」は意味が通らない。"}], "correct_answer": "の", "explanations": {"の": "「固体の氷」と名詞を修飾し、固体の状態の氷という意味になる。正解。", "を": "「を」は目的語を示すが、「固体を氷になる」は動詞「なる」と噛み合わず不自然。", "へ": "「へ」は方向を示すので、「固体へ氷になる」は文として成立しない。", "で": "「で」は手段や場所を示すが、「固体で氷になる」は意味が通らない。"}, "error_tags": {"を": "目的語", "へ": "方向", "で": "手段・場所"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca5920d4-ba89-425c-8b4e-47cfa4b9d998') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39500, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca5920d4-ba89-425c-8b4e-47cfa4b9d998') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39500, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "かたちがかたくて、じぶんでうごかないもの。", "primary_collocate": null, "pronunciation": "こたい", "ipa": "kotai", "syllable_count": 3, "sentences": [{"text": "石や氷のように、かたくて形が変わらないものを固体という。", "target_word": "固体", "complexity_tier": "T3", "furigana": "石[いし]や氷[こおり]のように、かたくて形[かたち]が変[か]わらないものを固体[こたい]という。", "sentence_source": "generated"}, {"text": "水は冷やすと固体の氷になる。", "target_word": "固体", "complexity_tier": "T3", "furigana": "水[みず]は冷[ひ]やすと固体[こたい]の氷[こおり]になる。", "sentence_source": "generated"}, {"text": "机の上の消しゴムは固体で、手で持つと形が変わらない。", "target_word": "固体", "complexity_tier": "T3", "furigana": "机[つくえ]の上[うえ]の消[け]しゴムは固体[こたい]で、手[て]で持[も]つと形[かたち]が変[か]わらない。", "sentence_source": "generated"}, {"text": "大きな石は固体で、風が吹いても自分で転がることはない。", "target_word": "固体", "complexity_tier": "T3", "furigana": "大(おお)きな石(いし)は固体(こたい)で、風(かぜ)が吹(ふ)いても自分(じぶん)で転(ころ)がることはない。", "sentence_source": "generated"}, {"text": "箱の中の積み木は固体で、ふっても中で形が変わらない。", "target_word": "固体", "complexity_tier": "T3", "furigana": "箱[はこ]の中[なか]の積[つ]み木[き]は固体[こたい]で、ふっても中[なか]で形[かたち]が変[か]わらない。", "sentence_source": "generated"}, {"text": "氷は固体だが、あたためると水になる。", "target_word": "固体", "complexity_tier": "T3", "furigana": "氷[こおり]は固体[こたい]だが、あたためると水[みず]になる。", "sentence_source": "generated"}, {"text": "理科の時間に、固体のものを三つ集めた。", "target_word": "固体", "complexity_tier": "T3", "furigana": "理科[りか]の時間[じかん]に、固体[こたい]のものを三[みっ]つ集[あつ]めた。", "sentence_source": "generated"}, {"text": "木や鉄は固体なので、手でつかんでも形が崩れない。", "target_word": "固体", "complexity_tier": "T3", "furigana": "木[き]や鉄[てつ]は固体[こたい]なので、手[て]でつかんでも形[かたち]が崩[くず]れない。", "sentence_source": "generated"}, {"text": "バターは冷蔵庫の中では固体だが、熱いフライパンの上では溶ける。", "target_word": "固体", "complexity_tier": "T3", "furigana": "バターは冷蔵庫[れいぞうこ]の中[なか]では固体[こたい]だが、熱[あつ]いフライパンの上[うえ]では溶[と]ける。", "sentence_source": "generated"}, {"text": "ガラスの瓶は固体だから、手でにぎっても形が変わらない。", "target_word": "固体", "complexity_tier": "T3", "furigana": "ガラス[がらす]の瓶[びん]は固体[こたい]だから、手[て]でにぎっても形[かたち]が変[か]わらない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "固体", "label": "基本形"}], "register": "中立", "sense_fingerprint": "石や氷など、かたくて形が変わらず自分では動かない身近なもの（子ども向けの説明）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '989c883e-1f67-4ecd-80a7-ae7c0f0d1e3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39500, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "固体", "is_correct": true, "explanation": "かたくて形が変わらないものを指す語で、「〜ものを___という」に入る。正解。"}, {"text": "液体", "is_correct": false, "explanation": "液体は流れて容器に合わせて形が変わるもので、「かたくて形が変わらないもの」を液体とは呼ばず、文が成り立たない。"}, {"text": "気体", "is_correct": false, "explanation": "気体は形を決めずに広がるもので、「かたくて形が変わらないもの」を指す語ではないので合わない。"}, {"text": "気泡", "is_correct": false, "explanation": "気泡は液体の中の小さな空気の粒で、かたくて形が変わらないものという定義には合わない。"}], "explanations": {"固体": "かたくて形が変わらないものを指す語で、「〜ものを___という」に入る。正解。", "液体": "液体は流れて容器に合わせて形が変わるもので、「かたくて形が変わらないもの」を液体とは呼ばず、文が成り立たない。", "気体": "気体は形を決めずに広がるもので、「かたくて形が変わらないもの」を指す語ではないので合わない。", "気泡": "気泡は液体の中の小さな空気の粒で、かたくて形が変わらないものという定義には合わない。"}, "sentence_index": 0, "correct_answer": "固体"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "固体は注ぐと、容器の形に合わせて広がり、こぼれても残らない。", "explanation": "ここは〈液体〉の意味。液体は注ぐと容器に合わせて広がるもので、かたくて形が変わらない固体の定義とは合わない。"}, {"text": "風船に入れた固体は、押すと形を変えて広がる。", "explanation": "ここは〈気体〉の意味。気体は袋や風船の中で広がるもので、固体は形が変わらないので合わない。"}, {"text": "固体は煙のように、手で払うと形を失って散る。", "explanation": "ここは〈煙〉の性質。煙は形がなく風に散るもので、形が決まっていてかたい固体の性質とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca5920d4-ba89-425c-8b4e-47cfa4b9d998') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39500, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "固体", "is_correct": true, "explanation": "かたくて形が変わらない物を指す語で、「理科の時間に___のものを三つ集めた」に入る。正解。"}, {"text": "音楽", "is_correct": false, "explanation": "「音楽のもの」では文が意味をなさず、理科で集める物の説明にならない。"}, {"text": "甘さ", "is_correct": false, "explanation": "甘さは物の性質で、「甘さのものを集める」は意味が通らない。"}, {"text": "寂しさ", "is_correct": false, "explanation": "感情を表す語で、理科の時間に集める物の説明にはならない。"}], "explanations": {"固体": "かたくて形が変わらない物を指す語で、「理科の時間に___のものを三つ集めた」に入る。正解。", "音楽": "「音楽のもの」では文が意味をなさず、理科で集める物の説明にならない。", "甘さ": "甘さは物の性質で、「甘さのものを集める」は意味が通らない。", "寂しさ": "感情を表す語で、理科の時間に集める物の説明にはならない。"}, "sentence_index": 6, "correct_answer": "固体"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "固体は形が決まっていないので、どんな容器にも入る。", "explanation": "ここは〈水〉の性質。水は形が決まらず容器に合わせて変わるもので、固体はかたくて形が変わらないので合わない。"}, {"text": "固体は目に見えず、袋に入れると袋の形になる。", "explanation": "ここは〈空気〉の性質。空気は目に見えず袋の形に合わせて広がるもので、固体は形が変わらないので合わない。"}, {"text": "固体は雨のように降り注ぎ、地面を流れていく。", "explanation": "ここは〈雨（液体）〉の性質。雨は地面を流れるもので、流れず形が決まっている固体の定義とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca5920d4-ba89-425c-8b4e-47cfa4b9d998') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39500, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "鉄の棒は室温でも固体をままだ。", "corrected_sentence": "鉄の棒は室温でも固体のままだ。", "error_description": "「固体」に続く「のまま」の「の」が「を」になっている。「を」は目的語を示すので、ここでは誤り。正しくは「固体のまま」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca5920d4-ba89-425c-8b4e-47cfa4b9d998') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39500, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この石の塊は固体くて、ふっても形が変わらない。", "corrected_sentence": "この石の塊は固体で、ふっても形が変わらない。", "error_description": "「固体」は名詞なので、形容詞の活用「くて」は付かない。正しくは「固体で」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca5920d4-ba89-425c-8b4e-47cfa4b9d998') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39501, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「は」は主題を示し、「固体は液体や気体と違って」と対比の主題になる。正解。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示すが、「固体を液体や気体と違って」は意味が通らない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は帰着や位置を示すが、「固体に液体や気体と違って」は不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すが、「固体へ液体や気体と違って」は成り立たない。"}], "correct_answer": "は", "explanations": {"は": "「は」は主題を示し、「固体は液体や気体と違って」と対比の主題になる。正解。", "を": "「を」は目的語を示すが、「固体を液体や気体と違って」は意味が通らない。", "に": "「に」は帰着や位置を示すが、「固体に液体や気体と違って」は不自然。", "へ": "「へ」は方向を示すが、「固体へ液体や気体と違って」は成り立たない。"}, "error_tags": {"を": "目的語", "に": "帰着・位置", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca5920d4-ba89-425c-8b4e-47cfa4b9d998') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39501, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca5920d4-ba89-425c-8b4e-47cfa4b9d998') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39501, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "液体や気体のように流れず、形が決まっている物質。", "primary_collocate": null, "pronunciation": "こたい", "ipa": "kotai", "syllable_count": 3, "sentences": [{"text": "氷は水が凍ってできた固体だ。", "target_word": "固体", "complexity_tier": "T3", "furigana": "氷[こおり]は水[みず]が凍[こお]ってできた固体[こたい]だ。", "sentence_source": "generated"}, {"text": "固体は液体や気体と違って、容器を変えても形が変わらない。", "target_word": "固体", "complexity_tier": "T3", "furigana": "固体[こたい]は液体[えきたい]や気体[きたい]と違[ちが]って、容器[ようき]を変[か]えても形[かたち]が変[か]わらない。", "sentence_source": "generated"}, {"text": "温度を上げると、固体の鉄も溶けて液体になる。", "target_word": "固体", "complexity_tier": "T3", "furigana": "温度[おんど]を上[あ]げると、固体[こたい]の鉄[てつ]も溶[と]けて液体[えきたい]になる。", "sentence_source": "generated"}, {"text": "実験では、白い固体を水に溶かして溶液を作った。", "target_word": "固体", "complexity_tier": "T3", "furigana": "実験[じっけん]では、白[しろ]い固体[こたい]を水[みず]に溶[と]かして溶液[ようえき]を作[つく]った。", "sentence_source": "generated"}, {"text": "ドライアイスは二酸化炭素が固体になったものだ。", "target_word": "固体", "complexity_tier": "T3", "furigana": "ドライアイスは二酸化炭素[にさんかたんそ]が固体[こたい]になったものだ。", "sentence_source": "generated"}, {"text": "固体の中の粒子は、決まった位置で細かく振動している。", "target_word": "固体", "complexity_tier": "T3", "furigana": "固体[こたい]の中[なか]の粒子[りゅうし]は、決[き]まった位置[いち]で細[こま]かく振動[しんどう]している。", "sentence_source": "generated"}, {"text": "食塩のような固体は、水に溶けると見えなくなる。", "target_word": "固体", "complexity_tier": "T3", "furigana": "食塩[しょくえん]のような固体[こたい]は、水[みず]に溶[と]けると見[み]えなくなる。", "sentence_source": "generated"}, {"text": "固体、液体、気体をまとめて物質の三態と呼ぶ。", "target_word": "固体", "complexity_tier": "T3", "furigana": "固体[こたい]、液体[えきたい]、気体[きたい]をまとめて物質[ぶっしつ]の三態[さんたい]と呼[よ]ぶ。", "sentence_source": "generated"}, {"text": "この金属は常温で固体だが、高温では液体に変わる。", "target_word": "固体", "complexity_tier": "T3", "furigana": "この金属[きんぞく]は常温[じょうおん]で固体[こたい]だが、高温[こうおん]では液体[えきたい]に変[か]わる。", "sentence_source": "generated"}, {"text": "固体が直接気体になる変化を昇華という。", "target_word": "固体", "complexity_tier": "T3", "furigana": "固体[こたい]が直接[ちょくせつ]気体[きたい]になる変化[へんか]を昇華[しょうか]という。", "sentence_source": "generated"}], "morphological_forms": [{"form": "固体", "label": "基本形"}], "register": "中立", "sense_fingerprint": "物質の三態の一つ。液体・気体と対比される、流れず一定の形を保つ状態の物質（理科用語）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '989c883e-1f67-4ecd-80a7-ae7c0f0d1e3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39501, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "固体", "is_correct": true, "explanation": "流れず形が決まっている物質を指す語で、「氷は水が凍ってできた___だ」に入る。正解。"}, {"text": "液体", "is_correct": false, "explanation": "「凍ってできた液体」は矛盾し、凍った氷の説明として意味が通らない。"}, {"text": "気体", "is_correct": false, "explanation": "気体は形を決めず広がる物質で、凍ってできたという説明とは合わない。"}, {"text": "霧", "is_correct": false, "explanation": "霧は空気中に浮かぶ細かい水の粒で、凍って固まった氷の説明にはならない。"}], "explanations": {"固体": "流れず形が決まっている物質を指す語で、「氷は水が凍ってできた___だ」に入る。正解。", "液体": "「凍ってできた液体」は矛盾し、凍った氷の説明として意味が通らない。", "気体": "気体は形を決めず広がる物質で、凍ってできたという説明とは合わない。", "霧": "霧は空気中に浮かぶ細かい水の粒で、凍って固まった氷の説明にはならない。"}, "sentence_index": 0, "correct_answer": "固体"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この固体は容器を変えると、その形に広がる。", "explanation": "ここは〈液体〉の意味。液体は容器に合わせて広がる物質で、固体は流れず形が決まっているので合わない。"}, {"text": "この固体は容器の形に合わせて流れる。", "explanation": "ここは〈水〉の意味。水は流れて容器の形になるが、固体は流れず形が決まっているので合わない。"}, {"text": "この固体は表面がゆっくり広がり、垂れていく。", "explanation": "ここは〈油〉の性質。油は表面が広がって垂れるもので、流れずに形が決まっている固体の定義とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca5920d4-ba89-425c-8b4e-47cfa4b9d998') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39501, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "固体", "is_correct": true, "explanation": "物質の三態の一つで、昇華や溶解の話題に出る語。「食塩のような___は」に入る。正解。"}, {"text": "感情", "is_correct": false, "explanation": "「食塩のような感情」は成り立たず、水に溶けて見えなくなる話にならない。"}, {"text": "光沢", "is_correct": false, "explanation": "「食塩のような光沢」は意味が通らず、水に溶ける物の説明にならない。"}, {"text": "音楽", "is_correct": false, "explanation": "「食塩のような音楽」は成り立たず、水に溶けるかどうかの話にならない。"}], "explanations": {"固体": "物質の三態の一つで、昇華や溶解の話題に出る語。「食塩のような___は」に入る。正解。", "感情": "「食塩のような感情」は成り立たず、水に溶けて見えなくなる話にならない。", "光沢": "「食塩のような光沢」は意味が通らず、水に溶ける物の説明にならない。", "音楽": "「食塩のような音楽」は成り立たず、水に溶けるかどうかの話にならない。"}, "sentence_index": 6, "correct_answer": "固体"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "固体は容器いっぱいに広がり、形を決めない。", "explanation": "ここは〈気体〉の意味。気体は容器いっぱいに広がり形を決めないもので、固体は流れず形が決まっているので合わない。"}, {"text": "液体が固体に変わることを固体という。", "explanation": "ここは〈凝固〉の意味。液体が固まる変化の名称は凝固で、固体は物の状態を指す語なので合わない。"}, {"text": "お湯を沸かすと、固体が立ちのぼる。", "explanation": "ここは〈蒸気〉の意味。お湯を沸かすと立ちのぼるのは蒸気で、固体は立ちのぼらないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca5920d4-ba89-425c-8b4e-47cfa4b9d998') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39501, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ろうは常温では固体を、ろうそくの形を保っている。", "corrected_sentence": "ろうは常温では固体で、ろうそくの形を保っている。", "error_description": "「固体」の後は断定の「で」が続く。「を」は目的語を示すので、ここでは誤り。正しくは「固体で」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca5920d4-ba89-425c-8b4e-47cfa4b9d998') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39501, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この白い粉末は固体くて、水に入れても溶けない。", "corrected_sentence": "この白い粉末は固体で、水に入れても溶けない。", "error_description": "「固体」は名詞なので、形容詞の活用「くて」は付かない。正しくは「固体で」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca5920d4-ba89-425c-8b4e-47cfa4b9d998') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39502, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「電池を入れる」の目的語を示す。入れるのは電池なので「を」が合う。"}, {"text": "で", "is_correct": false, "explanation": "「電池で入れたら」は手段の意味になり、入れるものが電池だという文の意味に合わない。"}, {"text": "と", "is_correct": false, "explanation": "「電池と入れたら」は並列になり、入れる動作の対象を示せない。"}, {"text": "の", "is_correct": false, "explanation": "「電池の入れたら」は名詞修飾になり、入れる動作の目的語にならない。"}], "correct_answer": "を", "explanations": {"を": "「電池を入れる」の目的語を示す。入れるのは電池なので「を」が合う。", "で": "「電池で入れたら」は手段の意味になり、入れるものが電池だという文の意味に合わない。", "と": "「電池と入れたら」は並列になり、入れる動作の対象を示せない。", "の": "「電池の入れたら」は名詞修飾になり、入れる動作の目的語にならない。"}, "error_tags": {"で": "手段", "と": "並列", "の": "連体修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a0dc298-6400-44f3-a314-0d2bcbaf39a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39502, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「電池が足りない」の主語を示す。足りないのは電池なので「が」が合う。"}, {"text": "を", "is_correct": false, "explanation": "「足りない」は目的語をとらないので、「を」は合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「電池へ足りない」は方向の意味になり、不足の対象を示す形ではない。"}, {"text": "から", "is_correct": false, "explanation": "「電池から足りない」は起点の意味になり、不足を表す文の形に合わない。"}], "correct_answer": "が", "explanations": {"が": "「電池が足りない」の主語を示す。足りないのは電池なので「が」が合う。", "を": "「足りない」は目的語をとらないので、「を」は合わない。", "へ": "「電池へ足りない」は方向の意味になり、不足の対象を示す形ではない。", "から": "「電池から足りない」は起点の意味になり、不足を表す文の形に合わない。"}, "error_tags": {"を": "目的語", "へ": "方向", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a0dc298-6400-44f3-a314-0d2bcbaf39a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39502, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "電気をためたり、出したりするもの。おもちゃや小さな機械でつかう。", "primary_collocate": null, "pronunciation": "でんち", "ipa": "dentɕi", "syllable_count": 3, "sentences": [{"text": "おもちゃの電池が切れて、車が動かなくなった。", "target_word": "電池", "complexity_tier": "T3", "furigana": "おもちゃの電池[でんち]が切[き]れて、車[くるま]が動[うご]かなくなった。", "sentence_source": "generated"}, {"text": "新しい電池を入れたら、懐中電灯がまた光った。", "target_word": "電池", "complexity_tier": "T3", "furigana": "新[あたら]しい電池[でんち]を入[い]れたら、懐中電灯[かいちゅうでんとう]がまた光[ひか]った。", "sentence_source": "generated"}, {"text": "リモコンの電池を買いに、コンビニへ行った。", "target_word": "電池", "complexity_tier": "T3", "furigana": "リモコンの電池[でんち]を買[か]いに、コンビニへ行[い]った。", "sentence_source": "generated"}, {"text": "弟は電池の向きをまちがえて、ロボットを動かせなかった。", "target_word": "電池", "complexity_tier": "T3", "furigana": "弟[おとうと]は電池[でんち]の向[む]きをまちがえて、ロボットを動[うご]かせなかった。", "sentence_source": "generated"}, {"text": "時計が止まったので、電池を取りかえた。", "target_word": "電池", "complexity_tier": "T3", "furigana": "時計[とけい]が止[と]まったので、電池[でんち]を取[と]りかえた。", "sentence_source": "generated"}, {"text": "使い終わった電池は、店の箱に入れて捨てる。", "target_word": "電池", "complexity_tier": "T3", "furigana": "使[つか]い終[お]わった電池[でんち]は、店[みせ]の箱[はこ]に入[い]れて捨[す]てる。", "sentence_source": "generated"}, {"text": "このラジオは電池を入れれば、コンセントがない場所でも聞ける。", "target_word": "電池", "complexity_tier": "T3", "furigana": "このラジオは電池[でんち]を入[い]れれば、コンセントがない場所[ばしょ]でも聞[き]ける。", "sentence_source": "generated"}, {"text": "電池が足りないので、二本買ってきた。", "target_word": "電池", "complexity_tier": "T3", "furigana": "電池[でんち]が足[た]りないので、二本[にほん]買[か]ってきた。", "sentence_source": "generated"}, {"text": "電池を入れる場所のふたが、なかなかあかない。", "target_word": "電池", "complexity_tier": "T3", "furigana": "電池[でんち]を入[い]れる場所[ばしょ]のふたが、なかなかあかない。", "sentence_source": "generated"}, {"text": "旅行に行く前に、カメラの電池を新しくしておいた。", "target_word": "電池", "complexity_tier": "T3", "furigana": "旅行[りょこう]に行[い]く前[まえ]に、カメラの電池[でんち]を新[あたら]しくしておいた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "電池", "label": "基本形"}, {"form": "電池の", "label": "連体形(の)"}, {"form": "電池を", "label": "目的格(を)"}], "register": "neutral", "sense_fingerprint": "電池: おもちゃや小さな機械を動かす身近な電気の元", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 4 above tier T2: contains vocabulary far above tier T2: 取りかえ (Zipf 1.48)']::text[], '25ca05e1-aa05-4ad7-add9-a71a38ebfa4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39502, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "電池", "is_correct": true, "explanation": "「おもちゃの電池が切れて」は動力源が切れる意味で、車が動かなくなる原因として合う。"}, {"text": "人形", "is_correct": false, "explanation": "人形は「切れる」ものではなく、車が動かなくなる原因として成り立たない。"}, {"text": "積み木", "is_correct": false, "explanation": "積み木は電気で動かないので、「切れて車が動かなくなった」の原因にならない。"}, {"text": "絵本", "is_correct": false, "explanation": "絵本は切れて動力が止まるものではなく、この文の主語として意味が通らない。"}], "explanations": {"電池": "「おもちゃの電池が切れて」は動力源が切れる意味で、車が動かなくなる原因として合う。", "人形": "人形は「切れる」ものではなく、車が動かなくなる原因として成り立たない。", "積み木": "積み木は電気で動かないので、「切れて車が動かなくなった」の原因にならない。", "絵本": "絵本は切れて動力が止まるものではなく、この文の主語として意味が通らない。"}, "sentence_index": 0, "correct_answer": "電池"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この地下室では電池が届かず、通話が途切れてしまう。", "explanation": "ここは〈電波〉の意味。届かないのは電波で、電池は届くものではないので合わない。"}, {"text": "台風の強い風で、電池が道路の上に垂れ下がった。", "explanation": "ここは〈電線〉の意味。道路の上に垂れ下がるのは電線で、電池はそのように垂れ下がるものではない。"}, {"text": "停電のあいだ、部屋の電池がすべて消えていた。", "explanation": "ここは〈電気〉の意味。停電で消えるのは電気で、電池は消えるものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a0dc298-6400-44f3-a314-0d2bcbaf39a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39502, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "電池", "is_correct": true, "explanation": "「ラジオは電池を入れれば」は電源として電池を入れる意味で、コンセントがなくても聞けるという文に合う。"}, {"text": "周波数", "is_correct": false, "explanation": "周波数は入れるものではなく、ラジオが聞ける条件にもならない。"}, {"text": "音量", "is_correct": false, "explanation": "音量は入れるものではないので、「入れれば」とつながらない。"}, {"text": "感度", "is_correct": false, "explanation": "感度は入れるものではなく、電源の代わりにもならない。"}], "explanations": {"電池": "「ラジオは電池を入れれば」は電源として電池を入れる意味で、コンセントがなくても聞けるという文に合う。", "周波数": "周波数は入れるものではなく、ラジオが聞ける条件にもならない。", "音量": "音量は入れるものではないので、「入れれば」とつながらない。", "感度": "感度は入れるものではなく、電源の代わりにもならない。"}, "sentence_index": 6, "correct_answer": "電池"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夜になったので、部屋の電池をつけた。", "explanation": "ここは〈電灯〉の意味。つけたり消したりするのは電灯で、電池は「つける」ものではない。"}, {"text": "旅行中に電池が鳴ったので、あわてて出た。", "explanation": "ここは〈電話〉の意味。鳴って出るのは電話で、電池は鳴らない。"}, {"text": "計算のあとで電池のボタンを押した。", "explanation": "ここは〈電卓〉の意味。ボタンを押すのは電卓で、電池にはボタンがない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a0dc298-6400-44f3-a314-0d2bcbaf39a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39502, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "リモコンの電池で入れかえたら、テレビが映った。", "corrected_sentence": "リモコンの電池を入れかえたら、テレビが映った。", "error_description": "「入れかえる」は目的語に「を」をとる。「電池で」は誤りで、正しくは「電池を入れかえる」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a0dc298-6400-44f3-a314-0d2bcbaf39a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39502, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "コントローラーの電池を切れたので、新しいのを買った。", "corrected_sentence": "コントローラーの電池が切れたので、新しいのを買った。", "error_description": "「切れる」は主語に「が」をとる。「電池を」は誤りで、正しくは「電池が切れた」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a0dc298-6400-44f3-a314-0d2bcbaf39a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39504, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「同期がずれる」で、同期が崩れる対象を主語として示す。正解。"}, {"text": "を", "is_correct": false, "explanation": "「同期をずれる」は、目的語を取れない自動詞「ずれる」に合わない。"}, {"text": "に", "is_correct": false, "explanation": "「同期にずれる」は結果や方向を示す「に」で、主語の位置に合わない。"}, {"text": "へ", "is_correct": false, "explanation": "方向の助詞で、「同期へずれる」は意味が通らない。"}], "correct_answer": "が", "explanations": {"が": "「同期がずれる」で、同期が崩れる対象を主語として示す。正解。", "を": "「同期をずれる」は、目的語を取れない自動詞「ずれる」に合わない。", "に": "「同期にずれる」は結果や方向を示す「に」で、主語の位置に合わない。", "へ": "方向の助詞で、「同期へずれる」は意味が通らない。"}, "error_tags": {"を": "目的語の誤り", "に": "方向・結果", "へ": "方向"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "非同期", "is_correct": true, "explanation": "「同じ時間に起こる」の対義語として辞書に載る語。「時間が揃っていない」状態を指す。正解。"}, {"text": "偏在", "is_correct": false, "explanation": "かたよって存在する意味で、タイミングの一致とは無関係。対義語ではない。"}, {"text": "固定", "is_correct": false, "explanation": "動かないよう定めること。タイミングの一致の対義語ではない。"}, {"text": "増減", "is_correct": false, "explanation": "増えたり減ったりすること。対義語ではない。"}], "correct_answer": "非同期", "explanations": {"非同期": "「同じ時間に起こる」の対義語として辞書に載る語。「時間が揃っていない」状態を指す。正解。", "偏在": "かたよって存在する意味で、タイミングの一致とは無関係。対義語ではない。", "固定": "動かないよう定めること。タイミングの一致の対義語ではない。", "増減": "増えたり減ったりすること。対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2de2e87d-d8b3-4d62-9ef4-2a893ed50514') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39504, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "「足音が同期すると」で、同期する相手や条件を示す「と」。正解。"}, {"text": "を", "is_correct": false, "explanation": "「同期するを」は動詞に続かず非文になる。"}, {"text": "へ", "is_correct": false, "explanation": "方向の助詞で、「同期へすると」は意味が通らない。"}, {"text": "で", "is_correct": false, "explanation": "「同期するで」は文として成り立たず非文になる。"}], "correct_answer": "と", "explanations": {"と": "「足音が同期すると」で、同期する相手や条件を示す「と」。正解。", "を": "「同期するを」は動詞に続かず非文になる。", "へ": "方向の助詞で、「同期へすると」は意味が通らない。", "で": "「同期するで」は文として成り立たず非文になる。"}, "error_tags": {"を": "位置の誤り", "へ": "方向", "で": "接続の誤り"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "非同期", "is_correct": true, "explanation": "「同じ時間に起こる」の対義語として辞書に載る語。正解。"}, {"text": "散在", "is_correct": false, "explanation": "あちこちに散らばっている意味で、対義語ではない。"}, {"text": "持続", "is_correct": false, "explanation": "続くことを表し、タイミングの対義語ではない。"}, {"text": "偏重", "is_correct": false, "explanation": "一方に重きを置く意味で、対義語ではない。"}], "correct_answer": "非同期", "explanations": {"非同期": "「同じ時間に起こる」の対義語として辞書に載る語。正解。", "散在": "あちこちに散らばっている意味で、対義語ではない。", "持続": "続くことを表し、タイミングの対義語ではない。", "偏重": "一方に重きを置く意味で、対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2de2e87d-d8b3-4d62-9ef4-2a893ed50514') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39504, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "いくつかのものが同じ時間に起こること。", "primary_collocate": null, "pronunciation": "どうき", "ipa": "doːki", "syllable_count": 3, "sentences": [{"text": "映像と音声の同期が取れていない。", "target_word": "同期", "complexity_tier": "T3", "furigana": "映像[えいぞう]と音声[おんせい]の同期[どうき]が取[と]れていない。", "sentence_source": "generated"}, {"text": "同期がずれると、ビデオ会議では話す声が遅れて聞こえる。", "target_word": "同期", "complexity_tier": "T3", "furigana": "同期[どうき]がずれると、ビデオ会議[かいぎ]では話[はな]す声[こえ]が遅[おく]れて聞[き]こえる。", "sentence_source": "generated"}, {"text": "全員のライトを同期させて、ステージを一斉に光らせた。", "target_word": "同期", "complexity_tier": "T3", "furigana": "全員[ぜんいん]のライトを同期[どうき]させて、ステージを一斉[いっせい]に光[ひか]らせた。", "sentence_source": "generated"}, {"text": "左右の手の動きを同期させる練習をした。", "target_word": "同期", "complexity_tier": "T3", "furigana": "左右[さゆう]の手[て]の動[うご]きを同期[どうき]させる練習[れんしゅう]をした。", "sentence_source": "generated"}, {"text": "二つの信号は同期していて、同時に赤から青に変わる。", "target_word": "同期", "complexity_tier": "T3", "furigana": "二[ふた]つの信号[しんごう]は同期[どうき]していて、同時[どうじ]に赤[あか]から青[あお]に変[か]わる。", "sentence_source": "generated"}, {"text": "三人の歌手が同期して歌い出し、会場が静かになった。", "target_word": "同期", "complexity_tier": "T3", "furigana": "三人[さんにん]の歌手[かしゅ]が同期[どうき]して歌い出[うただ]し、会場[かいじょう]が静[しず]かになった。", "sentence_source": "generated"}, {"text": "打ち上げ花火は、音楽と同期して夜空に広がった。", "target_word": "同期", "complexity_tier": "T3", "furigana": "打[う]ち上[あ]げ花火[はなび]は、音楽[おんがく]と同期[どうき]して夜空[よぞら]に広[ひろ]がった。", "sentence_source": "generated"}, {"text": "足音が同期すると、行進の列がきれいに揃って見える。", "target_word": "同期", "complexity_tier": "T3", "furigana": "足音[あしおと]が同期[どうき]すると、行進[こうしん]の列[れつ]がきれいに揃[そろ]って見[み]える。", "sentence_source": "generated"}, {"text": "シンクロの競技では、選手の動きが同期していることが大切だ。", "target_word": "同期", "complexity_tier": "T3", "furigana": "シンクロの競技[きょうぎ]では、選手[せんしゅ]の動[うご]きが同期[どうき]していることが大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "二つの時計が同期していなかったので、会議の開始時刻がずれてしまった。", "target_word": "同期", "complexity_tier": "T3", "furigana": "二[ふた]つの時計[とけい]が同期[どうき]していなかったので、会議[かいぎ]の開始[かいし]時刻[じこく]がずれてしまった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "同期", "label": "基本形"}, {"form": "同期する", "label": "サ変動詞形"}, {"form": "同期させる", "label": "使役形"}], "register": "neutral", "sense_fingerprint": "いくつかのことが同じ時間に起こる、タイミングが合うこと(同期、シンクロ)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba344cc6-eef7-4152-b08a-769bb2bfac14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39504, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "同期", "is_correct": true, "explanation": "「映像と音声の同期が取れている」で、二つの時間が揃う意味。正解。"}, {"text": "音量", "is_correct": false, "explanation": "「音量が取れていない」とは言わず、取れる・取れないの対象にならない。"}, {"text": "文法", "is_correct": false, "explanation": "「文法が取れていない」とは言わず、映像と音声の関係に合わず文脈が通らない。"}, {"text": "背景", "is_correct": false, "explanation": "「背景が取れていない」は映像と音声の関係に合わず、意味が通らない。"}], "explanations": {"同期": "「映像と音声の同期が取れている」で、二つの時間が揃う意味。正解。", "音量": "「音量が取れていない」とは言わず、取れる・取れないの対象にならない。", "文法": "「文法が取れていない」とは言わず、映像と音声の関係に合わず文脈が通らない。", "背景": "「背景が取れていない」は映像と音声の関係に合わず、意味が通らない。"}, "sentence_index": 0, "correct_answer": "同期"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼の話に同期して、深く感心した。", "explanation": "ここは〈同感〉の意味。話に共感することは時間の一致ではないので、〈同期〉は合わない。"}, {"text": "先輩に同期して、資料を直した。", "explanation": "ここは〈相談〉の意味。先輩に意見を求めることは時間が揃うことではないので、〈同期〉は合わない。"}, {"text": "二人の意見が同期した。", "explanation": "ここは〈一致〉の意味。意見が同じになることは時間が揃うことではないので、〈同期〉は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2de2e87d-d8b3-4d62-9ef4-2a893ed50514') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39504, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "同期", "is_correct": true, "explanation": "「音楽と同期して夜空に広がった」で、音楽と時間を揃える意味。正解。"}, {"text": "沈黙", "is_correct": false, "explanation": "「音楽と沈黙して」は意味が通らず、音楽に合わせる文脈に合わない。"}, {"text": "停滞", "is_correct": false, "explanation": "「音楽と停滞して」は意味が通らない。"}, {"text": "腐敗", "is_correct": false, "explanation": "「音楽と腐敗して」は意味が通らず、文脈に合わない。"}], "explanations": {"同期": "「音楽と同期して夜空に広がった」で、音楽と時間を揃える意味。正解。", "沈黙": "「音楽と沈黙して」は意味が通らず、音楽に合わせる文脈に合わない。", "停滞": "「音楽と停滞して」は意味が通らない。", "腐敗": "「音楽と腐敗して」は意味が通らず、文脈に合わない。"}, "sentence_index": 6, "correct_answer": "同期"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "会議の席に同期して、資料を配った。", "explanation": "ここは〈同席〉の意味。同じ場にいることは時間の一致ではないので、〈同期〉は合わない。"}, {"text": "委員会で同期して、規則を決めた。", "explanation": "ここは〈協議〉の意味。話し合って決めることは時間の一致ではないので、〈同期〉は合わない。"}, {"text": "提案に同期して、契約を結んだ。", "explanation": "ここは〈同意〉の意味。提案を認めることは時間が揃うことではないので、〈同期〉は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2de2e87d-d8b3-4d62-9ef4-2a893ed50514') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39504, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ライブの照明を同期せて、会場を明るくした。", "corrected_sentence": "ライブの照明を同期させて、会場を明るくした。", "error_description": "「同期せて」は誤りで、正しくは使役形「同期させて」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2de2e87d-d8b3-4d62-9ef4-2a893ed50514') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39504, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "三人の歌手が声が同期させて歌い出した。", "corrected_sentence": "三人の歌手が声を同期させて歌い出した。", "error_description": "「同期させる」は他動詞なので、対象の「声」は「を」で示す。「が」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2de2e87d-d8b3-4d62-9ef4-2a893ed50514') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39505, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「こぐ動きを同期させる」で、同期させる対象を示す目的格。正解。"}, {"text": "が", "is_correct": false, "explanation": "「こぐ動きが同期させて」では主語になり、他動詞「同期させる」の目的語が欠ける。"}, {"text": "へ", "is_correct": false, "explanation": "「こぐ動きへ同期させて」は方向の助詞で、同期させる対象の示し方として不自然。"}, {"text": "から", "is_correct": false, "explanation": "起点の助詞で、「こぐ動きから同期させて」とは言えない。"}], "correct_answer": "を", "explanations": {"を": "「こぐ動きを同期させる」で、同期させる対象を示す目的格。正解。", "が": "「こぐ動きが同期させて」では主語になり、他動詞「同期させる」の目的語が欠ける。", "へ": "「こぐ動きへ同期させて」は方向の助詞で、同期させる対象の示し方として不自然。", "から": "起点の助詞で、「こぐ動きから同期させて」とは言えない。"}, "error_tags": {"が": "主語化の誤り", "へ": "方向", "から": "起点"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "非同期", "is_correct": true, "explanation": "「同時に動く・存在する」の対義語として辞書に載る語。「同期していない」状態を指す。正解。"}, {"text": "偏在", "is_correct": false, "explanation": "かたよって存在する意味で、タイミングの一致とは無関係。対義語ではない。"}, {"text": "固定", "is_correct": false, "explanation": "動かないよう定めること。タイミングの一致の対義語ではない。"}, {"text": "増減", "is_correct": false, "explanation": "増えたり減ったりすること。タイミングの反対概念ではなく、対義語ではない。"}], "correct_answer": "非同期", "explanations": {"非同期": "「同時に動く・存在する」の対義語として辞書に載る語。「同期していない」状態を指す。正解。", "偏在": "かたよって存在する意味で、タイミングの一致とは無関係。対義語ではない。", "固定": "動かないよう定めること。タイミングの一致の対義語ではない。", "増減": "増えたり減ったりすること。タイミングの反対概念ではなく、対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2de2e87d-d8b3-4d62-9ef4-2a893ed50514') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39505, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「制御装置を使う」で、使う対象を示す目的格。正解。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞どうしを結ぶ助詞で、「同期して」の対象を示す位置には入らないので合わない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を示すので、同期させる対象を表す位置には合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「制御装置へ使う」は「使う」の対象を示せず非文になる。"}], "correct_answer": "を", "explanations": {"を": "「制御装置を使う」で、使う対象を示す目的格。正解。", "の": "「の」は名詞どうしを結ぶ助詞で、「同期して」の対象を示す位置には入らないので合わない。", "より": "「より」は比較を示すので、同期させる対象を表す位置には合わない。", "へ": "「制御装置へ使う」は「使う」の対象を示せず非文になる。"}, "error_tags": {"の": "連体修飾", "より": "比較", "へ": "方向"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "非同期", "is_correct": true, "explanation": "「同時に起こらない・揃わない」状態を表す対義語として辞書に載る語。正解。"}, {"text": "散在", "is_correct": false, "explanation": "あちこちに散らばっている意味で、タイミングの反対概念ではなく、対義語ではない。"}, {"text": "持続", "is_correct": false, "explanation": "途切れずに続く意味で、タイミングの一致の対義語ではない。"}, {"text": "偏重", "is_correct": false, "explanation": "一方に重きを置く意味で、対義語ではない。"}], "correct_answer": "非同期", "explanations": {"非同期": "「同時に起こらない・揃わない」状態を表す対義語として辞書に載る語。正解。", "散在": "あちこちに散らばっている意味で、タイミングの反対概念ではなく、対義語ではない。", "持続": "途切れずに続く意味で、タイミングの一致の対義語ではない。", "偏重": "一方に重きを置く意味で、対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2de2e87d-d8b3-4d62-9ef4-2a893ed50514') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39505, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "二つ以上のものが同じ時期に動いたり、存在したりすること。", "primary_collocate": null, "pronunciation": "どうき", "ipa": "doːki", "syllable_count": 3, "sentences": [{"text": "しかる後に、プログラミングという「神経系」を構築し、抽象的論理と物理的挙動を厳密に同期させるのだ。", "target_word": "同期", "complexity_tier": "T3", "furigana": "しかる後[のち]に、プログラミングという「神経系[しんけいけい]」を構築[こうちく]し、抽象的[ちゅうしょうてき]論理[ろんり]と物理的[ぶつりてき]挙動[きょどう]を厳密[げんみつ]に同期[どうき]させるのだ。", "sentence_source": "mined"}, {"text": "ボートの選手たちは、こぐ動きを同期させて速度を上げた。", "target_word": "同期", "complexity_tier": "T3", "furigana": "選手[せんしゅ]たちは、こぐ動[うご]きを同期[どうき]させて速度[そくど]を上[あ]げた。", "sentence_source": "generated"}, {"text": "二台のカメラの映像を同期して、一つの動画にまとめた。", "target_word": "同期", "complexity_tier": "T3", "furigana": "二台[にだい]のカメラの映像[えいぞう]を同期[どうき]して、一[ひと]つの動画[どうが]にまとめた。", "sentence_source": "generated"}, {"text": "音と映像が同期していないので、話している声と口の動きがずれている。", "target_word": "同期", "complexity_tier": "T3", "furigana": "音[おと]と映像[えいぞう]が同期[どうき]していないので、話[はな]している声[こえ]と口[くち]の動[うご]きがずれている。", "sentence_source": "generated"}, {"text": "ダンスでは、全員の動きが同期すると、とても美しく見える。", "target_word": "同期", "complexity_tier": "T3", "furigana": "ダンスでは、全員[ぜんいん]の動[うご]きが同期[どうき]すると、とても美[うつく]しく見[み]える。", "sentence_source": "generated"}, {"text": "全員の手拍子を同期させるため、指揮者が手を上げた。", "target_word": "同期", "complexity_tier": "T3", "furigana": "全員[ぜんいん]の手拍子[てびょうし]を同期[どうき]させるため、指揮者[しきしゃ]が手[て]を上[あ]げた。", "sentence_source": "generated"}, {"text": "時計を同期させておかないと、記録の時刻が合わなくなる。", "target_word": "同期", "complexity_tier": "T3", "furigana": "時計[とけい]を同期[どうき]させておかないと、記録[きろく]の時刻[じこく]が合[あ]わなくなる。", "sentence_source": "generated"}, {"text": "二つのモーターを同期して回すために、制御装置を使う。", "target_word": "同期", "complexity_tier": "T4", "furigana": "二[ふた]つのモーターを同期[どうき]して回[まわ]すために、制御装置[せいぎょそうち]を使[つか]う。", "sentence_source": "generated"}, {"text": "信号が同期しないと、データは正しく読み取れない。", "target_word": "同期", "complexity_tier": "T3", "furigana": "信号[しんごう]が同期[どうき]しないと、データは正[ただ]しく読[よ]み取[と]れない。", "sentence_source": "generated"}, {"text": "作業員たちは、同期して合図を出し、同時に機械を止めた。", "target_word": "同期", "complexity_tier": "T3", "furigana": "作業員[さぎょういん]たちは、同期[どうき]して合図[あいず]を出[だ]し、同時[どうじ]に機械[きかい]を止[と]めた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "同期", "label": "基本形"}, {"form": "同期する", "label": "サ変動詞形"}, {"form": "同期させる", "label": "使役形"}], "register": "neutral", "sense_fingerprint": "複数のものが同じ時期・タイミングで動く、または一致すること(同期、シンクロ)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba344cc6-eef7-4152-b08a-769bb2bfac14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39505, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "同期", "is_correct": true, "explanation": "「論理と挙動を厳密に同期させる」で、二つを同じタイミングで一致させる意味。正解。"}, {"text": "解散", "is_correct": false, "explanation": "「解散させる」は集団を解く意味で、論理と挙動を対応させる文脈には合わない。"}, {"text": "放棄", "is_correct": false, "explanation": "「放棄させる」は手放す意味で、論理と挙動の一致を述べる文には合わない。"}, {"text": "増量", "is_correct": false, "explanation": "「増量させる」は量を増やす意味で、タイミングを合わせる文脈では意味が通らない。"}], "explanations": {"同期": "「論理と挙動を厳密に同期させる」で、二つを同じタイミングで一致させる意味。正解。", "解散": "「解散させる」は集団を解く意味で、論理と挙動を対応させる文脈には合わない。", "放棄": "「放棄させる」は手放す意味で、論理と挙動の一致を述べる文には合わない。", "増量": "「増量させる」は量を増やす意味で、タイミングを合わせる文脈では意味が通らない。"}, "sentence_index": 0, "correct_answer": "同期"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "全員が考えを同期して、大きな荷物を運び出した。", "explanation": "ここは〈協力〉の意味。考えを合わせることは時間が揃うことではないので、〈同期〉は合わない。"}, {"text": "彼は周りの意見に同期して、反対せずに従った。", "explanation": "ここは〈同調〉の意味。意見に従うことは時間の一致ではないので、〈同期〉では合わない。"}, {"text": "二人の答えが同期して、検算の結果が合った。", "explanation": "ここは〈一致〉の意味。答えが合うことは時間が揃うことではないので、〈同期〉は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2de2e87d-d8b3-4d62-9ef4-2a893ed50514') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39505, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "同期", "is_correct": true, "explanation": "「時計を同期させておく」で、時計の時刻を揃える意味。正解。"}, {"text": "購入", "is_correct": false, "explanation": "「時計を購入させておく」は意味が通らない。"}, {"text": "移転", "is_correct": false, "explanation": "「時計を移転させておく」は文脈に合わない。"}, {"text": "点滅", "is_correct": false, "explanation": "「時計を点滅させておく」では時刻を揃える意味にならない。"}], "explanations": {"同期": "「時計を同期させておく」で、時計の時刻を揃える意味。正解。", "購入": "「時計を購入させておく」は意味が通らない。", "移転": "「時計を移転させておく」は文脈に合わない。", "点滅": "「時計を点滅させておく」では時刻を揃える意味にならない。"}, "sentence_index": 6, "correct_answer": "同期"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "先生の案内に同期して、博物館へ向かった。", "explanation": "ここは〈同行〉の意味。人について行くことは時間が揃うことではないので、〈同期〉は合わない。"}, {"text": "上司に同期して、報告書を直した。", "explanation": "ここは〈相談〉の意味。上司に意見を求めることは時間の一致ではないので、〈同期〉は合わない。"}, {"text": "会議で同期して、予算を決めた。", "explanation": "ここは〈協議〉の意味。話し合って決めることは時間が揃うことではないので、〈同期〉は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2de2e87d-d8b3-4d62-9ef4-2a893ed50514') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39505, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "三人のダンサーが動きを同期せて、会場を沸かせた。", "corrected_sentence": "三人のダンサーが動きを同期させて、会場を沸かせた。", "error_description": "「同期せて」は誤りで、正しくは使役形「同期させて」。サ変動詞「同期する」の使役は「同期させる」になる。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2de2e87d-d8b3-4d62-9ef4-2a893ed50514') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39505, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "二台のロボットの動きが同期させるため、制御を変えた。", "corrected_sentence": "二台のロボットの動きを同期させるため、制御を変えた。", "error_description": "「同期させる」は他動詞なので、動きを表す語は「を」で示す。「が」は誤りで、正しくは「動きを同期させる」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2de2e87d-d8b3-4d62-9ef4-2a893ed50514') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39506, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「衝撃を吸収してくれる」で、取り込まれる対象を示す格助詞。"}, {"text": "へ", "is_correct": false, "explanation": "「衝撃へ吸収してくれる」は方向の意味になり、衝撃を取り込む対象にならない。"}, {"text": "より", "is_correct": false, "explanation": "「衝撃より吸収してくれる」は比較の意味になり、目的語にならない。"}, {"text": "と", "is_correct": false, "explanation": "「衝撃と吸収してくれる」は並列や共同の意味になり、目的語にならない。"}], "correct_answer": "を", "explanations": {"を": "「衝撃を吸収してくれる」で、取り込まれる対象を示す格助詞。", "へ": "「衝撃へ吸収してくれる」は方向の意味になり、衝撃を取り込む対象にならない。", "より": "「衝撃より吸収してくれる」は比較の意味になり、目的語にならない。", "と": "「衝撃と吸収してくれる」は並列や共同の意味になり、目的語にならない。"}, "error_tags": {"へ": "方向を示し、目的語にならない", "より": "比較を示し、目的語にならない", "と": "並列や共同を示し、目的語にならない"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d112de-9172-419b-b83c-ad1b8ddc501f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39506, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「隣の町に吸収され」で、吸収される先を示す格助詞。"}, {"text": "と", "is_correct": false, "explanation": "「隣の町と吸収され」は並列や共同の意味になり、吸収される先を示せない。"}, {"text": "の", "is_correct": false, "explanation": "「隣の町の吸収され」は名詞修飾になり、文が成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "「隣の町を吸収され」は目的語の「を」を残す誤りになる。"}], "correct_answer": "に", "explanations": {"に": "「隣の町に吸収され」で、吸収される先を示す格助詞。", "と": "「隣の町と吸収され」は並列や共同の意味になり、吸収される先を示せない。", "の": "「隣の町の吸収され」は名詞修飾になり、文が成り立たない。", "を": "「隣の町を吸収され」は目的語の「を」を残す誤りになる。"}, "error_tags": {"の": "名詞修飾になり、文が成り立たない", "を": "目的語を残す誤り", "と": "並列や共同を示し、吸収される先を示せない"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d112de-9172-419b-b83c-ad1b8ddc501f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39506, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "何かを、中に取り込むこと。", "primary_collocate": null, "pronunciation": "きゅうしゅう", "ipa": "kʲɯːɕɯː", "syllable_count": 4, "sentences": [{"text": "黒い服は光を吸収するので、夏に着ると暑く感じやすい。", "target_word": "吸収", "complexity_tier": "T3", "furigana": "黒[くろ]い服[ふく]は光[ひかり]を吸収[きゅうしゅう]するので、夏[なつ]に着[き]ると暑[あつ]く感[かん]じやすい。", "sentence_source": "generated"}, {"text": "このマットは衝撃を吸収してくれるため、転んでも怪我をしにくい。", "target_word": "吸収", "complexity_tier": "T3", "furigana": "このマットは衝撃[しょうげき]を吸収[きゅうしゅう]してくれるため、転[ころ]んでも怪我[けが]をしにくい。", "sentence_source": "generated"}, {"text": "厚いカーテンは音を吸収し、部屋の外に声が漏れにくくなる。", "target_word": "吸収", "complexity_tier": "T3", "furigana": "厚[あつ]いカーテンは音[おと]を吸収[きゅうしゅう]し、部屋[へや]の外[そと]に声[こえ]が漏[も]れにくくなる。", "sentence_source": "generated"}, {"text": "会社は経営が苦しくなった小さな店を吸収して、事業を大きくした。", "target_word": "吸収", "complexity_tier": "T3", "furigana": "会社[かいしゃ]は経営[けいえい]が苦[くる]しくなった小[ちい]さな店[みせ]を吸収[きゅうしゅう]して、事業[じぎょう]を大[おお]きくした。", "sentence_source": "generated"}, {"text": "車のサスペンションが道の揺れを吸収するので、乗り心地がよい。", "target_word": "吸収", "complexity_tier": "T3", "furigana": "車[くるま]のサスペンションが道[みち]の揺[ゆ]れを吸収[きゅうしゅう]するので、乗[の]り心地[ごこち]がよい。", "sentence_source": "generated"}, {"text": "砂は雨水をすぐに吸収するため、地面に水たまりができにくい。", "target_word": "吸収", "complexity_tier": "T3", "furigana": "砂[すな]は雨水[あまみず]をすぐに吸収[きゅうしゅう]するため、地面[じめん]に水[みず]たまりができにくい。", "sentence_source": "generated"}, {"text": "雪は周りの音を吸収して、冬の朝は町がとても静かに感じられる。", "target_word": "吸収", "complexity_tier": "T3", "furigana": "雪[ゆき]は周[まわ]りの音[おと]を吸収[きゅうしゅう]して、冬[ふゆ]の朝[あさ]は町[まち]がとても静[しず]かに感[かん]じられる。", "sentence_source": "generated"}, {"text": "小さな村は隣の町に吸収され、今では地図に名前が残っていない。", "target_word": "吸収", "complexity_tier": "T3", "furigana": "小[ちい]さな村[むら]は隣[となり]の町[まち]に吸収[きゅうしゅう]され、今[いま]では地図[ちず]に名前[なまえ]が残[のこ]っていない。", "sentence_source": "generated"}, {"text": "タオルは水をよく吸収する素材を選ぶと、使い心地がよくなる。", "target_word": "吸収", "complexity_tier": "T3", "furigana": "タオルは水[みず]をよく吸収[きゅうしゅう]する素材[そざい]を選[えら]ぶと、使[つか]い心地[ごこち]がよくなる。", "sentence_source": "generated"}, {"text": "このシートは臭いを吸収するので、冷蔵庫の中に置いておくとよい。", "target_word": "吸収", "complexity_tier": "T3", "furigana": "このシートは臭[にお]いを吸収[きゅうしゅう]するので、冷蔵庫[れいぞうこ]の中[なか]に置[お]いておくとよい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "吸収", "label": "基本形"}, {"form": "吸収する", "label": "終止形"}, {"form": "吸収した", "label": "過去形"}, {"form": "吸収される", "label": "受身形"}, {"form": "吸収して", "label": "て形"}], "register": "plain", "sense_fingerprint": "光・音・衝撃や他の組織などを中に取り込むこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a11d6d33-ed8f-4c09-aaf1-468a0c04d56b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39506, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "吸収", "is_correct": true, "explanation": "「光を吸収する」で、光を内部に取り込むことを表す。"}, {"text": "排気", "is_correct": false, "explanation": "排気は中の気体を外へ出すことで、「光を排気する」は意味が通らない。"}, {"text": "洗浄", "is_correct": false, "explanation": "洗浄は汚れを洗い流すことで、「光を洗浄する」は不自然。"}, {"text": "冷却", "is_correct": false, "explanation": "冷却は温度を下げることで、「光を冷却する」は合わない。"}], "explanations": {"吸収": "「光を吸収する」で、光を内部に取り込むことを表す。", "排気": "排気は中の気体を外へ出すことで、「光を排気する」は意味が通らない。", "洗浄": "洗浄は汚れを洗い流すことで、「光を洗浄する」は不自然。", "冷却": "冷却は温度を下げることで、「光を冷却する」は合わない。"}, "sentence_index": 0, "correct_answer": "吸収"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "網で魚を吸収して、船に積み込んだ。", "explanation": "ここは〈捕獲〉の意味。生き物を捕まえる動作は捕獲で、吸収では表せない。"}, {"text": "ボルトで板を吸収して、すき間をなくした。", "explanation": "ここは〈固定〉の意味。部材を留める動作は固定で、取り込む吸収とは違う。"}, {"text": "スクリーンに映像を吸収して、会場の全員に見せた。", "explanation": "ここは〈投影〉の意味。映像を映し出すことは投影で、吸収は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d112de-9172-419b-b83c-ad1b8ddc501f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39506, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "吸収", "is_correct": true, "explanation": "「音を吸収して」で、音を取り込んで減らすことを表す。"}, {"text": "乾燥", "is_correct": false, "explanation": "乾燥は水分を失うことで、「音を乾燥して」は意味が通らない。"}, {"text": "蒸発", "is_correct": false, "explanation": "蒸発は液体が気体になることで、音には使えない。"}, {"text": "凝固", "is_correct": false, "explanation": "凝固は固まることで、「音を凝固して」は不自然。"}], "explanations": {"吸収": "「音を吸収して」で、音を取り込んで減らすことを表す。", "乾燥": "乾燥は水分を失うことで、「音を乾燥して」は意味が通らない。", "蒸発": "蒸発は液体が気体になることで、音には使えない。", "凝固": "凝固は固まることで、「音を凝固して」は不自然。"}, "sentence_index": 6, "correct_answer": "吸収"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "郵便局は手紙を吸収して、家まで届けた。", "explanation": "ここは〈配達〉の意味。品物を外へ届けることは配達で、中に取り込む吸収とは向きが逆なので合わない。"}, {"text": "山で石炭を吸収して、掘り出した。", "explanation": "ここは〈採掘〉の意味。地中から掘り出すことは採掘で、吸収では表せない。"}, {"text": "ガスを吸収して、火をつけた。", "explanation": "ここは〈点火〉の意味。火をつける動作は点火で、取り込む吸収とは違う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d112de-9172-419b-b83c-ad1b8ddc501f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39506, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "このカーテンは光を吸収され、部屋が暗くなる。", "corrected_sentence": "このカーテンは光が吸収され、部屋が暗くなる。", "error_description": "受身文では、吸収される対象が主語になるので「が」で示す。「光を吸収され」は目的語の「を」を残しているため誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d112de-9172-419b-b83c-ad1b8ddc501f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39506, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この壁材は音を吸収ったので、部屋が静かになった。", "corrected_sentence": "この壁材は音を吸収したので、部屋が静かになった。", "error_description": "動詞「吸収する」の過去形は「吸収した」。「吸収った」は活用を誤った形で、正しくは「吸収した」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d112de-9172-419b-b83c-ad1b8ddc501f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39507, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「水を素早く吸収する」で、取り込まれる対象を示す格助詞。"}, {"text": "の", "is_correct": false, "explanation": "「水の素早く吸収する」は名詞修飾になり、動詞の目的語を示せない。"}, {"text": "と", "is_correct": false, "explanation": "「水と素早く吸収する」は共同の意味になり、目的語を示せない。"}, {"text": "に", "is_correct": false, "explanation": "「水に素早く吸収する」は吸収先を示すことになり、スポンジが水を取り込む意味にならない。"}], "correct_answer": "を", "explanations": {"を": "「水を素早く吸収する」で、取り込まれる対象を示す格助詞。", "の": "「水の素早く吸収する」は名詞修飾になり、動詞の目的語を示せない。", "と": "「水と素早く吸収する」は共同の意味になり、目的語を示せない。", "に": "「水に素早く吸収する」は吸収先を示すことになり、スポンジが水を取り込む意味にならない。"}, "error_tags": {"の": "名詞修飾になり、動詞の目的語を示せない", "と": "共同の意味になり、目的語を示せない", "に": "吸収先を示し、取り込む対象にならない"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d112de-9172-419b-b83c-ad1b8ddc501f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39507, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「二酸化炭素を吸収して」で、取り込まれる対象を示す格助詞。"}, {"text": "で", "is_correct": false, "explanation": "「二酸化炭素で吸収して」では手段や場所の意味になり、取り込む対象を示せない。"}, {"text": "より", "is_correct": false, "explanation": "「二酸化炭素より吸収して」は比較の意味になり、対象を示せない。"}, {"text": "へ", "is_correct": false, "explanation": "「二酸化炭素へ吸収して」は方向を示すことになり、取り込む対象にならない。"}], "correct_answer": "を", "explanations": {"を": "「二酸化炭素を吸収して」で、取り込まれる対象を示す格助詞。", "で": "「二酸化炭素で吸収して」では手段や場所の意味になり、取り込む対象を示せない。", "より": "「二酸化炭素より吸収して」は比較の意味になり、対象を示せない。", "へ": "「二酸化炭素へ吸収して」は方向を示すことになり、取り込む対象にならない。"}, "error_tags": {"で": "手段や場所を示し、取り込む対象にならない", "より": "比較を示し、目的語にならない", "へ": "方向を示し、取り込む対象にならない"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d112de-9172-419b-b83c-ad1b8ddc501f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39507, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "外部にあるものを、自分の内部に取り込むこと。特に、液体や気体、情報、影響などを取り込む場合に使う。", "primary_collocate": null, "pronunciation": "きゅうしゅう", "ipa": "kʲɯːɕɯː", "syllable_count": 4, "sentences": [{"text": "その後、長時間にわたる低温発酵を経ることで、グルテンの網目は緻密さを増し、消化吸収にも優れた変容を遂げる。", "target_word": "吸収", "complexity_tier": "T4", "furigana": "その後[そのあと]、長時間[ちょうじかん]にわたる低温[ていおん]発酵[はっこう]を経[へ]ることで、グルテンの網目[あみめ]は緻密[ちみつ]さを増[ま]し、消化[しょうか]吸収[きゅうしゅう]にも優[すぐ]れた変容[へんよう]を遂[と]げる。", "sentence_source": "mined"}, {"text": "乾いたスポンジは水を素早く吸収するので、こぼした牛乳もすぐにふき取れた。", "target_word": "吸収", "complexity_tier": "T3", "furigana": "乾[かわ]いたスポンジは水[みず]を素早[すばや]く吸収[きゅうしゅう]するので、こぼした牛乳[ぎゅうにゅう]もすぐにふき取[と]れた。", "sentence_source": "generated"}, {"text": "植物は根から水分を吸収し、葉で光を受けて養分を作る。", "target_word": "吸収", "complexity_tier": "T3", "furigana": "植物[しょくぶつ]は根[ね]から水分[すいぶん]を吸収[きゅうしゅう]し、葉[は]で光[ひかり]を受[う]けて養分[ようぶん]を作[つく]る。", "sentence_source": "generated"}, {"text": "留学中の彼は、現地の文化を吸収しようと毎日人々と話した。", "target_word": "吸収", "complexity_tier": "T3", "furigana": "留学中[りゅうがくちゅう]の彼[かれ]は、現地[げんち]の文化[ぶんか]を吸収[きゅうしゅう]しようと毎日[まいにち]人々[ひとびと]と話[はな]した。", "sentence_source": "generated"}, {"text": "この素材は汗を吸収して乾きやすいため、運動着によく使われる。", "target_word": "吸収", "complexity_tier": "T3", "furigana": "この素材[そざい]は汗[あせ]を吸収[きゅうしゅう]して乾[かわ]きやすいため、運動着[うんどうぎ]によく使[つか]われる。", "sentence_source": "generated"}, {"text": "子どもは新しい言葉を驚くほど速く吸収するので、教える側も楽しい。", "target_word": "吸収", "complexity_tier": "T3", "furigana": "子[こ]どもは新[あたら]しい言葉[ことば]を驚[おどろ]くほど速[はや]く吸収[きゅうしゅう]するので、教[おし]える側[がわ]も楽[たの]しい。", "sentence_source": "generated"}, {"text": "鉄分はビタミンCと一緒にとると吸収されやすくなる。", "target_word": "吸収", "complexity_tier": "T3", "furigana": "鉄分[てつぶん]はビタミンCと一緒[いっしょ]にとると吸収[きゅうしゅう]されやすくなる。", "sentence_source": "generated"}, {"text": "森の木々は二酸化炭素を吸収して、地球温暖化を和らげる働きをしている。", "target_word": "吸収", "complexity_tier": "T3", "furigana": "森[もり]の木々[きぎ]は二酸化炭素[にさんかたんそ]を吸収[きゅうしゅう]して、地球[ちきゅう]温暖化[おんだんか]を和[やわ]らげる働[はたら]きをしている。", "sentence_source": "generated"}, {"text": "若い選手は先輩の技術を吸収して、短い期間で大きく成長した。", "target_word": "吸収", "complexity_tier": "T3", "furigana": "若[わか]い選手[せんしゅ]は先輩[せんぱい]の技術[ぎじゅつ]を吸収[きゅうしゅう]して、短[みじか]い期間[きかん]で大[おお]きく成長[せいちょう]した。", "sentence_source": "generated"}, {"text": "薬は胃より腸で吸収されるため、効果が出るまでに少し時間がかかる。", "target_word": "吸収", "complexity_tier": "T3", "furigana": "薬[くすり]は胃[い]より腸[ちょう]で吸収[きゅうしゅう]されるため、効果[こうか]が出[で]るまでに少[すこ]し時間[じかん]がかかる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "吸収", "label": "基本形"}, {"form": "吸収する", "label": "終止形"}, {"form": "吸収した", "label": "過去形"}, {"form": "吸収される", "label": "受身形"}, {"form": "吸収して", "label": "て形"}], "register": "neutral", "sense_fingerprint": "液体・気体・情報・影響などを内部に取り込むこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T2: 7 words above tier T2 (max 3): 低温 (Zipf 3.63), 経る (Zipf 2.96), グルテン (Zipf 2.78), 網目 (Zipf 2.67), 緻密 (Zipf 3.25), 変容 (Zipf 3.25)','sentence 2 above tier T2: contains vocabulary far above tier T2: 根から (Zipf 2.23)']::text[], 'a11d6d33-ed8f-4c09-aaf1-468a0c04d56b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39507, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "吸収", "is_correct": true, "explanation": "「湿気を吸収して」で、湿気を内部に取り込むことを表す。"}, {"text": "点火", "is_correct": false, "explanation": "点火は火をつけることで、「湿気を点火して」は意味が通らない。"}, {"text": "発酵", "is_correct": false, "explanation": "発酵は微生物による変化で、「湿気を発酵して」は意味が通らない。"}, {"text": "粉砕", "is_correct": false, "explanation": "粉砕は細かく砕くことで、「湿気を粉砕して」は意味が通らない。"}], "explanations": {"吸収": "「湿気を吸収して」で、湿気を内部に取り込むことを表す。", "点火": "点火は火をつけることで、「湿気を点火して」は意味が通らない。", "発酵": "発酵は微生物による変化で、「湿気を発酵して」は意味が通らない。", "粉砕": "粉砕は細かく砕くことで、「湿気を粉砕して」は意味が通らない。"}, "sentence_index": 0, "correct_answer": "吸収"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "掃除機は床のごみを吸収して、部屋をきれいにした。", "explanation": "ここは〈吸引〉の意味。掃除機が空気ごとごみを引き込む動作は吸引で、吸収とは言わない。"}, {"text": "体の中の不要な水分は、腎臓で吸収されて外へ出る。", "explanation": "ここは〈排泄〉の意味。体の外へ出す働きは排泄で、取り込む意味の吸収とは逆になる。"}, {"text": "毎朝野菜を吸収して、元気に過ごしている。", "explanation": "ここは〈摂取〉（食べ物を口から取る）の意味。食べることは摂取で、消化の後に体内へ取り込まれる吸収とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d112de-9172-419b-b83c-ad1b8ddc501f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39507, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "吸収", "is_correct": true, "explanation": "「吸収される」で、外のものが取り込まれることを表す。"}, {"text": "蒸発", "is_correct": false, "explanation": "蒸発は液体が気体になることで、「鉄分は蒸発されやすくなる」は合わない。"}, {"text": "発酵", "is_correct": false, "explanation": "発酵は微生物による変化で、鉄分の性質として「発酵されやすくなる」は不自然。"}, {"text": "凝固", "is_correct": false, "explanation": "凝固は固まることで、鉄分が「凝固されやすくなる」という話にはならない。"}], "explanations": {"吸収": "「吸収される」で、外のものが取り込まれることを表す。", "蒸発": "蒸発は液体が気体になることで、「鉄分は蒸発されやすくなる」は合わない。", "発酵": "発酵は微生物による変化で、鉄分の性質として「発酵されやすくなる」は不自然。", "凝固": "凝固は固まることで、鉄分が「凝固されやすくなる」という話にはならない。"}, "sentence_index": 6, "correct_answer": "吸収"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "泡立て器で卵を吸収して、ふんわりさせた。", "explanation": "ここは〈攪拌〉（かき混ぜる）の意味。材料をかき混ぜる動作は攪拌で、中に取り込む吸収とは違う。"}, {"text": "山で石炭を吸収して、掘り出した。", "explanation": "ここは〈採掘〉の意味。地中から掘り出すことは採掘で、吸収では表せない。"}, {"text": "ガスを吸収して、火をつけた。", "explanation": "ここは〈点火〉の意味。火をつける動作は点火で、取り込む吸収とは違う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d112de-9172-419b-b83c-ad1b8ddc501f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39507, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この布は汗を吸収として、すぐに乾く。", "corrected_sentence": "この布は汗を吸収して、すぐに乾く。", "error_description": "「吸収」は動詞「吸収する」の連用形「吸収して」が続くべきところに、「として」が付いている。「吸収として」は『吸収という立場で』の意味になり、文が通らない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d112de-9172-419b-b83c-ad1b8ddc501f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39507, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この乳酸菌は腸で吸収さやすく、整腸作用が出やすい。", "corrected_sentence": "この乳酸菌は腸で吸収されやすく、整腸作用が出やすい。", "error_description": "「吸収される」の受身形の「れ」が抜けている。「吸収さやすく」は誤りで、正しくは「吸収されやすく」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d112de-9172-419b-b83c-ad1b8ddc501f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39508, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「想像の域」で、域を修飾する「の」。文の意味が通る。"}, {"text": "が", "is_correct": false, "explanation": "「想像が域を出ない」は主語と述語にならず、修飾関係が成立しない。"}, {"text": "に", "is_correct": false, "explanation": "「想像に域」は名詞の接続として成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「想像で域」は手段や場所の意味にならない。"}], "correct_answer": "の", "explanations": {"の": "「想像の域」で、域を修飾する「の」。文の意味が通る。", "が": "「想像が域を出ない」は主語と述語にならず、修飾関係が成立しない。", "に": "「想像に域」は名詞の接続として成り立たない。", "で": "「想像で域」は手段や場所の意味にならない。"}, "error_tags": {"が": "主語", "に": "対象", "で": "手段・場所"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca5920d4-ba89-425c-8b4e-47cfa4b9d998') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39508, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「域に近づく」で、近づく先を示す「に」。文の意味が通る。"}, {"text": "を", "is_correct": false, "explanation": "「域を近づく」は成り立たない。近づくは移動の先を「に」で示す。"}, {"text": "で", "is_correct": false, "explanation": "「域で近づく」は手段や場所の意味にならない。"}, {"text": "と", "is_correct": false, "explanation": "「域と近づく」は共同の動作を表せず、文が成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「域に近づく」で、近づく先を示す「に」。文の意味が通る。", "を": "「域を近づく」は成り立たない。近づくは移動の先を「に」で示す。", "で": "「域で近づく」は手段や場所の意味にならない。", "と": "「域と近づく」は共同の動作を表せず、文が成り立たない。"}, "error_tags": {"を": "目的語", "で": "手段・場所", "と": "相手・並列"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca5920d4-ba89-425c-8b4e-47cfa4b9d998') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39508, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ある場所や広がりの範囲。また、技量や状態が達する段階・境地。", "primary_collocate": null, "pronunciation": "いき", "ipa": "iki", "syllable_count": 2, "sentences": [{"text": "長年の練習で、彼の絵はプロの域に達している。", "target_word": "域", "complexity_tier": "T3", "furigana": "長年[ながねん]の練習[れんしゅう]で、彼[かれ]の絵[え]はプロの域[いき]に達[たっ]している。", "sentence_source": "generated"}, {"text": "その話は事実ではなく、想像の域を出ない。", "target_word": "域", "complexity_tier": "T3", "furigana": "その話[はなし]は事実[じじつ]ではなく、想像[そうぞう]の域[いき]を出[で]ない。", "sentence_source": "generated"}, {"text": "彼女のピアノは趣味の域を超えていて、演奏会にも呼ばれる。", "target_word": "域", "complexity_tier": "T3", "furigana": "彼女[かのじょ]のピアノは趣味[しゅみ]の域[いき]を超[こ]えていて、演奏会[えんそうかい]にも呼[よ]ばれる。", "sentence_source": "generated"}, {"text": "気温が体に危険な域に入ったので、外での運動を中止した。", "target_word": "域", "complexity_tier": "T3", "furigana": "気温[きおん]が体[からだ]に危険[きけん]な域[いき]に入[はい]ったので、外[そと]での運動[うんどう]を中止[ちゅうし]した。", "sentence_source": "generated"}, {"text": "先生の料理は、もう名人の域だと言われている。", "target_word": "域", "complexity_tier": "T3", "furigana": "先生[せんせい]の料理[りょうり]は、もう名人[めいじん]の域[いき]だと言[い]われている。", "sentence_source": "generated"}, {"text": "この出来事は、常識の域を超えていて、だれにも説明できない。", "target_word": "域", "complexity_tier": "T3", "furigana": "この出来事[できごと]は、常識[じょうしき]の域[いき]を超[こ]えていて、だれにも説明[せつめい]できない。", "sentence_source": "generated"}, {"text": "検査の数値は正常な域に収まっているので、心配はいらない。", "target_word": "域", "complexity_tier": "T3", "furigana": "検査[けんさ]の数値[すうち]は正常[せいじょう]な域[いき]に収[おさ]まっているので、心配[しんぱい]はいらない。", "sentence_source": "generated"}, {"text": "雨の量が警戒すべき域に近づいている。", "target_word": "域", "complexity_tier": "T3", "furigana": "雨[あめ]の量[りょう]が警戒[けいかい]すべき域[いき]に近[ちか]づいている。", "sentence_source": "generated"}, {"text": "山の高さが三千メートルを超える域では、空気がうすくなる。", "target_word": "域", "complexity_tier": "T3", "furigana": "山[やま]の高[たか]さが三千[さんぜん]メートルを超[こ]える域[いき]では、空気[くうき]がうすくなる。", "sentence_source": "generated"}, {"text": "年を重ねて、父の書は円熟の域に入った。", "target_word": "域", "complexity_tier": "T3", "furigana": "年[とし]を重[かさ]ねて、父[ちち]の書[しょ]は円熟[えんじゅく]の域[いき]に入[はい]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "域", "label": "基本形"}], "register": "文章語", "sense_fingerprint": "「〜の域」の形で、ある範囲・段階・境地を表す名詞（域に達する・域を出ない）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '989c883e-1f67-4ecd-80a7-ae7c0f0d1e3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39508, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "域", "is_correct": true, "explanation": "「プロの域」の形で、ある技量の段階・境地を表すので、この文に合う。"}, {"text": "畑", "is_correct": false, "explanation": "畑は耕す土地を指し、絵の技量の段階には使えない。"}, {"text": "箱", "is_correct": false, "explanation": "箱は容器のことで、プロの段階を表す語にはならない。"}, {"text": "窓", "is_correct": false, "explanation": "窓は開口部のことで、「達している」の対象にならない。"}], "explanations": {"域": "「プロの域」の形で、ある技量の段階・境地を表すので、この文に合う。", "畑": "畑は耕す土地を指し、絵の技量の段階には使えない。", "箱": "箱は容器のことで、プロの段階を表す語にはならない。", "窓": "窓は開口部のことで、「達している」の対象にならない。"}, "sentence_index": 0, "correct_answer": "域"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は会議で、域を述べた。", "explanation": "ここは〈意見〉の意味。意見を述べるのは考えを言葉で示すことで、域（範囲）は述べられない。"}, {"text": "その計画は、域を経て少しずつ形になった。", "explanation": "ここは〈過程〉の意味。「過程を経る」は段階を踏んで進むことで、域（範囲）は経られないので合わない。"}, {"text": "彼は場の域を読むのがうまい。", "explanation": "ここは〈空気〉（その場の雰囲気）の意味。雰囲気は読むものだが、域は範囲や段階を指すので読めない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca5920d4-ba89-425c-8b4e-47cfa4b9d998') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39508, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "域", "is_correct": true, "explanation": "「正常な域」で、正常とされる範囲を表すので、数値が収まる文脈に合う。"}, {"text": "鍋", "is_correct": false, "explanation": "鍋は調理器具で、数値が収まる範囲にはならない。"}, {"text": "穴", "is_correct": false, "explanation": "穴はくぼみを指し、数値の範囲を表せない。"}, {"text": "皿", "is_correct": false, "explanation": "皿は食器で、数値の範囲に当たらない。"}], "explanations": {"域": "「正常な域」で、正常とされる範囲を表すので、数値が収まる文脈に合う。", "鍋": "鍋は調理器具で、数値が収まる範囲にはならない。", "穴": "穴はくぼみを指し、数値の範囲を表せない。", "皿": "皿は食器で、数値の範囲に当たらない。"}, "sentence_index": 6, "correct_answer": "域"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "その選手は努力の末に、ついに試合の域を勝ち取った。", "explanation": "ここは〈権利〉の意味。権利は勝ち取るものだが、域（範囲や段階）は勝ち取れないので合わない。"}, {"text": "その作品は、長い域を経て完成した。", "explanation": "ここは〈過程〉の意味。「過程を経る」は段階を経て進むことで、範囲である域は経る対象にならない。"}, {"text": "域を踏んで申請してください。", "explanation": "ここは〈手順〉の意味。「手順を踏む」は決まった順序を進むことで、域は踏めない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca5920d4-ba89-425c-8b4e-47cfa4b9d998') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39508, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "その計画は、単なる夢の域に出ない。", "corrected_sentence": "その計画は、単なる夢の域を出ない。", "error_description": "「域を出る」は範囲の外に出ることを表すので、出るには「を」が必要。ここの「に」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca5920d4-ba89-425c-8b4e-47cfa4b9d998') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39508, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "数年の努力で、彼の文章は作家を域に入った。", "corrected_sentence": "数年の努力で、彼の文章は作家の域に入った。", "error_description": "「作家の域」の「の」が正しい。ここで「を」を使うと、域の修飾関係が崩れて文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca5920d4-ba89-425c-8b4e-47cfa4b9d998') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39510, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「上着を脱いだ」で、脱ぐの対象を示す「を」。"}, {"text": "に", "is_correct": false, "explanation": "「上着に脱いだ」は対象を示せず、文が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「上着で脱いだ」は手段の意味にならない。"}, {"text": "と", "is_correct": false, "explanation": "「上着と脱いだ」は対象を示せない。"}], "correct_answer": "を", "explanations": {"を": "「上着を脱いだ」で、脱ぐの対象を示す「を」。", "に": "「上着に脱いだ」は対象を示せず、文が成り立たない。", "で": "「上着で脱いだ」は手段の意味にならない。", "と": "「上着と脱いだ」は対象を示せない。"}, "error_tags": {"に": "target_marker", "で": "means_location", "と": "comitative"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "着る", "is_correct": true, "explanation": "服を脱ぐの対義語で、身につけるという反対の動作。"}, {"text": "包む", "is_correct": false, "explanation": "包むは覆う動作で、脱ぐの対義語ではない。"}, {"text": "食べる", "is_correct": false, "explanation": "食べるは飲食の動作で、脱ぐとは対になる関係ではない。"}, {"text": "見る", "is_correct": false, "explanation": "見るは視覚の動作で、脱ぐとは対になる関係ではない。"}], "correct_answer": "着る", "explanations": {"着る": "服を脱ぐの対義語で、身につけるという反対の動作。", "包む": "包むは覆う動作で、脱ぐの対義語ではない。", "食べる": "食べるは飲食の動作で、脱ぐとは対になる関係ではない。", "見る": "見るは視覚の動作で、脱ぐとは対になる関係ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca5920d4-ba89-425c-8b4e-47cfa4b9d998') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39510, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「シャツを脱がない」で、脱がないの対象を示す「を」。"}, {"text": "へ", "is_correct": false, "explanation": "「シャツへ脱がない」は方向を表せず、成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "「シャツより脱がない」は比較の形で、ここの文に合わない。"}, {"text": "の", "is_correct": false, "explanation": "「シャツの脱がない」は名詞修飾にならない。"}], "correct_answer": "を", "explanations": {"を": "「シャツを脱がない」で、脱がないの対象を示す「を」。", "へ": "「シャツへ脱がない」は方向を表せず、成り立たない。", "より": "「シャツより脱がない」は比較の形で、ここの文に合わない。", "の": "「シャツの脱がない」は名詞修飾にならない。"}, "error_tags": {"へ": "direction", "より": "comparison", "の": "attributive"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "着る", "is_correct": true, "explanation": "服を脱いでの対義語で、身につけるという反対の動作。"}, {"text": "運ぶ", "is_correct": false, "explanation": "運ぶは移動させる動作で、脱ぐの対義語ではない。"}, {"text": "眠る", "is_correct": false, "explanation": "眠るは休息の状態で、脱ぐとは対になる関係ではない。"}, {"text": "歌う", "is_correct": false, "explanation": "歌うは声を出す動作で、脱ぐとは対になる関係ではない。"}], "correct_answer": "着る", "explanations": {"着る": "服を脱いでの対義語で、身につけるという反対の動作。", "運ぶ": "運ぶは移動させる動作で、脱ぐの対義語ではない。", "眠る": "眠るは休息の状態で、脱ぐとは対になる関係ではない。", "歌う": "歌うは声を出す動作で、脱ぐとは対になる関係ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca5920d4-ba89-425c-8b4e-47cfa4b9d998') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39510, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "からだについている服をとること。", "primary_collocate": null, "pronunciation": "ぬぐ", "ipa": "nɯɡɯ", "syllable_count": 2, "sentences": [{"text": "雨でぬれた服は、家に着いたらすぐ脱ぐほうがいい。", "target_word": "脱ぐ", "complexity_tier": "T3", "furigana": "雨[あめ]でぬれた服[ふく]は、家[いえ]に着[つ]いたらすぐ脱[ぬ]ぐほうがいい。", "sentence_source": "generated"}, {"text": "暑くなったので、上着を脱いだ。", "target_word": "脱いだ", "complexity_tier": "T3", "furigana": "暑[あつ]くなったので、上着[うわぎ]を脱[ぬ]いだ。", "sentence_source": "generated"}, {"text": "風呂に入る前に、服を脱いでかごに入れる。", "target_word": "脱いで", "complexity_tier": "T3", "furigana": "風呂[ふろ]に入[はい]る前[まえ]に、服[ふく]を脱[ぬ]いでかごに入[い]れる。", "sentence_source": "generated"}, {"text": "部屋が暖かいから、コートを脱いだほうがいい。", "target_word": "脱いだ", "complexity_tier": "T3", "furigana": "部屋[へや]が暖[あたた]かいから、コートを脱[ぬ]いだほうがいい。", "sentence_source": "generated"}, {"text": "子どもは眠くなると、靴下を脱ぎたがる。", "target_word": "脱ぎたがる", "complexity_tier": "T3", "furigana": "子[こ]どもは眠[ねむ]くなると、靴下[くつした]を脱[ぬ]ぎたがる。", "sentence_source": "generated"}, {"text": "帽子を脱いで、先生にあいさつした。", "target_word": "脱いで", "complexity_tier": "T3", "furigana": "帽子[ぼうし]を脱[ぬ]いで、先生[せんせい]にあいさつした。", "sentence_source": "generated"}, {"text": "病院で、医者に言われてシャツを脱いだ。", "target_word": "脱いだ", "complexity_tier": "T3", "furigana": "病院[びょういん]で、医者[いしゃ]に言[い]われてシャツを脱[ぬ]いだ。", "sentence_source": "generated"}, {"text": "汗でぬれたシャツを脱がないと、風邪をひく。", "target_word": "脱がない", "complexity_tier": "T3", "furigana": "汗[あせ]でぬれたシャツを脱[ぬ]がないと、風邪[かぜ]をひく。", "sentence_source": "generated"}, {"text": "汗をかいた日は、寝る前にシャツを脱ぐと楽だ。", "target_word": "脱ぐ", "complexity_tier": "T3", "furigana": "汗[あせ]をかいた日[ひ]は、寝[ね]る前[まえ]にシャツを脱[ぬ]ぐと楽[らく]だ。", "sentence_source": "generated"}, {"text": "運動のあと、ぬれた服を脱いで日なたに干した。", "target_word": "脱いで", "complexity_tier": "T3", "furigana": "運動[うんどう]のあと、ぬれた服[ふく]を脱[ぬ]いで日[ひ]なたに干[ほ]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "脱ぐ", "label": "終止形"}, {"form": "脱いで", "label": "て形"}, {"form": "脱いだ", "label": "過去形"}, {"form": "脱がない", "label": "否定形"}, {"form": "脱ぎます", "label": "ます形"}, {"form": "脱げば", "label": "仮定形"}, {"form": "脱ごう", "label": "意志形"}, {"form": "脱げる", "label": "可能形"}], "register": "中立", "sense_fingerprint": "身につけている服・靴・帽子などを体から取り外す動作（着る・履くの反対）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '989c883e-1f67-4ecd-80a7-ae7c0f0d1e3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39510, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "脱ぐ", "is_correct": true, "explanation": "服をすぐ体から取るという意味で、ぬれた服を家で処理する文に合う。"}, {"text": "叩く", "is_correct": false, "explanation": "叩くは打つ動作で、ぬれた服には合わない。"}, {"text": "消す", "is_correct": false, "explanation": "消すは火や明かりを止める動作で、服の対象にならない。"}, {"text": "結ぶ", "is_correct": false, "explanation": "結ぶはひもなどを縛る動作で、この文脈に合わない。"}], "explanations": {"脱ぐ": "服をすぐ体から取るという意味で、ぬれた服を家で処理する文に合う。", "叩く": "叩くは打つ動作で、ぬれた服には合わない。", "消す": "消すは火や明かりを止める動作で、服の対象にならない。", "結ぶ": "結ぶはひもなどを縛る動作で、この文脈に合わない。"}, "sentence_index": 0, "correct_answer": "脱ぐ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "古くなった釘を脱いで、板をはずした。", "explanation": "ここは〈抜く〉の意味。釘を引き抜くのは抜くで、脱ぐは身につけた衣服をとるときにだけ使う。"}, {"text": "寝る前に眼鏡を脱いで、机に置いた。", "explanation": "ここは〈外す〉の意味。眼鏡やアクセサリーは外すと言い、脱ぐとは言わない。"}, {"text": "壁に貼ったポスターを脱いで、丸めて捨てた。", "explanation": "ここは〈剥がす〉の意味。貼りついたものを表面から取るのは剥がすで、脱ぐは身につけた衣類に使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca5920d4-ba89-425c-8b4e-47cfa4b9d998') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39510, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "脱いだ", "is_correct": true, "explanation": "シャツを体から取った過去の動作を表し、医者に言われた文脈に合う。"}, {"text": "煮た", "is_correct": false, "explanation": "煮るは加熱する動作で、シャツには合わない。"}, {"text": "噛んだ", "is_correct": false, "explanation": "噛むは口の動作で、シャツを対象にできない。"}, {"text": "焼いた", "is_correct": false, "explanation": "焼くは加熱する動作で、医者の指示として成り立たない。"}], "explanations": {"脱いだ": "シャツを体から取った過去の動作を表し、医者に言われた文脈に合う。", "煮た": "煮るは加熱する動作で、シャツには合わない。", "噛んだ": "噛むは口の動作で、シャツを対象にできない。", "焼いた": "焼くは加熱する動作で、医者の指示として成り立たない。"}, "sentence_index": 6, "correct_answer": "脱いだ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "靴ひもを脱いで、結び直した。", "explanation": "ここは〈解く〉の意味。靴ひもをほどくのは解くで、体から服をとる脱ぐとは違う。"}, {"text": "棚の上の荷物を脱いで、床に置いた。", "explanation": "ここは〈下ろす〉の意味。高い所から物を取るのは下ろすで、脱ぐは身につけたものに使う。"}, {"text": "かばんから財布を脱いで、支払いをした。", "explanation": "ここは〈取り出す〉の意味。かばんの中から出すのは取り出すで、脱ぐとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca5920d4-ba89-425c-8b4e-47cfa4b9d998') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39510, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "雨に降られた日は、帰ったらすぐ服に脱ぐ。", "corrected_sentence": "雨に降られた日は、帰ったらすぐ服を脱ぐ。", "error_description": "脱ぐは直接の対象に「を」を取る。「服に脱ぐ」の「に」は誤りで、正しくは「を」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "脱いだ", "is_correct": true, "explanation": "「暑くなったので」を受けて、動作が終わった過去を述べる形。"}, {"text": "脱いで", "is_correct": false, "explanation": "て形のままでは文が途中で止まり、過去として完結しない。"}, {"text": "脱ぎた", "is_correct": false, "explanation": "「脱ぎたい」の途中形で、過去の形として成り立たない。"}, {"text": "脱いたい", "is_correct": false, "explanation": "「脱いだ」に「たい」を付けた形で、正しい活用ではない。"}], "correct_form": "脱いだ", "base_form": "脱ぐ", "form_label": "過去形", "sentence_index": 1, "explanations": {"脱いだ": "「暑くなったので」を受けて、動作が終わった過去を述べる形。", "脱いで": "て形のままでは文が途中で止まり、過去として完結しない。", "脱ぎた": "「脱ぎたい」の途中形で、過去の形として成り立たない。", "脱いたい": "「脱いだ」に「たい」を付けた形で、正しい活用ではない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca5920d4-ba89-425c-8b4e-47cfa4b9d998') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39510, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "体が冷えないうちに、服を脱げて着替えよう。", "corrected_sentence": "体が冷えないうちに、服を脱いで着替えよう。", "error_description": "脱ぐは自分が服を取る動作。「脱げて」は服が自然に落ちる意味になり、文の動作と合わない。正しくは「脱いで」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "脱がない", "is_correct": true, "explanation": "「脱がないと」で、否定の条件を表す形。"}, {"text": "脱ぎない", "is_correct": false, "explanation": "否定形の作り方が誤っていて、日本語として成り立たない。"}, {"text": "脱ぐない", "is_correct": false, "explanation": "否定形の作り方が誤っていて、日本語として成り立たない。"}, {"text": "脱いない", "is_correct": false, "explanation": "否定形の作り方が誤っていて、日本語として成り立たない。"}], "correct_form": "脱がない", "base_form": "脱ぐ", "form_label": "否定形", "sentence_index": 7, "explanations": {"脱がない": "「脱がないと」で、否定の条件を表す形。", "脱ぎない": "否定形の作り方が誤っていて、日本語として成り立たない。", "脱ぐない": "否定形の作り方が誤っていて、日本語として成り立たない。", "脱いない": "否定形の作り方が誤っていて、日本語として成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca5920d4-ba89-425c-8b4e-47cfa4b9d998') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39511, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「上着を脱いで」で、脱ぐ対象を示す「を」。"}, {"text": "と", "is_correct": false, "explanation": "「上着と脱いで」は対象を示せず、成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「上着へ脱いで」は方向の意味にならない。"}, {"text": "の", "is_correct": false, "explanation": "「上着の脱いで」は名詞修飾にならない。"}], "correct_answer": "を", "explanations": {"を": "「上着を脱いで」で、脱ぐ対象を示す「を」。", "と": "「上着と脱いで」は対象を示せず、成り立たない。", "へ": "「上着へ脱いで」は方向の意味にならない。", "の": "「上着の脱いで」は名詞修飾にならない。"}, "error_tags": {"と": "comitative", "へ": "direction", "の": "attributive"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "被る", "is_correct": true, "explanation": "帽子を脱ぐの対義語で、頭に身につけるという反対の動作。"}, {"text": "運ぶ", "is_correct": false, "explanation": "運ぶは移動させる動作で、脱ぐの対義語ではない。"}, {"text": "眠る", "is_correct": false, "explanation": "眠るは休息の状態で、脱ぐとは対になる関係ではない。"}, {"text": "歌う", "is_correct": false, "explanation": "歌うは声を出す動作で、脱ぐとは対になる関係ではない。"}], "correct_answer": "被る", "explanations": {"被る": "帽子を脱ぐの対義語で、頭に身につけるという反対の動作。", "運ぶ": "運ぶは移動させる動作で、脱ぐの対義語ではない。", "眠る": "眠るは休息の状態で、脱ぐとは対になる関係ではない。", "歌う": "歌うは声を出す動作で、脱ぐとは対になる関係ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca5920d4-ba89-425c-8b4e-47cfa4b9d998') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39511, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「帽子を脱いで」で、脱ぐ対象を示す「を」。"}, {"text": "に", "is_correct": false, "explanation": "「帽子に脱いで」は対象を示せず、成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「帽子で脱いで」は手段の意味にならない。"}, {"text": "より", "is_correct": false, "explanation": "「帽子より脱いで」は比較の形で、この文に合わない。"}], "correct_answer": "を", "explanations": {"を": "「帽子を脱いで」で、脱ぐ対象を示す「を」。", "に": "「帽子に脱いで」は対象を示せず、成り立たない。", "で": "「帽子で脱いで」は手段の意味にならない。", "より": "「帽子より脱いで」は比較の形で、この文に合わない。"}, "error_tags": {"に": "target_marker", "で": "means_location", "より": "comparison"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "履く", "is_correct": true, "explanation": "靴を脱ぐの対義語で、足に身につけるという反対の動作。"}, {"text": "包む", "is_correct": false, "explanation": "包むは覆う動作で、脱ぐの対義語ではない。"}, {"text": "食べる", "is_correct": false, "explanation": "食べるは飲食の動作で、脱ぐとは対になる関係ではない。"}, {"text": "見る", "is_correct": false, "explanation": "見るは視覚の動作で、脱ぐとは対になる関係ではない。"}], "correct_answer": "履く", "explanations": {"履く": "靴を脱ぐの対義語で、足に身につけるという反対の動作。", "包む": "包むは覆う動作で、脱ぐの対義語ではない。", "食べる": "食べるは飲食の動作で、脱ぐとは対になる関係ではない。", "見る": "見るは視覚の動作で、脱ぐとは対になる関係ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca5920d4-ba89-425c-8b4e-47cfa4b9d998') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39511, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "身に着けている衣服や履物などを、体から取り去る。", "primary_collocate": null, "pronunciation": "ぬぐ", "ipa": "nɯɡɯ", "syllable_count": 2, "sentences": [{"text": "家に入るときは、玄関で靴を脱ぎます。", "target_word": "脱ぎ", "complexity_tier": "T2", "furigana": "家[いえ]に入[はい]るときは、玄関[げんかん]で靴[くつ]を脱[ぬ]ぎます。", "sentence_source": "generated"}, {"text": "暑くなったので、上着を脱いで椅子にかけた。", "target_word": "脱いで", "complexity_tier": "T3", "furigana": "暑[あつ]くなったので、上着[うわぎ]を脱[ぬ]いで椅子[いす]にかけた。", "sentence_source": "generated"}, {"text": "温泉に入る前に、服を全部脱ぎます。", "target_word": "脱ぎ", "complexity_tier": "T3", "furigana": "温泉[おんせん]に入[はい]る前[まえ]に、服[ふく]を全部[ぜんぶ]脱[ぬ]ぎます。", "sentence_source": "generated"}, {"text": "子どもは帽子を脱がないで、部屋の中を走り回っている。", "target_word": "脱がないで", "complexity_tier": "T3", "furigana": "子[こ]どもは帽子[ぼうし]を脱[ぬ]がないで、部屋[へや]の中[なか]を走[はし]り回[まわ]っている。", "sentence_source": "generated"}, {"text": "汗でぬれたシャツを脱いだら、とても楽になった。", "target_word": "脱いだら", "complexity_tier": "T3", "furigana": "汗[あせ]でぬれたシャツを脱[ぬ]いだら、とても楽[らく]になった。", "sentence_source": "generated"}, {"text": "寒かったので、コートを脱がずに座った。", "target_word": "脱がずに", "complexity_tier": "T4", "furigana": "寒[さむ]かったので、コートを脱[ぬ]がずに座[すわ]った。", "sentence_source": "generated"}, {"text": "病院で、医者に「上着を脱いでください」と言われた。", "target_word": "脱いで", "complexity_tier": "T3", "furigana": "病院[びょういん]で、医者[いしゃ]に「上着[うわぎ]を脱[ぬ]いでください」と言[い]われた。", "sentence_source": "generated"}, {"text": "帽子を脱いで、先生にあいさつした。", "target_word": "脱いで", "complexity_tier": "T2", "furigana": "帽子[ぼうし]を脱[ぬ]いで、先生[せんせい]にあいさつした。", "sentence_source": "generated"}, {"text": "兄は毎日、帰ってすぐ靴下を脱ぐ。", "target_word": "脱ぐ", "complexity_tier": "T2", "furigana": "兄[あに]は毎日[まいにち]、帰[かえ]ってすぐ靴下[くつした]を脱[ぬ]ぐ。", "sentence_source": "generated"}, {"text": "靴を脱ぐ場所がわからなくて、店の入り口で困った。", "target_word": "脱ぐ", "complexity_tier": "T4", "furigana": "靴[くつ]を脱[ぬ]ぐ場所[ばしょ]がわからなくて、店[みせ]の入[い]り口[ぐち]で困[こま]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "脱ぐ", "label": "辞書形"}, {"form": "脱ぎ", "label": "連用形"}, {"form": "脱いで", "label": "て形"}, {"form": "脱いだ", "label": "過去形"}, {"form": "脱がない", "label": "否定形"}, {"form": "脱げば", "label": "仮定形"}], "register": "中立", "sense_fingerprint": "衣服や靴などを体から外す動作", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '989c883e-1f67-4ecd-80a7-ae7c0f0d1e3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39511, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "脱ぎ", "is_correct": true, "explanation": "「靴を脱ぎます」の一部で、玄関で靴を体から外す動作を表す。"}, {"text": "泣き", "is_correct": false, "explanation": "泣くは感情の動作で、靴を目的語にできない。"}, {"text": "笑い", "is_correct": false, "explanation": "笑うは表情の動作で、靴の動作にはならない。"}, {"text": "眠り", "is_correct": false, "explanation": "眠るは休む状態で、靴には合わない。"}], "explanations": {"脱ぎ": "「靴を脱ぎます」の一部で、玄関で靴を体から外す動作を表す。", "泣き": "泣くは感情の動作で、靴を目的語にできない。", "笑い": "笑うは表情の動作で、靴の動作にはならない。", "眠り": "眠るは休む状態で、靴には合わない。"}, "sentence_index": 0, "correct_answer": "脱ぎ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "虫歯を脱いでもらった。", "explanation": "ここは〈抜く〉の意味。歯を体から外すのは抜くで、脱ぐは衣類や靴に使う。"}, {"text": "本のページを脱いで、次を読んだ。", "explanation": "ここは〈めくる〉の意味。ページを返して次に進むのはめくるで、脱ぐは身に着けたものを体から取るときに使う。"}, {"text": "ラベルを脱いで、びんを洗った。", "explanation": "ここは〈剥がす〉の意味。貼ってあるものをはがすのは剥がすで、脱ぐは身につけたものにだけ使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca5920d4-ba89-425c-8b4e-47cfa4b9d998') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39511, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "脱いで", "is_correct": true, "explanation": "「上着を脱いでください」の一部で、体から外す指示に合う。"}, {"text": "煮て", "is_correct": false, "explanation": "煮るは加熱する動作で、上着には合わない。"}, {"text": "噛んで", "is_correct": false, "explanation": "噛むは口の動作で、上着を対象にできない。"}, {"text": "焼いて", "is_correct": false, "explanation": "焼くは加熱する動作で、医者の指示として成り立たない。"}], "explanations": {"脱いで": "「上着を脱いでください」の一部で、体から外す指示に合う。", "煮て": "煮るは加熱する動作で、上着には合わない。", "噛んで": "噛むは口の動作で、上着を対象にできない。", "焼いて": "焼くは加熱する動作で、医者の指示として成り立たない。"}, "sentence_index": 6, "correct_answer": "脱いで"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "靴ひもを脱いで、結び直した。", "explanation": "ここは〈解く〉の意味。靴ひもをほどくのは解くで、靴を脱ぐ動作とは違う。"}, {"text": "棚の上の荷物を脱いで、床に置いた。", "explanation": "ここは〈下ろす〉の意味。高い所から物を取るのは下ろすで、脱ぐは身につけたものに使う。"}, {"text": "かばんから財布を脱いで、支払いをした。", "explanation": "ここは〈取り出す〉の意味。かばんの中から出すのは取り出すで、脱ぐとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca5920d4-ba89-425c-8b4e-47cfa4b9d998') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39511, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "寒い日は、部屋に入ったら上着に脱ぐ。", "corrected_sentence": "寒い日は、部屋に入ったら上着を脱ぐ。", "error_description": "脱ぐは直接の対象に「を」を取る。「上着に脱ぐ」の「に」は誤りで、正しくは「を」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "脱いで", "is_correct": true, "explanation": "て形で、「椅子にかけた」へつながる前の動作を表す。"}, {"text": "脱ぎます", "is_correct": false, "explanation": "丁寧形で、後ろの「椅子にかけた」へ続けにくい。"}, {"text": "脱いたい", "is_correct": false, "explanation": "「脱いだ」に「たい」を付けた形で、正しい活用ではない。"}, {"text": "脱ぎない", "is_correct": false, "explanation": "否定形の作り方が誤っていて、日本語として成り立たない。"}], "correct_form": "脱いで", "base_form": "脱ぐ", "form_label": "て形", "sentence_index": 1, "explanations": {"脱いで": "て形で、「椅子にかけた」へつながる前の動作を表す。", "脱ぎます": "丁寧形で、後ろの「椅子にかけた」へ続けにくい。", "脱いたい": "「脱いだ」に「たい」を付けた形で、正しい活用ではない。", "脱ぎない": "否定形の作り方が誤っていて、日本語として成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca5920d4-ba89-425c-8b4e-47cfa4b9d998') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39511, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雨の日は、玄関で靴を脱ぎて上がる。", "corrected_sentence": "雨の日は、玄関で靴を脱いで上がる。", "error_description": "て形は「脱いで」。連用形の「脱ぎ」に「て」を付けると誤り。音便で「脱いで」になる。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "脱いで", "is_correct": true, "explanation": "て形で、帽子を脱いでから先生にあいさつしたという前の動作を表す。"}, {"text": "脱いぎ", "is_correct": false, "explanation": "連用形の語幹に誤って音を付けた形で、日本語として成り立たない。"}, {"text": "脱ぐない", "is_correct": false, "explanation": "否定形の作り方が誤っていて、日本語として成り立たない。"}, {"text": "脱ぎない", "is_correct": false, "explanation": "否定形の作り方が誤っていて、日本語として成り立たない。"}], "correct_form": "脱いで", "base_form": "脱ぐ", "form_label": "て形", "sentence_index": 7, "explanations": {"脱いで": "て形で、帽子を脱いでから先生にあいさつしたという前の動作を表す。", "脱いぎ": "連用形の語幹に誤って音を付けた形で、日本語として成り立たない。", "脱ぐない": "否定形の作り方が誤っていて、日本語として成り立たない。", "脱ぎない": "否定形の作り方が誤っていて、日本語として成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca5920d4-ba89-425c-8b4e-47cfa4b9d998') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39512, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "『蒸気で』いっぱいになる、という状態の原因・材料を示す『で』が正しい。"}, {"text": "に", "is_correct": false, "explanation": "『蒸気に』では充満するものを示せず、文が成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "『いっぱいになる』は自動詞なので、目的語の『を』は取れない。"}, {"text": "と", "is_correct": false, "explanation": "『と』は並列や相手を示すので、『蒸気といっぱい』は意味が通らない。"}], "correct_answer": "で", "explanations": {"で": "『蒸気で』いっぱいになる、という状態の原因・材料を示す『で』が正しい。", "に": "『蒸気に』では充満するものを示せず、文が成り立たない。", "を": "『いっぱいになる』は自動詞なので、目的語の『を』は取れない。", "と": "『と』は並列や相手を示すので、『蒸気といっぱい』は意味が通らない。"}, "error_tags": {"に": "到着点・状態", "を": "目的語（他動詞）", "と": "並列・相手"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '756040c1-37ff-47fa-8b7d-9c1d20b9a3a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39512, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "『蒸気』が『上がっている』の主語にあたる。動作の主体を示す『が』が正しい。"}, {"text": "へ", "is_correct": false, "explanation": "『へ』は方向を示すので、主語の位置に入れると『蒸気へ上がっている』は不自然。"}, {"text": "を", "is_correct": false, "explanation": "『蒸気を』は道筋ではなく、動作の主体は『が』で示す。『を』では成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "『で』は手段や場所を示すので、『蒸気で上がっている』は主語にならない。"}], "correct_answer": "が", "explanations": {"が": "『蒸気』が『上がっている』の主語にあたる。動作の主体を示す『が』が正しい。", "へ": "『へ』は方向を示すので、主語の位置に入れると『蒸気へ上がっている』は不自然。", "を": "『蒸気を』は道筋ではなく、動作の主体は『が』で示す。『を』では成り立たない。", "で": "『で』は手段や場所を示すので、『蒸気で上がっている』は主語にならない。"}, "error_tags": {"を": "目的語・道筋（主語の位置に不可）", "へ": "方向", "で": "手段・場所"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '756040c1-37ff-47fa-8b7d-9c1d20b9a3a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39512, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "水が熱くなって出る白いもの。", "primary_collocate": null, "pronunciation": "じょうき", "ipa": "dʑoːki", "syllable_count": 3, "sentences": [{"text": "やかんの口から白い蒸気が出てきたので、火を止めた。", "target_word": "蒸気", "complexity_tier": "T3", "furigana": "やかんの口[くち]から白[しろ]い蒸気[じょうき]が出[で]てきたので、火[ひ]を止[と]めた。", "sentence_source": "generated"}, {"text": "冬の朝、お風呂場は蒸気でいっぱいになった。", "target_word": "蒸気", "complexity_tier": "T3", "furigana": "冬[ふゆ]の朝[あさ]、お風呂場[ふろば]は蒸気[じょうき]でいっぱいになった。", "sentence_source": "generated"}, {"text": "ラーメンの鍋から、白い蒸気がもくもくと上がっている。", "target_word": "蒸気", "complexity_tier": "T3", "furigana": "ラーメンの鍋[なべ]から、白[しろ]い蒸気[じょうき]がもくもくと上[あ]がっている。", "sentence_source": "generated"}, {"text": "蒸気で眼鏡がくもって、前がよく見えなくなった。", "target_word": "蒸気", "complexity_tier": "T3", "furigana": "蒸気[じょうき]で眼鏡[めがね]がくもって、前[まえ]がよく見[み]えなくなった。", "sentence_source": "generated"}, {"text": "洗濯物にアイロンを当てると、白い蒸気が立ちのぼった。", "target_word": "蒸気", "complexity_tier": "T3", "furigana": "洗濯物[せんたくもの]にアイロンを当[あ]てると、白[しろ]い蒸気[じょうき]が立[た]ちのぼった。", "sentence_source": "generated"}, {"text": "肉まんのふたを取ると、熱い蒸気がふわっと顔にかかった。", "target_word": "蒸気", "complexity_tier": "T3", "furigana": "肉[にく]まんのふたを取[と]ると、熱[あつ]い蒸気[じょうき]がふわっと顔[かお]にかかった。", "sentence_source": "generated"}, {"text": "加湿器から出る蒸気で、部屋が少ししめってきた。", "target_word": "蒸気", "complexity_tier": "T3", "furigana": "加湿器[かしつき]から出[で]る蒸気[じょうき]で、部屋[へや]が少[すこ]ししめってきた。", "sentence_source": "generated"}, {"text": "蒸気が上がっているから、お湯はもうすぐわくだろう。", "target_word": "蒸気", "complexity_tier": "T3", "furigana": "蒸気[じょうき]が上[あ]がっているから、お湯[ゆ]はもうすぐわくだろう。", "sentence_source": "generated"}, {"text": "寒い日は、ほかほかの蒸気が窓ガラスをくもらせる。", "target_word": "蒸気", "complexity_tier": "T3", "furigana": "寒[さむ]い日[ひ]は、ほかほかの蒸気[じょうき]が窓[まど]ガラスをくもらせる。", "sentence_source": "generated"}, {"text": "調理場の天井に、蒸気がたまって水のしずくになった。", "target_word": "蒸気", "complexity_tier": "T3", "furigana": "調理場[ちょうりば]の天井[てんじょう]に、蒸気[じょうき]がたまって水[みず]のしずくになった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "蒸気", "label": "基本形"}], "register": "中立", "sense_fingerprint": "熱い水から立ちのぼる、目に見える白いもの。やかんや鍋、風呂場などの身近な場面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 4 above tier T3: contains vocabulary far above tier T3: 立ちのぼっ (Zipf 1.24)','sentence 6 above tier T3: contains vocabulary far above tier T3: しめっ (Zipf 1.83)','sentence 8 above tier T3: contains vocabulary far above tier T3: くもらせる (Zipf 1.21)']::text[], '15ff9fe7-707a-4585-aee1-5053efbd78c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39512, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "蒸気", "is_correct": true, "explanation": "水が熱くなって出る白いもので、やかんの口から出てくる様子に合う。"}, {"text": "氷", "is_correct": false, "explanation": "やかんの口から出てくるのは熱い蒸気で、氷ではないので合わない。"}, {"text": "石", "is_correct": false, "explanation": "石がやかんの口から出てくることはないので、文の内容に合わない。"}, {"text": "綿", "is_correct": false, "explanation": "綿は白いが、熱いやかんの口から出てくるものではないので合わない。"}], "explanations": {"蒸気": "水が熱くなって出る白いもので、やかんの口から出てくる様子に合う。", "氷": "やかんの口から出てくるのは熱い蒸気で、氷ではないので合わない。", "石": "石がやかんの口から出てくることはないので、文の内容に合わない。", "綿": "綿は白いが、熱いやかんの口から出てくるものではないので合わない。"}, "sentence_index": 0, "correct_answer": "蒸気"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "焚き火の蒸気が夜空へ昇っていった。", "explanation": "ここは〈煙〉の意味。焚き火から出るのは煙で、水が熱くなって出る白い蒸気とは別物。"}, {"text": "走り終えた選手の額に蒸気がにじんでいた。", "explanation": "ここは〈汗〉の意味。にじむのは皮膚から出る汗で、蒸気は人の体からにじみ出るものではない。"}, {"text": "ポットの蒸気を注いで、お茶をいれた。", "explanation": "ここは〈湯〉の意味。注ぐのは液体の湯で、気体の蒸気は注げない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '756040c1-37ff-47fa-8b7d-9c1d20b9a3a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39512, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "蒸気", "is_correct": true, "explanation": "加湿器から出て部屋をしめらせる水の蒸気で、文の内容に合う。"}, {"text": "紙", "is_correct": false, "explanation": "紙は加湿器から出るものではなく、部屋をしめらせる働きもないので合わない。"}, {"text": "木", "is_correct": false, "explanation": "木が加湿器から出ることはないので、文の内容に合わない。"}, {"text": "砂", "is_correct": false, "explanation": "砂が加湿器から出て部屋をしめらせることはないので合わない。"}], "explanations": {"蒸気": "加湿器から出て部屋をしめらせる水の蒸気で、文の内容に合う。", "紙": "紙は加湿器から出るものではなく、部屋をしめらせる働きもないので合わない。", "木": "木が加湿器から出ることはないので、文の内容に合わない。", "砂": "砂が加湿器から出て部屋をしめらせることはないので合わない。"}, "sentence_index": 6, "correct_answer": "蒸気"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "朝から蒸気が降り続いていた。", "explanation": "ここは〈霧雨〉の意味。降るのは細かい雨粒で、気体の蒸気は降るものではない。"}, {"text": "朝、草に蒸気がおりていた。", "explanation": "ここは〈露〉の意味。草などにつく水滴で、おりるのは露や霜であり、蒸気はおりるとは言わない。"}, {"text": "屋根に蒸気が積もっていた。", "explanation": "ここは〈雪〉の意味。積もるのは固体の雪で、気体の蒸気は積もらない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '756040c1-37ff-47fa-8b7d-9c1d20b9a3a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39512, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ふたを取ると、白い蒸気がふわっと広げた。", "corrected_sentence": "ふたを取ると、白い蒸気がふわっと広がった。", "error_description": "『広がる』は自動詞なので、動きの主体『蒸気が』と組む。『広げた』は他動詞で、『蒸気が広げた』とは言えない。正しくは『広がった』。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '756040c1-37ff-47fa-8b7d-9c1d20b9a3a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39512, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "寒い日の朝、暖房の蒸気を窓がくもった。", "corrected_sentence": "寒い日の朝、暖房の蒸気で窓がくもった。", "error_description": "『くもる』は原因・手段を『で』で示す。『蒸気を』は他動詞の目的語の助詞で、ここでは誤り。正しくは『蒸気で』。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '756040c1-37ff-47fa-8b7d-9c1d20b9a3a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39513, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "『蒸気』が『上がり』の主語にあたる。動作の主体を示す『が』が正しい。"}, {"text": "を", "is_correct": false, "explanation": "『上がる』は自動詞なので、目的語の『を』は取れない。"}, {"text": "へ", "is_correct": false, "explanation": "『へ』は方向を示すが、主語の位置に置くと『蒸気へ勢いよく上がり』は不自然。"}, {"text": "と", "is_correct": false, "explanation": "『と』は並列や共同を示すので、『蒸気と勢いよく上がり』は意味が通らない。"}], "correct_answer": "が", "explanations": {"が": "『蒸気』が『上がり』の主語にあたる。動作の主体を示す『が』が正しい。", "を": "『上がる』は自動詞なので、目的語の『を』は取れない。", "へ": "『へ』は方向を示すが、主語の位置に置くと『蒸気へ勢いよく上がり』は不自然。", "と": "『と』は並列や共同を示すので、『蒸気と勢いよく上がり』は意味が通らない。"}, "error_tags": {"を": "目的語（他動詞）", "へ": "方向", "と": "並列・共同"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '756040c1-37ff-47fa-8b7d-9c1d20b9a3a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39513, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "『蒸気』が『出る』の主語にあたる。動作の主体を示す『が』が正しい。"}, {"text": "で", "is_correct": false, "explanation": "『で』は手段や場所を示すので、『蒸気で出る』は不自然。"}, {"text": "に", "is_correct": false, "explanation": "『に』は到着点や相手を示すので、『蒸気に出る』は成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "『蒸気を』は道筋ではなく、動作の主体は『が』で示す。『を』では成り立たない。"}], "correct_answer": "が", "explanations": {"が": "『蒸気』が『出る』の主語にあたる。動作の主体を示す『が』が正しい。", "で": "『で』は手段や場所を示すので、『蒸気で出る』は不自然。", "に": "『に』は到着点や相手を示すので、『蒸気に出る』は成り立たない。", "を": "『蒸気を』は道筋ではなく、動作の主体は『が』で示す。『を』では成り立たない。"}, "error_tags": {"で": "手段・場所", "に": "到着点・相手", "を": "目的語・道筋（主語の位置に不可）"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '756040c1-37ff-47fa-8b7d-9c1d20b9a3a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39513, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "水が沸騰して気体になったもの。", "primary_collocate": null, "pronunciation": "じょうき", "ipa": "dʑoːki", "syllable_count": 3, "sentences": [{"text": "最終段階のベーキングでは、高温の蒸気と共に膨張した生地が、黄金色の硬質で脆いクラストを纏い、内部は瑞々しくも弾力に富んだクラムへと昇華する。", "target_word": "蒸気", "complexity_tier": "T4", "furigana": "最終[さいしゅう]段階[だんかい]のベーキングでは、高温[こうおん]の蒸気[じょうき]と共[とも]に膨張[ぼうちょう]した生地[きじ]が、黄金色[こがねいろ]の硬質[こうしつ]で脆[もろ]いクラストを纏[まと]い、内部[ないぶ]は瑞々[みずみず]しくも弾力[だんりょく]に富[と]んだクラムへと昇華[しょうか]する。", "sentence_source": "mined"}, {"text": "沸騰したお湯から蒸気が勢いよく上がり、台所の窓がくもった。", "target_word": "蒸気", "complexity_tier": "T3", "furigana": "沸騰[ふっとう]したお湯[ゆ]から蒸気[じょうき]が勢[いきお]いよく上[あ]がり、台所[だいどころ]の窓[まど]がくもった。", "sentence_source": "generated"}, {"text": "蒸気を利用して発電する工場が、川沿いに建てられている。", "target_word": "蒸気", "complexity_tier": "T3", "furigana": "蒸気[じょうき]を利用[りよう]して発電[はつでん]する工場[こうじょう]が、川沿[かわぞ]いに建[た]てられている。", "sentence_source": "generated"}, {"text": "圧力鍋の中では蒸気がこもるので、短い時間で豆がやわらかくなる。", "target_word": "蒸気", "complexity_tier": "T3", "furigana": "圧力鍋[あつりょくなべ]の中[なか]では蒸気[じょうき]がこもるので、短[みじか]い時間[じかん]で豆[まめ]がやわらかくなる。", "sentence_source": "generated"}, {"text": "鍋のふたを開けると、熱い蒸気でやけどをすることがある。", "target_word": "蒸気", "complexity_tier": "T3", "furigana": "鍋[なべ]のふたを開[あ]けると、熱[あつ]い蒸気[じょうき]でやけどをすることがある。", "sentence_source": "generated"}, {"text": "古い機関車は、石炭を燃やして作った蒸気の力で走っていた。", "target_word": "蒸気", "complexity_tier": "T3", "furigana": "古[ふる]い機関車[きかんしゃ]は、石炭[せきたん]を燃[も]やして作[つく]った蒸気[じょうき]の力[ちから]で走[はし]っていた。", "sentence_source": "generated"}, {"text": "蒸気は冷やされると、また水にもどる。", "target_word": "蒸気", "complexity_tier": "T3", "furigana": "蒸気[じょうき]は冷[ひ]やされると、また水[みず]にもどる。", "sentence_source": "generated"}, {"text": "アイロンから蒸気が出るので、しわが簡単にのびる。", "target_word": "蒸気", "complexity_tier": "T3", "furigana": "アイロンから蒸気[じょうき]が出[で]るので、しわが簡単[かんたん]にのびる。", "sentence_source": "generated"}, {"text": "蒸し器の蒸気で、肉まんがふっくらと温まった。", "target_word": "蒸気", "complexity_tier": "T3", "furigana": "蒸[む]し器[き]の蒸気[じょうき]で、肉[にく]まんがふっくらと温[あたた]まった。", "sentence_source": "generated"}, {"text": "この温泉地では、地面から高温の蒸気が噴き出している。", "target_word": "蒸気", "complexity_tier": "T3", "furigana": "この温泉地[おんせんち]では、地面[じめん]から高温[こうおん]の蒸気[じょうき]が噴[ふ]き出[だ]している。", "sentence_source": "generated"}], "morphological_forms": [{"form": "蒸気", "label": "基本形"}], "register": "中立", "sense_fingerprint": "水が沸騰して気体になった水蒸気。調理や発電など、加熱の結果として扱われる気体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T3: contains vocabulary far above tier T3: ベーキング (Zipf 1.24), 瑞々しく (Zipf 1.76)','sentence 8 above tier T3: 4 words above tier T3 (max 3): 蒸し器 (Zipf 2.14), 肉まん (Zipf 3.1), ふっくら (Zipf 3.3), 温まっ (Zipf 2.86)']::text[], '15ff9fe7-707a-4585-aee1-5053efbd78c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39513, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "蒸気", "is_correct": true, "explanation": "水が沸騰してできた気体で、「高温の〜と共に膨張した」という文脈に合う。"}, {"text": "氷", "is_correct": false, "explanation": "氷は低温の固体なので、「高温の」と矛盾し、生地と共に膨張する気体にもならない。"}, {"text": "石", "is_correct": false, "explanation": "石は固体で、熱せられた生地と共に膨らむ働きがないので文に合わない。"}, {"text": "土", "is_correct": false, "explanation": "土は焼成中に生地と共に膨張する気体ではないので、この空所には入らない。"}], "explanations": {"蒸気": "水が沸騰してできた気体で、「高温の〜と共に膨張した」という文脈に合う。", "氷": "氷は低温の固体なので、「高温の」と矛盾し、生地と共に膨張する気体にもならない。", "石": "石は固体で、熱せられた生地と共に膨らむ働きがないので文に合わない。", "土": "土は焼成中に生地と共に膨張する気体ではないので、この空所には入らない。"}, "sentence_index": 0, "correct_answer": "蒸気"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "梅雨の蒸気で、洗濯物がなかなか乾かない。", "explanation": "ここは〈湿気〉の意味。空気中の水分の多さを指し、熱して出る蒸気とは別物なので合わない。"}, {"text": "マラソンのあと、額に蒸気がにじんでいた。", "explanation": "ここは〈汗〉の意味。皮膚からにじむのは汗で、蒸気は人の体からにじみ出るものではない。"}, {"text": "試合の終盤、観客の蒸気が会場を包んだ。", "explanation": "ここは〈熱気〉の意味。人の盛り上がりや意気込みを指すので、水の気体である蒸気とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '756040c1-37ff-47fa-8b7d-9c1d20b9a3a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39513, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "蒸気", "is_correct": true, "explanation": "水が気体になったもので、冷やされると水にもどる性質に合う。"}, {"text": "砂", "is_correct": false, "explanation": "砂は冷やされても水にはもどらないので、文の内容に合わない。"}, {"text": "木", "is_correct": false, "explanation": "木は冷やされても水にはならないので、この文の主語として合わない。"}, {"text": "油", "is_correct": false, "explanation": "油は冷えても水にはもどらず、固まったり粘り気が増したりするだけなので合わない。"}], "explanations": {"蒸気": "水が気体になったもので、冷やされると水にもどる性質に合う。", "砂": "砂は冷やされても水にはもどらないので、文の内容に合わない。", "木": "木は冷やされても水にはならないので、この文の主語として合わない。", "油": "油は冷えても水にはもどらず、固まったり粘り気が増したりするだけなので合わない。"}, "sentence_index": 6, "correct_answer": "蒸気"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "朝から蒸気が降り続いていた。", "explanation": "ここは〈霧雨〉の意味。降るのは細かい雨粒で、水の気体である蒸気は降るものではない。"}, {"text": "ポットに蒸気を注いだ。", "explanation": "ここは〈湯〉の意味。注ぐのは液体の湯で、気体の蒸気は注げない。"}, {"text": "冬の朝、窓の外側に蒸気がおりていた。", "explanation": "ここは〈霜〉の意味。窓などに固まってつくのが霜で、蒸気が『おりる』とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '756040c1-37ff-47fa-8b7d-9c1d20b9a3a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39513, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "電子レンジの中から蒸気を出て、ふきんが湿った。", "corrected_sentence": "電子レンジの中から蒸気が出て、ふきんが湿った。", "error_description": "『出る』は自動詞なので、動作の主体を『が』で示す。『蒸気を』は他動詞の目的語を表す助詞で誤り。正しくは『蒸気が出て』。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '756040c1-37ff-47fa-8b7d-9c1d20b9a3a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39513, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "鍋から蒸気が立ちのぼらて、キッチンが暑くなった。", "corrected_sentence": "鍋から蒸気が立ちのぼって、キッチンが暑くなった。", "error_description": "『立ちのぼる』は五段活用なので、て形は『立ちのぼって』になる。『立ちのぼらて』は活用の誤りで、『蒸気が』に続く動詞の形が崩れている。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '756040c1-37ff-47fa-8b7d-9c1d20b9a3a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39514, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「出現」の直後に置いて、「ライバルの出現」を主題にする。"}, {"text": "を", "is_correct": false, "explanation": "目的語の「を」は、「なった」で結ぶ文に合わない。「出現を、」と続けても文が成立しない。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」は、出現という出来事には続かず、文に合わない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は後に名詞が続く形で、「出現の、」とは続かない。"}], "correct_answer": "は", "explanations": {"は": "「出現」の直後に置いて、「ライバルの出現」を主題にする。", "を": "目的語の「を」は、「なった」で結ぶ文に合わない。「出現を、」と続けても文が成立しない。", "へ": "方向の「へ」は、出現という出来事には続かず、文に合わない。", "の": "「の」は後に名詞が続く形で、「出現の、」とは続かない。"}, "error_tags": {"を": "目的語", "へ": "方向", "の": "連体修飾"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "消滅", "is_correct": true, "explanation": "存在しなかったものが新たに現れる意味の反対で、見えなくなること。出現の対義語として辞書に挙がる。"}, {"text": "出発", "is_correct": false, "explanation": "場所を離れる意味。現れることの反対語ではなく、対義語として挙がらない。"}, {"text": "継続", "is_correct": false, "explanation": "続くこと。出現の反対語ではない。"}, {"text": "残存", "is_correct": false, "explanation": "後に残ること。出現の反対語とは言えない。"}], "correct_answer": "消滅", "explanations": {"消滅": "存在しなかったものが新たに現れる意味の反対で、見えなくなること。出現の対義語として辞書に挙がる。", "出発": "場所を離れる意味。現れることの反対語ではなく、対義語として挙がらない。", "継続": "続くこと。出現の反対語ではない。", "残存": "後に残ること。出現の反対語とは言えない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f111902-c57f-40b5-8d46-9239e1a44017') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39514, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "消滅", "is_correct": true, "explanation": "存在しなかったものが新たに現れる意味の反対で、見えなくなること。出現の対義語として辞書に挙がる。"}, {"text": "帰還", "is_correct": false, "explanation": "元の場所に戻ること。現れることの反対語ではない。"}, {"text": "発見", "is_correct": false, "explanation": "見つけ出すこと。現れる意味の反対語ではなく、対義語として挙がらない。"}, {"text": "開始", "is_correct": false, "explanation": "始まること。出現の反対語ではない。"}], "correct_answer": "消滅", "explanations": {"消滅": "存在しなかったものが新たに現れる意味の反対で、見えなくなること。出現の対義語として辞書に挙がる。", "帰還": "元の場所に戻ること。現れることの反対語ではない。", "発見": "見つけ出すこと。現れる意味の反対語ではなく、対義語として挙がらない。", "開始": "始まること。出現の反対語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f111902-c57f-40b5-8d46-9239e1a44017') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39514, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "何かが新しく現れること。", "primary_collocate": null, "pronunciation": "しゅつげん", "ipa": "ɕutsɯɡeɴ", "syllable_count": 4, "sentences": [{"text": "新しい店の出現で、町の人通りが増えた。", "target_word": "出現", "complexity_tier": "T3", "furigana": "新[あたら]しい店[みせ]の出現[しゅつげん]で、町[まち]の人通[ひとどお]りが増[ふ]えた。", "sentence_source": "generated"}, {"text": "ライバルの出現は、彼にとって良い刺激になった。", "target_word": "出現", "complexity_tier": "T3", "furigana": "ライバルの出現[しゅつげん]は、彼[かれ]にとって良[よ]い刺激[しげき]になった。", "sentence_source": "generated"}, {"text": "スマートフォンの出現が、人々の生活を変えた。", "target_word": "出現", "complexity_tier": "T3", "furigana": "スマートフォンの出現[しゅつげん]が、人々[ひとびと]の生活[せいかつ]を変[か]えた。", "sentence_source": "generated"}, {"text": "森にクマが出現したため、山道は閉鎖された。", "target_word": "出現", "complexity_tier": "T3", "furigana": "森[もり]にクマが出現[しゅつげん]したため、山道[やまみち]は閉鎖[へいさ]された。", "sentence_source": "generated"}, {"text": "新しい星の出現を、天文学者は観測で確認した。", "target_word": "出現", "complexity_tier": "T3", "furigana": "新[あたら]しい星[ほし]の出現[しゅつげん]を、天文学者[てんもんがくしゃ]は観測[かんそく]で確認[かくにん]した。", "sentence_source": "generated"}, {"text": "突然の雨雲の出現に、運動会は中止になった。", "target_word": "出現", "complexity_tier": "T3", "furigana": "突然[とつぜん]の雨雲[あまぐも]の出現[しゅつげん]に、運動会[うんどうかい]は中止[ちゅうし]になった。", "sentence_source": "generated"}, {"text": "強い選手の出現で、チームは優勝を狙えるようになった。", "target_word": "出現", "complexity_tier": "T3", "furigana": "強[つよ]い選手[せんしゅ]の出現[しゅつげん]で、チームは優勝[ゆうしょう]を狙[ねら]えるようになった。", "sentence_source": "generated"}, {"text": "空に不思議な光が出現して、みんな驚いた。", "target_word": "出現", "complexity_tier": "T3", "furigana": "空[そら]に不思議[ふしぎ]な光[ひかり]が出現[しゅつげん]して、みんな驚[おどろ]いた。", "sentence_source": "generated"}, {"text": "新しい薬の出現を、患者たちは待ち望んでいた。", "target_word": "出現", "complexity_tier": "T3", "furigana": "新[あたら]しい薬[くすり]の出現[しゅつげん]を、患者[かんじゃ]たちは待[ま]ち望[のぞ]んでいた。", "sentence_source": "generated"}, {"text": "ゲームの中でボスが出現すると、音楽が変わる。", "target_word": "出現", "complexity_tier": "T3", "furigana": "ゲームの中[なか]でボスが出現[しゅつげん]すると、音楽[おんがく]が変[か]わる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "出現", "label": "基本形"}, {"form": "出現する", "label": "サ変動詞形"}, {"form": "出現した", "label": "過去形"}, {"form": "出現の", "label": "名詞＋の"}], "register": "neutral", "sense_fingerprint": "人や物が新たに姿を現すこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6541566-104a-41c9-9aa1-ddb22492a21a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39514, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "出現", "is_correct": true, "explanation": "新しい店が現れたことを表す名詞で、「〜の出現で、人通りが増えた」という原因の文に合う。"}, {"text": "解散", "is_correct": false, "explanation": "「解散」は集まりが別れること。新しい店には使えず、人通りが増える理由として合わない。"}, {"text": "紛失", "is_correct": false, "explanation": "持ち物をなくすこと。店には使えず、人通りの増加とも結びつかない。"}, {"text": "返却", "is_correct": false, "explanation": "借りた物を返すこと。新しい店には使えず、文の意味に合わない。"}], "explanations": {"出現": "新しい店が現れたことを表す名詞で、「〜の出現で、人通りが増えた」という原因の文に合う。", "解散": "「解散」は集まりが別れること。新しい店には使えず、人通りが増える理由として合わない。", "紛失": "持ち物をなくすこと。店には使えず、人通りの増加とも結びつかない。", "返却": "借りた物を返すこと。新しい店には使えず、文の意味に合わない。"}, "sentence_index": 0, "correct_answer": "出現"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "町の中心部で、大きな火事が出現した。", "explanation": "ここは〈発生〉の意味。出現は姿や存在が新たに現れることに使い、火事や事故が起きる場面では使わない。"}, {"text": "古いエアコンが出現して、部屋がとても暑くなった。", "explanation": "ここは〈故障〉の意味。出現は今までなかったものが現れることで、機械が壊れる場合には使わない。"}, {"text": "鍋のお湯が出現したので、火を止めた。", "explanation": "ここは〈沸く〉の意味。出現は、液体が熱で泡立つことには使わず、お湯が沸く場面に合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f111902-c57f-40b5-8d46-9239e1a44017') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39514, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "出現", "is_correct": true, "explanation": "強い選手が新たに現れたことを表し、「優勝を狙えるようになった」という結果の文に合う。"}, {"text": "返品", "is_correct": false, "explanation": "買った物を返すこと。選手には使えず、文の意味に合わない。"}, {"text": "拒否", "is_correct": false, "explanation": "断ること。選手の存在とは結びつかず、チームが優勝を狙える理由にならない。"}, {"text": "漏洩", "is_correct": false, "explanation": "情報が外に漏れること。選手には使えず、文に合わない。"}], "explanations": {"出現": "強い選手が新たに現れたことを表し、「優勝を狙えるようになった」という結果の文に合う。", "返品": "買った物を返すこと。選手には使えず、文の意味に合わない。", "拒否": "断ること。選手の存在とは結びつかず、チームが優勝を狙える理由にならない。", "漏洩": "情報が外に漏れること。選手には使えず、文に合わない。"}, "sentence_index": 6, "correct_answer": "出現"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "電池が出現すると、画面が消える。", "explanation": "ここは〈切れる〉の意味。出現は今までなかったものが新たに現れることで、電池が尽きる場合には使わない。"}, {"text": "強風で棚が出現すると、中の物が散らばる。", "explanation": "ここは〈倒れる〉の意味。出現は新しく現れることで、物が倒れて崩れる場面には合わない。"}, {"text": "洗濯物が出現すると、いい匂いがする。", "explanation": "ここは〈乾く〉の意味。出現は現れることで、洗濯物が乾いて匂いがする状態には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f111902-c57f-40b5-8d46-9239e1a44017') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39514, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "町に新しい店が出現しで、人通りが増えた。", "corrected_sentence": "町に新しい店が出現して、人通りが増えた。", "error_description": "サ変動詞「出現する」のて形は「出現して」。「出現しで」は誤った形で、正しくは「出現して」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f111902-c57f-40b5-8d46-9239e1a44017') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39514, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "森の奥に、珍しい鳥が出現しった。", "corrected_sentence": "森の奥に、珍しい鳥が出現した。", "error_description": "過去形の誤り。「出現しった」は促音が入った誤った形で、正しくは「出現した」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f111902-c57f-40b5-8d46-9239e1a44017') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
