INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39515, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「出現」の直後に置いて、「新しい言葉の出現」を主題にする。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列を示すが、「出現と、社会の変化を表している」では並んだ語の役割が定まらず、文が不自然。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較の基準を示すが、「出現より、社会の変化を表している」は比べる相手がなく、文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すが、「出現へ、社会の変化を表している」は方向の意味が立たず不自然。"}], "correct_answer": "は", "explanations": {"は": "「出現」の直後に置いて、「新しい言葉の出現」を主題にする。", "と": "「と」は並列を示すが、「出現と、社会の変化を表している」では並んだ語の役割が定まらず、文が不自然。", "より": "「より」は比較の基準を示すが、「出現より、社会の変化を表している」は比べる相手がなく、文が成り立たない。", "へ": "「へ」は方向を示すが、「出現へ、社会の変化を表している」は方向の意味が立たず不自然。"}, "error_tags": {"と": "並列", "より": "比較", "へ": "方向"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "消滅", "is_correct": true, "explanation": "存在しなかったものが新たに現れる意味の反対で、見えなくなること。出現の対義語として辞書に挙がる。"}, {"text": "帰還", "is_correct": false, "explanation": "元の場所に戻ること。現れることの反対語ではない。"}, {"text": "発見", "is_correct": false, "explanation": "見つけ出すこと。現れる意味の反対語ではなく、対義語として挙がらない。"}, {"text": "開始", "is_correct": false, "explanation": "始まること。出現の反対語ではない。"}], "correct_answer": "消滅", "explanations": {"消滅": "存在しなかったものが新たに現れる意味の反対で、見えなくなること。出現の対義語として辞書に挙がる。", "帰還": "元の場所に戻ること。現れることの反対語ではない。", "発見": "見つけ出すこと。現れる意味の反対語ではなく、対義語として挙がらない。", "開始": "始まること。出現の反対語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f111902-c57f-40b5-8d46-9239e1a44017') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39515, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "今までなかったものが現れること。", "primary_collocate": null, "pronunciation": "しゅつげん", "ipa": "ɕutsɯɡeɴ", "syllable_count": 4, "sentences": [{"text": "インターネットの出現で、情報の集め方が大きく変わった。", "target_word": "出現", "complexity_tier": "T3", "furigana": "インターネットの出現[しゅつげん]で、情報[じょうほう]の集[あつ]め方[かた]が大[おお]きく変[か]わった。", "sentence_source": "generated"}, {"text": "新型のロボットの出現に、会場がざわついた。", "target_word": "出現", "complexity_tier": "T3", "furigana": "新型[しんがた]のロボットの出現[しゅつげん]に、会場[かいじょう]がざわついた。", "sentence_source": "generated"}, {"text": "町に大きな駅ビルが出現して、景色が一変した。", "target_word": "出現", "complexity_tier": "T3", "furigana": "町[まち]に大[おお]きな駅[えき]ビルが出現[しゅつげん]して、景色[けしき]が一変[いっぺん]した。", "sentence_source": "generated"}, {"text": "砂漠に突然、緑の島が出現したかのようだった。", "target_word": "出現", "complexity_tier": "T3", "furigana": "砂漠[さばく]に突然[とつぜん]、緑[みどり]の島[しま]が出現[しゅつげん]したかのようだった。", "sentence_source": "generated"}, {"text": "画期的な発明の出現が、産業を変えた。", "target_word": "出現", "complexity_tier": "T3", "furigana": "画期的[かっきてき]な発明[はつめい]の出現[しゅつげん]が、産業[さんぎょう]を変[か]えた。", "sentence_source": "generated"}, {"text": "見たことのない虫が庭に出現して、母が悲鳴を上げた。", "target_word": "出現", "complexity_tier": "T3", "furigana": "見[み]たことのない虫[むし]が庭[にわ]に出現[しゅつげん]して、母[はは]が悲鳴[ひめい]を上[あ]げた。", "sentence_source": "generated"}, {"text": "天才画家の出現を、美術界は待っていた。", "target_word": "出現", "complexity_tier": "T3", "furigana": "天才[てんさい]画家[がか]の出現[しゅつげん]を、美術界[びじゅつかい]は待[ま]っていた。", "sentence_source": "generated"}, {"text": "新しい言葉の出現は、社会の変化を表している。", "target_word": "出現", "complexity_tier": "T3", "furigana": "新[あたら]しい言葉[ことば]の出現[しゅつげん]は、社会[しゃかい]の変化[へんか]を表[あらわ]している。", "sentence_source": "generated"}, {"text": "大雨の後、川の中に今までなかった小島が出現し、調査が始まった。", "target_word": "出現", "complexity_tier": "T3", "furigana": "大雨[おおあめ]の後[あと]、川[かわ]の中[なか]に今[いま]までなかった小島[こじま]が出現[しゅつげん]し、調査[ちょうさ]が始[はじ]まった。", "sentence_source": "generated"}, {"text": "新しいルールの出現で、試合の進め方が変わった。", "target_word": "出現", "complexity_tier": "T3", "furigana": "新[あたら]しいルールの出現[しゅつげん]で、試合[しあい]の進[すす]め方[かた]が変[か]わった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "出現", "label": "基本形"}, {"form": "出現する", "label": "サ変動詞形"}, {"form": "出現した", "label": "過去形"}, {"form": "出現の", "label": "名詞＋の"}], "register": "neutral", "sense_fingerprint": "これまでなかったものが初めて現れること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 1 above tier T2: contains vocabulary far above tier T2: ざわつい (Zipf 2.35)']::text[], 'a6541566-104a-41c9-9aa1-ddb22492a21a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39515, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "出現", "is_correct": true, "explanation": "今までなかったものが現れたことを表し、「情報の集め方が大きく変わった」という原因の文に合う。"}, {"text": "悲鳴", "is_correct": false, "explanation": "叫び声のこと。インターネットには使えず、情報の集め方を変える理由にならない。"}, {"text": "落胆", "is_correct": false, "explanation": "がっかりすること。インターネットの説明として成り立たない。"}, {"text": "寝坊", "is_correct": false, "explanation": "起きるのが遅れること。インターネットには使えず、文の意味に合わない。"}], "explanations": {"出現": "今までなかったものが現れたことを表し、「情報の集め方が大きく変わった」という原因の文に合う。", "悲鳴": "叫び声のこと。インターネットには使えず、情報の集め方を変える理由にならない。", "落胆": "がっかりすること。インターネットの説明として成り立たない。", "寝坊": "起きるのが遅れること。インターネットには使えず、文の意味に合わない。"}, "sentence_index": 0, "correct_answer": "出現"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "洗濯物が出現したので、取り込んだ。", "explanation": "ここは〈乾く〉の意味。出現は今までなかったものが現れることで、洗濯物が乾く場面には使わない。"}, {"text": "コップが出現して、手を切った。", "explanation": "ここは〈割れる〉の意味。出現は新しく現れることで、物が壊れて破片になる場面には使わない。"}, {"text": "昔からある神社が、今年も出現した。", "explanation": "ここは〈存在する〉の意味。出現は今までなかったものが新たに現れることなので、昔から存在するものには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f111902-c57f-40b5-8d46-9239e1a44017') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39515, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "出現", "is_correct": true, "explanation": "天才画家が新たに現れることを表し、「待っていた」の対象として合う。"}, {"text": "停電", "is_correct": false, "explanation": "電気が止まること。画家には使えず、待つ対象として成り立たない。"}, {"text": "台風", "is_correct": false, "explanation": "強い低気圧のこと。人には使えず、文の意味に合わない。"}, {"text": "乾燥", "is_correct": false, "explanation": "水分が失われること。画家には使えず、文に合わない。"}], "explanations": {"出現": "天才画家が新たに現れることを表し、「待っていた」の対象として合う。", "停電": "電気が止まること。画家には使えず、待つ対象として成り立たない。", "台風": "強い低気圧のこと。人には使えず、文の意味に合わない。", "乾燥": "水分が失われること。画家には使えず、文に合わない。"}, "sentence_index": 6, "correct_answer": "出現"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "パンが出現して、苦い味がした。", "explanation": "ここは〈焦げる〉の意味。出現は新たに現れることで、焼き物が焦げる場合には使わない。"}, {"text": "雨で服が出現して、風邪をひいた。", "explanation": "ここは〈濡れる〉の意味。出現は現れることで、水に濡れる状態には使わない。"}, {"text": "冷蔵庫に入れた牛乳が出現して、酸っぱい臭いがした。", "explanation": "ここは〈腐る〉の意味。出現は新たに現れることで、食べ物が傷んで酸っぱくなる変化には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f111902-c57f-40b5-8d46-9239e1a44017') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39515, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "新しい機械が出現を、工場の仕事が変わった。", "corrected_sentence": "新しい機械が出現して、工場の仕事が変わった。", "error_description": "出現は自動詞なので目的語の「を」を取れない。正しくは「出現して」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f111902-c57f-40b5-8d46-9239e1a44017') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39515, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "町の空に大きな虹が出現された。", "corrected_sentence": "町の空に大きな虹が出現した。", "error_description": "出現は自動詞なので受身「出現された」にはできない。正しくは「出現した」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f111902-c57f-40b5-8d46-9239e1a44017') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39516, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「プロに匹敵する」で、比べる相手を示す「に」。"}, {"text": "を", "is_correct": false, "explanation": "「プロを匹敵する」は成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「プロへ匹敵する」は方向の意味にならない。"}, {"text": "で", "is_correct": false, "explanation": "「プロで匹敵する」は手段の意味にならない。"}], "correct_answer": "に", "explanations": {"に": "「プロに匹敵する」で、比べる相手を示す「に」。", "を": "「プロを匹敵する」は成り立たない。", "へ": "「プロへ匹敵する」は方向の意味にならない。", "で": "「プロで匹敵する」は手段の意味にならない。"}, "error_tags": {"を": "object_marker", "へ": "direction", "で": "means_location"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca5920d4-ba89-425c-8b4e-47cfa4b9d998') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39516, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「小さなパソコンに匹敵する」で、比べる相手を示す「に」。"}, {"text": "から", "is_correct": false, "explanation": "「パソコンから匹敵する」は起点の意味になり、成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "「パソコンより匹敵する」は比較の形で、この文に合わない。"}, {"text": "の", "is_correct": false, "explanation": "「パソコンの匹敵する」は名詞修飾にならない。"}], "correct_answer": "に", "explanations": {"に": "「小さなパソコンに匹敵する」で、比べる相手を示す「に」。", "から": "「パソコンから匹敵する」は起点の意味になり、成り立たない。", "より": "「パソコンより匹敵する」は比較の形で、この文に合わない。", "の": "「パソコンの匹敵する」は名詞修飾にならない。"}, "error_tags": {"から": "source", "より": "comparison", "の": "attributive"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca5920d4-ba89-425c-8b4e-47cfa4b9d998') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39516, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "他のものと同じくらい、とてもよく似ていること。", "primary_collocate": null, "pronunciation": "ひってき", "ipa": "çitːeki", "syllable_count": 4, "sentences": [{"text": "この小さな店のパンの味は、有名な店のパンに匹敵する。", "target_word": "匹敵する", "complexity_tier": "T3", "furigana": "この小[ちい]さな店[みせ]のパンの味[あじ]は、有名[ゆうめい]な店[みせ]のパンに匹敵[ひってき]する。", "sentence_source": "generated"}, {"text": "彼のピアノの腕前は、プロに匹敵する。", "target_word": "匹敵", "complexity_tier": "T3", "furigana": "彼[かれ]のピアノの腕前[うでまえ]は、プロに匹敵[ひってき]する。", "sentence_source": "generated"}, {"text": "新しい店のカレーは、有名なレストランの味に匹敵するおいしさだ。", "target_word": "匹敵", "complexity_tier": "T4", "furigana": "新[あたら]しい店[みせ]のカレーは、有名[ゆうめい]なレストランの味[あじ]に匹敵[ひってき]するおいしさだ。", "sentence_source": "generated"}, {"text": "この犬の足の速さは、人間の選手に匹敵すると言われている。", "target_word": "匹敵", "complexity_tier": "T4", "furigana": "この犬[いぬ]の足[あし]の速[はや]さは、人間[にんげん]の選手[せんしゅ]に匹敵[ひってき]すると言[い]われている。", "sentence_source": "generated"}, {"text": "彼女の語学力は、通訳者に匹敵するほどだ。", "target_word": "匹敵", "complexity_tier": "T3", "furigana": "彼女[かのじょ]の語学力[ごがくりょく]は、通訳者[つうやくしゃ]に匹敵[ひってき]するほどだ。", "sentence_source": "generated"}, {"text": "この湖の広さは、東京の一つの区に匹敵する。", "target_word": "匹敵", "complexity_tier": "T3", "furigana": "この湖[みずうみ]の広[ひろ]さは、東京[とうきょう]の一[ひと]つの区[く]に匹敵[ひってき]する。", "sentence_source": "generated"}, {"text": "彼の集中力に匹敵する人は、クラスにいない。", "target_word": "匹敵", "complexity_tier": "T3", "furigana": "彼[かれ]の集中力[しゅうちゅうりょく]に匹敵[ひってき]する人[ひと]は、クラスにいない。", "sentence_source": "generated"}, {"text": "このスマートフォンの性能は、小さなパソコンに匹敵する。", "target_word": "匹敵", "complexity_tier": "T4", "furigana": "このスマートフォンの性能[せいのう]は、小[ちい]さなパソコンに匹敵[ひってき]する。", "sentence_source": "generated"}, {"text": "一日の雨の量が、ふつうの一か月分に匹敵した。", "target_word": "匹敵", "complexity_tier": "T4", "furigana": "一日[いちにち]の雨[あめ]の量[りょう]が、ふつうの一[いっ]か月分[げつぶん]に匹敵[ひってき]した。", "sentence_source": "generated"}, {"text": "その絵の価値は、家一軒の値段に匹敵するそうだ。", "target_word": "匹敵", "complexity_tier": "T4", "furigana": "その絵[え]の価値[かち]は、家[いえ]一軒[いっけん]の値段[ねだん]に匹敵[ひってき]するそうだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "匹敵する", "label": "辞書形"}, {"form": "匹敵した", "label": "過去形"}, {"form": "匹敵しない", "label": "否定形"}, {"form": "匹敵して", "label": "て形"}], "register": "中立", "sense_fingerprint": "ある物事が程度や価値で別のものと並ぶほどであること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '989c883e-1f67-4ecd-80a7-ae7c0f0d1e3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39516, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "匹敵する", "is_correct": true, "explanation": "「有名な店のパンに匹敵する」で、同じくらいの味だという意味を表す。"}, {"text": "焼く", "is_correct": false, "explanation": "焼くは加熱する動作で、「に」の後に続いても同等の意味にならない。"}, {"text": "洗う", "is_correct": false, "explanation": "洗うは汚れを落とす動作で、味の比較には合わない。"}, {"text": "踏む", "is_correct": false, "explanation": "踏むは足で押す動作で、同等の意味にならない。"}], "explanations": {"匹敵する": "「有名な店のパンに匹敵する」で、同じくらいの味だという意味を表す。", "焼く": "焼くは加熱する動作で、「に」の後に続いても同等の意味にならない。", "洗う": "洗うは汚れを落とす動作で、味の比較には合わない。", "踏む": "踏むは足で押す動作で、同等の意味にならない。"}, "sentence_index": 0, "correct_answer": "匹敵する"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この店のパンは有名店に匹敵するほど固くて、まずい。", "explanation": "匹敵に〈劣る〉の意味はなく、「まずい」と組むと同等の評価と低評価が両立しない。"}, {"text": "この選手の記録は、前の記録に匹敵するほど大きく上回った。", "explanation": "匹敵に〈上回る〉の意味はなく、「大きく上回った」は同等を表す語と矛盾する。"}, {"text": "決勝でライバルに匹敵して、優勝を決めた。", "explanation": "匹敵に〈勝つ〉の意味はなく、勝敗の結果は同等を表す語では表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca5920d4-ba89-425c-8b4e-47cfa4b9d998') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39516, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "匹敵", "is_correct": true, "explanation": "「集中力に匹敵する人」で、同じくらいの集中力を指す。"}, {"text": "焦り", "is_correct": false, "explanation": "焦りは気持ちの状態で、集中力に並ぶ意味にはならない。"}, {"text": "眠り", "is_correct": false, "explanation": "眠りは休息の状態で、比べる文脈に合わない。"}, {"text": "煮え", "is_correct": false, "explanation": "煮えは加熱の状態で、集中力には合わない。"}], "explanations": {"匹敵": "「集中力に匹敵する人」で、同じくらいの集中力を指す。", "焦り": "焦りは気持ちの状態で、集中力に並ぶ意味にはならない。", "眠り": "眠りは休息の状態で、比べる文脈に合わない。", "煮え": "煮えは加熱の状態で、集中力には合わない。"}, "sentence_index": 6, "correct_answer": "匹敵"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "その絵の価値は、家一軒の値段に匹敵するほど低いそうだ。", "explanation": "匹敵に〈低い〉の意味はなく、「匹敵するほど低い」は同等と低評価が矛盾する。"}, {"text": "その絵と家一軒を値段で匹敵させて、どちらが高いか比べてみた。", "explanation": "匹敵に〈比べる〉の意味はなく、「匹敵させて比べる」は同等を作る語義と合わない。"}, {"text": "その絵は、家一軒の値段に匹敵して、一晩で値が下がった。", "explanation": "匹敵に〈下がる〉の意味はなく、同等を表す語では値の下落は表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca5920d4-ba89-425c-8b4e-47cfa4b9d998') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39516, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この歌手の声量は、オペラ歌手を匹敵する。", "corrected_sentence": "この歌手の声量は、オペラ歌手に匹敵する。", "error_description": "匹敵は「〜に匹敵する」と「に」を取る。「を」は誤りで、正しくは「に」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca5920d4-ba89-425c-8b4e-47cfa4b9d998') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39516, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この部品の精度は、高級品に匹敵さない。", "corrected_sentence": "この部品の精度は、高級品に匹敵しない。", "error_description": "「匹敵する」の否定形は「匹敵しない」。サ変の「する」は「さ」に変えないため、「匹敵さない」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca5920d4-ba89-425c-8b4e-47cfa4b9d998') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39517, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "主語を示す格助詞。「両チームの力が」で、「力」が「匹敵している」の主語になる。"}, {"text": "を", "is_correct": false, "explanation": "対象を示すが、「力を匹敵している」では述語が主語を取れず、文が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を示すが、「力で匹敵している」では意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示すが、「力へ匹敵している」は不自然で文に合わない。"}], "correct_answer": "が", "explanations": {"が": "主語を示す格助詞。「両チームの力が」で、「力」が「匹敵している」の主語になる。", "を": "対象を示すが、「力を匹敵している」では述語が主語を取れず、文が成り立たない。", "で": "手段や場所を示すが、「力で匹敵している」では意味が通らない。", "へ": "方向を示すが、「力へ匹敵している」は不自然で文に合わない。"}, "error_tags": {"を": "対象", "で": "手段", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca5920d4-ba89-425c-8b4e-47cfa4b9d998') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39517, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "主語を示す格助詞。「どちらの案も価値が」で、「価値」が「匹敵していて」の主語になる。"}, {"text": "から", "is_correct": false, "explanation": "起点を示すが、「価値から匹敵していて」では主語を示せず、文が成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "比較の基準を示すが、「価値より匹敵していて」では同じ程度を表す述語と合わない。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾を示すが、「価値の匹敵していて」では述語が文に立たず不自然。"}], "correct_answer": "が", "explanations": {"が": "主語を示す格助詞。「どちらの案も価値が」で、「価値」が「匹敵していて」の主語になる。", "から": "起点を示すが、「価値から匹敵していて」では主語を示せず、文が成り立たない。", "より": "比較の基準を示すが、「価値より匹敵していて」では同じ程度を表す述語と合わない。", "の": "連体修飾を示すが、「価値の匹敵していて」では述語が文に立たず不自然。"}, "error_tags": {"から": "起点", "より": "比較", "の": "連体"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca5920d4-ba89-425c-8b4e-47cfa4b9d998') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39517, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "二つのものが互いに優劣なく、同じ程度の力や価値を持つこと。比べ合って、どちらも負けないこと。", "primary_collocate": null, "pronunciation": "ひってき", "ipa": "çitːeki", "syllable_count": 4, "sentences": [{"text": "二人の選手の実力は匹敵していて、試合はなかなか終わらなかった。", "target_word": "匹敵", "complexity_tier": "T4", "furigana": "二人[ふたり]の選手[せんしゅ]の実力[じつりょく]は匹敵[ひってき]していて、試合[しあい]はなかなか終[お]わらなかった。", "sentence_source": "generated"}, {"text": "両チームの力が匹敵しているので、どちらが勝つかわからない。", "target_word": "匹敵", "complexity_tier": "T3", "furigana": "両[りょう]チームの力[ちから]が匹敵[ひってき]しているので、どちらが勝[か]つかわからない。", "sentence_source": "generated"}, {"text": "二つの会社の技術力は匹敵し、競争が激しくなっている。", "target_word": "匹敵", "complexity_tier": "T4", "furigana": "二[ふた]つの会社[かいしゃ]の技術力[ぎじゅつりょく]は匹敵[ひってき]し、競争[きょうそう]が激[はげ]しくなっている。", "sentence_source": "generated"}, {"text": "兄と弟は走る速さが匹敵していて、いつも同じ順位になる。", "target_word": "匹敵", "complexity_tier": "T3", "furigana": "兄[あに]と弟[おとうと]は走[はし]る速[はや]さが匹敵[ひってき]していて、いつも同[おな]じ順位[じゅんい]になる。", "sentence_source": "generated"}, {"text": "二人の学力は匹敵するため、先生も成績をつけるのに迷った。", "target_word": "匹敵", "complexity_tier": "T4", "furigana": "二人[ふたり]の学力[がくりょく]は匹敵[ひってき]するため、先生[せんせい]も成績[せいせき]をつけるのに迷[まよ]った。", "sentence_source": "generated"}, {"text": "力が匹敵する相手と戦うと、いい勉強になる。", "target_word": "匹敵", "complexity_tier": "T3", "furigana": "力[ちから]が匹敵[ひってき]する相手[あいて]と戦[たたか]うと、いい勉強[べんきょう]になる。", "sentence_source": "generated"}, {"text": "双子の姉妹は、歌のうまさが互いに匹敵している。", "target_word": "匹敵", "complexity_tier": "T3", "furigana": "双子[ふたご]の姉妹[しまい]は、歌[うた]のうまさが互[たが]いに匹敵[ひってき]している。", "sentence_source": "generated"}, {"text": "どちらの案も価値が匹敵していて、決めるのが難しい。", "target_word": "匹敵", "complexity_tier": "T4", "furigana": "どちらの案[あん]も価値[かち]が匹敵[ひってき]していて、決[き]めるのが難[むずか]しい。", "sentence_source": "generated"}, {"text": "両国の経済力は匹敵しており、どちらも相手に負けない。", "target_word": "匹敵", "complexity_tier": "T4", "furigana": "両国[りょうこく]の経済力[けいざいりょく]は匹敵[ひってき]しており、どちらも相手[あいて]に負[ま]けない。", "sentence_source": "generated"}, {"text": "力が匹敵するライバルがいるから、毎日練習をがんばれる。", "target_word": "匹敵", "complexity_tier": "T3", "furigana": "力[ちから]が匹敵[ひってき]するライバルがいるから、毎日[まいにち]練習[れんしゅう]をがんばれる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "匹敵する", "label": "辞書形"}, {"form": "匹敵した", "label": "過去形"}, {"form": "匹敵している", "label": "進行・状態"}, {"form": "匹敵しない", "label": "否定形"}], "register": "中立", "sense_fingerprint": "二者の力や価値が互角で、どちらも負けないこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '989c883e-1f67-4ecd-80a7-ae7c0f0d1e3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39517, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "匹敵", "is_correct": true, "explanation": "「匹敵している」の形で、二人の実力が同じ程度であることを表す。"}, {"text": "転嫁", "is_correct": false, "explanation": "責任や費用を他に移す意味で、実力の比べ方には使わない。"}, {"text": "反発", "is_correct": false, "explanation": "互いに押し返す意味で、同じ程度の実力という文脈に合わない。"}, {"text": "撤回", "is_correct": false, "explanation": "言ったことを取り消す意味で、実力の話には合わない。"}], "explanations": {"匹敵": "「匹敵している」の形で、二人の実力が同じ程度であることを表す。", "転嫁": "責任や費用を他に移す意味で、実力の比べ方には使わない。", "反発": "互いに押し返す意味で、同じ程度の実力という文脈に合わない。", "撤回": "言ったことを取り消す意味で、実力の話には合わない。"}, "sentence_index": 0, "correct_answer": "匹敵"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "新製品は前作の性能に大きく匹敵した。", "explanation": "匹敵に〈凌駕〉の意味はなく、「大きく」と組むと同等の意味と矛盾する。"}, {"text": "チームは対戦相手に大差で匹敵した。", "explanation": "匹敵に〈勝つ〉の意味はなく、「大差」は同等を表す語と両立しない。"}, {"text": "この製品は高価な製品に比べて性能がずっと匹敵する。", "explanation": "匹敵に〈劣る〉の意味はなく、「ずっと匹敵する」は同等を表す語として矛盾する。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca5920d4-ba89-425c-8b4e-47cfa4b9d998') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39517, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "匹敵", "is_correct": true, "explanation": "「互いに匹敵している」で、歌のうまさが同じ程度であることを表す。"}, {"text": "迎合", "is_correct": false, "explanation": "相手に合わせて機嫌をとる意味で、能力の比較には合わない。"}, {"text": "隔離", "is_correct": false, "explanation": "人や物を切り離す意味で、同じ程度という文脈に合わない。"}, {"text": "謝罪", "is_correct": false, "explanation": "過ちをわびる意味で、歌のうまさの話には合わない。"}], "explanations": {"匹敵": "「互いに匹敵している」で、歌のうまさが同じ程度であることを表す。", "迎合": "相手に合わせて機嫌をとる意味で、能力の比較には合わない。", "隔離": "人や物を切り離す意味で、同じ程度という文脈に合わない。", "謝罪": "過ちをわびる意味で、歌のうまさの話には合わない。"}, "sentence_index": 6, "correct_answer": "匹敵"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "チームは相手に圧倒的に匹敵した。", "explanation": "匹敵に〈上回る〉の意味はなく、「圧倒的に」は同等を表す語と矛盾する。"}, {"text": "彼は運命に匹敵した。", "explanation": "匹敵に〈対抗する〉の意味はなく、運命を相手にする用法は同等を表す語として不自然。"}, {"text": "彼は一人だけ大幅に匹敵した。", "explanation": "匹敵に〈遅れる〉の意味はなく、「大幅に」は同等を表す語と矛盾する。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca5920d4-ba89-425c-8b4e-47cfa4b9d998') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39517, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この新人の実力は、ベテラン選手を匹敵している。", "corrected_sentence": "この新人の実力は、ベテラン選手に匹敵している。", "error_description": "「匹敵する」は「〜に匹敵する」と格助詞「に」を取る。「を」は誤りで、正しくは「に」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca5920d4-ba89-425c-8b4e-47cfa4b9d998') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39517, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ベテランに匹敵しくない実力では、この大会は勝てない。", "corrected_sentence": "ベテランに匹敵しない実力では、この大会は勝てない。", "error_description": "「匹敵する」の否定形は「匹敵しない」。「匹敵しくない」は形容詞の活用で、誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca5920d4-ba89-425c-8b4e-47cfa4b9d998') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
