INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39518, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "function", "definition": "「もう」と同じく、ある時点より前に、そのことがすでに起きていたことを表す副詞。", "primary_collocate": null, "pronunciation": "すでに", "ipa": "sɯdeni", "syllable_count": 3, "sentences": [{"text": "その話は既に先生から聞いて知っていた。", "target_word": "既に", "complexity_tier": "T3", "furigana": "その話[はなし]は既[すで]に先生[せんせい]から聞[き]いて知[し]っていた。", "sentence_source": "generated"}, {"text": "駅に着いたとき、電車は既に出ていた。", "target_word": "既に", "complexity_tier": "T3", "furigana": "駅[えき]に着[つ]いたとき、電車[でんしゃ]は既[すで]に出[で]ていた。", "sentence_source": "generated"}, {"text": "彼女は既に宿題を終えて、遊びに行った。", "target_word": "既に", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は既[すで]に宿題[しゅくだい]を終[お]えて、遊[あそ]びに行[い]った。", "sentence_source": "generated"}, {"text": "私が電話をかけたときには、父は既に家を出ていた。", "target_word": "既に", "complexity_tier": "T3", "furigana": "私[わたし]が電話[でんわ]をかけたときには、父[ちち]は既[すで]に家[いえ]を出[で]ていた。", "sentence_source": "generated"}, {"text": "その本は既に読んだから、別のを貸してほしい。", "target_word": "既に", "complexity_tier": "T3", "furigana": "その本[ほん]は既[すで]に読[よ]んだから、別[べつ]のを貸[か]してほしい。", "sentence_source": "generated"}, {"text": "店に行ったが、人気のパンは既に売り切れていた。", "target_word": "既に", "complexity_tier": "T3", "furigana": "店[みせ]に行[い]ったが、人気[にんき]のパンは既[すで]に売[う]り切[き]れていた。", "sentence_source": "generated"}, {"text": "手紙を書こうと思ったが、友達は既に引っ越していた。", "target_word": "既に", "complexity_tier": "T3", "furigana": "手紙[てがみ]を書[か]こうと思[おも]ったが、友達[ともだち]は既[すで]に引[ひ]っ越[こ]していた。", "sentence_source": "generated"}, {"text": "会議が始まる前に、資料は既に配られていた。", "target_word": "既に", "complexity_tier": "T3", "furigana": "会議[かいぎ]が始[はじ]まる前[まえ]に、資料[しりょう]は既[すで]に配[くば]られていた。", "sentence_source": "generated"}, {"text": "彼は既に二回もその山に登ったことがある。", "target_word": "既に", "complexity_tier": "T3", "furigana": "彼[かれ]は既[すで]に二回[にかい]もその山[やま]に登[のぼ]ったことがある。", "sentence_source": "generated"}, {"text": "空港に着くと、飛行機は既に飛んだ後だった。", "target_word": "既に", "complexity_tier": "T3", "furigana": "空港[くうこう]に着[つ]くと、飛行機[ひこうき]は既[すで]に飛[と]んだ後[あと]だった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "既に", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "ある時点より前に、そのことがもう起きていたと言う副詞", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2bd11da-41e2-49c8-8a73-9a8a84891b15') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39518, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "既に", "is_correct": true, "explanation": "「すでに」は、先生から聞くよりも前に話を知っていたことを示す。ここに入る正しい語。"}, {"text": "決して", "is_correct": false, "explanation": "「決して」は後ろに打ち消しの語を必要とする。肯定の「聞いて知っていた」とは合わない。"}, {"text": "ぜひ", "is_correct": false, "explanation": "「ぜひ」は願望や勧めに使う副詞で、過去の出来事を説明する文には入らない。"}, {"text": "一度も", "is_correct": false, "explanation": "「一度も」は否定の文で使う。肯定の「聞いて知っていた」とは合わない。"}], "explanations": {"既に": "「すでに」は、先生から聞くよりも前に話を知っていたことを示す。ここに入る正しい語。", "決して": "「決して」は後ろに打ち消しの語を必要とする。肯定の「聞いて知っていた」とは合わない。", "ぜひ": "「ぜひ」は願望や勧めに使う副詞で、過去の出来事を説明する文には入らない。", "一度も": "「一度も」は否定の文で使う。肯定の「聞いて知っていた」とは合わない。"}, "sentence_index": 0, "correct_answer": "既に"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "明日の朝、父は既に家を出るだろう。", "explanation": "ここは「まもなく」の意味。「既に」は動作がもう完了していることを表すので、明日の予定には合わない。"}, {"text": "電話をかけたとき、父は既に家を出そうだった。", "explanation": "ここは「今にも」の意味。「既に」は完了を表すので、まだ始まっていない「出そうだ」とは合わない。"}, {"text": "父は既に毎朝八時に家を出る。", "explanation": "ここは「いつも」の意味。「既に」は一度きりの完了を表すので、毎朝の習慣には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '196c77a7-afc3-481c-87f3-1ba8dda84301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39518, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "既に", "is_correct": true, "explanation": "ここは「すでに」で、手紙を書こうとした時点より前に、友達がもう引っ越していたことを示す。ここに入る正しい語。"}, {"text": "なかなか", "is_correct": false, "explanation": "「なかなか」は否定と一緒に使い、「なかなか〜ない」の形をとる。肯定の「引っ越していた」とは合わない。"}, {"text": "必ずしも", "is_correct": false, "explanation": "「必ずしも」は後ろに否定を伴う。肯定の「引っ越していた」とは合わない。"}, {"text": "もっとも", "is_correct": false, "explanation": "「もっとも」は程度や順序の最上を表す。ここでは時間の前後関係を述べる文に合わない。"}], "explanations": {"既に": "ここは「すでに」で、手紙を書こうとした時点より前に、友達がもう引っ越していたことを示す。ここに入る正しい語。", "なかなか": "「なかなか」は否定と一緒に使い、「なかなか〜ない」の形をとる。肯定の「引っ越していた」とは合わない。", "必ずしも": "「必ずしも」は後ろに否定を伴う。肯定の「引っ越していた」とは合わない。", "もっとも": "「もっとも」は程度や順序の最上を表す。ここでは時間の前後関係を述べる文に合わない。"}, "sentence_index": 6, "correct_answer": "既に"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "空港に着いたら、既に飛行機に乗ります。", "explanation": "ここは「今から」の意味。「既に」は完了した動作に使うので、これから行う行動には合わない。"}, {"text": "駅に着いたが、電車は既に来ていない。", "explanation": "ここは「まだ」の意味。「既に」は完了を表すので、否定の「来ていない」とは合わない。"}, {"text": "空港に着くと、飛行機は既に毎回飛ぶ。", "explanation": "ここは「毎回」の意味。「既に」は一度きりの完了を表すので、繰り返し起こる出来事には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '196c77a7-afc3-481c-87f3-1ba8dda84301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39518, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "駅に着いたとき、電車は既に出発する。", "corrected_sentence": "駅に着いたとき、電車は既に出発していた。", "error_description": "「既に」は、ある時点より前に出来事が終わっていたことを表すので、非過去の「出発する」ではなく過去の完了を表す「出発していた」にする。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '196c77a7-afc3-481c-87f3-1ba8dda84301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39518, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "空港に着くと、飛行機は既に飛ぶ。", "corrected_sentence": "空港に着くと、飛行機は既に飛んでいた。", "error_description": "「既に」は出来事が先に終わっていたことを表すので、非過去の「飛ぶ」ではなく過去の完了を表す「飛んでいた」にする。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '196c77a7-afc3-481c-87f3-1ba8dda84301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
