INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39519, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "function", "definition": "動作や状態がすでに完了し、その段階に入っていることを表す副詞。", "primary_collocate": null, "pronunciation": "すでに", "ipa": "sɯdeni", "syllable_count": 3, "sentences": [{"text": "彼は既に大人の世界に足を踏み入れている。", "target_word": "既に", "complexity_tier": "T3", "furigana": "彼[かれ]は既[すで]に大人[おとな]の世界[せかい]に足[あし]を踏[ふ]み入[い]れている。", "sentence_source": "generated"}, {"text": "工事は既に最終の段階に入っている。", "target_word": "既に", "complexity_tier": "T3", "furigana": "工事[こうじ]は既[すで]に最終[さいしゅう]の段階[だんかい]に入[はい]っている。", "sentence_source": "generated"}, {"text": "この町は既に冬の寒さに包まれている。", "target_word": "既に", "complexity_tier": "T3", "furigana": "この町[まち]は既[すで]に冬[ふゆ]の寒[さむ]さに包[つつ]まれている。", "sentence_source": "generated"}, {"text": "事態は既に取り返しのつかない状態になっている。", "target_word": "既に", "complexity_tier": "T3", "furigana": "事態[じたい]は既[すで]に取[と]り返[かえ]しのつかない状態[じょうたい]になっている。", "sentence_source": "generated"}, {"text": "既に答えは出ているのに、彼は決めようとしない。", "target_word": "既に", "complexity_tier": "T3", "furigana": "既[すで]に答[こた]えは出[で]ているのに、彼[かれ]は決[き]めようとしない。", "sentence_source": "generated"}, {"text": "彼女は既に社会人として働き始めている。", "target_word": "既に", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は既[すで]に社会人[しゃかいじん]として働[はたら]き始[はじ]めている。", "sentence_source": "generated"}, {"text": "計画は既に動き出しているので、今さら止められない。", "target_word": "既に", "complexity_tier": "T3", "furigana": "計画[けいかく]は既[すで]に動[うご]き出[だ]しているので、今[いま]さら止[と]められない。", "sentence_source": "generated"}, {"text": "桜は既に満開を過ぎ、花びらが散り始めた。", "target_word": "既に", "complexity_tier": "T3", "furigana": "桜[さくら]は既[すで]に満開[まんかい]を過[す]ぎ、花[はな]びらが散[ち]り始[はじ]めた。", "sentence_source": "generated"}, {"text": "そのころ、彼の体は既に限界に近づいていた。", "target_word": "既に", "complexity_tier": "T3", "furigana": "そのころ、彼[かれ]の体[からだ]は既[すで]に限界[げんかい]に近[ちか]づいていた。", "sentence_source": "generated"}, {"text": "準備は既に整っているから、いつでも始められる。", "target_word": "既に", "complexity_tier": "T3", "furigana": "準備[じゅんび]は既[すで]に整[ととの]っているから、いつでも始[はじ]められる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "既に", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "動作や状態がもう完了し、その段階に入っていることを表す副詞", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2bd11da-41e2-49c8-8a73-9a8a84891b15') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39519, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "既に", "is_correct": true, "explanation": "ここは「すでに」で、大人の世界にもう入っている状態を示す。ここに入る正しい語。"}, {"text": "一度も", "is_correct": false, "explanation": "「一度も」は否定の文で使う。肯定の「踏み入れている」とは合わない。"}, {"text": "決して", "is_correct": false, "explanation": "「決して」は後ろに打ち消しの語を必要とする。肯定の状態を述べる文には合わない。"}, {"text": "ぜひ", "is_correct": false, "explanation": "「ぜひ」は願望や勧めに使う副詞で、状態を述べる文には合わない。"}], "explanations": {"既に": "ここは「すでに」で、大人の世界にもう入っている状態を示す。ここに入る正しい語。", "一度も": "「一度も」は否定の文で使う。肯定の「踏み入れている」とは合わない。", "決して": "「決して」は後ろに打ち消しの語を必要とする。肯定の状態を述べる文には合わない。", "ぜひ": "「ぜひ」は願望や勧めに使う副詞で、状態を述べる文には合わない。"}, "sentence_index": 0, "correct_answer": "既に"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "来週、工事は既に最終の段階に入るだろう。", "explanation": "ここは「まもなく」の意味。「既に」は完了した状態に使うので、来週の予定には合わない。"}, {"text": "空は既に暗くなりそうだ。", "explanation": "ここは「今にも」の意味。「既に」は完了を表すので、まだ起きていない「なりそうだ」とは合わない。"}, {"text": "事態は既に取り返しのつかない状態になっていない。", "explanation": "ここは「まだ」の意味。「既に」は完了を表すので、否定の「なっていない」とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '196c77a7-afc3-481c-87f3-1ba8dda84301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39519, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "既に", "is_correct": true, "explanation": "ここは「すでに」で、計画がもう動き出している状態を示す。ここに入る正しい語。"}, {"text": "必ずしも", "is_correct": false, "explanation": "「必ずしも」は後ろに否定を伴う。肯定の「動き出している」とは合わない。"}, {"text": "なかなか", "is_correct": false, "explanation": "「なかなか」は「〜ない」の否定と結びつく。肯定の「動き出している」とは合わない。"}, {"text": "もっとも", "is_correct": false, "explanation": "「もっとも」は程度や順序の最上を表す。ここでの状態を述べる文には合わない。"}], "explanations": {"既に": "ここは「すでに」で、計画がもう動き出している状態を示す。ここに入る正しい語。", "必ずしも": "「必ずしも」は後ろに否定を伴う。肯定の「動き出している」とは合わない。", "なかなか": "「なかなか」は「〜ない」の否定と結びつく。肯定の「動き出している」とは合わない。", "もっとも": "「もっとも」は程度や順序の最上を表す。ここでの状態を述べる文には合わない。"}, "sentence_index": 6, "correct_answer": "既に"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "準備は既に毎回整うから、いつでも始められる。", "explanation": "ここは「毎回」の意味。「既に」は一度きりの完了を表すので、繰り返し行う準備には使えない。"}, {"text": "準備は既にこれから整うので、少し待ってほしい。", "explanation": "ここは「これから」の意味。「既に」は完了を表すので、これから行う準備には合わない。"}, {"text": "準備は既に整うだろうから、いつでも始められる。", "explanation": "ここは「いずれ」の意味。「既に」は完了を表すので、未来の推量の「整うだろう」とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '196c77a7-afc3-481c-87f3-1ba8dda84301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39519, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は既に大人の世界に足を踏み入れる。", "corrected_sentence": "彼は既に大人の世界に足を踏み入れていた。", "error_description": "「既に」は動作が完了して状態が続いていることを表すので、非過去の「踏み入れる」ではなく「踏み入れていた」にする。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '196c77a7-afc3-481c-87f3-1ba8dda84301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39519, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "計画は既に動き出すため、今さら止めることはできない。", "corrected_sentence": "計画は既に動き出しているため、今さら止めることはできない。", "error_description": "「既に」は完了して続いている状態に使うので、これからの「動き出す」ではなく「動き出している」にする。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '196c77a7-afc3-481c-87f3-1ba8dda84301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
