INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39520, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「足の筋肉」の「の」で、足が筋肉を修飾する関係を示す。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、筋肉を修飾する形にはならない。"}, {"text": "を", "is_correct": false, "explanation": "目的語の格では筋肉を修飾しない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段を示すので、筋肉を修飾する形にはならない。"}], "correct_answer": "の", "explanations": {"の": "「足の筋肉」の「の」で、足が筋肉を修飾する関係を示す。", "へ": "「へ」は方向を示すので、筋肉を修飾する形にはならない。", "を": "目的語の格では筋肉を修飾しない。", "で": "「で」は手段を示すので、筋肉を修飾する形にはならない。"}, "error_tags": {"を": "目的語の格", "へ": "方向の格", "で": "手段の格"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25737dca-c8b0-466c-9dc6-412a3b29aa59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39520, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "足は、人が立ったり歩いたりするときにつかう体の部分です。", "primary_collocate": null, "pronunciation": "あし", "ipa": "aɕi", "syllable_count": 2, "sentences": [{"text": "朝のジョギングで足が疲れたので、ゆっくりお風呂に入った。", "target_word": "足", "complexity_tier": "T3", "furigana": "朝[あさ]のジョギングで足[あし]が疲[つか]れたので、ゆっくりお風呂[ふろ]に入[はい]った。", "sentence_source": "generated"}, {"text": "赤ちゃんの小さな足は、とてもやわらかい。", "target_word": "足", "complexity_tier": "T2", "furigana": "赤[あか]ちゃんの小[ちい]さな足[あし]は、とてもやわらかい。", "sentence_source": "generated"}, {"text": "足をけがしたため、しばらく学校を休んだ。", "target_word": "足", "complexity_tier": "T3", "furigana": "足[あし]をけがしたため、しばらく学校[がっこう]を休[やす]んだ。", "sentence_source": "generated"}, {"text": "猫は足が四本あって、高いところにも軽く登れる。", "target_word": "足", "complexity_tier": "T3", "furigana": "猫[ねこ]は足[あし]が四本[よんほん]あって、高[たか]いところにも軽[かる]く登[のぼ]れる。", "sentence_source": "generated"}, {"text": "寒い日は、足が冷えるので、厚い靴下をはく。", "target_word": "足", "complexity_tier": "T3", "furigana": "寒[さむ]い日[ひ]は、足[あし]が冷[ひ]えるので、厚[あつ]い靴下[くつした]をはく。", "sentence_source": "generated"}, {"text": "椅子に座るとき、足を床にしっかりつけると楽だ。", "target_word": "足", "complexity_tier": "T3", "furigana": "椅子[いす]に座[すわ]るとき、足[あし]を床[ゆか]にしっかりつけると楽[らく]だ。", "sentence_source": "generated"}, {"text": "彼は足を滑らせて、階段から落ちそうになった。", "target_word": "足", "complexity_tier": "T3", "furigana": "彼[かれ]は足[あし]を滑[すべ]らせて、階段[かいだん]から落[お]ちそうになった。", "sentence_source": "generated"}, {"text": "自転車に乗ると、足の筋肉が強くなる。", "target_word": "足", "complexity_tier": "T3", "furigana": "自転車[じてんしゃ]に乗[の]ると、足[あし]の筋肉[きんにく]が強[つよ]くなる。", "sentence_source": "generated"}, {"text": "雨の日は、足がぬれないように長靴をはく。", "target_word": "足", "complexity_tier": "T3", "furigana": "雨[あめ]の日[ひ]は、足[あし]が濡[ぬ]れないように長靴[ながぐつ]をはく。", "sentence_source": "generated"}, {"text": "プールで泳ぐ前に、足を軽く動かして準備をした。", "target_word": "足", "complexity_tier": "T3", "furigana": "プールで泳[およ]ぐ前[まえ]に、足[あし]を軽[かる]く動[うご]かして準備[じゅんび]をした。", "sentence_source": "generated"}], "morphological_forms": [{"form": "足", "label": "基本形"}, {"form": "足が", "label": "主格(が)"}, {"form": "足を", "label": "目的格(を)"}], "register": "標準(中立)", "sense_fingerprint": "立つ・歩くときに使う体の部分(脚・足)。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 2 above tier T1: contains vocabulary far above tier T1: けがし (Zipf 2.18)','sentence 4 above tier T1: 4 words above tier T1 (max 2): 冷える (Zipf 3.31), 厚い (Zipf 3.7), 靴下 (Zipf 3.97), はく (Zipf 3.72)','sentence 8 above tier T1: 3 words above tier T1 (max 2): ぬれ (Zipf 3.24), 長靴 (Zipf 3.14), はく (Zipf 3.72)']::text[], '0f6b1235-7c2d-4e61-9691-9f3fcb3a9405') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39520, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "足", "is_correct": true, "explanation": "「足が疲れた」は脚の疲れを指し、ジョギングの後の文に合う。"}, {"text": "歯", "is_correct": false, "explanation": "歯が疲れるという文脈にはならず、ジョギングの文に合わない。"}, {"text": "鼻", "is_correct": false, "explanation": "鼻が疲れるという文脈にはならない。"}, {"text": "耳", "is_correct": false, "explanation": "耳が疲れるという文脈にはならない。"}], "explanations": {"足": "「足が疲れた」は脚の疲れを指し、ジョギングの後の文に合う。", "歯": "歯が疲れるという文脈にはならず、ジョギングの文に合わない。", "鼻": "鼻が疲れるという文脈にはならない。", "耳": "耳が疲れるという文脈にはならない。"}, "sentence_index": 0, "correct_answer": "足"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "新しいペンを二足買った。", "explanation": "ここは靴やサンダルを数える助数詞の「足」の誤用。ペンは「本」で数えるので、「足」は使わない。"}, {"text": "先生の質問に、生徒は足を縦に振って答えた。", "explanation": "「首を縦に振る」（同意する）の「首」を「足」に替えた文。足を縦に振るという言い方はしない。"}, {"text": "引っ越しで重い荷物を運ぶので、友人に足を貸してもらった。", "explanation": "「手を貸す」（手伝う）の「手」を「足」に替えた文。足を貸すという言い方はしない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25737dca-c8b0-466c-9dc6-412a3b29aa59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39520, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "足", "is_correct": true, "explanation": "「足を滑らせる」は脚が滑る意味で、階段から落ちそうになる文に合う。"}, {"text": "額", "is_correct": false, "explanation": "「額を滑らせる」という言い方はなく、文として成り立たない。"}, {"text": "首", "is_correct": false, "explanation": "「首を滑らせる」という言い方はなく、階段から落ちる文脈に合わない。"}, {"text": "頬", "is_correct": false, "explanation": "「頬を滑らせる」という言い方はなく、文として成り立たない。"}], "explanations": {"足": "「足を滑らせる」は脚が滑る意味で、階段から落ちそうになる文に合う。", "額": "「額を滑らせる」という言い方はなく、文として成り立たない。", "首": "「首を滑らせる」という言い方はなく、階段から落ちる文脈に合わない。", "頬": "「頬を滑らせる」という言い方はなく、文として成り立たない。"}, "sentence_index": 6, "correct_answer": "足"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "作業が終わって足が空いたので、お茶を入れます。", "explanation": "「手が空く」の「手」を「足」に替えた文。足が空くという言い方はしない。"}, {"text": "先輩に会ったので、足を下げてあいさつした。", "explanation": "「頭を下げる」の形に足を入れた文。足を下げてあいさつするという言い方はしない。"}, {"text": "ハンカチを二足買った。", "explanation": "ここは靴や靴下を数える助数詞の「足」の誤用。ハンカチは「枚」で数えるので、「足」は使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25737dca-c8b0-466c-9dc6-412a3b29aa59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39520, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "朝の散歩で、足を痛くて少し歩けなかった。", "corrected_sentence": "朝の散歩で、足が痛くて少し歩けなかった。", "error_description": "「痛い」の主語は助詞「が」で示す。「足を」は誤りで、正しくは「足が」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25737dca-c8b0-466c-9dc6-412a3b29aa59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
