INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39521, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「足が痛い」のように、痛いという状態の主語は「が」で示す。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示すので、痛いの主語にはならない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示すので、ここには合わない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は共同や引用を示すので、痛いの主語には入らない。"}], "correct_answer": "が", "explanations": {"が": "「足が痛い」のように、痛いという状態の主語は「が」で示す。", "を": "「を」は目的語を示すので、痛いの主語にはならない。", "で": "「で」は手段や場所を示すので、ここには合わない。", "と": "「と」は共同や引用を示すので、痛いの主語には入らない。"}, "error_tags": {"を": "目的語の格で主語にならない", "で": "手段・場所の格", "と": "共同・引用の格"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25737dca-c8b0-466c-9dc6-412a3b29aa59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
