INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39521, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "人間や動物の体の一部で、歩いたり立ったりするために使う部分。", "primary_collocate": null, "pronunciation": "あし", "ipa": "aɕi", "syllable_count": 2, "sentences": [{"text": "農家の男は、鶏舎までの雪道を足で踏みしめて歩いた。", "target_word": "足", "complexity_tier": "T4", "furigana": "農家[のうか]の男[おとこ]は、鶏舎[けいしゃ]までの雪道[ゆきみち]を足[あし]で踏[ふ]みしめて歩[あゆ]いた。", "sentence_source": "generated"}, {"text": "昨日たくさん歩いたので、今日は足が痛くて階段がつらい。", "target_word": "足", "complexity_tier": "T3", "furigana": "昨日[きのう]たくさん歩[ある]いたので、今日[きょう]は足[あし]が痛[いた]くて階段[かいだん]がつらい。", "sentence_source": "generated"}, {"text": "犬は四本の足で、雪の上を元気よく走っていく。", "target_word": "足", "complexity_tier": "T3", "furigana": "犬[いぬ]は四本[よんほん]の足[あし]で、雪[ゆき]の上[うえ]を元気[げんき]よく走[はし]っていく。", "sentence_source": "generated"}, {"text": "靴が小さすぎて、足にまめができてしまった。", "target_word": "足", "complexity_tier": "T3", "furigana": "靴[くつ]が小[ちい]さすぎて、足[あし]にまめができてしまった。", "sentence_source": "generated"}, {"text": "サッカー選手は、足が速いだけでなく、ボールの扱いも上手だ。", "target_word": "足", "complexity_tier": "T3", "furigana": "サッカー選手[せんしゅ]は、足[あし]が速[はや]いだけでなく、ボールの扱[あつか]いも上手[じょうず]だ。", "sentence_source": "generated"}, {"text": "電車が混んでいて、隣の人に足を踏まれた。", "target_word": "足", "complexity_tier": "T3", "furigana": "電車[でんしゃ]が混[こ]んでいて、隣[となり]の人[ひと]に足[あし]を踏[ふ]まれた。", "sentence_source": "generated"}, {"text": "長く座っていたので、足がしびれて立てなかった。", "target_word": "足", "complexity_tier": "T3", "furigana": "長[なが]く座[すわ]っていたので、足[あし]がしびれて立[た]てなかった。", "sentence_source": "generated"}, {"text": "祖母は足が悪いので、遠くへ行くときはいつも車を使う。", "target_word": "足", "complexity_tier": "T3", "furigana": "祖母[そぼ]は足[あし]が悪[わる]いので、遠[とお]くへ行[い]くときはいつも車[くるま]を使[つか]う。", "sentence_source": "generated"}, {"text": "海の水は冷たかったが、足だけ入れて遊んだ。", "target_word": "足", "complexity_tier": "T3", "furigana": "海[うみ]の水[みず]は冷[つめ]たかったが、足[あし]だけ入[い]れて遊[あそ]んだ。", "sentence_source": "generated"}, {"text": "彼女は足を組んで、窓の外をぼんやり見ていた。", "target_word": "足", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は足[あし]を組[く]んで、窓[まど]の外[そと]をぼんやり見[み]ていた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "足", "label": "基本形"}, {"form": "足が", "label": "主格(が)"}, {"form": "足を", "label": "目的格(を)"}], "register": "標準(中立)", "sense_fingerprint": "人や動物の、歩いたり立ったりするための体の部分(脚・足)。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T1: contains vocabulary far above tier T1: 鶏舎 (Zipf 2.02), 踏みしめ (Zipf 2.25)']::text[], '0f6b1235-7c2d-4e61-9691-9f3fcb3a9405') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39521, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "足", "is_correct": true, "explanation": "雪道を踏みしめるのは脚の足で、体の部分として文脈に合う。"}, {"text": "手", "is_correct": false, "explanation": "手で雪道を踏みしめることはできず、文として合わない。"}, {"text": "腰", "is_correct": false, "explanation": "腰で雪道を踏みしめるとは言わず、文として合わない。"}, {"text": "膝", "is_correct": false, "explanation": "膝で雪道を踏みしめるとは言わず、文として合わない。"}], "explanations": {"足": "雪道を踏みしめるのは脚の足で、体の部分として文脈に合う。", "手": "手で雪道を踏みしめることはできず、文として合わない。", "腰": "腰で雪道を踏みしめるとは言わず、文として合わない。", "膝": "膝で雪道を踏みしめるとは言わず、文として合わない。"}, "sentence_index": 0, "correct_answer": "足"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "新しい椅子を三足買った。", "explanation": "ここは靴や靴下を数える助数詞の「足」の誤用。椅子は「脚」で数えるので、「足」は使わない。"}, {"text": "提案を聞いて、彼は足を縦に振って賛成した。", "explanation": "「首を縦に振る」（承諾する）の「首」を「足」に替えた文。足を縦に振るという言い方はしない。"}, {"text": "友人の悩みに、じっくり足を貸してあげた。", "explanation": "「耳を貸す」（話を聞く）の「耳」を「足」に替えた文。足を貸すという言い方はしない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25737dca-c8b0-466c-9dc6-412a3b29aa59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39521, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "足", "is_correct": true, "explanation": "「足がしびれる」の足。座りすぎて脚がしびれ、立てなかった文脈に合う。"}, {"text": "耳", "is_correct": false, "explanation": "耳がしびれて立てないという文にはならない。"}, {"text": "口", "is_correct": false, "explanation": "口がしびれても立てない理由にはならず、文として合わない。"}, {"text": "鼻", "is_correct": false, "explanation": "鼻がしびれて立てないという内容は成り立たない。"}], "explanations": {"足": "「足がしびれる」の足。座りすぎて脚がしびれ、立てなかった文脈に合う。", "耳": "耳がしびれて立てないという文にはならない。", "口": "口がしびれても立てない理由にはならず、文として合わない。", "鼻": "鼻がしびれて立てないという内容は成り立たない。"}, "sentence_index": 6, "correct_answer": "足"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今、足が空いているので、手伝いに行けます。", "explanation": "「手が空く」は手が自由な状態を指す言い方。足にこの言い方は使わない。"}, {"text": "取引先に深く足を下げて、謝った。", "explanation": "「頭を下げる」の形に足を入れた文。足を下げて謝るという言い方はしない。"}, {"text": "卵を三足買って、朝ごはんに食べた。", "explanation": "ここは靴や靴下を数える助数詞の「足」の誤用。卵は「個」で数えるので、「足」は使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25737dca-c8b0-466c-9dc6-412a3b29aa59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39521, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "長い山道を歩いたので、足を痛くて今日は動けない。", "corrected_sentence": "長い山道を歩いたので、足が痛くて今日は動けない。", "error_description": "「痛い」の主語は助詞「が」で示す。「足を」は誤りで、正しくは「足が」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25737dca-c8b0-466c-9dc6-412a3b29aa59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39521, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雨で道がぬれていて、足を滑らせるて転んだ。", "corrected_sentence": "雨で道がぬれていて、足を滑らせて転んだ。", "error_description": "「滑らせる」の連用形は「滑らせて」。「滑らせるて」は活用の誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25737dca-c8b0-466c-9dc6-412a3b29aa59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39522, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "動詞の辞書形に付いて「踏み入れると」となり、踏み入れると空気が冷たかったという条件の文に合う。"}, {"text": "を", "is_correct": false, "explanation": "動詞に「を」を付けると目的語になり、「踏み入れを」は条件の文として成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "進む方向を示すが、条件の関係は作れず「踏み入れへ」では文が続かない。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を示すが、「踏み入れると」の条件にはならない。"}], "correct_answer": "と", "explanations": {"と": "動詞の辞書形に付いて「踏み入れると」となり、踏み入れると空気が冷たかったという条件の文に合う。", "を": "動詞に「を」を付けると目的語になり、「踏み入れを」は条件の文として成り立たない。", "へ": "進む方向を示すが、条件の関係は作れず「踏み入れへ」では文が続かない。", "で": "手段や場所を示すが、「踏み入れると」の条件にはならない。"}, "error_tags": {"を": "object: 動詞の後に付けると目的語になり、条件文が壊れる", "へ": "direction: 進む方向を示すが、条件の関係は作れない", "で": "means: 手段や場所を示すが、「踏み入れると」の条件にはならない"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '428960e7-4a5a-41fe-b648-586a676def59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39522, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '428960e7-4a5a-41fe-b648-586a676def59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39522, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "足を中に入れること。", "primary_collocate": null, "pronunciation": "ふみいれる", "ipa": "ɸɯmiiɾeɾɯ", "syllable_count": 5, "sentences": [{"text": "靴のまま部屋に足を踏み入れてはいけません。", "target_word": "踏み入れ", "complexity_tier": "T3", "furigana": "靴[くつ]のまま部屋[へや]に足[あし]を踏[ふ]み入[い]れてはいけません。", "sentence_source": "generated"}, {"text": "森の中へ一歩足を踏み入れると、空気が冷たかった。", "target_word": "踏み入れる", "complexity_tier": "T3", "furigana": "森[もり]の中[なか]へ一歩[いっぽ]足[あし]を踏[ふ]み入[い]れると、空気[くうき]が冷[つめ]たかった。", "sentence_source": "generated"}, {"text": "川に足を踏み入れたら、水が思ったより深かった。", "target_word": "踏み入れた", "complexity_tier": "T3", "furigana": "川[かわ]に足[あし]を踏[ふ]み入[い]れたら、水[みず]が思[おも]ったより深[ふか]かった。", "sentence_source": "generated"}, {"text": "彼は暗い洞窟に、そっと足を踏み入れた。", "target_word": "踏み入れた", "complexity_tier": "T3", "furigana": "彼[かれ]は暗[くら]い洞窟[どうくつ]に、そっと足[あし]を踏[ふ]み入[い]れた。", "sentence_source": "generated"}, {"text": "畑に足を踏み入れると、土が靴にくっついた。", "target_word": "踏み入れる", "complexity_tier": "T3", "furigana": "畑[はたけ]に足[あし]を踏[ふ]み入[い]れると、土[つち]が靴[くつ]にくっついた。", "sentence_source": "generated"}, {"text": "雪の積もった庭に、足を踏み入れてみた。", "target_word": "踏み入れて", "complexity_tier": "T3", "furigana": "雪[ゆき]の積[つ]もった庭[にわ]に、足[あし]を踏[ふ]み入[い]れてみた。", "sentence_source": "generated"}, {"text": "工事中の場所には、足を踏み入れないでください。", "target_word": "踏み入れない", "complexity_tier": "T3", "furigana": "工事中[こうじちゅう]の場所[ばしょ]には、足[あし]を踏[ふ]み入[い]れないでください。", "sentence_source": "generated"}, {"text": "古い神社の門をくぐり、境内に足を踏み入れた。", "target_word": "踏み入れた", "complexity_tier": "T3", "furigana": "古[ふる]い神社[じんじゃ]の門[もん]をくぐり、境内[けいだい]に足[あし]を踏[ふ]み入[い]れた。", "sentence_source": "generated"}, {"text": "泥の中に足を踏み入れて、靴が汚れてしまった。", "target_word": "踏み入れて", "complexity_tier": "T3", "furigana": "泥[どろ]の中[なか]に足[あし]を踏[ふ]み入[い]れて、靴[くつ]が汚[よご]れてしまった。", "sentence_source": "generated"}, {"text": "犬は、知らない家の玄関に足を踏み入れた。", "target_word": "踏み入れた", "complexity_tier": "T3", "furigana": "犬[いぬ]は、知[し]らない家[いえ]の玄関[げんかん]に足[あし]を踏[ふ]み入[い]れた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "踏み入れる", "label": "辞書形"}, {"form": "踏み入れた", "label": "過去形"}, {"form": "踏み入れて", "label": "て形"}, {"form": "踏み入れない", "label": "否定形"}, {"form": "踏み入れ", "label": "連用形"}], "register": "neutral", "sense_fingerprint": "実際に足を場所の中へ入れる動作。『部屋・川・庭に足を踏み入れる』", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b30eead4-b8b9-4166-94ba-a26d8a550d93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39522, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "踏み入れ", "is_correct": true, "explanation": "部屋の中に足を入れる動作を表し、「足を〜てはいけません」の形に合う。"}, {"text": "近づき", "is_correct": false, "explanation": "近づく動詞は「足を」を目的語にとれず、「足を近づきて」は成り立たない。"}, {"text": "戻り", "is_correct": false, "explanation": "元の場所へ帰る自動詞で、「足を」を取れないので合わない。"}, {"text": "通り", "is_correct": false, "explanation": "通過する自動詞で、「足を通りて」の形は文として成り立たない。"}], "explanations": {"踏み入れ": "部屋の中に足を入れる動作を表し、「足を〜てはいけません」の形に合う。", "近づき": "近づく動詞は「足を」を目的語にとれず、「足を近づきて」は成り立たない。", "戻り": "元の場所へ帰る自動詞で、「足を」を取れないので合わない。", "通り": "通過する自動詞で、「足を通りて」の形は文として成り立たない。"}, "sentence_index": 0, "correct_answer": "踏み入れ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は庭に、そっと手を踏み入れた。", "explanation": "ここは〈手を入れる〉（手を加える）の意味。手は踏めないので、踏み入れるの対象には足が必要。"}, {"text": "階段で足を踏み入れ、転びそうになった。", "explanation": "ここは〈踏み外す〉の意味。踏み入れるは中へ入る意味で、段を外して転ぶ動きには合わない。"}, {"text": "彼は空き缶を、そっと踏み入れた。", "explanation": "ここは〈踏み潰す〉の意味。物を踏み入れることはできず、踏んで潰す動作はこの語に合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '428960e7-4a5a-41fe-b648-586a676def59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39522, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "踏み入れない", "is_correct": true, "explanation": "禁止を表す「ないでください」に合い、足を中に入れないという意味になる。"}, {"text": "離れない", "is_correct": false, "explanation": "離れるは場所を目的語にとるので、「足を離れないでください」は意味をなさない。"}, {"text": "登らない", "is_correct": false, "explanation": "登るは「山を登る」のように場所を目的語にとるので、「足を登らないでください」は意味をなさない。"}, {"text": "寝ない", "is_correct": false, "explanation": "寝るは自動詞で、「足を寝ないでください」は意味をなさない。"}], "explanations": {"踏み入れない": "禁止を表す「ないでください」に合い、足を中に入れないという意味になる。", "離れない": "離れるは場所を目的語にとるので、「足を離れないでください」は意味をなさない。", "登らない": "登るは「山を登る」のように場所を目的語にとるので、「足を登らないでください」は意味をなさない。", "寝ない": "寝るは自動詞で、「足を寝ないでください」は意味をなさない。"}, "sentence_index": 6, "correct_answer": "踏み入れない"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "犬は、知らない家の玄関で、花を踏み入れた。", "explanation": "ここは〈踏み荒らす〉（踏んで傷つける）の意味。花は入っていく場所ではなく、踏み入れるとは言わない。"}, {"text": "会議で彼は踏み入れた質問をされ、困った。", "explanation": "ここは〈踏み込む〉（深く立ち入って聞く）の意味。「踏み入れた質問」とは言わず、「踏み込んだ質問」と言う。"}, {"text": "犬は、知らない家の玄関で、足音を踏み入れた。", "explanation": "ここは〈足音〉の意味。足音は立てるもので、踏み入れるものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '428960e7-4a5a-41fe-b648-586a676def59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39522, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "山道に足を踏み入れを、霧が濃くなった。", "corrected_sentence": "山道に足を踏み入れると、霧が濃くなった。", "error_description": "動詞の連用形に『を』は続かない。条件は『と』などで表すので、正しくは『踏み入れると』。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "踏み入れる", "is_correct": true, "explanation": "辞書形に「と」が付いて「〜すると」の条件になり、文と合う。"}, {"text": "踏み入れ", "is_correct": false, "explanation": "連用形で、「と」は続かないので条件の文が作れない。"}, {"text": "踏み入れて", "is_correct": false, "explanation": "て形で、「と」の条件文にはならない。"}, {"text": "踏み入れよう", "is_correct": false, "explanation": "意向形で意志を表し、「踏み入れようと」は条件ではなく意図の文になる。"}], "correct_form": "踏み入れる", "base_form": "踏み入れる", "form_label": "辞書形", "sentence_index": 1, "explanations": {"踏み入れる": "辞書形に「と」が付いて「〜すると」の条件になり、文と合う。", "踏み入れ": "連用形で、「と」は続かないので条件の文が作れない。", "踏み入れて": "て形で、「と」の条件文にはならない。", "踏み入れよう": "意向形で意志を表し、「踏み入れようと」は条件ではなく意図の文になる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '428960e7-4a5a-41fe-b648-586a676def59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39522, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夜中に足を踏み入れたり、警報が鳴った。", "corrected_sentence": "夜中に足を踏み入れたら、警報が鳴った。", "error_description": "条件の「たら」が正しい。「たり」は動作を並べる形で、後ろにもう一つの動作が続かないと文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "踏み入れた", "is_correct": true, "explanation": "過去形で、過去に足を入れた出来事を表し、文と合う。"}, {"text": "踏み入れない", "is_correct": false, "explanation": "否定形で、入らないという意味になり、過去に入った出来事を述べる文と合わない。"}, {"text": "踏み入れられ", "is_correct": false, "explanation": "受け身の形で、足が入れられる意味になり、主語が合わなくなる。"}, {"text": "踏み入れさせ", "is_correct": false, "explanation": "使役の形で、誰かに入らせる意味になり、文の意味が変わる。"}], "correct_form": "踏み入れた", "base_form": "踏み入れる", "form_label": "過去形", "sentence_index": 7, "explanations": {"踏み入れた": "過去形で、過去に足を入れた出来事を表し、文と合う。", "踏み入れない": "否定形で、入らないという意味になり、過去に入った出来事を述べる文と合わない。", "踏み入れられ": "受け身の形で、足が入れられる意味になり、主語が合わなくなる。", "踏み入れさせ": "使役の形で、誰かに入らせる意味になり、文の意味が変わる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '428960e7-4a5a-41fe-b648-586a676def59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
