INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39523, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "ある場所や状況に、足を入れて進むこと。", "primary_collocate": null, "pronunciation": "ふみいれる", "ipa": "ɸɯmiiɾeɾɯ", "syllable_count": 5, "sentences": [{"text": "彼女は初めて、研究の世界に足を踏み入れた。", "target_word": "踏み入れた", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は初[はじ]めて、研究[けんきゅう]の世界[せかい]に足[あし]を踏[ふ]み入[い]れた。", "sentence_source": "generated"}, {"text": "見知らぬ町に足を踏み入れ、道に迷った。", "target_word": "踏み入れ", "complexity_tier": "T3", "furigana": "見知[みし]らぬ町[まち]に足[あし]を踏[ふ]み入[い]れ、道[みち]に迷[まよ]った。", "sentence_source": "generated"}, {"text": "危険な地域に足を踏み入れる前に、情報を集めた。", "target_word": "踏み入れる", "complexity_tier": "T3", "furigana": "危険[きけん]な地域[ちいき]に足[あし]を踏[ふ]み入[い]れる前[まえ]に、情報[じょうほう]を集[あつ]めた。", "sentence_source": "generated"}, {"text": "新しい仕事の分野に足を踏み入れるのは不安だ。", "target_word": "踏み入れる", "complexity_tier": "T3", "furigana": "新[あたら]しい仕事[しごと]の分野[ぶんや]に足[あし]を踏[ふ]み入[い]れるのは不安[ふあん]だ。", "sentence_source": "generated"}, {"text": "彼は未知の領域に足を踏み入れた科学者だ。", "target_word": "踏み入れた", "complexity_tier": "T3", "furigana": "彼[かれ]は未知[みち]の領域[りょういき]に足[あし]を踏[ふ]み入[い]れた科学者[かがくしゃ]だ。", "sentence_source": "generated"}, {"text": "一度でも争いに足を踏み入れると、抜け出しにくい。", "target_word": "踏み入れる", "complexity_tier": "T3", "furigana": "一度[いちど]でも争[あらそ]いに足[あし]を踏[ふ]み入[い]れると、抜[ぬ]け出[だ]しにくい。", "sentence_source": "generated"}, {"text": "兵士たちは、霧の深い山道に足を踏み入れた。", "target_word": "踏み入れた", "complexity_tier": "T3", "furigana": "兵士[へいし]たちは、霧[きり]の深[ふか]い山道[やまみち]に足[あし]を踏[ふ]み入[い]れた。", "sentence_source": "generated"}, {"text": "音楽の世界に足を踏み入れたのは、十五歳のときだ。", "target_word": "踏み入れた", "complexity_tier": "T3", "furigana": "音楽[おんがく]の世界[せかい]に足[あし]を踏[ふ]み入[い]れたのは、十五歳[じゅうごさい]のときだ。", "sentence_source": "generated"}, {"text": "立ち入り禁止の区域に足を踏み入れて、注意された。", "target_word": "踏み入れて", "complexity_tier": "T3", "furigana": "立[た]ち入[い]り禁止[きんし]の区域[くいき]に足[あし]を踏[ふ]み入[い]れて、注意[ちゅうい]された。", "sentence_source": "generated"}, {"text": "誰も行ったことのない島に、足を踏み入れた。", "target_word": "踏み入れた", "complexity_tier": "T3", "furigana": "誰[だれ]も行[い]ったことのない島[しま]に、足[あし]を踏[ふ]み入[い]れた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "踏み入れる", "label": "辞書形"}, {"form": "踏み入れた", "label": "過去形"}, {"form": "踏み入れて", "label": "て形"}, {"form": "踏み入れない", "label": "否定形"}, {"form": "踏み入れ", "label": "連用形"}], "register": "neutral", "sense_fingerprint": "ある場所・世界・状況の中へ入って進むこと。『未知の領域・世界に足を踏み入れる』", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b30eead4-b8b9-4166-94ba-a26d8a550d93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39523, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "踏み入れた", "is_correct": true, "explanation": "過去形で、初めて経験した出来事として文と合う。"}, {"text": "踏み入れよう", "is_correct": false, "explanation": "意向形で意志を表すため、過去の出来事を語る文と合わない。"}, {"text": "踏み入れて", "is_correct": false, "explanation": "て形で、文が途中で切れてしまい、終わりの形にならない。"}, {"text": "踏み入れさせた", "is_correct": false, "explanation": "使役形で、彼女が人を入らせた意味になり、主語と合わない。"}], "explanations": {"踏み入れた": "過去形で、初めて経験した出来事として文と合う。", "踏み入れよう": "意向形で意志を表すため、過去の出来事を語る文と合わない。", "踏み入れて": "て形で、文が途中で切れてしまい、終わりの形にならない。", "踏み入れさせた": "使役形で、彼女が人を入らせた意味になり、主語と合わない。"}, "sentence_index": 0, "correct_answer": "踏み入れた"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "新しい仕事の分野に心を踏み入れるのは不安だ。", "explanation": "ここは〈心を向ける〉の意味。心は踏めないので、踏み入れるの対象にはならない。"}, {"text": "新しい仕事の分野に、人の足を踏み入れるのは不安だ。", "explanation": "ここは〈踏みつける〉の意味。他人の足を踏むことは踏みつけると言い、踏み入れるは自分の足を場所へ入れることなので合わない。"}, {"text": "新しい仕事の分野に、期待を踏み入れるのは不安だ。", "explanation": "ここは〈期待を寄せる〉の意味。期待は踏み入れられないので、踏み入れるの対象にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '428960e7-4a5a-41fe-b648-586a676def59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39523, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "踏み入れた", "is_correct": true, "explanation": "過去形で、山道に入った出来事を表し、文と合う。"}, {"text": "踏み入れられ", "is_correct": false, "explanation": "受け身の形で、足が入れられる意味になり、兵士たちが主語の文と合わない。"}, {"text": "踏み入れられる", "is_correct": false, "explanation": "受け身の辞書形で、過去の出来事を表す文と合わない。"}, {"text": "踏み入れさせる", "is_correct": false, "explanation": "使役の辞書形で、誰かに入らせる意味になり、文の意味が変わる。"}], "explanations": {"踏み入れた": "過去形で、山道に入った出来事を表し、文と合う。", "踏み入れられ": "受け身の形で、足が入れられる意味になり、兵士たちが主語の文と合わない。", "踏み入れられる": "受け身の辞書形で、過去の出来事を表す文と合わない。", "踏み入れさせる": "使役の辞書形で、誰かに入らせる意味になり、文の意味が変わる。"}, "sentence_index": 6, "correct_answer": "踏み入れた"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "誰も行ったことのない島に、波が足を踏み入れた。", "explanation": "ここは〈波が押し寄せる〉の意味。波には足がないので、足を踏み入れるの主語にはならない。"}, {"text": "誰も行ったことのない島に、船を踏み入れた。", "explanation": "ここは〈船を出す〉の意味。船は足で踏むものではなく、踏み入れるの対象にはならない。"}, {"text": "誰も行ったことのない島に、夢を踏み入れた。", "explanation": "ここは〈夢を抱く〉の意味。夢は足で入っていける場所ではないので、踏み入れるの対象にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '428960e7-4a5a-41fe-b648-586a676def59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39523, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "山の奥に足を踏み入たら、道が分からなくなった。", "corrected_sentence": "山の奥に足を踏み入れたら、道が分からなくなった。", "error_description": "「踏み入れる」の活用は「踏み入れ・た」。「踏み入た」は語幹の「れ」が抜けた誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "踏み入れ", "is_correct": true, "explanation": "連用形で、「踏み入れ、道に迷った」と動作を順に並べる形に合う。"}, {"text": "踏み入れる", "is_correct": false, "explanation": "辞書形は動作を並べる形として続かず、文が成り立たない。"}, {"text": "踏み入れない", "is_correct": false, "explanation": "否定形で、町に入らないという意味になり、道に迷った結果とは続かない。"}, {"text": "踏み入れよう", "is_correct": false, "explanation": "意向形で入ろうという意志を表し、道に迷った結果とは続かない。"}], "correct_form": "踏み入れ", "base_form": "踏み入れる", "form_label": "連用形", "sentence_index": 1, "explanations": {"踏み入れ": "連用形で、「踏み入れ、道に迷った」と動作を順に並べる形に合う。", "踏み入れる": "辞書形は動作を並べる形として続かず、文が成り立たない。", "踏み入れない": "否定形で、町に入らないという意味になり、道に迷った結果とは続かない。", "踏み入れよう": "意向形で入ろうという意志を表し、道に迷った結果とは続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '428960e7-4a5a-41fe-b648-586a676def59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39523, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "霧の深い山道に足を踏み入れるに、まだ早い。", "corrected_sentence": "霧の深い山道に足を踏み入れるのは、まだ早い。", "error_description": "「のは」の「の」が正しい。「に」では名詞の形が成り立たず、主語の「のは」に続かない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "踏み入れた", "is_correct": true, "explanation": "過去形で、音楽の世界に入った出来事を表し、文と合う。"}, {"text": "踏み入れさせる", "is_correct": false, "explanation": "使役の辞書形で、人に入らせる意味になり、文と合わない。"}, {"text": "踏み入れられない", "is_correct": false, "explanation": "受け身の否定形で、主語が足ではなくなり文と合わない。"}, {"text": "踏み入れさせない", "is_correct": false, "explanation": "使役の否定形で、誰かを入らせない意味になり、文と合わない。"}], "correct_form": "踏み入れた", "base_form": "踏み入れる", "form_label": "過去形", "sentence_index": 7, "explanations": {"踏み入れた": "過去形で、音楽の世界に入った出来事を表し、文と合う。", "踏み入れさせる": "使役の辞書形で、人に入らせる意味になり、文と合わない。", "踏み入れられない": "受け身の否定形で、主語が足ではなくなり文と合わない。", "踏み入れさせない": "使役の否定形で、誰かを入らせない意味になり、文と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '428960e7-4a5a-41fe-b648-586a676def59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39524, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「蜜蜂が来る」の「が」で、蜜蜂が動作の主語であることを示す。"}, {"text": "を", "is_correct": false, "explanation": "「来る」は目的語を取らない動詞なので、「蜜蜂を来る」は成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を示す「で」では、「蜜蜂で来る」は意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "到達点を示す「へ」では、蜜蜂を到達先にする文になり合わない。"}], "correct_answer": "が", "explanations": {"が": "「蜜蜂が来る」の「が」で、蜜蜂が動作の主語であることを示す。", "を": "「来る」は目的語を取らない動詞なので、「蜜蜂を来る」は成り立たない。", "で": "手段や場所を示す「で」では、「蜜蜂で来る」は意味が通らない。", "へ": "到達点を示す「へ」では、蜜蜂を到達先にする文になり合わない。"}, "error_tags": {"が": "主語", "を": "目的語", "で": "手段・場所", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ac1b130-5bc9-47de-9744-1638a9b421cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39524, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ac1b130-5bc9-47de-9744-1638a9b421cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39524, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "みつばちは、はなのみつをあつめるむしです。", "primary_collocate": null, "pronunciation": "みつばち", "ipa": "mit͡sɯbat͡ɕi", "syllable_count": 4, "sentences": [{"text": "蜜蜂は花から花へ飛んで、蜜を集めています。", "target_word": "蜜蜂", "complexity_tier": "T3", "furigana": "蜜蜂[みつばち]は花[はな]から花[はな]へ飛[と]んで、蜜[みつ]を集[あつ]めています。", "sentence_source": "generated"}, {"text": "春になると、庭の菜の花に蜜蜂がたくさん来ます。", "target_word": "蜜蜂", "complexity_tier": "T3", "furigana": "春[はる]になると、庭[にわ]の菜[な]の花[はな]に蜜蜂[みつばち]がたくさん来[き]ます。", "sentence_source": "generated"}, {"text": "小さな蜜蜂が、あたたかい日にひまわりの上で動いていた。", "target_word": "蜜蜂", "complexity_tier": "T3", "furigana": "小[ちい]さな蜜蜂[みつばち]が、あたたかい日[ひ]にひまわりの上[うえ]で動[うご]いていた。", "sentence_source": "generated"}, {"text": "蜜蜂は口で花の蜜を吸って、巣へ持って帰ります。", "target_word": "蜜蜂", "complexity_tier": "T3", "furigana": "蜜蜂[みつばち]は口[くち]で花[はな]の蜜[みつ]を吸[す]って、巣[す]へ持[も]って帰[かえ]ります。", "sentence_source": "generated"}, {"text": "雨の日は、蜜蜂があまり外に出てきません。", "target_word": "蜜蜂", "complexity_tier": "T3", "furigana": "雨[あめ]の日[ひ]は、蜜蜂[みつばち]があまり外[そと]に出[で]てきません。", "sentence_source": "generated"}, {"text": "妹は花の近くで蜜蜂を見つけて、そっと遠くから見ていた。", "target_word": "蜜蜂", "complexity_tier": "T3", "furigana": "妹[いもうと]は花[はな]の近[ちか]くで蜜蜂[みつばち]を見[み]つけて、そっと遠[とお]くから見[み]ていた。", "sentence_source": "generated"}, {"text": "蜜蜂は小さな虫だが、花にとってはとても大切だ。", "target_word": "蜜蜂", "complexity_tier": "T3", "furigana": "蜜蜂[みつばち]は小[ちい]さな虫[むし]だが、花[はな]にとってはとても大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "公園の花だんで、蜜蜂の羽の音が聞こえました。", "target_word": "蜜蜂", "complexity_tier": "T3", "furigana": "公園[こうえん]の花[はな]だんで、蜜蜂[みつばち]の羽[はね]の音[おと]が聞[き]こえました。", "sentence_source": "generated"}, {"text": "蜜蜂がとまると、花が少しゆれた。", "target_word": "蜜蜂", "complexity_tier": "T3", "furigana": "蜜蜂[みつばち]がとまると、花[はな]が少[すこ]しゆれた。", "sentence_source": "generated"}, {"text": "図鑑で、蜜蜂と普通のハエのちがいを調べました。", "target_word": "蜜蜂", "complexity_tier": "T3", "furigana": "図鑑[ずかん]で、蜜蜂[みつばち]と普通[ふつう]のハエのちがいを調[しら]べました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "蜜蜂", "label": "基本形"}], "register": "中立", "sense_fingerprint": "花の蜜を集めて飛びまわる小さな虫", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1150120c-165e-4f2c-8c6f-3d4fb6877a27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39524, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "蜜蜂", "is_correct": true, "explanation": "花から花へ飛んで蜜を集める虫で、文の内容に合う。"}, {"text": "蟻", "is_correct": false, "explanation": "蟻には羽がなく、飛ぶことはできないので文に合わない。"}, {"text": "猫", "is_correct": false, "explanation": "猫は飛ばず、花の蜜も集めないので文に合わない。"}, {"text": "魚", "is_correct": false, "explanation": "魚は水中に住み、空を飛んで花に行くことはないので合わない。"}], "explanations": {"蜜蜂": "花から花へ飛んで蜜を集める虫で、文の内容に合う。", "蟻": "蟻には羽がなく、飛ぶことはできないので文に合わない。", "猫": "猫は飛ばず、花の蜜も集めないので文に合わない。", "魚": "魚は水中に住み、空を飛んで花に行くことはないので合わない。"}, "sentence_index": 0, "correct_answer": "蜜蜂"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "朝ごはんに、蜜蜂をたっぷりかけて食べた。", "explanation": "ここは〈蜂蜜〉の意味。食べ物にかける物は「蜂蜜」で、虫の蜜蜂は合わない。"}, {"text": "夏の夜、木の上で蜜蜂がずっと鳴いている。", "explanation": "ここは〈蝉〉の意味。鳴くのは蝉で、蜜蜂は羽音を立てて飛ぶ虫なので「鳴く」とは言わない。"}, {"text": "春の畑で、蜜蜂がひらひら舞っている。", "explanation": "ここは〈蝶〉の意味。ひらひら舞うのは蝶で、蜜蜂はブンブン飛ぶので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ac1b130-5bc9-47de-9744-1638a9b421cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39524, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "蜜蜂", "is_correct": true, "explanation": "小さな虫だが花に大切な役目を持つ生き物で、文の内容に合う。"}, {"text": "木", "is_correct": false, "explanation": "木は虫ではないので、「小さな虫だが」の文には合わない。"}, {"text": "石", "is_correct": false, "explanation": "石は生き物ではなく、虫でもないので文に合わない。"}, {"text": "雲", "is_correct": false, "explanation": "雲は虫ではなく、花にとって大切な役目を持つ生き物でもないので合わない。"}], "explanations": {"蜜蜂": "小さな虫だが花に大切な役目を持つ生き物で、文の内容に合う。", "木": "木は虫ではないので、「小さな虫だが」の文には合わない。", "石": "石は生き物ではなく、虫でもないので文に合わない。", "雲": "雲は虫ではなく、花にとって大切な役目を持つ生き物でもないので合わない。"}, "sentence_index": 6, "correct_answer": "蜜蜂"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夏の夜、蜜蜂が腕の血を吸った。", "explanation": "ここは〈蚊〉の意味。血を吸うのは蚊で、蜜蜂は花の蜜を集める虫なので合わない。"}, {"text": "夏の夜、蜜蜂が川辺で光っている。", "explanation": "ここは〈蛍〉の意味。光るのは蛍で、蜜蜂は光らないので合わない。"}, {"text": "夏の夜、明かりに蜜蜂が集まってくる。", "explanation": "ここは〈蛾〉の意味。夜に明かりへ集まるのは蛾で、蜜蜂には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ac1b130-5bc9-47de-9744-1638a9b421cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39524, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "庭の花を、蜜蜂を次々と訪れている。", "corrected_sentence": "庭の花を、蜜蜂が次々と訪れている。", "error_description": "「訪れる」の動作主は蜜蜂なので、主語には「が」が必要。「を」にしたため、蜜蜂が訪れられる対象のように読めて誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ac1b130-5bc9-47de-9744-1638a9b421cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39524, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "蜜蜂は、雨の日にはあまり飛ばない。", "corrected_sentence": "蜜蜂は、雨の日にはあまり飛べない。", "error_description": "「飛ぶ」の可能形「飛べない」が正しい。「飛ばない」は他動詞「飛ばす」の否定形になり、蜜蜂が何かを飛ばさないという意味になって誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ac1b130-5bc9-47de-9744-1638a9b421cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
