INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39525, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ac1b130-5bc9-47de-9744-1638a9b421cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39525, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "蜜蜂は、花の蜜を集めて巣を作り、ハチミツを作る働きを持つ昆虫です。", "primary_collocate": null, "pronunciation": "みつばち", "ipa": "mit͡sɯbat͡ɕi", "syllable_count": 4, "sentences": [{"text": "蜜蜂は巣の中でハチミツを作り、冬のために蓄えます。", "target_word": "蜜蜂", "complexity_tier": "T3", "furigana": "蜜蜂[みつばち]は巣[す]の中[なか]でハチミツを作[つく]り、冬[ふゆ]のために蓄[たくわ]えます。", "sentence_source": "generated"}, {"text": "蜜蜂は役目を分けて協力し、みんなで巣を守ります。", "target_word": "蜜蜂", "complexity_tier": "T3", "furigana": "蜜蜂[みつばち]は役目[やくめ]を分[わ]けて協力[きょうりょく]し、みんなで巣[す]を守[まも]ります。", "sentence_source": "generated"}, {"text": "養蜂家は、箱の中で蜜蜂を育ててハチミツを取ります。", "target_word": "蜜蜂", "complexity_tier": "T3", "furigana": "養蜂家[ようほうか]は、箱[はこ]の中[なか]で蜜蜂[みつばち]を育[そだ]ててハチミツを取[と]ります。", "sentence_source": "generated"}, {"text": "蜜蜂が作った六角形の巣は、とても丈夫で形が整っています。", "target_word": "蜜蜂", "complexity_tier": "T3", "furigana": "蜜蜂[みつばち]が作[つく]った六角形[ろっかくけい]の巣[す]は、とても丈夫[じょうぶ]で形[かたち]が整[ととの]っています。", "sentence_source": "generated"}, {"text": "蜜蜂の巣から取れたハチミツは、パンにぬるとおいしい。", "target_word": "蜜蜂", "complexity_tier": "T3", "furigana": "蜜蜂[みつばち]の巣[す]から取[と]れたハチミツは、パンにぬるとおいしい。", "sentence_source": "generated"}, {"text": "蜜蜂が減ると、果物の実がなりにくくなることがある。", "target_word": "蜜蜂", "complexity_tier": "T3", "furigana": "蜜蜂[みつばち]が減[へ]ると、果物[くだもの]の実[み]がなりにくくなることがある。", "sentence_source": "generated"}, {"text": "一つの巣には、数万匹の蜜蜂がいっしょに暮らしている。", "target_word": "蜜蜂", "complexity_tier": "T3", "furigana": "一[ひと]つの巣[す]には、数万匹[すうまんびき]の蜜蜂[みつばち]がいっしょに暮[く]らしている。", "sentence_source": "generated"}, {"text": "蜜蜂は花粉も運ぶので、農家の人にとって大事な昆虫です。", "target_word": "蜜蜂", "complexity_tier": "T3", "furigana": "蜜蜂[みつばち]は花粉[かふん]も運[はこ]ぶので、農家[のうか]の人[ひと]にとって大事[だいじ]な昆虫[こんちゅう]です。", "sentence_source": "generated"}, {"text": "冬の間、蜜蜂は巣の中で集まって、体をあたためます。", "target_word": "蜜蜂", "complexity_tier": "T3", "furigana": "冬[ふゆ]の間[あいだ]、蜜蜂[みつばち]は巣[す]の中[なか]で集[あつ]まって、体[からだ]をあたためます。", "sentence_source": "generated"}, {"text": "蜜蜂が巣を作る様子を、観察ガラス越しに見学した。", "target_word": "蜜蜂", "complexity_tier": "T3", "furigana": "蜜蜂[みつばち]が巣[す]を作[つく]る様子[ようす]を、観察[かんさつ]ガラス越[ご]しに見学[けんがく]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "蜜蜂", "label": "基本形"}], "register": "中立", "sense_fingerprint": "群れで巣を作り、ハチミツを作る働きをもつ昆虫", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1150120c-165e-4f2c-8c6f-3d4fb6877a27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39525, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "蜜蜂", "is_correct": true, "explanation": "巣の中でハチミツを作り、冬に蓄える虫で、文の内容に合う。"}, {"text": "蝶", "is_correct": false, "explanation": "蝶は蜜を吸うが、ハチミツを作って巣に蓄えることはしない。"}, {"text": "蝉", "is_correct": false, "explanation": "蝉はハチミツを作らず、巣に蓄える習性もないので文に合わない。"}, {"text": "蛍", "is_correct": false, "explanation": "蛍は光る虫で、ハチミツを作って蓄えることはないので合わない。"}], "explanations": {"蜜蜂": "巣の中でハチミツを作り、冬に蓄える虫で、文の内容に合う。", "蝶": "蝶は蜜を吸うが、ハチミツを作って巣に蓄えることはしない。", "蝉": "蝉はハチミツを作らず、巣に蓄える習性もないので文に合わない。", "蛍": "蛍は光る虫で、ハチミツを作って蓄えることはないので合わない。"}, "sentence_index": 0, "correct_answer": "蜜蜂"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "雨上がりの台所で、蜜蜂が一列に並んで、落ちた砂糖を巣へ運んでいた。", "explanation": "ここは〈蟻〉の意味。一列に並んで食べ物を巣へ運ぶのは蟻で、蜜蜂は花の蜜を集める虫なので、行列を作って砂糖を運ぶとは言わない。"}, {"text": "来年から、蜜蜂を始めるつもりだ。", "explanation": "ここは〈養蜂〉の意味。始めるのはハチを飼う活動で、「蜜蜂を始める」とは言わない。"}, {"text": "夏の夜、蜜蜂が光りながら川辺を飛ぶ。", "explanation": "ここは〈蛍〉の意味。光りながら飛ぶのは蛍で、蜜蜂は光らないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ac1b130-5bc9-47de-9744-1638a9b421cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39525, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "蜜蜂", "is_correct": true, "explanation": "数万匹で一つの巣に暮らす虫で、「匹」で数えるので文に合う。"}, {"text": "人", "is_correct": false, "explanation": "人は「人」で数えるので、「数万匹の人」とは言わない。"}, {"text": "木", "is_correct": false, "explanation": "木は「本」で数えるので、「匹」の文には合わない。"}, {"text": "家", "is_correct": false, "explanation": "家は「軒」で数えるので、「数万匹の家」とは言わず、巣にも暮らさない。"}], "explanations": {"蜜蜂": "数万匹で一つの巣に暮らす虫で、「匹」で数えるので文に合う。", "人": "人は「人」で数えるので、「数万匹の人」とは言わない。", "木": "木は「本」で数えるので、「匹」の文には合わない。", "家": "家は「軒」で数えるので、「数万匹の家」とは言わず、巣にも暮らさない。"}, "sentence_index": 6, "correct_answer": "蜜蜂"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夏の夜、蜜蜂が腕の血を吸った。", "explanation": "ここは〈蚊〉の意味。血を吸うのは蚊で、蜜蜂は花の蜜を集める虫なので合わない。"}, {"text": "春の畑で、蜜蜂が花のまわりを、ひらひらと舞う。", "explanation": "ここは〈蝶〉の意味。ひらひらと舞うのは蝶で、蜜蜂は羽音を立てて飛ぶので合わない。"}, {"text": "夏の夜、明かりに蜜蜂が集まってくる。", "explanation": "ここは〈蛾〉の意味。夜に明かりへ集まるのは蛾で、蜜蜂には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ac1b130-5bc9-47de-9744-1638a9b421cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39525, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "蜜蜂を、巣の中の温度を一定に保っている。", "corrected_sentence": "蜜蜂が、巣の中の温度を一定に保っている。", "error_description": "温度を保つ動作の主語は蜜蜂なので、「が」が必要。「を」にしたため、蜜蜂が目的語になり文の形が崩れて誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ac1b130-5bc9-47de-9744-1638a9b421cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39525, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "蜜蜂で巣は、とても丈夫にできている。", "corrected_sentence": "蜜蜂の巣は、とても丈夫にできている。", "error_description": "「蜜蜂の巣」と「の」で名詞をつなぐ必要がある。「で」は手段や場所を示すため、「蜜蜂で巣」は不自然で誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ac1b130-5bc9-47de-9744-1638a9b421cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39526, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "『花を』は、あげるという動作の目的語を示す。『あげる』の対象には『を』を付ける。"}, {"text": "で", "is_correct": false, "explanation": "『で』は場所や手段を示すため、あげる対象にはならない。"}, {"text": "へ", "is_correct": false, "explanation": "『へ』は方向を示すが、『花へあげた』では植物に送る形になり不自然。"}, {"text": "が", "is_correct": false, "explanation": "『花が』は主語を示すため、あげる動作の目的語にはならない。"}], "correct_answer": "を", "explanations": {"を": "『花を』は、あげるという動作の目的語を示す。『あげる』の対象には『を』を付ける。", "で": "『で』は場所や手段を示すため、あげる対象にはならない。", "へ": "『へ』は方向を示すが、『花へあげた』では植物に送る形になり不自然。", "が": "『花が』は主語を示すため、あげる動作の目的語にはならない。"}, "error_tags": {"で": "場所・手段", "へ": "方向", "が": "主語"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75f8b2ea-b1b2-4b0b-bd9b-d6649c858d5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39526, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "『花を』は、かざすという動作の目的語を示す。『かざす』の対象には『を』を付ける。"}, {"text": "に", "is_correct": false, "explanation": "『に』は場所や相手を示すため、かざす対象にはならない。"}, {"text": "と", "is_correct": false, "explanation": "『と』は並列や相手を示すため、かざす対象にはならない。"}, {"text": "から", "is_correct": false, "explanation": "『から』は起点を示すため、かざす対象にはならない。"}], "correct_answer": "を", "explanations": {"を": "『花を』は、かざすという動作の目的語を示す。『かざす』の対象には『を』を付ける。", "に": "『に』は場所や相手を示すため、かざす対象にはならない。", "と": "『と』は並列や相手を示すため、かざす対象にはならない。", "から": "『から』は起点を示すため、かざす対象にはならない。"}, "error_tags": {"に": "場所・相手", "と": "並列・相手", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75f8b2ea-b1b2-4b0b-bd9b-d6649c858d5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39526, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "はなは、木や草にできる、きれいな色のところです。", "primary_collocate": null, "pronunciation": "はな", "ipa": "hana", "syllable_count": 2, "sentences": [{"text": "庭に赤い花が咲いている。", "target_word": "花", "complexity_tier": "T3", "furigana": "庭[にわ]に赤[あか]い花[はな]が咲[さ]いている。", "sentence_source": "generated"}, {"text": "母の誕生日に花をあげた。", "target_word": "花", "complexity_tier": "T3", "furigana": "母[はは]の誕生日[たんじょうび]に花[はな]をあげた。", "sentence_source": "generated"}, {"text": "この花はとてもいいにおいがする。", "target_word": "花", "complexity_tier": "T3", "furigana": "この花[はな]はとてもいいにおいがする。", "sentence_source": "generated"}, {"text": "春になると、公園の花を見に行く。", "target_word": "花", "complexity_tier": "T3", "furigana": "春[はる]になると、公園[こうえん]の花[はな]を見[み]に行[い]く。", "sentence_source": "generated"}, {"text": "水をやらなかったので、花がしおれた。", "target_word": "花", "complexity_tier": "T3", "furigana": "水[みず]をやらなかったので、花[はな]がしおれた。", "sentence_source": "generated"}, {"text": "花の色は白からピンクにかわる。", "target_word": "花", "complexity_tier": "T3", "furigana": "花[はな]の色[いろ]は白[しろ]からピンクにかわる。", "sentence_source": "generated"}, {"text": "道ばたに小さな花が落ちていた。", "target_word": "花", "complexity_tier": "T3", "furigana": "道[みち]ばたに小[ちい]さな花[はな]が落[お]ちていた。", "sentence_source": "generated"}, {"text": "机の上に花をかざった。", "target_word": "花", "complexity_tier": "T3", "furigana": "机[つくえ]の上[うえ]に花[はな]をかざった。", "sentence_source": "generated"}, {"text": "木の花に、ちょうちょが止まった。", "target_word": "花", "complexity_tier": "T3", "furigana": "木[き]の花[はな]に、ちょうちょが止[と]まった。", "sentence_source": "generated"}, {"text": "雨が降って、花がぬれている。", "target_word": "花", "complexity_tier": "T3", "furigana": "雨[あめ]が降[ふ]って、花[はな]がぬれている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "花", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "木や草にさく、きれいな色のもの", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55d77c36-1221-46e8-9ca1-e98c3b3fa4f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39526, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "花", "is_correct": true, "explanation": "庭の木に咲く、赤くきれいな色の部分が花。『咲いている』と自然に結びつく。"}, {"text": "葉", "is_correct": false, "explanation": "葉は緑色の部分で、咲くものではない。"}, {"text": "枝", "is_correct": false, "explanation": "枝は幹から出る部分で、咲くことはない。"}, {"text": "実", "is_correct": false, "explanation": "実は熟して食べられる部分で、咲くものではない。"}], "explanations": {"花": "庭の木に咲く、赤くきれいな色の部分が花。『咲いている』と自然に結びつく。", "葉": "葉は緑色の部分で、咲くものではない。", "枝": "枝は幹から出る部分で、咲くことはない。", "実": "実は熟して食べられる部分で、咲くものではない。"}, "sentence_index": 0, "correct_answer": "花"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ガラス製の花を水で満たし、窓辺に置いた。", "explanation": "ここは〈花瓶〉の意味。水を満たして窓辺に置くのは花瓶で、木や草にできる色のところの花とは合わない。"}, {"text": "雨が上がったあと、庭の木の花が赤く色づいて、いっそう明るくなった。", "explanation": "ここは〈葉〉の意味。赤く色づいて紅葉するのは葉で、咲いた色のところの花とは合わない。"}, {"text": "秋になると、庭の木の花が赤く熟して、甘くなった。", "explanation": "ここは〈実〉の意味。熟して甘くなるのは実で、咲く花は熟して甘くならないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75f8b2ea-b1b2-4b0b-bd9b-d6649c858d5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39526, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "花", "is_correct": true, "explanation": "道ばたに小さく落ちるものとして、花が自然に当てはまる。"}, {"text": "香り", "is_correct": false, "explanation": "香りは空気中にただようもので、落ちているものではない。"}, {"text": "色", "is_correct": false, "explanation": "色は物の性質で、落ちているものとして数えられない。"}, {"text": "咲き方", "is_correct": false, "explanation": "咲き方は様子を表す語で、落ちているものにはならない。"}], "explanations": {"花": "道ばたに小さく落ちるものとして、花が自然に当てはまる。", "香り": "香りは空気中にただようもので、落ちているものではない。", "色": "色は物の性質で、落ちているものとして数えられない。", "咲き方": "咲き方は様子を表す語で、落ちているものにはならない。"}, "sentence_index": 6, "correct_answer": "花"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この大木の花は太く、表面がごつごつしている。", "explanation": "ここは〈幹〉の意味。太くて表面がごつごつしているのは幹で、きれいな色のところとしての花とは合わない。"}, {"text": "この草の花は土の中で白く細くのびて、水をすいあげる。", "explanation": "ここは〈根〉の意味。土の中で伸びて水を吸うのは根で、花は土の中にはできないので合わない。"}, {"text": "春になると、花が土の中から出てきて、やがて葉を広げる。", "explanation": "ここは〈芽〉の意味。土から出て葉を広げるのは芽で、花はそうした成長をしないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75f8b2ea-b1b2-4b0b-bd9b-d6649c858d5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39526, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "気温が低いと、花を咲かない年もある。", "corrected_sentence": "気温が低いと、花が咲かない年もある。", "error_description": "『咲く』は自動詞なので、動作の主体は『が』で示す。『花を咲かない』の『を』は誤りで、正しくは『花が咲かない』。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75f8b2ea-b1b2-4b0b-bd9b-d6649c858d5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39526, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "花がすっかり色あせった。", "corrected_sentence": "花がすっかり色あせた。", "error_description": "『色あせる』の過去形は『色あせた』。『色あせった』は活用を誤った形で、正しくは『色あせた』。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75f8b2ea-b1b2-4b0b-bd9b-d6649c858d5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39527, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "『花が』は、咲いたあとに実ができる流れの主体を示す。『咲く』の主語には『が』を付ける。"}, {"text": "を", "is_correct": false, "explanation": "『を』は目的語を示すため、咲く動作の主体にはならない。"}, {"text": "で", "is_correct": false, "explanation": "『で』は場所や手段を示すため、咲く主体の役割は果たせない。"}, {"text": "より", "is_correct": false, "explanation": "『より』は比較の基準を示すため、咲く主体にはならない。"}], "correct_answer": "が", "explanations": {"が": "『花が』は、咲いたあとに実ができる流れの主体を示す。『咲く』の主語には『が』を付ける。", "を": "『を』は目的語を示すため、咲く動作の主体にはならない。", "で": "『で』は場所や手段を示すため、咲く主体の役割は果たせない。", "より": "『より』は比較の基準を示すため、咲く主体にはならない。"}, "error_tags": {"を": "目的語", "で": "場所・手段", "より": "比較"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75f8b2ea-b1b2-4b0b-bd9b-d6649c858d5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39527, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "『サクラの花は』は、ここで話題にされる主題を示す。順番を述べる主題には『は』を付ける。"}, {"text": "に", "is_correct": false, "explanation": "『に』は相手や時点を示すため、主題の役割は果たせない。"}, {"text": "へ", "is_correct": false, "explanation": "『へ』は方向を示すため、主題にはならない。"}, {"text": "で", "is_correct": false, "explanation": "『で』は場所や手段を示すため、『サクラの花で、葉より先に開く』は手段の意味になり不自然。"}], "correct_answer": "は", "explanations": {"は": "『サクラの花は』は、ここで話題にされる主題を示す。順番を述べる主題には『は』を付ける。", "に": "『に』は相手や時点を示すため、主題の役割は果たせない。", "へ": "『へ』は方向を示すため、主題にはならない。", "で": "『で』は場所や手段を示すため、『サクラの花で、葉より先に開く』は手段の意味になり不自然。"}, "error_tags": {"に": "相手・時点", "へ": "方向", "で": "場所・手段"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75f8b2ea-b1b2-4b0b-bd9b-d6649c858d5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39527, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "はな：植物の生殖器官であり、咲くことによって実や種子を生じる部分。", "primary_collocate": null, "pronunciation": "はな", "ipa": "hana", "syllable_count": 2, "sentences": [{"text": "花は種子植物の生殖器官である。", "target_word": "花", "complexity_tier": "T3", "furigana": "花[はな]は種子植物[しゅししょくぶつ]の生殖器官[せいしょくきかん]である。", "sentence_source": "generated"}, {"text": "花が咲いたあとに、実ができる。", "target_word": "花", "complexity_tier": "T3", "furigana": "花[はな]が咲[さ]いたあとに、実[み]ができる。", "sentence_source": "generated"}, {"text": "受粉した花は、やがて種子を作る。", "target_word": "花", "complexity_tier": "T3", "furigana": "受粉[じゅふん]した花[はな]は、やがて種子[しゅし]を作[つく]る。", "sentence_source": "generated"}, {"text": "この植物は、春に黄色い花をつける。", "target_word": "花", "complexity_tier": "T3", "furigana": "この植物[しょくぶつ]は、春[はる]に黄色[きいろ]い花[はな]をつける。", "sentence_source": "generated"}, {"text": "一つの花に、おしべとめしべがそろっている。", "target_word": "花", "complexity_tier": "T3", "furigana": "一[ひと]つの花[はな]に、おしべとめしべがそろっている。", "sentence_source": "generated"}, {"text": "昆虫が蜜を求めて花を訪れ、受粉を助ける。", "target_word": "花", "complexity_tier": "T3", "furigana": "昆虫[こんちゅう]が蜜[みつ]を求[もと]めて花[はな]を訪[おとず]れ、受粉[じゅふん]を助[たす]ける。", "sentence_source": "generated"}, {"text": "気温が低いと、花が咲く時期がおくれる。", "target_word": "花", "complexity_tier": "T3", "furigana": "気温[きおん]が低[ひく]いと、花[はな]が咲[さ]く時期[じき]がおくれる。", "sentence_source": "generated"}, {"text": "サクラの花は、葉より先に開く。", "target_word": "花", "complexity_tier": "T3", "furigana": "サクラの花[はな]は、葉[は]より先[さき]に開[ひら]く。", "sentence_source": "generated"}, {"text": "花の数が多い木ほど、実もたくさんなる。", "target_word": "花", "complexity_tier": "T3", "furigana": "花[はな]の数[かず]が多[おお]い木[き]ほど、実[み]もたくさんなる。", "sentence_source": "generated"}, {"text": "花が開かないまま、枯れてしまう種もある。", "target_word": "花", "complexity_tier": "T3", "furigana": "花[はな]が開[ひら]かないまま、枯[か]れてしまう種[しゅ]もある。", "sentence_source": "generated"}], "morphological_forms": [{"form": "花", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "植物の生殖器官、実や種子のもと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 6 above tier T3: contains vocabulary far above tier T3: おくれる (Zipf 1.94)']::text[], '55d77c36-1221-46e8-9ca1-e98c3b3fa4f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39527, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "花", "is_correct": true, "explanation": "種子植物の生殖器官として定義されるのは花。『は種子植物の生殖器官である』と正しく結びつく。"}, {"text": "細胞", "is_correct": false, "explanation": "細胞は器官より小さい単位で、生殖器官とは呼ばない。"}, {"text": "組織", "is_correct": false, "explanation": "組織は同じ働きをする細胞の集まりで、生殖器官そのものとは言わない。"}, {"text": "根", "is_correct": false, "explanation": "根は養分を吸う器官で、生殖には関わらないので定義に合わない。"}], "explanations": {"花": "種子植物の生殖器官として定義されるのは花。『は種子植物の生殖器官である』と正しく結びつく。", "細胞": "細胞は器官より小さい単位で、生殖器官とは呼ばない。", "組織": "組織は同じ働きをする細胞の集まりで、生殖器官そのものとは言わない。", "根": "根は養分を吸う器官で、生殖には関わらないので定義に合わない。"}, "sentence_index": 0, "correct_answer": "花"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この植物は、夏の日差しを受けて、大きな花で光合成をする。", "explanation": "ここは〈葉〉の意味。光合成で養分を作るのは葉で、種子を作る生殖器官の花とは役目が違うので合わない。"}, {"text": "熟した花の中に、甘い果肉と一つの種が入っている。", "explanation": "ここは〈実〉の意味。果肉と種を包むのは実で、生殖器官としての花には果肉がないので合わない。"}, {"text": "この植物は、春に黄色い花を伸ばし、土に深く張る。", "explanation": "ここは〈根〉の意味。土に深く張って養分を吸うのは根で、花ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75f8b2ea-b1b2-4b0b-bd9b-d6649c858d5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39527, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "花", "is_correct": true, "explanation": "気温が低いと咲く時期がおくれるのは花。『花が咲く時期』と自然に結びつく。"}, {"text": "種", "is_correct": false, "explanation": "種は咲くものではなく、咲く時期とは結びつかない。"}, {"text": "芽", "is_correct": false, "explanation": "芽は伸びるもので、咲くものではない。"}, {"text": "葉", "is_correct": false, "explanation": "葉は広がる部分で、咲く時期の主語にはならない。"}], "explanations": {"花": "気温が低いと咲く時期がおくれるのは花。『花が咲く時期』と自然に結びつく。", "種": "種は咲くものではなく、咲く時期とは結びつかない。", "芽": "芽は伸びるもので、咲くものではない。", "葉": "葉は広がる部分で、咲く時期の主語にはならない。"}, "sentence_index": 6, "correct_answer": "花"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この草は、花が土の中で冬を越し、春に芽を出す。", "explanation": "ここは〈種子〉の意味。土の中で冬を越して芽を出すのは種子で、生殖器官の花はそうしないので合わない。"}, {"text": "夏の夜、花が空いっぱいに広がり、見物客が歓声をあげた。", "explanation": "ここは〈花火〉の意味。夜空に広がって歓声をあげさせるのは花火で、植物の生殖器官の花とは合わない。"}, {"text": "この木の花は細く長く伸びて、先に葉をつける。", "explanation": "ここは〈枝〉の意味。細く伸びて葉をつけるのは枝で、生殖器官の花はそうした役目を持たないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75f8b2ea-b1b2-4b0b-bd9b-d6649c858d5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39527, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "庭の花で、朝の光を浴びて開く。", "corrected_sentence": "庭の花が、朝の光を浴びて開く。", "error_description": "『花が開く』の主語は『が』。『花で』の『で』は手段や場所を示すため、開く主体を示せない。正しくは『花が』。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75f8b2ea-b1b2-4b0b-bd9b-d6649c858d5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39527, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "気温が上がると、花は一斉に開いる。", "corrected_sentence": "気温が上がると、花は一斉に開く。", "error_description": "『開く』の終止形は『開く』。『開いる』は活用を誤った形で、正しくは『開く』。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75f8b2ea-b1b2-4b0b-bd9b-d6649c858d5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39528, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "乗り出す対象の身を表すので「を」。"}, {"text": "に", "is_correct": false, "explanation": "「身に乗り出す」とは言わず、乗り出す対象を表せない。"}, {"text": "で", "is_correct": false, "explanation": "手段を表す「で」では、乗り出す動作の対象にならない。"}, {"text": "が", "is_correct": false, "explanation": "「身が乗り出す」では身が主語になり、乗り出す人の動作を表せない。"}], "correct_answer": "を", "explanations": {"を": "乗り出す対象の身を表すので「を」。", "に": "「身に乗り出す」とは言わず、乗り出す対象を表せない。", "で": "手段を表す「で」では、乗り出す動作の対象にならない。", "が": "「身が乗り出す」では身が主語になり、乗り出す人の動作を表せない。"}, "error_tags": {"に": "方向・位置", "で": "手段・場所", "が": "主語"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74db7eed-5d9a-45a8-a0e9-e766affdf1f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39528, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "よじる対象の身を表すので「を」。"}, {"text": "と", "is_correct": false, "explanation": "「身とよじる」では動作の対象が成り立たず、不自然。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す「へ」では、よじる対象の身にならない。"}, {"text": "から", "is_correct": false, "explanation": "起点を表す「から」では、よじる対象にならない。"}], "correct_answer": "を", "explanations": {"を": "よじる対象の身を表すので「を」。", "と": "「身とよじる」では動作の対象が成り立たず、不自然。", "へ": "方向を表す「へ」では、よじる対象の身にならない。", "から": "起点を表す「から」では、よじる対象にならない。"}, "error_tags": {"と": "共同・引用", "へ": "方向", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74db7eed-5d9a-45a8-a0e9-e766affdf1f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39528, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "からだの こと。", "primary_collocate": null, "pronunciation": "み", "ipa": "mi", "syllable_count": 1, "sentences": [{"text": "低い入り口では、身をかがめないと頭をぶつけてしまう。", "target_word": "身", "complexity_tier": "T3", "furigana": "低[ひく]い入[い]り口[ぐち]では、身[み]をかがめないと頭[あたま]をぶつけてしまう。", "sentence_source": "generated"}, {"text": "窓から身を乗り出して、下にいる友達に手を振った。", "target_word": "身", "complexity_tier": "T3", "furigana": "窓[まど]から身[み]を乗[の]り出[だ]して、下[した]にいる友達[ともだち]に手[て]を振[ふ]った。", "sentence_source": "generated"}, {"text": "彼女は軽く身をひねって、後ろの人にぶつからないようにした。", "target_word": "身", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は軽[かる]く身[み]をひねって、後[うし]ろの人[ひと]にぶつからないようにした。", "sentence_source": "generated"}, {"text": "猫は小さな隙間に身を滑り込ませて、部屋に入ってきた。", "target_word": "身", "complexity_tier": "T3", "furigana": "猫[ねこ]は小[ちい]さな隙間[すきま]に身[み]を滑[すべ]り込[こ]ませて、部屋[へや]に入[はい]ってきた。", "sentence_source": "generated"}, {"text": "冷たい風に身を震わせながら、バスを待った。", "target_word": "身", "complexity_tier": "T3", "furigana": "冷[つめ]たい風[かぜ]に身[み]を震[ふる]わせながら、バスを待[ま]った。", "sentence_source": "generated"}, {"text": "選手は身を低くして、相手のボールを待ちかまえた。", "target_word": "身", "complexity_tier": "T3", "furigana": "選手[せんしゅ]は身[み]を低[ひく]くして、相手[あいて]のボールを待[ま]ちかまえた。", "sentence_source": "generated"}, {"text": "疲れた身をベッドに投げ出して、そのまま眠ってしまった。", "target_word": "身", "complexity_tier": "T3", "furigana": "疲[つか]れた身[み]をベッドに投[な]げ出[だ]して、そのまま眠[ねむ]ってしまった。", "sentence_source": "generated"}, {"text": "彼は身をよじって笑いながら、ソファから落ちた。", "target_word": "身", "complexity_tier": "T3", "furigana": "彼[かれ]は身[み]をよじって笑[わら]いながら、ソファから落[お]ちた。", "sentence_source": "generated"}, {"text": "老人は杖に頼りながら、ゆっくりと身を起こした。", "target_word": "身", "complexity_tier": "T3", "furigana": "老人[ろうじん]は杖[つえ]に頼[たよ]りながら、ゆっくりと身[み]を起[お]こした。", "sentence_source": "generated"}, {"text": "母は寒そうに身を縮めて、コートの襟を立てた。", "target_word": "身", "complexity_tier": "T3", "furigana": "母[はは]は寒[さむ]そうに身[み]を縮[ちぢ]めて、コートの襟[えり]を立[た]てた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "身", "label": "基本形"}], "register": "標準", "sense_fingerprint": "身|人のからだそのもの(身をかがめる・身を乗り出す)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T2: contains vocabulary far above tier T2: かがめ (Zipf 2.21)','sentence 3 above tier T2: contains vocabulary far above tier T2: 滑り込ま (Zipf 2.06)','sentence 5 above tier T2: contains vocabulary far above tier T2: 待ちかまえ (Zipf 1.89)','sentence 7 above tier T2: contains vocabulary far above tier T2: よじっ (Zipf 1.5)']::text[], '99762afa-59c1-4c2e-a5e4-2262b3d2a431') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39528, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "身", "is_correct": true, "explanation": "かがむのは体全体なので「身をかがめる」。"}, {"text": "声", "is_correct": false, "explanation": "「声をかがめる」は言わず、姿勢の話に合わない。"}, {"text": "紙", "is_correct": false, "explanation": "「紙をかがめる」は意味をなさず、頭をぶつける文脈に合わない。"}, {"text": "色", "is_correct": false, "explanation": "「色をかがめる」は成立せず、文の内容に合わない。"}], "explanations": {"身": "かがむのは体全体なので「身をかがめる」。", "声": "「声をかがめる」は言わず、姿勢の話に合わない。", "紙": "「紙をかがめる」は意味をなさず、頭をぶつける文脈に合わない。", "色": "「色をかがめる」は成立せず、文の内容に合わない。"}, "sentence_index": 0, "correct_answer": "身"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は身を横に振って、答えを拒んだ。", "explanation": "ここは〈首〉の意味（首を横に振る）。身を横に振るとは言わず、この文では合わない。"}, {"text": "彼女は身を込めて、手作りのケーキを焼いた。", "explanation": "ここは〈心〉の意味。「心を込める」の心を身に置き換えており、からだを指す身では言わない。"}, {"text": "彼は驚いて身を抜かし、その場に座り込んだ。", "explanation": "ここは〈腰〉の意味（腰を抜かす）。身を抜かすとは言わず、この文では合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74db7eed-5d9a-45a8-a0e9-e766affdf1f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39528, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "身", "is_correct": true, "explanation": "ベッドに投げ出すのはからだなので「疲れた身」。"}, {"text": "空", "is_correct": false, "explanation": "「疲れた空をベッドに投げ出す」は成立せず、文の内容に合わない。"}, {"text": "波", "is_correct": false, "explanation": "「疲れた波をベッドに投げ出す」は意味をなさない。"}, {"text": "雲", "is_correct": false, "explanation": "「疲れた雲をベッドに投げ出す」は不自然で、この文に合わない。"}], "explanations": {"身": "ベッドに投げ出すのはからだなので「疲れた身」。", "空": "「疲れた空をベッドに投げ出す」は成立せず、文の内容に合わない。", "波": "「疲れた波をベッドに投げ出す」は意味をなさない。", "雲": "「疲れた雲をベッドに投げ出す」は不自然で、この文に合わない。"}, "sentence_index": 6, "correct_answer": "身"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は身の肩を落として、がっかりしていた。", "explanation": "ここは〈肩〉の意味（肩を落とす）。身の肩とは言わず、この文では合わない。"}, {"text": "彼女は身を細めて、遠くの景色を見た。", "explanation": "ここは〈目〉の意味。「目を細める」の目を身に置き換えており、この言い方はしない。"}, {"text": "彼は身を殺して、音を立てないようにした。", "explanation": "ここは〈息〉の意味（息を殺す）。身を殺すとは言わず、この文では合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74db7eed-5d9a-45a8-a0e9-e766affdf1f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39528, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "寒い夜は布団の中で身が縮めて眠る。", "corrected_sentence": "寒い夜は布団の中で身を縮めて眠る。", "error_description": "「身」に係る助詞は「を」（身を縮める）。「が」にすると身が主語になり、他動詞「縮める」の目的語にならない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74db7eed-5d9a-45a8-a0e9-e766affdf1f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39528, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "風邪をひいた身が、布団で休ませた。", "corrected_sentence": "風邪をひいた身を、布団で休ませた。", "error_description": "「身」に係る助詞は「を」（休ませる対象）。「が」にすると身が主語になり、他動詞「休ませる」の目的語にならない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74db7eed-5d9a-45a8-a0e9-e766affdf1f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39529, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "置く対象の身を表すので「を」。"}, {"text": "に", "is_correct": false, "explanation": "「身に置く」とは言わず、置く対象を表せない。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所の「で」では、置く対象の身にならない。"}, {"text": "が", "is_correct": false, "explanation": "「身が置く」では身が主語になり、置く動作の対象にならない。"}], "correct_answer": "を", "explanations": {"を": "置く対象の身を表すので「を」。", "に": "「身に置く」とは言わず、置く対象を表せない。", "で": "手段や場所の「で」では、置く対象の身にならない。", "が": "「身が置く」では身が主語になり、置く動作の対象にならない。"}, "error_tags": {"に": "置く先の場所", "で": "手段・場所", "が": "主語"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74db7eed-5d9a-45a8-a0e9-e766affdf1f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
