INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39529, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "からだ。また、自分自身。", "primary_collocate": null, "pronunciation": "み", "ipa": "mi", "syllable_count": 1, "sentences": [{"text": "彼は不器用ながらも、分厚いコートの袖に腕を通し、冷気から身を守るための鎧を着る。", "target_word": "身", "complexity_tier": "T3", "furigana": "彼[かれ]は不器用[ぶきよう]ながらも、分厚[ぶあつ]いコートの袖[そで]に腕[うで]を通[とお]し、冷気[れいき]から身[み]を守[まも]るための鎧[よろい]を着[き]る。", "sentence_source": "mined"}, {"text": "責任ある立場に身を置くと、判断の重さがよくわかる。", "target_word": "身", "complexity_tier": "T3", "furigana": "責任[せきにん]ある立場[たちば]に身[み]を置[お]くと、判断[はんだん]の重[おも]さがよくわかる。", "sentence_source": "generated"}, {"text": "山道で急に雨が降り、小さな木の下に身を隠した。", "target_word": "身", "complexity_tier": "T3", "furigana": "山道[やまみち]で急[きゅう]に雨[あめ]が降[ふ]り、小[ちい]さな木[き]の下[した]に身[み]を隠[かく]した。", "sentence_source": "generated"}, {"text": "彼は自分の身に起きたことを、静かに友人に話した。", "target_word": "身", "complexity_tier": "T3", "furigana": "彼[かれ]は自分[じぶん]の身[み]に起[お]きたことを、静[しず]かに友人[ゆうじん]に話[はな]した。", "sentence_source": "generated"}, {"text": "危険を感じたので、すぐに身をかわして車を避けた。", "target_word": "身", "complexity_tier": "T3", "furigana": "危険[きけん]を感[かん]じたので、すぐに身[み]をかわして車[くるま]を避[さ]けた。", "sentence_source": "generated"}, {"text": "新しい制服に身を包んだ妹は、少し緊張した顔で玄関に立っていた。", "target_word": "身", "complexity_tier": "T3", "furigana": "新[あたら]しい制服[せいふく]に身[み]を包[つつ]んだ妹[いもうと]は、少[すこ]し緊張[きんちょう]した顔[かお]で玄関[げんかん]に立[た]っていた。", "sentence_source": "generated"}, {"text": "他人の話だと思っていたが、いざ自分の身に降りかかると何もできなかった。", "target_word": "身", "complexity_tier": "T4", "furigana": "他人[たにん]の話[はなし]だと思[おも]っていたが、いざ自分[じぶん]の身[み]に降[ふ]りかかると何[なに]もできなかった。", "sentence_source": "generated"}, {"text": "長い旅を終えて、ようやく家で身を休めることができた。", "target_word": "身", "complexity_tier": "T3", "furigana": "長[なが]い旅[たび]を終[お]えて、ようやく家[いえ]で身[み]を休[やす]めることができた。", "sentence_source": "generated"}, {"text": "先生は私の身を案じて、夜は一人で歩かないように言った。", "target_word": "身", "complexity_tier": "T3", "furigana": "先生[せんせい]は私[わたし]の身[み]を案[あん]じて、夜[よる]は一人[ひとり]で歩[ある]かないように言[い]った。", "sentence_source": "generated"}, {"text": "私は身の安全を第一に考えて、夜の外出をやめた。", "target_word": "身", "complexity_tier": "T3", "furigana": "私[わたし]は身[み]の安全[あんぜん]を第一[だいいち]に考[かんが]えて、夜[よる]の外出[がいしゅつ]をやめた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "身", "label": "基本形"}], "register": "標準", "sense_fingerprint": "身|からだ、また自分自身(身を守る・身に起きる)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99762afa-59c1-4c2e-a5e4-2262b3d2a431') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39529, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "身", "is_correct": true, "explanation": "冷気から守る対象は自分のからだなので「身」が入る。"}, {"text": "声", "is_correct": false, "explanation": "「冷気から声を守る」とは言わず、鎧で守る対象にもならない。"}, {"text": "色", "is_correct": false, "explanation": "「冷気から色を守る」は意味が通らず、鎧を着る理由にならない。"}, {"text": "空", "is_correct": false, "explanation": "「冷気から空を守る」は成立せず、文脈に合わない。"}], "explanations": {"身": "冷気から守る対象は自分のからだなので「身」が入る。", "声": "「冷気から声を守る」とは言わず、鎧で守る対象にもならない。", "色": "「冷気から色を守る」は意味が通らず、鎧を着る理由にならない。", "空": "「冷気から空を守る」は成立せず、文脈に合わない。"}, "sentence_index": 0, "correct_answer": "身"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は身を貸して、友人の引っ越しを手伝った。", "explanation": "ここは〈手〉の意味（手を貸す）。身は「手を貸す」の手の代わりにはならないので、この言い方はしない。"}, {"text": "彼は身の底から彼女を心配していた。", "explanation": "ここは〈心〉の意味。「心の底から」の心を身に置き換えており、からだを指す身では言わない。"}, {"text": "彼の見事な演奏には、思わず身を巻いた。", "explanation": "ここは〈舌〉の意味（舌を巻く）。身を巻くとは言わず、この文では合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74db7eed-5d9a-45a8-a0e9-e766affdf1f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39529, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "身", "is_correct": true, "explanation": "降りかかるのは自分のからだ・自分自身なので「自分の身」。"}, {"text": "紙", "is_correct": false, "explanation": "「自分の紙に降りかかる」は意味をなさず、文脈に合わない。"}, {"text": "波", "is_correct": false, "explanation": "「自分の波に降りかかる」は成立せず、比喩としても通じない。"}, {"text": "雲", "is_correct": false, "explanation": "「自分の雲に降りかかる」は不自然で、この文の内容に合わない。"}], "explanations": {"身": "降りかかるのは自分のからだ・自分自身なので「自分の身」。", "紙": "「自分の紙に降りかかる」は意味をなさず、文脈に合わない。", "波": "「自分の波に降りかかる」は成立せず、比喩としても通じない。", "雲": "「自分の雲に降りかかる」は不自然で、この文の内容に合わない。"}, "sentence_index": 6, "correct_answer": "身"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女は身をなで下ろして、ゆっくりと椅子に座った。", "explanation": "ここは〈胸〉の意味（胸をなで下ろす）。身をなで下ろすとは言わず、この文では合わない。"}, {"text": "彼は身を抜かして、その場に座り込んだ。", "explanation": "ここは〈腰〉の意味（腰を抜かす）。身を抜かすとは言わず、この文では合わない。"}, {"text": "彼女は身を閉じて、静かに音楽を聞いた。", "explanation": "ここは〈目〉の意味。「目を閉じる」の目を身に置き換えており、この言い方はしない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74db7eed-5d9a-45a8-a0e9-e766affdf1f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39529, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "寒い日は、暖かい部屋で身が休めることにした。", "corrected_sentence": "寒い日は、暖かい部屋で身を休めることにした。", "error_description": "「身」に係る助詞は「を」（身を休める）。「が」にすると身が主語になり、他動詞「休める」の目的語にならない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74db7eed-5d9a-45a8-a0e9-e766affdf1f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39529, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "寒さで冷えた身が、熱いお茶で温めた。", "corrected_sentence": "寒さで冷えた身を、熱いお茶で温めた。", "error_description": "「身」に係る助詞は「を」（温める対象）。「が」にすると身が主語になり、「温めた」の目的語にならない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74db7eed-5d9a-45a8-a0e9-e766affdf1f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
