INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39530, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「リンゴを食べた」の「を」は、食べる対象（リンゴ）を示す。"}, {"text": "が", "is_correct": false, "explanation": "主語の「が」だと「リンゴが食べた」となり、食べる対象として不自然。"}, {"text": "に", "is_correct": false, "explanation": "相手や場所を示す「に」は、食べる対象にならない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」は、食べる対象にならない。"}], "correct_answer": "を", "explanations": {"を": "「リンゴを食べた」の「を」は、食べる対象（リンゴ）を示す。", "が": "主語の「が」だと「リンゴが食べた」となり、食べる対象として不自然。", "に": "相手や場所を示す「に」は、食べる対象にならない。", "へ": "方向を示す「へ」は、食べる対象にならない。"}, "error_tags": {"が": "主語にすると「林檎が食べた」で不自然", "に": "相手や場所を示し、食べる対象にならない", "へ": "方向を示し、食べる対象にならない"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50db52b9-91c9-4847-af4b-a4928aa63ecd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39530, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "あかいくだもので、たべるとあまいです。", "primary_collocate": null, "pronunciation": "りんご", "ipa": "ɾiŋɡo", "syllable_count": 3, "sentences": [{"text": "赤いリンゴを一つ、かごに入れた。", "target_word": "リンゴ", "complexity_tier": "T3", "furigana": "赤[あか]いリンゴを一[ひと]つ、かごに入[い]れた。", "sentence_source": "generated"}, {"text": "リンゴは甘くて、私の大好きなくだものだ。", "target_word": "リンゴ", "complexity_tier": "T3", "furigana": "リンゴは甘[あま]くて、私[わたし]の大好[だいす]きなくだものだ。", "sentence_source": "generated"}, {"text": "弟はおやつにリンゴを食べた。", "target_word": "リンゴ", "complexity_tier": "T3", "furigana": "弟[おとうと]はおやつにリンゴを食[た]べた。", "sentence_source": "generated"}, {"text": "木の下に林檎がころがっている。", "target_word": "林檎", "complexity_tier": "T3", "furigana": "木[き]の下[した]に林檎[りんご]がころがっている。", "sentence_source": "generated"}, {"text": "スーパーで、リンゴを三つ買った。", "target_word": "リンゴ", "complexity_tier": "T3", "furigana": "スーパーで、リンゴを三[みっ]つ買[か]った。", "sentence_source": "generated"}, {"text": "母がリンゴを小さく切って、お皿に出してくれた。", "target_word": "リンゴ", "complexity_tier": "T3", "furigana": "母[はは]がリンゴを小[ちい]さく切[き]って、お皿[さら]に出[だ]してくれた。", "sentence_source": "generated"}, {"text": "このリンゴは赤くて、とても甘い。", "target_word": "リンゴ", "complexity_tier": "T3", "furigana": "このリンゴは赤[あか]くて、とても甘[あま]い。", "sentence_source": "generated"}, {"text": "朝ごはんに、パンとリンゴを食べた。", "target_word": "リンゴ", "complexity_tier": "T3", "furigana": "朝[あさ]ごはんに、パンとリンゴを食[た]べた。", "sentence_source": "generated"}, {"text": "先生に、赤いリンゴをひとつあげた。", "target_word": "リンゴ", "complexity_tier": "T3", "furigana": "先生[せんせい]に、赤[あか]いリンゴをひとつあげた。", "sentence_source": "generated"}, {"text": "おなかがすいたので、リンゴをかじった。", "target_word": "リンゴ", "complexity_tier": "T3", "furigana": "おなかがすいたので、リンゴをかじった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "林檎", "label": "基本形（漢字表記）"}, {"form": "リンゴ", "label": "カタカナ表記"}, {"form": "りんご", "label": "ひらがな表記"}], "register": "中立（日常的）", "sense_fingerprint": "赤くて甘いくだもの", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f0678b8-7528-4b42-8e6f-0845db3ee1bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39530, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "リンゴ", "is_correct": true, "explanation": "「赤いリンゴを一つ」は、赤くて甘い果物として自然な描写。"}, {"text": "バナナ", "is_correct": false, "explanation": "バナナは黄色い果物で、「赤いバナナ」とは言わない。"}, {"text": "レモン", "is_correct": false, "explanation": "レモンは黄色い果物で、赤いとは言わない。"}, {"text": "メロン", "is_correct": false, "explanation": "メロンは緑や黄色の果物で、赤いメロンは一般的でない。"}], "explanations": {"リンゴ": "「赤いリンゴを一つ」は、赤くて甘い果物として自然な描写。", "バナナ": "バナナは黄色い果物で、「赤いバナナ」とは言わない。", "レモン": "レモンは黄色い果物で、赤いとは言わない。", "メロン": "メロンは緑や黄色の果物で、赤いメロンは一般的でない。"}, "sentence_index": 0, "correct_answer": "リンゴ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "スーパーで林檎を一本買った。", "explanation": "林檎は「個」で数える。「本」は細長いもの（バナナなど）の数え方なので、ここは〈バナナ〉の数え方との混同。"}, {"text": "林檎を一匹かじった。", "explanation": "「匹」は動物の数え方。林檎は「個」で数えるので、ここは〈動物〉の数え方との混同。"}, {"text": "林檎を一粒かじった。", "explanation": "「粒」は小さな粒状のものの数え方。林檎は「個」で数えるので、ここは〈ぶどう〉の数え方との混同。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50db52b9-91c9-4847-af4b-a4928aa63ecd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39530, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "リンゴ", "is_correct": true, "explanation": "「このリンゴは赤くて、とても甘い」は、赤くて甘い果物として自然。"}, {"text": "みかん", "is_correct": false, "explanation": "みかんは橙色で、赤いとは言わない。"}, {"text": "パイナップル", "is_correct": false, "explanation": "パイナップルは黄色く、赤いとは言わない。"}, {"text": "キウイ", "is_correct": false, "explanation": "キウイは緑色で、赤いとは言わない。"}], "explanations": {"リンゴ": "「このリンゴは赤くて、とても甘い」は、赤くて甘い果物として自然。", "みかん": "みかんは橙色で、赤いとは言わない。", "パイナップル": "パイナップルは黄色く、赤いとは言わない。", "キウイ": "キウイは緑色で、赤いとは言わない。"}, "sentence_index": 6, "correct_answer": "リンゴ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "スーパーで林檎を一玉買った。", "explanation": "「玉」はキャベツなど丸く大きな野菜の数え方。林檎は「個」で数えるので、ここは〈キャベツ〉の数え方との混同。"}, {"text": "林檎を一房買った。", "explanation": "「房」はぶどうなどの数え方。林檎は「個」で数えるので、ここは〈ぶどう〉の数え方との混同。"}, {"text": "スーパーで林檎を一枚買った。", "explanation": "「枚」は紙など薄いものの数え方。林檎は「個」で数えるので、ここは〈紙〉の数え方との混同。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50db52b9-91c9-4847-af4b-a4928aa63ecd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39530, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夕方の畑で、真っ赤な林檎が一つもぎ取った。", "corrected_sentence": "夕方の畑で、真っ赤な林檎を一つもぎ取った。", "error_description": "誤りは「林檎が」（主語の「が」）。正しくは「林檎を」（もぎ取る対象の「を」）。「もぎ取る」は他動詞なので、対象は「を」で示す。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50db52b9-91c9-4847-af4b-a4928aa63ecd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39530, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "机の上に、林檎で三つ置いてあった。", "corrected_sentence": "机の上に、林檎が三つ置いてあった。", "error_description": "誤りは「林檎で」（手段の「で」）。正しくは「林檎が」（存在する主体の「が」）。「置いてある」は存在を示す文で、林檎は主語になる。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50db52b9-91c9-4847-af4b-a4928aa63ecd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39531, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「リンゴが赤く色づく」の「が」は、色づく主体（リンゴ）を示す主語。"}, {"text": "を", "is_correct": false, "explanation": "「色づく」は自動詞で目的語を取れないので、「を」は不自然。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」は主語にならず、「色づく」の主体と合わない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は主語にならず、色づく主体を示せない。"}], "correct_answer": "が", "explanations": {"が": "「リンゴが赤く色づく」の「が」は、色づく主体（リンゴ）を示す主語。", "を": "「色づく」は自動詞で目的語を取れないので、「を」は不自然。", "へ": "方向の「へ」は主語にならず、「色づく」の主体と合わない。", "に": "「に」は主語にならず、色づく主体を示せない。"}, "error_tags": {"を": "自動詞「色づく」は目的語を取れない", "へ": "方向を示すため主語にならない", "に": "主語にならず、色づく主体と合わない"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50db52b9-91c9-4847-af4b-a4928aa63ecd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39531, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「リンゴを洗っている」の「を」は、洗う対象（リンゴ）を示す。"}, {"text": "が", "is_correct": false, "explanation": "主語の「が」だと「リンゴが台所で洗っている」となり、洗う対象として不自然。"}, {"text": "と", "is_correct": false, "explanation": "並列の「と」では洗う対象が一つに決まらず、文が成立しない。"}, {"text": "で", "is_correct": false, "explanation": "手段の「で」だと洗う対象が示せず、文が成立しない。"}], "correct_answer": "を", "explanations": {"を": "「リンゴを洗っている」の「を」は、洗う対象（リンゴ）を示す。", "が": "主語の「が」だと「リンゴが台所で洗っている」となり、洗う対象として不自然。", "と": "並列の「と」では洗う対象が一つに決まらず、文が成立しない。", "で": "手段の「で」だと洗う対象が示せず、文が成立しない。"}, "error_tags": {"が": "洗う対象を主語にすると不自然", "と": "並列の相手がなく文が成立しない", "で": "手段を示し、洗う対象を表せない"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50db52b9-91c9-4847-af4b-a4928aa63ecd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39531, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "木になる果物で、赤や黄色の皮があり、甘酸っぱい味がします。", "primary_collocate": null, "pronunciation": "りんご", "ipa": "ɾiŋɡo", "syllable_count": 3, "sentences": [{"text": "それはまさに、自然の営みと時間が凝縮したかような深紅を纏うリンゴであった。", "target_word": "リンゴ", "complexity_tier": "T4", "furigana": "それはまさに、自然[しぜん]の営[いとな]みと時間[じかん]が凝縮[ぎょうしゅく]したかような深紅[しんく]を纏[まと]うリンゴであった。", "sentence_source": "mined"}, {"text": "秋になると、木になったリンゴが赤く色づく。", "target_word": "リンゴ", "complexity_tier": "T3", "furigana": "秋[あき]になると、木[き]になったリンゴが赤[あか]く色[いろ]づく。", "sentence_source": "generated"}, {"text": "祖母は黄色い皮のリンゴを、薄く切ってくれた。", "target_word": "リンゴ", "complexity_tier": "T3", "furigana": "祖母[そぼ]は黄色[きいろ]い皮[かわ]のリンゴを、薄[うす]く切[き]ってくれた。", "sentence_source": "generated"}, {"text": "このリンゴは甘酸っぱくて、パイに入れるとおいしい。", "target_word": "リンゴ", "complexity_tier": "T3", "furigana": "このリンゴは甘酸[あまず]っぱくて、パイに入[い]れるとおいしい。", "sentence_source": "generated"}, {"text": "農家の人が、はしごに登ってリンゴを収穫している。", "target_word": "リンゴ", "complexity_tier": "T3", "furigana": "農家[のうか]の人[ひと]が、はしごに登[のぼ]ってリンゴを収穫[しゅうかく]している。", "sentence_source": "generated"}, {"text": "リンゴの皮をむくと、白い実から果汁があふれた。", "target_word": "リンゴ", "complexity_tier": "T3", "furigana": "リンゴの皮[かわ]をむくと、白[しろ]い実[み]から果汁[かじゅう]があふれた。", "sentence_source": "generated"}, {"text": "青森はリンゴの産地として、全国に知られている。", "target_word": "リンゴ", "complexity_tier": "T3", "furigana": "青森[あおもり]はリンゴの産地[さんち]として、全国[ぜんこく]に知[し]られている。", "sentence_source": "generated"}, {"text": "祖母は、畑でとれたリンゴを台所で洗っている。", "target_word": "リンゴ", "complexity_tier": "T3", "furigana": "祖母[そぼ]は、畑[はたけ]でとれたリンゴを台所[だいどころ]で洗っている。", "sentence_source": "generated"}, {"text": "毎朝、リンゴを一個食べるようにしている。", "target_word": "リンゴ", "complexity_tier": "T3", "furigana": "毎朝[まいあさ]、リンゴを一個[いっこ]食[た]べるようにしている。", "sentence_source": "generated"}, {"text": "風でリンゴが枝から落ち、地面にころがった。", "target_word": "リンゴ", "complexity_tier": "T3", "furigana": "風[かぜ]でリンゴが枝[えだ]から落[お]ち、地面[じめん]にころがった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "林檎", "label": "基本形（漢字表記）"}, {"form": "リンゴ", "label": "カタカナ表記"}, {"form": "りんご", "label": "ひらがな表記"}], "register": "中立（日常的）", "sense_fingerprint": "木になる、赤や黄色の皮で甘酸っぱい味の果物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T3: 4 words above tier T3 (max 3): 営み (Zipf 3.27), 凝縮 (Zipf 3.38), 深紅 (Zipf 2.91), 纏う (Zipf 2.77)']::text[], '6f0678b8-7528-4b42-8e6f-0845db3ee1bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39531, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "リンゴ", "is_correct": true, "explanation": "深紅を纏う果物として、自然の営みが凝縮したリンゴは文の描写に合う。"}, {"text": "バナナ", "is_correct": false, "explanation": "バナナは黄色い果物で、深紅を纏うという描写には合わない。"}, {"text": "みかん", "is_correct": false, "explanation": "みかんは橙色で、深紅を纏うという描写には合わない。"}, {"text": "レモン", "is_correct": false, "explanation": "レモンは黄色い果物で、深紅を纏うという描写には合わない。"}], "explanations": {"リンゴ": "深紅を纏う果物として、自然の営みが凝縮したリンゴは文の描写に合う。", "バナナ": "バナナは黄色い果物で、深紅を纏うという描写には合わない。", "みかん": "みかんは橙色で、深紅を纏うという描写には合わない。", "レモン": "レモンは黄色い果物で、深紅を纏うという描写には合わない。"}, "sentence_index": 0, "correct_answer": "リンゴ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "スーパーでリンゴを一本買った。", "explanation": "リンゴは「個」で数える。「本」は細長いもの（バナナなど）の数え方なので、ここは〈バナナ〉の数え方との混同。"}, {"text": "林檎を一匹かじった。", "explanation": "「匹」は動物の数え方。林檎は「個」で数えるので、ここは〈動物〉の数え方との混同。"}, {"text": "リンゴを一粒かじった。", "explanation": "「粒」は小さな粒状のものの数え方。リンゴは「個」で数えるので、ここは〈ぶどう〉の数え方との混同。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50db52b9-91c9-4847-af4b-a4928aa63ecd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39531, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "リンゴ", "is_correct": true, "explanation": "青森がリンゴの産地として知られているという事実に合う。"}, {"text": "マンゴー", "is_correct": false, "explanation": "マンゴーは青森の産地ではなく、この文の事実と合わない。"}, {"text": "キウイ", "is_correct": false, "explanation": "キウイは青森の産地として知られておらず、文脈に合わない。"}, {"text": "パイナップル", "is_correct": false, "explanation": "パイナップルは青森の名産ではなく、この文の事実と合わない。"}], "explanations": {"リンゴ": "青森がリンゴの産地として知られているという事実に合う。", "マンゴー": "マンゴーは青森の産地ではなく、この文の事実と合わない。", "キウイ": "キウイは青森の産地として知られておらず、文脈に合わない。", "パイナップル": "パイナップルは青森の名産ではなく、この文の事実と合わない。"}, "sentence_index": 6, "correct_answer": "リンゴ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "リンゴを一房買った。", "explanation": "「房」はぶどうなどの数え方。リンゴは「個」で数えるので、ここは〈ぶどう〉の数え方との混同。"}, {"text": "スーパーでリンゴを一玉買った。", "explanation": "「玉」はキャベツなど丸く大きな野菜の数え方。リンゴは「個」で数えるので、ここは〈キャベツ〉の数え方との混同。"}, {"text": "スーパーでリンゴを一枚買った。", "explanation": "「枚」は紙など薄いものの数え方。リンゴは「個」で数えるので、ここは〈紙〉の数え方との混同。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50db52b9-91c9-4847-af4b-a4928aa63ecd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39531, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "枝についたリンゴが、手で摘み取った。", "corrected_sentence": "枝についたリンゴを、手で摘み取った。", "error_description": "誤りは「リンゴが」（主語の「が」）。正しくは「リンゴを」（摘み取る対象の「を」）。「摘み取る」は他動詞なので、対象は「を」で示す。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50db52b9-91c9-4847-af4b-a4928aa63ecd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39531, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "市場に並んでいる真っ赤なリンゴが一つ選んだ。", "corrected_sentence": "市場に並んでいる真っ赤なリンゴを一つ選んだ。", "error_description": "誤りは「リンゴが」（主語の「が」）。正しくは「リンゴを」（選ぶ対象の「を」）。「選ぶ」は他動詞なので、対象は「を」で示す。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50db52b9-91c9-4847-af4b-a4928aa63ecd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39532, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「この胡瓜は細長くて」の「は」。胡瓜について述べる主題を示す。"}, {"text": "を", "is_correct": false, "explanation": "「この胡瓜を細長くて」は成り立たない。「を」は動作の対象を示すが、形容の文には合わない。"}, {"text": "に", "is_correct": false, "explanation": "「この胡瓜に細長くて」は不自然。「に」の受け手や到着点がない。"}, {"text": "で", "is_correct": false, "explanation": "「この胡瓜で細長くて」は意味が通らない。「で」の手段や場所の意味が合わない。"}], "correct_answer": "は", "explanations": {"は": "「この胡瓜は細長くて」の「は」。胡瓜について述べる主題を示す。", "を": "「この胡瓜を細長くて」は成り立たない。「を」は動作の対象を示すが、形容の文には合わない。", "に": "「この胡瓜に細長くて」は不自然。「に」の受け手や到着点がない。", "で": "「この胡瓜で細長くて」は意味が通らない。「で」の手段や場所の意味が合わない。"}, "error_tags": {"を": "object: no verb fits", "に": "dative: no receiver", "で": "means: no fit"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bad1c4d-f01b-4f87-8fe3-07018ad5ba8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39532, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「庭の胡瓜に花がさいた」の「に」。胡瓜の場所を示し、花が咲いた場所として自然。"}, {"text": "を", "is_correct": false, "explanation": "「庭の胡瓜を花がさいた」は成り立たない。「を」は咲く動作の対象にならない。"}, {"text": "へ", "is_correct": false, "explanation": "「胡瓜へ花がさいた」は方向の意味になり不自然。咲く場所を示す語ではない。"}, {"text": "から", "is_correct": false, "explanation": "「胡瓜から花がさいた」は起点を示すことになり、ここでは意味が合わない。"}], "correct_answer": "に", "explanations": {"に": "「庭の胡瓜に花がさいた」の「に」。胡瓜の場所を示し、花が咲いた場所として自然。", "を": "「庭の胡瓜を花がさいた」は成り立たない。「を」は咲く動作の対象にならない。", "へ": "「胡瓜へ花がさいた」は方向の意味になり不自然。咲く場所を示す語ではない。", "から": "「胡瓜から花がさいた」は起点を示すことになり、ここでは意味が合わない。"}, "error_tags": {"を": "object: no verb fits", "へ": "direction: not a place of blooming", "から": "source: wrong meaning here"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bad1c4d-f01b-4f87-8fe3-07018ad5ba8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39532, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "みどりの　やさいで、ほそながい　かたちです。", "primary_collocate": null, "pronunciation": "きゅうり", "ipa": "kʲɯːɾi", "syllable_count": 3, "sentences": [{"text": "夏になると、母は毎日胡瓜を食べる。", "target_word": "胡瓜", "complexity_tier": "T3", "furigana": "夏[なつ]になると、母[はは]は毎日[まいにち]胡瓜[きゅうり]を食[た]べる。", "sentence_source": "generated"}, {"text": "この胡瓜は細長くて、色がこい緑だ。", "target_word": "胡瓜", "complexity_tier": "T3", "furigana": "この胡瓜[きゅうり]は細長[ほそなが]くて、色[いろ]がこい緑[みどり]だ。", "sentence_source": "generated"}, {"text": "畑で採れたての胡瓜は、水分が多くてみずみずしい。", "target_word": "胡瓜", "complexity_tier": "T3", "furigana": "畑[はたけ]で採[と]れたての胡瓜[きゅうり]は、水分[すいぶん]が多[おお]くてみずみずしい。", "sentence_source": "generated"}, {"text": "胡瓜を薄く切って、サラダに入れた。", "target_word": "胡瓜", "complexity_tier": "T3", "furigana": "胡瓜[きゅうり]を薄[うす]く切[き]って、サラダに入[い]れた。", "sentence_source": "generated"}, {"text": "弟は胡瓜が苦手で、いつも残してしまう。", "target_word": "胡瓜", "complexity_tier": "T3", "furigana": "弟[おとうと]は胡瓜[きゅうり]が苦手[にがて]で、いつも残[のこ]してしまう。", "sentence_source": "generated"}, {"text": "スーパーで胡瓜を三本買ってきた。", "target_word": "胡瓜", "complexity_tier": "T3", "furigana": "スーパーで胡瓜[きゅうり]を三本[さんぼん]買[か]ってきた。", "sentence_source": "generated"}, {"text": "胡瓜は冷蔵庫に入れると、冷たくておいしい。", "target_word": "胡瓜", "complexity_tier": "T3", "furigana": "胡瓜[きゅうり]は冷蔵庫[れいぞうこ]に入[い]れると、冷[つめ]たくておいしい。", "sentence_source": "generated"}, {"text": "庭の胡瓜に、小さな黄色い花がさいた。", "target_word": "胡瓜", "complexity_tier": "T3", "furigana": "庭[にわ]の胡瓜[きゅうり]に、小[ちい]さな黄色[きいろ]い花[はな]がさいた。", "sentence_source": "generated"}, {"text": "胡瓜のつるが、ささえの棒にからまっている。", "target_word": "胡瓜", "complexity_tier": "T3", "furigana": "胡瓜[きゅうり]のつるが、ささえの棒[ぼう]にからまっている。", "sentence_source": "generated"}, {"text": "胡瓜と、トマトと、レタスでサラダを作った。", "target_word": "胡瓜", "complexity_tier": "T3", "furigana": "胡瓜[きゅうり]と、トマトと、レタスでサラダを作[つく]った。", "sentence_source": "generated"}], "morphological_forms": [], "register": "neutral", "sense_fingerprint": "緑色で細長い、生で食べる身近な野菜", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48ed5f6e-9d04-40a4-a25c-2e0d32e54d62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39532, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "胡瓜", "is_correct": true, "explanation": "「毎日胡瓜を食べる」は自然な文。胡瓜は生で食べる野菜なので文脈に合う。"}, {"text": "石鹸", "is_correct": false, "explanation": "「毎日石鹸を食べる」は成り立たない。石鹸は食べ物ではない。"}, {"text": "手紙", "is_correct": false, "explanation": "「毎日手紙を食べる」は意味が通らない。手紙は食べる対象にならない。"}, {"text": "切手", "is_correct": false, "explanation": "「毎日切手を食べる」は成り立たない。切手は食べ物ではない。"}], "explanations": {"胡瓜": "「毎日胡瓜を食べる」は自然な文。胡瓜は生で食べる野菜なので文脈に合う。", "石鹸": "「毎日石鹸を食べる」は成り立たない。石鹸は食べ物ではない。", "手紙": "「毎日手紙を食べる」は意味が通らない。手紙は食べる対象にならない。", "切手": "「毎日切手を食べる」は成り立たない。切手は食べ物ではない。"}, "sentence_index": 0, "correct_answer": "胡瓜"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "胡瓜は冬の寒い日に、鍋で煮込んでおでんにする。", "explanation": "ここは〈大根〉の意味。胡瓜は煮込むと崩れやすく、おでんの具にはしないので合わない。"}, {"text": "胡瓜の葉を一枚ずつはがして、塩で漬けた。", "explanation": "ここは〈白菜〉の意味。胡瓜は葉を重ねて漬ける野菜ではなく、この作業は合わない。"}, {"text": "胡瓜を縦に割って、りんごのようにパイに焼いた。", "explanation": "ここは〈りんご〉の意味。パイに焼くのはりんごで、胡瓜には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bad1c4d-f01b-4f87-8fe3-07018ad5ba8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39532, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "胡瓜", "is_correct": true, "explanation": "「胡瓜は冷蔵庫に入れると」は胡瓜を冷やす話として自然。"}, {"text": "鍵", "is_correct": false, "explanation": "「鍵は冷蔵庫に入れると、冷たくておいしい」は成り立たない。鍵は食べ物ではない。"}, {"text": "帽子", "is_correct": false, "explanation": "「帽子は冷蔵庫に入れると、おいしい」は意味が通らない。帽子は食べ物ではない。"}, {"text": "座布団", "is_correct": false, "explanation": "「座布団は冷蔵庫に入れると、おいしい」は成り立たない。座布団は食べ物ではない。"}], "explanations": {"胡瓜": "「胡瓜は冷蔵庫に入れると」は胡瓜を冷やす話として自然。", "鍵": "「鍵は冷蔵庫に入れると、冷たくておいしい」は成り立たない。鍵は食べ物ではない。", "帽子": "「帽子は冷蔵庫に入れると、おいしい」は意味が通らない。帽子は食べ物ではない。", "座布団": "「座布団は冷蔵庫に入れると、おいしい」は成り立たない。座布団は食べ物ではない。"}, "sentence_index": 6, "correct_answer": "胡瓜"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "胡瓜を薄切りにして、涙が出るまで水にさらした。", "explanation": "ここは〈玉ねぎ〉の意味。涙が出るほど水にさらす野菜は玉ねぎで、胡瓜には合わない。"}, {"text": "胡瓜の殻を割って、中の豆を取り出した。", "explanation": "ここは〈落花生〉の意味。殻を割って中の豆を取り出すのは落花生で、胡瓜には合わない。"}, {"text": "胡瓜をすりおろして、オレンジ色のジュースにした。", "explanation": "ここは〈人参〉の意味。オレンジ色のジュースにするのは人参で、胡瓜には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bad1c4d-f01b-4f87-8fe3-07018ad5ba8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39532, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "胡瓜を好きで、毎日サラダにする。", "corrected_sentence": "胡瓜が好きで、毎日サラダにする。", "error_description": "「好きだ」は「が」を取る。胡瓜に続く助詞が「を」になっているのは誤りで、正しくは「胡瓜が」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bad1c4d-f01b-4f87-8fe3-07018ad5ba8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39532, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "胡瓜を薄く切りし、塩をふった。", "corrected_sentence": "胡瓜を薄く切り、塩をふった。", "error_description": "「切る」の過去は「切った」。「切りし」は文語的な古い形で、現代の文では使わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bad1c4d-f01b-4f87-8fe3-07018ad5ba8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39533, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「胡瓜の表面」の「の」。胡瓜に属する表面を示し、後ろの名詞につながる。"}, {"text": "を", "is_correct": false, "explanation": "「胡瓜を表面には」は成り立たない。「を」は動作の対象で、名詞を結ぶ用法ではない。"}, {"text": "に", "is_correct": false, "explanation": "「胡瓜に表面には」は不自然。「に」の受け手や場所がなく、名詞を結べない。"}, {"text": "で", "is_correct": false, "explanation": "「胡瓜で表面には」は意味が通らない。「で」の手段や場所の意味が合わない。"}], "correct_answer": "の", "explanations": {"の": "「胡瓜の表面」の「の」。胡瓜に属する表面を示し、後ろの名詞につながる。", "を": "「胡瓜を表面には」は成り立たない。「を」は動作の対象で、名詞を結ぶ用法ではない。", "に": "「胡瓜に表面には」は不自然。「に」の受け手や場所がなく、名詞を結べない。", "で": "「胡瓜で表面には」は意味が通らない。「で」の手段や場所の意味が合わない。"}, "error_tags": {"を": "object: no verb fits", "に": "dative: no receiver", "で": "means: no fit"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bad1c4d-f01b-4f87-8fe3-07018ad5ba8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39533, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「胡瓜の漬物」の「の」。胡瓜を材料とする漬物を示し、後ろの名詞につながる。"}, {"text": "を", "is_correct": false, "explanation": "「胡瓜を漬物は」は「を」の目的語が動詞を持たず、文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「胡瓜へ漬物は」は方向の意味になり不自然。名詞を結ぶ用法ではない。"}, {"text": "で", "is_correct": false, "explanation": "「胡瓜で漬物は」は手段や場所の意味が合わず、名詞を結べない。"}], "correct_answer": "の", "explanations": {"の": "「胡瓜の漬物」の「の」。胡瓜を材料とする漬物を示し、後ろの名詞につながる。", "を": "「胡瓜を漬物は」は「を」の目的語が動詞を持たず、文が成り立たない。", "へ": "「胡瓜へ漬物は」は方向の意味になり不自然。名詞を結ぶ用法ではない。", "で": "「胡瓜で漬物は」は手段や場所の意味が合わず、名詞を結べない。"}, "error_tags": {"を": "object: no verb fits", "へ": "direction: no fit", "で": "means: no fit"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bad1c4d-f01b-4f87-8fe3-07018ad5ba8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39533, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "きゅうり。うり科の一年草、またはその果実。淡緑色で細長く、多くは表面に小さなとげがある。生で食べることが多い。", "primary_collocate": null, "pronunciation": "きゅうり", "ipa": "kʲɯːɾi", "syllable_count": 3, "sentences": [{"text": "胡瓜はうり科の植物で、細長い実をつける。", "target_word": "胡瓜", "complexity_tier": "T3", "furigana": "胡瓜[きゅうり]はうり科[か]の植物[しょくぶつ]で、細長[ほそなが]い実[み]をつける。", "sentence_source": "generated"}, {"text": "胡瓜の表面には、小さなとげがあることが多い。", "target_word": "胡瓜", "complexity_tier": "T3", "furigana": "胡瓜[きゅうり]の表面[ひょうめん]には、小[ちい]さなとげがあることが多[おお]い。", "sentence_source": "generated"}, {"text": "胡瓜は生で食べることが多く、酢の物にも使う。", "target_word": "胡瓜", "complexity_tier": "T3", "furigana": "胡瓜[きゅうり]は生[なま]で食[た]べることが多[おお]く、酢[す]の物[もの]にも使[つか]う。", "sentence_source": "generated"}, {"text": "市場に並ぶ胡瓜は、淡い緑色をしている。", "target_word": "胡瓜", "complexity_tier": "T3", "furigana": "市場[いちば]に並[なら]ぶ胡瓜[きゅうり]は、淡[あわ]い緑色[みどりいろ]をしている。", "sentence_source": "generated"}, {"text": "胡瓜は一年草なので、毎年種をまいて育てる。", "target_word": "胡瓜", "complexity_tier": "T3", "furigana": "胡瓜[きゅうり]は一年草[いちねんそう]なので、毎年[まいとし]種[たね]をまいて育[そだ]てる。", "sentence_source": "generated"}, {"text": "新鮮な胡瓜ほど、表面のとげがはっきりしている。", "target_word": "胡瓜", "complexity_tier": "T3", "furigana": "新鮮[しんせん]な胡瓜[きゅうり]ほど、表面[ひょうめん]のとげがはっきりしている。", "sentence_source": "generated"}, {"text": "夏の暑い日には、塩をふった胡瓜が食べたくなる。", "target_word": "胡瓜", "complexity_tier": "T3", "furigana": "夏[なつ]の暑[あつ]い日[ひ]には、塩[しお]をふった胡瓜[きゅうり]が食[た]べたくなる。", "sentence_source": "generated"}, {"text": "胡瓜の漬物は、ご飯によく合う。", "target_word": "胡瓜", "complexity_tier": "T3", "furigana": "胡瓜[きゅうり]の漬物[つけもの]は、ご飯[はん]によく合[あ]う。", "sentence_source": "generated"}, {"text": "胡瓜を細切りにして、冷たいそばにのせた。", "target_word": "胡瓜", "complexity_tier": "T3", "furigana": "胡瓜[きゅうり]を細切[ほそぎ]りにして、冷[つめ]たいそばにのせた。", "sentence_source": "generated"}, {"text": "胡瓜は九割以上が水分でできている。", "target_word": "胡瓜", "complexity_tier": "T3", "furigana": "胡瓜[きゅうり]は九割[きゅうわり]以上[いじょう]が水分[すいぶん]でできている。", "sentence_source": "generated"}], "morphological_forms": [], "register": "neutral", "sense_fingerprint": "うり科の一年草、またはその細長い果実", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48ed5f6e-9d04-40a4-a25c-2e0d32e54d62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39533, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "胡瓜", "is_correct": true, "explanation": "「胡瓜はうり科の植物で」は、この植物の説明として自然に通る。"}, {"text": "石鹸", "is_correct": false, "explanation": "「石鹸はうり科の植物で」は成り立たない。石鹸は植物ではない。"}, {"text": "切手", "is_correct": false, "explanation": "「切手はうり科の植物で」は意味が通らない。切手は植物ではない。"}, {"text": "時計", "is_correct": false, "explanation": "「時計はうり科の植物で」は成り立たない。時計は植物ではない。"}], "explanations": {"胡瓜": "「胡瓜はうり科の植物で」は、この植物の説明として自然に通る。", "石鹸": "「石鹸はうり科の植物で」は成り立たない。石鹸は植物ではない。", "切手": "「切手はうり科の植物で」は意味が通らない。切手は植物ではない。", "時計": "「時計はうり科の植物で」は成り立たない。時計は植物ではない。"}, "sentence_index": 0, "correct_answer": "胡瓜"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "市場に並ぶ胡瓜は、薄皮をむくと涙が出る。", "explanation": "ここは〈玉ねぎ〉の意味。薄皮をむくと涙が出るのは玉ねぎで、胡瓜の性質ではない。"}, {"text": "市場に並ぶ胡瓜は、房になって甘い香りがする。", "explanation": "ここは〈ぶどう〉の意味。房になって並ぶのはぶどうで、胡瓜には当てはまらない。"}, {"text": "市場に並ぶ胡瓜は、かたい殻に包まれている。", "explanation": "ここは〈栗〉の意味。かたい殻に包まれるのは栗で、胡瓜の説明としては合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bad1c4d-f01b-4f87-8fe3-07018ad5ba8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39533, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "胡瓜", "is_correct": true, "explanation": "「塩をふった胡瓜が食べたくなる」は、暑い日に食べたくなる野菜として自然に通る。"}, {"text": "鍵", "is_correct": false, "explanation": "「塩をふった鍵が食べたくなる」は成り立たない。鍵は食べ物ではない。"}, {"text": "帽子", "is_correct": false, "explanation": "「塩をふった帽子が食べたくなる」は意味が通らない。帽子は食べ物ではない。"}, {"text": "座布団", "is_correct": false, "explanation": "「塩をふった座布団が食べたくなる」は成り立たない。座布団は食べ物ではない。"}], "explanations": {"胡瓜": "「塩をふった胡瓜が食べたくなる」は、暑い日に食べたくなる野菜として自然に通る。", "鍵": "「塩をふった鍵が食べたくなる」は成り立たない。鍵は食べ物ではない。", "帽子": "「塩をふった帽子が食べたくなる」は意味が通らない。帽子は食べ物ではない。", "座布団": "「塩をふった座布団が食べたくなる」は成り立たない。座布団は食べ物ではない。"}, "sentence_index": 6, "correct_answer": "胡瓜"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "胡瓜は冬に煮込むと、味がしみておいしい。", "explanation": "ここは〈大根〉の意味。冬に煮込んで味がしみるのは大根で、胡瓜は生で食べることが多く合わない。"}, {"text": "胡瓜は、すりおろしてオレンジ色のジュースにする。", "explanation": "ここは〈人参〉の意味。オレンジ色のジュースにするのは人参で、胡瓜には当てはまらない。"}, {"text": "胡瓜は、一枚ずつはがして漬物にする。", "explanation": "ここは〈白菜〉の意味。葉を一枚ずつはがして漬けるのは白菜で、胡瓜の調理法としては合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bad1c4d-f01b-4f87-8fe3-07018ad5ba8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39533, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "胡瓜に表面には、小さなとげがある。", "corrected_sentence": "胡瓜の表面には、小さなとげがある。", "error_description": "「胡瓜の表面」と所有を表す「の」で結ぶ。「胡瓜に」とすると文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bad1c4d-f01b-4f87-8fe3-07018ad5ba8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39533, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "胡瓜が塩でもみ、冷蔵庫で冷やした。", "corrected_sentence": "胡瓜を塩でもみ、冷蔵庫で冷やした。", "error_description": "「もむ」は目的語に「を」を取る。「胡瓜が」は誤りで、正しくは「胡瓜を」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bad1c4d-f01b-4f87-8fe3-07018ad5ba8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39534, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "『咲いて』いる場所を示す。花畑に花が咲いている。"}, {"text": "を", "is_correct": false, "explanation": "『咲く』は目的語を取らないので、『を』は合わない。"}, {"text": "へ", "is_correct": false, "explanation": "『へ』は方向を表し、咲いている場所は示せない。"}, {"text": "が", "is_correct": false, "explanation": "『花畑が』とすると主語になり、『には』の形が崩れて場所を示せない。"}], "correct_answer": "に", "explanations": {"に": "『咲いて』いる場所を示す。花畑に花が咲いている。", "を": "『咲く』は目的語を取らないので、『を』は合わない。", "へ": "『へ』は方向を表し、咲いている場所は示せない。", "が": "『花畑が』とすると主語になり、『には』の形が崩れて場所を示せない。"}, "error_tags": {"を": "目的語", "へ": "方向", "が": "主語"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bd28592-cbc0-45fd-b14a-bebd7286389c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
