INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39534, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "はなが たくさん さいている ばしょ です。", "primary_collocate": null, "pronunciation": "はなばたけ", "ipa": "hanabatake", "syllable_count": 5, "sentences": [{"text": "春になると、町の外れに大きな花畑ができます。", "target_word": "花畑", "complexity_tier": "T3", "furigana": "春[はる]になると、町[まち]の外[はず]れに大[おお]きな花畑[はなばたけ]ができます。", "sentence_source": "generated"}, {"text": "花畑には、赤や黄色の花がたくさん咲いています。", "target_word": "花畑", "complexity_tier": "T3", "furigana": "花畑[はなばたけ]には、赤[あか]や黄色[きいろ]の花[はな]がたくさん咲[さ]いています。", "sentence_source": "generated"}, {"text": "週末、家族で花畑へ写真を撮りに行きました。", "target_word": "花畑", "complexity_tier": "T3", "furigana": "週末[しゅうまつ]、家族[かぞく]で花畑[はなばたけ]へ写真[しゃしん]を撮[と]りに行[い]きました。", "sentence_source": "generated"}, {"text": "花畑の中を歩くと、いい香りがします。", "target_word": "花畑", "complexity_tier": "T3", "furigana": "花畑[はなばたけ]の中[なか]を歩[ある]くと、いい香[かお]りがします。", "sentence_source": "generated"}, {"text": "雨が降ったので、花畑は水にぬれて光っていました。", "target_word": "花畑", "complexity_tier": "T3", "furigana": "雨[あめ]が降[ふ]ったので、花畑[はなばたけ]は水[みず]にぬれて光[ひか]っていました。", "sentence_source": "generated"}, {"text": "花畑にはたくさんの蝶が飛んでいます。", "target_word": "花畑", "complexity_tier": "T3", "furigana": "花畑[はなばたけ]にはたくさんの蝶[ちょう]が飛[と]んでいます。", "sentence_source": "generated"}, {"text": "子どもたちは花畑で花の冠を作りました。", "target_word": "花畑", "complexity_tier": "T3", "furigana": "子[こ]どもたちは花畑[はなばたけ]で花[はな]の冠[かんむり]を作[つく]りました。", "sentence_source": "generated"}, {"text": "この花畑は、五月がいちばんきれいです。", "target_word": "花畑", "complexity_tier": "T3", "furigana": "この花畑[はなばたけ]は、五月[ごがつ]がいちばんきれいです。", "sentence_source": "generated"}, {"text": "花畑が広いので、一周するのに三十分かかります。", "target_word": "花畑", "complexity_tier": "T3", "furigana": "花畑[はなばたけ]が広[ひろ]いので、一周[いっしゅう]するのに三十分[さんじゅっぷん]かかります。", "sentence_source": "generated"}, {"text": "山の上に花畑があるので、バスで見に行きます。", "target_word": "花畑", "complexity_tier": "T3", "furigana": "山[やま]の上[うえ]に花畑[はなばたけ]があるので、バスで見[み]に行[い]きます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "花畑", "label": "基本形"}], "register": "丁寧語（です・ます体）", "sense_fingerprint": "たくさんの花が咲いている場所。見に行ったり歩いたりする所。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7027329f-781d-4983-bb14-05a931bba1d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39534, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "花畑", "is_correct": true, "explanation": "大きく広がって町の外れにできる、花が咲く場所は〈花畑〉で、文の意味に合う。"}, {"text": "花粉", "is_correct": false, "explanation": "花粉は小さな粒で、『大きな〜ができる』場所にはならない。"}, {"text": "花火", "is_correct": false, "explanation": "花火は一瞬の打ち上げで、町の外れに『できる』ものではない。"}, {"text": "花束", "is_correct": false, "explanation": "花束は持ち運ぶ物で、町の外れに『できる』場所にはならない。"}], "explanations": {"花畑": "大きく広がって町の外れにできる、花が咲く場所は〈花畑〉で、文の意味に合う。", "花粉": "花粉は小さな粒で、『大きな〜ができる』場所にはならない。", "花火": "花火は一瞬の打ち上げで、町の外れに『できる』ものではない。", "花束": "花束は持ち運ぶ物で、町の外れに『できる』場所にはならない。"}, "sentence_index": 0, "correct_answer": "花畑"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "母の日に、花畑を一つ買ってプレゼントしました。", "explanation": "ここは〈花束〉の意味。買ってプレゼントするのは花束で、花畑は場所なので一つ買えない。"}, {"text": "夜空に花畑が打ち上がりました。", "explanation": "ここは〈花火〉の意味。打ち上がるのは花火で、花畑は場所なので空に上がらない。"}, {"text": "風で花畑が舞って、目がかゆくなりました。", "explanation": "ここは〈花粉〉の意味。舞って目をかゆくするのは花粉で、花畑は場所なので舞わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bd28592-cbc0-45fd-b14a-bebd7286389c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39534, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "花畑", "is_correct": true, "explanation": "花が咲いている場所は〈花畑〉で、冠を作る場所として文に合う。"}, {"text": "花札", "is_correct": false, "explanation": "花札は遊び道具で、冠を作る場所にはならない。"}, {"text": "花茶", "is_correct": false, "explanation": "花茶は飲み物で、冠を作る場所にはならない。"}, {"text": "花占い", "is_correct": false, "explanation": "花占いは占いの方法で、冠を作る場所にはならない。"}], "explanations": {"花畑": "花が咲いている場所は〈花畑〉で、冠を作る場所として文に合う。", "花札": "花札は遊び道具で、冠を作る場所にはならない。", "花茶": "花茶は飲み物で、冠を作る場所にはならない。", "花占い": "花占いは占いの方法で、冠を作る場所にはならない。"}, "sentence_index": 6, "correct_answer": "花畑"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "テーブルに花畑を置いて、水を入れました。", "explanation": "ここは〈花瓶〉の意味。置いて水を入れるのは花瓶で、花畑は場所なのでテーブルに置けない。"}, {"text": "風で花畑が散りました。", "explanation": "ここは〈花びら〉の意味。散るのは花びらで、花畑は場所なので散らない。"}, {"text": "花畑を一輪、髪に挿しました。", "explanation": "ここは〈花〉の意味。一輪と数えて挿すのは花で、花畑は場所なので一輪と数えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bd28592-cbc0-45fd-b14a-bebd7286389c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39534, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夏休みに、家族で花畑を遊びに行きました。", "corrected_sentence": "夏休みに、家族で花畑へ遊びに行きました。", "error_description": "『を』が誤りで『へ』が正しい。『遊びに行く』の行き先は『へ』で示す。『を』は通過する場所に使うので、目的地には合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bd28592-cbc0-45fd-b14a-bebd7286389c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39534, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "放課後、子どもたちは花畑に遊んでいました。", "corrected_sentence": "放課後、子どもたちは花畑で遊んでいました。", "error_description": "『に』が誤りで『で』が正しい。『遊ぶ』の行為の場所は『で』で示す。『に』は存在や到着の場所で、遊ぶ場所には合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bd28592-cbc0-45fd-b14a-bebd7286389c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39535, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "チューリップの球根を植える場所を示す。花畑に植える。"}, {"text": "へ", "is_correct": false, "explanation": "『へ』は方向を表し、植える場所は示せない。"}, {"text": "が", "is_correct": false, "explanation": "『花畑が』とすると主語になり、植える行為の場所にはならない。"}, {"text": "から", "is_correct": false, "explanation": "『から』は起点を表し、植える場所を示せない。"}], "correct_answer": "に", "explanations": {"に": "チューリップの球根を植える場所を示す。花畑に植える。", "へ": "『へ』は方向を表し、植える場所は示せない。", "が": "『花畑が』とすると主語になり、植える行為の場所にはならない。", "から": "『から』は起点を表し、植える場所を示せない。"}, "error_tags": {"へ": "方向", "が": "主語", "から": "起点"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bd28592-cbc0-45fd-b14a-bebd7286389c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39535, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "『整えました』の対象を示す。広い花畑を整えた。"}, {"text": "の", "is_correct": false, "explanation": "『の』は名詞をつなぐだけで、整える対象は示せない。"}, {"text": "と", "is_correct": false, "explanation": "『と』は並列や相手を表し、整える対象にならない。"}, {"text": "より", "is_correct": false, "explanation": "『より』は比較や起点を表し、整える対象は示せない。"}], "correct_answer": "を", "explanations": {"を": "『整えました』の対象を示す。広い花畑を整えた。", "の": "『の』は名詞をつなぐだけで、整える対象は示せない。", "と": "『と』は並列や相手を表し、整える対象にならない。", "より": "『より』は比較や起点を表し、整える対象は示せない。"}, "error_tags": {"の": "連体修飾", "と": "並列", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bd28592-cbc0-45fd-b14a-bebd7286389c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39535, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "花がたくさん植えてある場所。花が一面に咲いている畑。", "primary_collocate": null, "pronunciation": "はなばたけ", "ipa": "hanabatake", "syllable_count": 5, "sentences": [{"text": "祖父は庭の裏に、小さな花畑を作りました。", "target_word": "花畑", "complexity_tier": "T3", "furigana": "祖父[そふ]は庭[にわ]の裏[うら]に、小[ちい]さな花畑[はなばたけ]を作[つく]りました。", "sentence_source": "generated"}, {"text": "花畑には毎年、チューリップの球根を植えます。", "target_word": "花畑", "complexity_tier": "T3", "furigana": "花畑[はなばたけ]には毎年[まいとし]、チューリップの球根[きゅうこん]を植[う]えます。", "sentence_source": "generated"}, {"text": "花畑の花は、町の人がみんなで育てています。", "target_word": "花畑", "complexity_tier": "T3", "furigana": "花畑[はなばたけ]の花[はな]は、町[まち]の人[ひと]がみんなで育[そだ]てています。", "sentence_source": "generated"}, {"text": "一面の花畑が、夕日で赤く染まりました。", "target_word": "花畑", "complexity_tier": "T3", "furigana": "一面[いちめん]の花畑[はなばたけ]が、夕日[ゆうひ]で赤[あか]く染[そ]まりました。", "sentence_source": "generated"}, {"text": "花畑の手入れをするために、朝六時に起きました。", "target_word": "花畑", "complexity_tier": "T3", "furigana": "花畑[はなばたけ]の手入[ていれ]をするために、朝[あさ]六時[ろくじ]に起[お]きました。", "sentence_source": "generated"}, {"text": "この花畑ではコスモスを育てているので、秋に見ごろです。", "target_word": "花畑", "complexity_tier": "T3", "furigana": "この花畑[はなばたけ]ではコスモスを育[そだ]てているので、秋[あき]に見[み]ごろです。", "sentence_source": "generated"}, {"text": "花畑に水をやるのは、私の毎日の仕事です。", "target_word": "花畑", "complexity_tier": "T3", "furigana": "花畑[はなばたけ]に水[みず]をやるのは、私[わたし]の毎日[まいにち]の仕事[しごと]です。", "sentence_source": "generated"}, {"text": "観光客に見てもらうために、村は広い花畑を整えました。", "target_word": "花畑", "complexity_tier": "T3", "furigana": "観光客[かんこうきゃく]に見[み]てもらうために、村[むら]は広[ひろ]い花畑[はなばたけ]を整[ととの]えました。", "sentence_source": "generated"}, {"text": "花畑の端から端まで、ひまわりが並んでいます。", "target_word": "花畑", "complexity_tier": "T3", "furigana": "花畑[はなばたけ]の端[はし]から端[はし]まで、ひまわりが並[なら]んでいます。", "sentence_source": "generated"}, {"text": "去年の花畑より、今年のほうが花の数が多いです。", "target_word": "花畑", "complexity_tier": "T3", "furigana": "去年[きょねん]の花畑[はなばたけ]より、今年[ことし]のほうが花[はな]の数[かず]が多[おお]いです。", "sentence_source": "generated"}], "morphological_forms": [{"form": "花畑", "label": "基本形"}], "register": "丁寧語（です・ます体）", "sense_fingerprint": "花を育てるために植えた畑。一面に花が咲く。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7027329f-781d-4983-bb14-05a931bba1d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39535, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "花畑", "is_correct": true, "explanation": "祖父が庭の裏に作る、花を植えた畑は〈花畑〉で、文の意味に合う。"}, {"text": "雑草", "is_correct": false, "explanation": "雑草は作るものではなく、『小さな〜を作る』には合わない。"}, {"text": "花粉", "is_correct": false, "explanation": "花粉は作って並べるものではなく、この文では意味が通らない。"}, {"text": "落ち葉", "is_correct": false, "explanation": "落ち葉は自然に落ちるもので、祖父が作るものではない。"}], "explanations": {"花畑": "祖父が庭の裏に作る、花を植えた畑は〈花畑〉で、文の意味に合う。", "雑草": "雑草は作るものではなく、『小さな〜を作る』には合わない。", "花粉": "花粉は作って並べるものではなく、この文では意味が通らない。", "落ち葉": "落ち葉は自然に落ちるもので、祖父が作るものではない。"}, "sentence_index": 0, "correct_answer": "花畑"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "友人の結婚式に、大きな花畑を贈りました。", "explanation": "ここは〈花束〉の意味。贈るのは花束で、花畑は畑なので贈り物にはならない。"}, {"text": "夏の夜、一面の花畑が打ち上がりました。", "explanation": "ここは〈花火〉の意味。打ち上がるのは花火で、花畑は畑なので空に上がらない。"}, {"text": "散った花畑を一枚ずつ数えました。", "explanation": "ここは〈花びら〉の意味。一枚ずつ数えるのは花びらで、花畑は畑なので枚では数えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bd28592-cbc0-45fd-b14a-bebd7286389c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39535, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "花畑", "is_correct": true, "explanation": "水をやる、花を植えた畑は〈花畑〉で、文の意味に合う。"}, {"text": "花札", "is_correct": false, "explanation": "花札は水をやる対象ではなく、文の意味に合わない。"}, {"text": "手紙", "is_correct": false, "explanation": "手紙は水をやるものではなく、この文では成り立たない。"}, {"text": "物置", "is_correct": false, "explanation": "物置は水をやる植物ではなく、この文に合わない。"}], "explanations": {"花畑": "水をやる、花を植えた畑は〈花畑〉で、文の意味に合う。", "花札": "花札は水をやる対象ではなく、文の意味に合わない。", "手紙": "手紙は水をやるものではなく、この文では成り立たない。", "物置": "物置は水をやる植物ではなく、この文に合わない。"}, "sentence_index": 6, "correct_answer": "花畑"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "たき火から花畑が立ちのぼりました。", "explanation": "ここは〈煙〉の意味。立ちのぼるのは煙で、花畑は場所なので立ちのぼらない。"}, {"text": "友人から花畑を一冊もらいました。", "explanation": "ここは〈本〉の意味。一冊と数えてもらうのは本で、花畑は畑なので冊では数えない。"}, {"text": "コップに花畑を注ぎました。", "explanation": "ここは〈水〉の意味。注ぐのは水などの液体で、花畑は畑なので注げない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bd28592-cbc0-45fd-b14a-bebd7286389c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39535, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夏の終わりに、祖父は裏庭の花畑が手入れしました。", "corrected_sentence": "夏の終わりに、祖父は裏庭の花畑を手入れしました。", "error_description": "『が』が誤りで『を』が正しい。『手入れする』の対象は『を』で示す。『が』にすると花畑が手入れする主体になり不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bd28592-cbc0-45fd-b14a-bebd7286389c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39535, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "町の人は、広い花畑を毎年整っています。", "corrected_sentence": "町の人は、広い花畑を毎年整えます。", "error_description": "『整っています』は自動詞で、目的語『を』を取れない。他動詞の『整えます』が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bd28592-cbc0-45fd-b14a-bebd7286389c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
