INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39536, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "から", "options": [{"text": "から", "is_correct": true, "explanation": "「焼いてから」の「から」で、順序を表す。ここに入る正しい助詞。"}, {"text": "に", "is_correct": false, "explanation": "「焼いてに」とはつながらない。「に」は時点や相手を示す。"}, {"text": "で", "is_correct": false, "explanation": "「焼いてで」とは続かない。「で」は手段や場所を示す。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、順序を表す文脈には合わない。"}], "correct_answer": "から", "explanations": {"から": "「焼いてから」の「から」で、順序を表す。ここに入る正しい助詞。", "に": "「焼いてに」とはつながらない。「に」は時点や相手を示す。", "で": "「焼いてで」とは続かない。「で」は手段や場所を示す。", "へ": "「へ」は方向を示すので、順序を表す文脈には合わない。"}, "error_tags": {"に": "時点・位置", "で": "手段・場所", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '196c77a7-afc3-481c-87f3-1ba8dda84301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39536, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "ものをあつくして、たべられるようにすること。", "primary_collocate": null, "pronunciation": "やく", "ipa": "jakɯ", "syllable_count": 2, "sentences": [{"text": "母は毎朝、台所で魚を焼く。", "target_word": "焼く", "complexity_tier": "T3", "furigana": "母[はは]は毎朝[まいあさ]、台所[だいどころ]で魚[さかな]を焼[や]く。", "sentence_source": "generated"}, {"text": "父は庭で肉を焼いて、家族に食べさせた。", "target_word": "焼いて", "complexity_tier": "T3", "furigana": "父[ちち]は庭[にわ]で肉[にく]を焼[や]いて、家族[かぞく]に食[た]べさせた。", "sentence_source": "generated"}, {"text": "魚を焼くときは、先に皮のほうに火を当てる。", "target_word": "焼く", "complexity_tier": "T3", "furigana": "魚[さかな]を焼[や]くときは、先[さき]に皮[かわ]のほうに火[ひ]を当[あ]てる。", "sentence_source": "generated"}, {"text": "朝ごはんに、パンを焼いて、バターをぬった。", "target_word": "焼いて", "complexity_tier": "T3", "furigana": "朝[あさ]ごはんに、パンを焼[や]いて、バターをぬった。", "sentence_source": "generated"}, {"text": "ホットプレートで肉と野菜を焼いて、みんなで食べた。", "target_word": "焼いて", "complexity_tier": "T3", "furigana": "ホットプレートで肉[にく]と野菜[やさい]を焼[や]いて、みんなで食[た]べた。", "sentence_source": "generated"}, {"text": "網でもちを焼くと、ふくらんで香りがよくなる。", "target_word": "焼く", "complexity_tier": "T3", "furigana": "網[あみ]でもちを焼[や]くと、ふくらんで香[かお]りがよくなる。", "sentence_source": "generated"}, {"text": "キャンプでは、川で釣った魚を焼いて食べた。", "target_word": "焼いて", "complexity_tier": "T3", "furigana": "キャンプでは、川[かわ]で釣[つ]った魚[さかな]を焼[や]いて食[た]べた。", "sentence_source": "generated"}, {"text": "ピーマンは、黒くなるまで焼いてから皮をむく。", "target_word": "焼いて", "complexity_tier": "T3", "furigana": "ピーマンは、黒[くろ]くなるまで焼[や]いてから皮[かわ]をむく。", "sentence_source": "generated"}, {"text": "弟は卵を焼くのが得意で、毎朝作ってくれる。", "target_word": "焼く", "complexity_tier": "T3", "furigana": "弟[おとうと]は卵[たまご]を焼[や]くのが得意[とくい]で、毎朝[まいあさ]作[つく]ってくれる。", "sentence_source": "generated"}, {"text": "さんまは火が強すぎると焦げるので、中火で焼く。", "target_word": "焼く", "complexity_tier": "T3", "furigana": "さんまは火[ひ]が強[つよ]すぎると焦[こ]げるので、中火[ちゅうび]で焼[や]く。", "sentence_source": "generated"}], "morphological_forms": [{"form": "焼く", "label": "終止形"}, {"form": "焼いた", "label": "過去形"}, {"form": "焼いて", "label": "て形"}, {"form": "焼かない", "label": "否定形"}, {"form": "焼きます", "label": "丁寧形"}], "register": "neutral", "sense_fingerprint": "魚・肉・野菜・もちなどに直接火を当てて、食べられるようにする", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2bd11da-41e2-49c8-8a73-9a8a84891b15') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39536, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "焼く", "is_correct": true, "explanation": "ここは魚に火を当てて食べられるようにする「焼く」で、台所での調理に合う。"}, {"text": "炊く", "is_correct": false, "explanation": "「炊く」は米や豆に使う。魚には合わない。"}, {"text": "植える", "is_correct": false, "explanation": "「植える」は植物を土に入れる動作。魚には使えない。"}, {"text": "着る", "is_correct": false, "explanation": "「着る」は衣服を身につける動作。魚には使えない。"}], "explanations": {"焼く": "ここは魚に火を当てて食べられるようにする「焼く」で、台所での調理に合う。", "炊く": "「炊く」は米や豆に使う。魚には合わない。", "植える": "「植える」は植物を土に入れる動作。魚には使えない。", "着る": "「着る」は衣服を身につける動作。魚には使えない。"}, "sentence_index": 0, "correct_answer": "焼く"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "冷めたスープを焼いて、温め直した。", "explanation": "ここは「温める」の意味。「焼く」は火で強く加熱して食べられるようにする意味で、冷めたものを温め直す動作には使えないので合わない。"}, {"text": "お湯を焼いて、コーヒーをいれた。", "explanation": "ここは「沸かす」の意味。液体を熱くする場合には「焼く」は使わないので合わない。"}, {"text": "洗濯物を焼いて、干した。", "explanation": "ここは「干す」の意味。衣類を焼くことは乾かすことにならず、「焼く」は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '196c77a7-afc3-481c-87f3-1ba8dda84301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39536, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "焼いて", "is_correct": true, "explanation": "ここは魚を火で加熱してから食べたことを表す「焼いて」で、キャンプの調理の流れに合う。"}, {"text": "炊いて", "is_correct": false, "explanation": "「炊く」は米や豆に使う。魚には合わない。"}, {"text": "研いで", "is_correct": false, "explanation": "「研ぐ」は米を水で洗う動作。魚には使えない。"}, {"text": "結んで", "is_correct": false, "explanation": "「結ぶ」はひもなどをつなぐ動作。魚を食べる流れに合わない。"}], "explanations": {"焼いて": "ここは魚を火で加熱してから食べたことを表す「焼いて」で、キャンプの調理の流れに合う。", "炊いて": "「炊く」は米や豆に使う。魚には合わない。", "研いで": "「研ぐ」は米を水で洗う動作。魚には使えない。", "結んで": "「結ぶ」はひもなどをつなぐ動作。魚を食べる流れに合わない。"}, "sentence_index": 6, "correct_answer": "焼いて"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "パスタを焼いて、ざるに上げた。", "explanation": "ここは「ゆでる」の意味。パスタは湯で茹でるもので、火で焼く調理とは違うので、ざるに上げる流れには合わない。"}, {"text": "雨でぬれた靴を焼いた。", "explanation": "ここは「乾かす」の意味。靴を加熱して焼くことにはならないので、「焼く」は合わない。"}, {"text": "スープを焼いて飲んだ。", "explanation": "ここは「冷ます」の意味。熱いものを冷ます動作で、スープを焼くことにはならないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '196c77a7-afc3-481c-87f3-1ba8dda84301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39536, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "母は毎朝、台所で魚が焼いている。", "corrected_sentence": "母は毎朝、台所で魚を焼いている。", "error_description": "「焼く」は対象を取る他動詞なので、対象の魚には「を」が必要。「が」にすると魚が自然に焼けるという意味になり、合わない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "焼いて", "is_correct": true, "explanation": "て形で、後ろの「食べさせた」へつながるつなぎの形。ここに入る正しい形。"}, {"text": "焼いた", "is_correct": false, "explanation": "過去形なので、「焼いた、家族に…」と続けると文が途切れて不自然。"}, {"text": "焼かない", "is_correct": false, "explanation": "否定形なので、肉を焼かなかったことになり意味が反対になる。"}, {"text": "焼きます", "is_correct": false, "explanation": "丁寧形なので、普通体の文の中には合わない。"}], "correct_form": "焼いて", "base_form": "焼く", "form_label": "て形", "sentence_index": 1, "explanations": {"焼いて": "て形で、後ろの「食べさせた」へつながるつなぎの形。ここに入る正しい形。", "焼いた": "過去形なので、「焼いた、家族に…」と続けると文が途切れて不自然。", "焼かない": "否定形なので、肉を焼かなかったことになり意味が反対になる。", "焼きます": "丁寧形なので、普通体の文の中には合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '196c77a7-afc3-481c-87f3-1ba8dda84301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39536, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "さんまは火が強すぎると焦げるので、中火をじっくり焼く。", "corrected_sentence": "さんまは火が強すぎると焦げるので、中火でじっくり焼く。", "error_description": "「中火で」の「で」は手段や場所を示す。「中火を」と「を」を使うと「中火を焼く」となり不自然。「中火で焼く」が正しい。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "焼いて", "is_correct": true, "explanation": "て形で、後ろの「皮をむく」へ「焼いてから」と続く形。ここに入る正しい形。"}, {"text": "焼く", "is_correct": false, "explanation": "辞書形なので、「焼いてから」の「て」につながらない。"}, {"text": "焼こう", "is_correct": false, "explanation": "意志の形なので、ピーマンを焼こうとする意味になり、焼いた後に皮をむくという順序に合わない。"}, {"text": "焼き", "is_correct": false, "explanation": "連用形の「焼き」は「てから」につながらず、「焼きてから」は文法的に成立しない。"}], "correct_form": "焼いて", "base_form": "焼く", "form_label": "て形", "sentence_index": 7, "explanations": {"焼いて": "て形で、後ろの「皮をむく」へ「焼いてから」と続く形。ここに入る正しい形。", "焼く": "辞書形なので、「焼いてから」の「て」につながらない。", "焼こう": "意志の形なので、ピーマンを焼こうとする意味になり、焼いた後に皮をむくという順序に合わない。", "焼き": "連用形の「焼き」は「てから」につながらず、「焼きてから」は文法的に成立しない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '196c77a7-afc3-481c-87f3-1ba8dda84301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
