INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39537, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "火や熱を使って、食材などを加熱し、食べられる状態にすること。", "primary_collocate": null, "pronunciation": "やく", "ipa": "jakɯ", "syllable_count": 2, "sentences": [{"text": "姉はオーブンでクッキーを焼いて、友達に配った。", "target_word": "焼いて", "complexity_tier": "T3", "furigana": "姉[あね]はオーブンでクッキーを焼[や]いて、友達[ともだち]に配[くば]った。", "sentence_source": "generated"}, {"text": "彼女は日曜日に、家族のためにケーキを焼く。", "target_word": "焼く", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は日曜日[にちようび]に、家族[かぞく]のためにケーキを焼[や]く。", "sentence_source": "generated"}, {"text": "パン屋では朝早くからパンを焼いている。", "target_word": "焼いて", "complexity_tier": "T3", "furigana": "パン屋[や]では朝早[あさはや]くからパンを焼[や]いている。", "sentence_source": "generated"}, {"text": "じゃがいもを焼くなら、アルミホイルで包むとよい。", "target_word": "焼く", "complexity_tier": "T3", "furigana": "じゃがいもを焼[や]くなら、アルミホイルで包[つつ]むとよい。", "sentence_source": "generated"}, {"text": "フライパンにふたをして、ゆっくり肉を焼いた。", "target_word": "焼いた", "complexity_tier": "T3", "furigana": "フライパンにふたをして、ゆっくり肉[にく]を焼[や]いた。", "sentence_source": "generated"}, {"text": "炭火で魚を焼くと、家のコンロより香ばしくなる。", "target_word": "焼く", "complexity_tier": "T3", "furigana": "炭火[すみび]で魚[さかな]を焼[や]くと、家[いえ]のコンロより香[こう]ばしくなる。", "sentence_source": "generated"}, {"text": "ピザを焼くには、高い温度のオーブンが必要だ。", "target_word": "焼く", "complexity_tier": "T3", "furigana": "ピザを焼[や]くには、高[たか]い温度[おんど]のオーブンが必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "パンを焼いたら、いい匂いが家じゅうに広がった。", "target_word": "焼いた", "complexity_tier": "T3", "furigana": "パンを焼[や]いたら、いい匂[にお]いが家[いえ]じゅうに広[ひろ]がった。", "sentence_source": "generated"}, {"text": "祖母は毎年、お正月にもちを焼いてくれる。", "target_word": "焼いて", "complexity_tier": "T3", "furigana": "祖母[そぼ]は毎年[まいとし]、お正月[しょうがつ]にもちを焼[や]いてくれる。", "sentence_source": "generated"}, {"text": "強い火で急いで焼くと、外は黒いのに中が生だ。", "target_word": "焼く", "complexity_tier": "T3", "furigana": "強[つよ]い火[ひ]で急[いそ]いで焼[や]くと、外[そと]は黒[くろ]いのに中[なか]が生[なま]だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "焼く", "label": "終止形"}, {"form": "焼いた", "label": "過去形"}, {"form": "焼いて", "label": "て形"}, {"form": "焼かない", "label": "否定形"}, {"form": "焼きます", "label": "丁寧形"}], "register": "neutral", "sense_fingerprint": "オーブンや炭火などの熱で、パン・菓子・食材を加熱して食べられる状態にする", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2bd11da-41e2-49c8-8a73-9a8a84891b15') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39537, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "焼いて", "is_correct": true, "explanation": "ここは火と熱でクッキーを加熱する「焼く」のて形で、オーブンでの調理に合う。"}, {"text": "研いで", "is_correct": false, "explanation": "「研ぐ」は米を水で洗う動作。クッキーには合わない。"}, {"text": "結んで", "is_correct": false, "explanation": "「結ぶ」はひもなどをつなぐ動作。食品には使わない。"}, {"text": "鳴らして", "is_correct": false, "explanation": "「鳴らす」は音を出す動作。クッキーには合わない。"}], "explanations": {"焼いて": "ここは火と熱でクッキーを加熱する「焼く」のて形で、オーブンでの調理に合う。", "研いで": "「研ぐ」は米を水で洗う動作。クッキーには合わない。", "結んで": "「結ぶ」はひもなどをつなぐ動作。食品には使わない。", "鳴らして": "「鳴らす」は音を出す動作。クッキーには合わない。"}, "sentence_index": 0, "correct_answer": "焼いて"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "スープを焼いて、冷ました。", "explanation": "ここは「冷ます」の意味。熱いものを冷ます動作で、火で加熱して食べられるようにする「焼く」とは反対の方向なので合わない。"}, {"text": "そうめんを焼いて、つゆにつけた。", "explanation": "ここは「茹でる」の意味。そうめんは湯で茹でるもので、焼く調理にはならない。"}, {"text": "やかんでお湯を焼いた。", "explanation": "ここは「沸かす」の意味。水を熱くするのに「焼く」は使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '196c77a7-afc3-481c-87f3-1ba8dda84301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39537, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "焼く", "is_correct": true, "explanation": "ここはピザを加熱して仕上げる「焼く」で、オーブンの温度の話に合う。"}, {"text": "摘む", "is_correct": false, "explanation": "「摘む」は花や野菜を手でとる動作。ピザには合わない。"}, {"text": "織る", "is_correct": false, "explanation": "「織る」は糸で布を作る動作。ピザには使わない。"}, {"text": "冷ます", "is_correct": false, "explanation": "「冷ます」は熱いものを冷たくする動作。高温のオーブンの話と反対の意味になる。"}], "explanations": {"焼く": "ここはピザを加熱して仕上げる「焼く」で、オーブンの温度の話に合う。", "摘む": "「摘む」は花や野菜を手でとる動作。ピザには合わない。", "織る": "「織る」は糸で布を作る動作。ピザには使わない。", "冷ます": "「冷ます」は熱いものを冷たくする動作。高温のオーブンの話と反対の意味になる。"}, "sentence_index": 6, "correct_answer": "焼く"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ほうれん草を焼いて、さっと湯がいた。", "explanation": "ここは「湯がく」の意味。湯に通す調理で、火や熱で焼いて食べられるようにする「焼く」の意味とは違うので、この文には合わない。"}, {"text": "鍋でカレーを焼くと、野菜がやわらかくなる。", "explanation": "ここは「煮込む」の意味。カレーは水分の中で煮込むもので、焼くでは意味が違う。"}, {"text": "湯せんでチョコを焼くと、なめらかになる。", "explanation": "ここは「溶かす」の意味。固体を溶かす動作で、加熱して焼くことにはならないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '196c77a7-afc3-481c-87f3-1ba8dda84301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39537, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "姉はオーブンでクッキーを焼くと、近所の友達に配った。", "corrected_sentence": "姉はオーブンでクッキーを焼いて、近所の友達に配った。", "error_description": "「焼くと」は条件を表すので、過去の動作「配った」と続けると合わない。動作を順に続けるには「焼いて」のて形にする。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "焼く", "is_correct": true, "explanation": "辞書形（終止形）で、文末に置いて「家族のためにケーキを焼く」という習慣的な動作を述べる形に合う。"}, {"text": "焼いて", "is_correct": false, "explanation": "て形は文を言い切れない形なので、「焼いて。」では文末として成立しない。"}, {"text": "焼けば", "is_correct": false, "explanation": "仮定形で、続きがないと文が完結しない。「焼けば」だけでは文末として成立しない。"}, {"text": "焼かれた", "is_correct": false, "explanation": "受け身の過去形なので、「ケーキを焼かれた」は主語と目的語の関係が合わず、文として成立しない。"}], "correct_form": "焼く", "base_form": "焼く", "form_label": "終止形", "sentence_index": 1, "explanations": {"焼く": "辞書形（終止形）で、文末に置いて「家族のためにケーキを焼く」という習慣的な動作を述べる形に合う。", "焼いて": "て形は文を言い切れない形なので、「焼いて。」では文末として成立しない。", "焼けば": "仮定形で、続きがないと文が完結しない。「焼けば」だけでは文末として成立しない。", "焼かれた": "受け身の過去形なので、「ケーキを焼かれた」は主語と目的語の関係が合わず、文として成立しない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '196c77a7-afc3-481c-87f3-1ba8dda84301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39537, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ピザを焼いたには、熱いオーブンを使う必要がある。", "corrected_sentence": "ピザを焼くには、熱いオーブンを使う必要がある。", "error_description": "「〜には」は目的を表し、辞書形の「焼く」につながる。過去形の「焼いた」を使うと「焼いたには」となり不自然。「焼くには」が正しい。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "焼いた", "is_correct": true, "explanation": "過去形で、パンを焼き終えたあとの出来事を述べる「焼いたら」の形に合う。"}, {"text": "焼く", "is_correct": false, "explanation": "辞書形なので、完了した動作の「焼いたら」の形にならない。"}, {"text": "焼こう", "is_correct": false, "explanation": "意志の形なので、パンを焼くつもりの意味になり、焼いた結果としていい匂いが広がったという文とは合わない。"}, {"text": "焼かれた", "is_correct": false, "explanation": "受け身の過去形なので、パンが何かに焼かれた意味になり、文の主語と流れに合わない。"}], "correct_form": "焼いた", "base_form": "焼く", "form_label": "過去形", "sentence_index": 7, "explanations": {"焼いた": "過去形で、パンを焼き終えたあとの出来事を述べる「焼いたら」の形に合う。", "焼く": "辞書形なので、完了した動作の「焼いたら」の形にならない。", "焼こう": "意志の形なので、パンを焼くつもりの意味になり、焼いた結果としていい匂いが広がったという文とは合わない。", "焼かれた": "受け身の過去形なので、パンが何かに焼かれた意味になり、文の主語と流れに合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '196c77a7-afc3-481c-87f3-1ba8dda84301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39538, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "『集める』の対象を示す。蜜を集める。"}, {"text": "が", "is_correct": false, "explanation": "『蜜が集める』では蜜が集める側になり、文の意味が合わない。"}, {"text": "で", "is_correct": false, "explanation": "『で』は手段や場所を表し、集める対象は示せない。"}, {"text": "へ", "is_correct": false, "explanation": "『へ』は方向を表し、集める対象にはならない。"}], "correct_answer": "を", "explanations": {"を": "『集める』の対象を示す。蜜を集める。", "が": "『蜜が集める』では蜜が集める側になり、文の意味が合わない。", "で": "『で』は手段や場所を表し、集める対象は示せない。", "へ": "『へ』は方向を表し、集める対象にはならない。"}, "error_tags": {"が": "主語", "で": "手段", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bd28592-cbc0-45fd-b14a-bebd7286389c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39538, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "『薄くなる』の主語は蜜なので、『が』が正しい。"}, {"text": "を", "is_correct": false, "explanation": "『薄くなる』は自動詞なので、目的語『を』は取らない。"}, {"text": "に", "is_correct": false, "explanation": "『に』は結果の相手を表すが、『蜜に薄くなる』は成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "『と』は並列や相手を表し、薄くなる主体にならない。"}], "correct_answer": "が", "explanations": {"が": "『薄くなる』の主語は蜜なので、『が』が正しい。", "を": "『薄くなる』は自動詞なので、目的語『を』は取らない。", "に": "『に』は結果の相手を表すが、『蜜に薄くなる』は成り立たない。", "と": "『と』は並列や相手を表し、薄くなる主体にならない。"}, "error_tags": {"を": "目的語", "に": "結果", "と": "並列"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bd28592-cbc0-45fd-b14a-bebd7286389c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39538, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "みつは、はなにあるあまいみずです。", "primary_collocate": null, "pronunciation": "みつ", "ipa": "mitsɯ", "syllable_count": 2, "sentences": [{"text": "蝶は花の蜜を吸って、元気に飛んでいきます。", "target_word": "蜜", "complexity_tier": "T3", "furigana": "蝶[ちょう]は花[はな]の蜜[みつ]を吸[す]って、元気[げんき]に飛[と]んでいきます。", "sentence_source": "generated"}, {"text": "春になると、ハチが花の蜜を集めに来ます。", "target_word": "蜜", "complexity_tier": "T3", "furigana": "春[はる]になると、ハチが花[はな]の蜜[みつ]を集[あつ]めに来[き]ます。", "sentence_source": "generated"}, {"text": "この花は蜜が多いので、たくさんの虫が集まります。", "target_word": "蜜", "complexity_tier": "T3", "furigana": "この花[はな]は蜜[みつ]が多[おお]いので、たくさんの虫[むし]が集[あつ]まります。", "sentence_source": "generated"}, {"text": "花の蜜は甘いので、鳥も飲みに来ます。", "target_word": "蜜", "complexity_tier": "T3", "furigana": "花[はな]の蜜[みつ]は甘[あま]いので、鳥[とり]も飲[の]みに来[き]ます。", "sentence_source": "generated"}, {"text": "朝早く、小さな蜂が花から蜜を運んでいました。", "target_word": "蜜", "complexity_tier": "T3", "furigana": "朝早[あさはや]く、小[ちい]さな蜂[はち]が花[はな]から蜜[みつ]を運[はこ]んでいました。", "sentence_source": "generated"}, {"text": "蜜がなくなった花に、もう蝶は来ません。", "target_word": "蜜", "complexity_tier": "T3", "furigana": "蜜[みつ]がなくなった花[はな]に、もう蝶[ちょう]は来[き]ません。", "sentence_source": "generated"}, {"text": "子どものころ、花の蜜を吸って遊びました。", "target_word": "蜜", "complexity_tier": "T3", "furigana": "子[こ]どものころ、花[はな]の蜜[みつ]を吸[す]って遊[あそ]びました。", "sentence_source": "generated"}, {"text": "雨の日は、花の蜜が薄くなってしまいます。", "target_word": "蜜", "complexity_tier": "T3", "furigana": "雨[あめ]の日[ひ]は、花[はな]の蜜[みつ]が薄[うす]くなってしまいます。", "sentence_source": "generated"}, {"text": "蝶は長い口で、花の奥にある蜜を吸います。", "target_word": "蜜", "complexity_tier": "T3", "furigana": "蝶[ちょう]は長[なが]い口[くち]で、花[はな]の奥[おく]にある蜜[みつ]を吸[す]います。", "sentence_source": "generated"}, {"text": "蜜を求めて、庭にいろいろな虫がやって来ました。", "target_word": "蜜", "complexity_tier": "T3", "furigana": "蜜[みつ]を求[もと]めて、庭[にわ]にいろいろな虫[むし]がやって来[き]ました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "蜜", "label": "基本形"}], "register": "丁寧語（です・ます体）", "sense_fingerprint": "花の中にある甘い汁。虫や鳥が吸いに来る。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7027329f-781d-4983-bb14-05a931bba1d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39538, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "蜜", "is_correct": true, "explanation": "蝶が花から吸うのは甘い汁の〈蜜〉で、文の意味に合う。"}, {"text": "花びら", "is_correct": false, "explanation": "花びらは吸って飲むものではなく、蝶が吸う甘い汁ではない。"}, {"text": "葉", "is_correct": false, "explanation": "葉は吸って取る対象ではなく、『吸って』と合わない。"}, {"text": "根", "is_correct": false, "explanation": "根は地中にあり、蝶が吸える場所や物ではない。"}], "explanations": {"蜜": "蝶が花から吸うのは甘い汁の〈蜜〉で、文の意味に合う。", "花びら": "花びらは吸って飲むものではなく、蝶が吸う甘い汁ではない。", "葉": "葉は吸って取る対象ではなく、『吸って』と合わない。", "根": "根は地中にあり、蝶が吸える場所や物ではない。"}, "sentence_index": 0, "correct_answer": "蜜"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "大雨のあと、道が蜜でぬかるみました。", "explanation": "ここは〈泥〉の意味。雨でぬかるむのは泥で、蜜は甘い液体なので道をぬかるませない。"}, {"text": "この花は強い蜜を放っていて、遠くからでも分かります。", "explanation": "ここは〈香り〉の意味。遠くまで届くのは香りで、蜜は甘い液体なので『放つ』とは言わない。"}, {"text": "暑い日は、体から蜜がたくさん出ます。", "explanation": "ここは〈汗〉の意味。体から出るのは汗で、蜜は花の甘い汁なので体からは出ない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bd28592-cbc0-45fd-b14a-bebd7286389c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39538, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "蜜", "is_correct": true, "explanation": "花の甘い汁は〈蜜〉で、吸って遊ぶ対象として文に合う。"}, {"text": "砂", "is_correct": false, "explanation": "砂は吸って遊ぶものではなく、この文には合わない。"}, {"text": "種", "is_correct": false, "explanation": "種は吸って取れるものではなく、この文には合わない。"}, {"text": "雑草", "is_correct": false, "explanation": "雑草は吸う対象ではなく、遊びとしても成り立たない。"}], "explanations": {"蜜": "花の甘い汁は〈蜜〉で、吸って遊ぶ対象として文に合う。", "砂": "砂は吸って遊ぶものではなく、この文には合わない。", "種": "種は吸って取れるものではなく、この文には合わない。", "雑草": "雑草は吸う対象ではなく、遊びとしても成り立たない。"}, "sentence_index": 6, "correct_answer": "蜜"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "悲しい映画を見て、目から蜜がこぼれました。", "explanation": "ここは〈涙〉の意味。目からこぼれるのは涙で、蜜は花の甘い汁なので目からは出ない。"}, {"text": "たき火から蜜が立ちのぼりました。", "explanation": "ここは〈煙〉の意味。立ちのぼるのは煙で、蜜は液体なので立ちのぼらない。"}, {"text": "夜のあいだに蜜が積もって、道が白くなりました。", "explanation": "ここは〈雪〉の意味。積もるのは雪で、蜜は積もらず道を白くもしない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bd28592-cbc0-45fd-b14a-bebd7286389c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39538, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "朝の庭で、蝶が花の蜜を噛んで休んでいました。", "corrected_sentence": "朝の庭で、蝶が花の蜜を吸って休んでいました。", "error_description": "『噛んで』が誤りで『吸って』が正しい。蜜は吸うもので、噛んで取るものではない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bd28592-cbc0-45fd-b14a-bebd7286389c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39538, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "秋の朝、花の蜜が吸いに、ハチがやって来ました。", "corrected_sentence": "秋の朝、花の蜜を吸いに、ハチがやって来ました。", "error_description": "『蜜が』は主語を示し、『吸いに』の対象にならない。正しくは目的語の『蜜を』。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bd28592-cbc0-45fd-b14a-bebd7286389c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39539, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "『吸った』の対象を示す。蜜を吸った。"}, {"text": "に", "is_correct": false, "explanation": "『に』は相手や場所を表し、吸う対象を示せない。"}, {"text": "で", "is_correct": false, "explanation": "『で』は手段や場所を表し、吸う対象にはならない。"}, {"text": "と", "is_correct": false, "explanation": "『と』は並列や相手を表し、吸う対象にはならない。"}], "correct_answer": "を", "explanations": {"を": "『吸った』の対象を示す。蜜を吸った。", "に": "『に』は相手や場所を表し、吸う対象を示せない。", "で": "『で』は手段や場所を表し、吸う対象にはならない。", "と": "『と』は並列や相手を表し、吸う対象にはならない。"}, "error_tags": {"に": "相手", "で": "手段", "と": "並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bd28592-cbc0-45fd-b14a-bebd7286389c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39539, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "『乾く』の主語は蜜なので、『が』が正しい。"}, {"text": "を", "is_correct": false, "explanation": "『乾く』は自動詞なので、目的語『を』は取らない。"}, {"text": "の", "is_correct": false, "explanation": "『の』は名詞をつなぐだけで、乾く主体を示せない。"}, {"text": "へ", "is_correct": false, "explanation": "『へ』は方向を表し、乾くものを表せない。"}], "correct_answer": "が", "explanations": {"が": "『乾く』の主語は蜜なので、『が』が正しい。", "を": "『乾く』は自動詞なので、目的語『を』は取らない。", "の": "『の』は名詞をつなぐだけで、乾く主体を示せない。", "へ": "『へ』は方向を表し、乾くものを表せない。"}, "error_tags": {"を": "目的語", "の": "連体修飾", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bd28592-cbc0-45fd-b14a-bebd7286389c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39539, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "花の蜜は、花が昆虫を引き寄せるために出す甘い液体です。", "primary_collocate": null, "pronunciation": "みつ", "ipa": "mitsɯ", "syllable_count": 2, "sentences": [{"text": "花は虫を呼ぶために、甘い蜜を出します。", "target_word": "蜜", "complexity_tier": "T3", "furigana": "花[はな]は虫[むし]を呼[よ]ぶために、甘[あま]い蜜[みつ]を出[だ]します。", "sentence_source": "generated"}, {"text": "蜜を吸った蝶が、花粉を別の花に運びます。", "target_word": "蜜", "complexity_tier": "T3", "furigana": "蜜[みつ]を吸[す]った蝶[ちょう]が、花粉[かふん]を別[べつ]の花[はな]に運[はこ]びます。", "sentence_source": "generated"}, {"text": "この椿は蜜がたっぷりあって、メジロがよく来ます。", "target_word": "蜜", "complexity_tier": "T3", "furigana": "この椿[つばき]は蜜[みつ]がたっぷりあって、メジロがよく来[き]ます。", "sentence_source": "generated"}, {"text": "蜜を出さない花には、虫があまり寄ってきません。", "target_word": "蜜", "complexity_tier": "T3", "furigana": "蜜[みつ]を出[だ]さない花[はな]には、虫[むし]があまり寄[よ]ってきません。", "sentence_source": "generated"}, {"text": "花の中に蜜があるので、虫は奥まで入っていきます。", "target_word": "蜜", "complexity_tier": "T3", "furigana": "花[はな]の中[なか]に蜜[みつ]があるので、虫[むし]は奥[おく]まで入[はい]っていきます。", "sentence_source": "generated"}, {"text": "蜜の多い花を植えると、庭に蝶が増えます。", "target_word": "蜜", "complexity_tier": "T3", "furigana": "蜜[みつ]の多[おお]い花[はな]を植[う]えると、庭[にわ]に蝶[ちょう]が増[ふ]えます。", "sentence_source": "generated"}, {"text": "ハチは集めた蜜を巣に持ち帰ります。", "target_word": "蜜", "complexity_tier": "T3", "furigana": "ハチは集[あつ]めた蜜[みつ]を巣[す]に持[も]ち帰[かえ]ります。", "sentence_source": "generated"}, {"text": "夏の暑い日は、花の蜜がすぐに乾いてしまいます。", "target_word": "蜜", "complexity_tier": "T3", "furigana": "夏[なつ]の暑[あつ]い日[ひ]は、花[はな]の蜜[みつ]がすぐに乾[かわ]いてしまいます。", "sentence_source": "generated"}, {"text": "蝶が蜜を吸うところを、じっと観察しました。", "target_word": "蜜", "complexity_tier": "T3", "furigana": "蝶[ちょう]が蜜[みつ]を吸[す]うところを、じっと観察[かんさつ]しました。", "sentence_source": "generated"}, {"text": "蜜の香りに誘われて、小さな虫が集まってきました。", "target_word": "蜜", "complexity_tier": "T3", "furigana": "蜜[みつ]の香[かお]りに誘[さそ]われて、小[ちい]さな虫[むし]が集[あつ]まってきました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "蜜", "label": "基本形"}], "register": "丁寧語（です・ます体）", "sense_fingerprint": "花が虫を呼ぶために出す甘い液体。花粉を運ぶ虫が吸う。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7027329f-781d-4983-bb14-05a931bba1d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39539, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "蜜", "is_correct": true, "explanation": "虫を呼ぶために花が出す甘い液体は〈蜜〉で、文の意味に合う。"}, {"text": "花びら", "is_correct": false, "explanation": "花びらは甘い液体を出すものではなく、『甘い』と合わない。"}, {"text": "根", "is_correct": false, "explanation": "根は甘い液体を出さず、虫を呼ぶ役割もない。"}, {"text": "茎", "is_correct": false, "explanation": "茎は甘い液を出すものではなく、この文では意味が通らない。"}], "explanations": {"蜜": "虫を呼ぶために花が出す甘い液体は〈蜜〉で、文の意味に合う。", "花びら": "花びらは甘い液体を出すものではなく、『甘い』と合わない。", "根": "根は甘い液体を出さず、虫を呼ぶ役割もない。", "茎": "茎は甘い液を出すものではなく、この文では意味が通らない。"}, "sentence_index": 0, "correct_answer": "蜜"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "大雨のあと、学校の庭が蜜でぬかるみました。", "explanation": "ここは〈泥〉の意味。雨でぬかるむのは泥で、蜜は甘い液体なので庭をぬかるませない。"}, {"text": "この花は強い蜜を放ち、遠くのハチを呼びます。", "explanation": "ここは〈香り〉の意味。遠くまで届くのは香りで、蜜は甘い液体なので『放つ』とは言わない。"}, {"text": "走ったあと、体から蜜が流れ出ました。", "explanation": "ここは〈汗〉の意味。体から流れ出るのは汗で、蜜は花の甘い汁なので体からは出ない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bd28592-cbc0-45fd-b14a-bebd7286389c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39539, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "蜜", "is_correct": true, "explanation": "ハチが集めて巣に持ち帰るのは花の蜜で、文の意味に合う。"}, {"text": "石", "is_correct": false, "explanation": "石はハチが集めて巣に持ち帰るものではなく、習性に合わない。"}, {"text": "硬貨", "is_correct": false, "explanation": "硬貨はハチが集めて巣に持ち帰るものではなく、習性に合わない。"}, {"text": "雨粒", "is_correct": false, "explanation": "雨粒は集めて持ち帰れるものではなく、この文では成り立たない。"}], "explanations": {"蜜": "ハチが集めて巣に持ち帰るのは花の蜜で、文の意味に合う。", "石": "石はハチが集めて巣に持ち帰るものではなく、習性に合わない。", "硬貨": "硬貨はハチが集めて巣に持ち帰るものではなく、習性に合わない。", "雨粒": "雨粒は集めて持ち帰れるものではなく、この文では成り立たない。"}, "sentence_index": 6, "correct_answer": "蜜"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "朝は蜜が立ちこめていて、道が見えませんでした。", "explanation": "ここは〈霧〉の意味。立ちこめるのは霧で、蜜は液体なので立ちこめない。"}, {"text": "屋根に蜜が積もりました。", "explanation": "ここは〈雪〉の意味。積もるのは雪で、蜜は積もらない。"}, {"text": "フライパンに蜜を引いて、卵を焼きました。", "explanation": "ここは〈油〉の意味。フライパンに引くのは油で、蜜は焼く前に引くものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bd28592-cbc0-45fd-b14a-bebd7286389c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39539, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "蝶は、花の蜜を噛むために、花へ来ます。", "corrected_sentence": "蝶は、花の蜜を吸うために、花へ来ます。", "error_description": "『噛む』が誤りで『吸う』が正しい。蜜は吸うもので、噛んで取るものではない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bd28592-cbc0-45fd-b14a-bebd7286389c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39539, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夏の朝、ハチが蜜に吸いに来ました。", "corrected_sentence": "夏の朝、ハチが蜜を吸いに来ました。", "error_description": "『蜜に』は対象を示せない。『吸う』の対象は『蜜を』で、『に』が誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bd28592-cbc0-45fd-b14a-bebd7286389c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39540, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "正解。「背中が」は凝っている状態の主語を示す。"}, {"text": "を", "is_correct": false, "explanation": "「凝る」は目的語を取らないので、「背中を凝っている」は成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所や手段を表すので、状態の主語にはならない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表すので、体の部分の状態を示せない。"}], "correct_answer": "が", "explanations": {"が": "正解。「背中が」は凝っている状態の主語を示す。", "を": "「凝る」は目的語を取らないので、「背中を凝っている」は成り立たない。", "で": "「で」は場所や手段を表すので、状態の主語にはならない。", "へ": "「へ」は方向を表すので、体の部分の状態を示せない。"}, "error_tags": {"を": "目的語（対象）", "で": "場所・手段", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bd28592-cbc0-45fd-b14a-bebd7286389c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
