INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39540, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "かたや せなかが かたくなること。", "primary_collocate": null, "pronunciation": "こる", "ipa": "koɾɯ", "syllable_count": 2, "sentences": [{"text": "一日中パソコンを使うと、肩が凝ります。", "target_word": "凝ります", "complexity_tier": "T3", "furigana": "一日中[いちにちじゅう]パソコンを使[つか]うと、肩[かた]が凝[こ]ります。", "sentence_source": "generated"}, {"text": "背中が凝っているので、マッサージに行きたいです。", "target_word": "凝って", "complexity_tier": "T3", "furigana": "背中[せなか]が凝[こ]っているので、マッサージに行[い]きたいです。", "sentence_source": "generated"}, {"text": "長い時間同じ姿勢で座っていたので、首が凝りました。", "target_word": "凝りました", "complexity_tier": "T3", "furigana": "長[なが]い時間[じかん]同[おな]じ姿勢[しせい]で座[すわ]っていたので、首[くび]が凝[こ]りました。", "sentence_source": "generated"}, {"text": "肩が凝ったときは、お風呂で温めると楽になります。", "target_word": "凝った", "complexity_tier": "T3", "furigana": "肩[かた]が凝[こ]ったときは、お風呂[ふろ]で温[あたた]めると楽[らく]になります。", "sentence_source": "generated"}, {"text": "重いかばんを持って歩くと、肩が凝りやすいです。", "target_word": "凝りやすい", "complexity_tier": "T3", "furigana": "重[おも]いかばんを持[も]って歩[ある]くと、肩[かた]が凝[こ]りやすいです。", "sentence_source": "generated"}, {"text": "運動不足で背中が凝って、夜よく眠れませんでした。", "target_word": "凝って", "complexity_tier": "T3", "furigana": "運動不足[うんどうぶそく]で背中[せなか]が凝[こ]って、夜[よる]よく眠[ねむ]れませんでした。", "sentence_source": "generated"}, {"text": "肩がひどく凝っていて、腕が上がりません。", "target_word": "凝って", "complexity_tier": "T3", "furigana": "肩[かた]がひどく凝[こ]っていて、腕[うで]が上[あ]がりません。", "sentence_source": "generated"}, {"text": "寒い日は体が冷えて、肩が凝ることが多いです。", "target_word": "凝る", "complexity_tier": "T3", "furigana": "寒[さむ]い日[ひ]は体[からだ]が冷[ひ]えて、肩[かた]が凝[こ]ることが多[おお]いです。", "sentence_source": "generated"}, {"text": "背中が凝らないように、ときどき立って体を伸ばします。", "target_word": "凝らない", "complexity_tier": "T3", "furigana": "背中[せなか]が凝[こ]らないように、ときどき立[た]って体[からだ]を伸[の]ばします。", "sentence_source": "generated"}, {"text": "仕事のあと、凝った肩を母にもんでもらいました。", "target_word": "凝った", "complexity_tier": "T3", "furigana": "仕事[しごと]のあと、凝[こ]った肩[かた]を母[はは]にもんでもらいました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "凝る", "label": "辞書形"}, {"form": "凝ります", "label": "ます形"}, {"form": "凝らない", "label": "ない形"}, {"form": "凝って", "label": "て形"}, {"form": "凝った", "label": "た形"}, {"form": "凝れば", "label": "ば形"}], "register": "丁寧語（です・ます体）", "sense_fingerprint": "肩や背中などの筋肉がかたくなって、重く痛く感じる。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7027329f-781d-4983-bb14-05a931bba1d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39540, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "凝ります", "is_correct": true, "explanation": "正解。肩の筋肉がかたくなる意味の「凝る」の丁寧形で、「肩が凝ります」が成り立つ。"}, {"text": "眠ります", "is_correct": false, "explanation": "「眠る」は寝ることなので、肩を主語にすると文が成り立たない。"}, {"text": "座ります", "is_correct": false, "explanation": "「座る」は体を下ろす動作で、肩が主語では意味が通らない。"}, {"text": "歩きます", "is_correct": false, "explanation": "「歩く」は体全体の移動なので、肩が主語では文が成り立たない。"}], "explanations": {"凝ります": "正解。肩の筋肉がかたくなる意味の「凝る」の丁寧形で、「肩が凝ります」が成り立つ。", "眠ります": "「眠る」は寝ることなので、肩を主語にすると文が成り立たない。", "座ります": "「座る」は体を下ろす動作で、肩が主語では意味が通らない。", "歩きます": "「歩く」は体全体の移動なので、肩が主語では文が成り立たない。"}, "sentence_index": 0, "correct_answer": "凝ります"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "緊張で声が凝って、うまく返事ができなかった。", "explanation": "ここは「強張る」の意味の文。「凝る」は肩や首、背中など体の部分がこわばるときに使い、声の緊張には使わない。"}, {"text": "寒い朝は、池の水が凝って、氷になる。", "explanation": "ここは「固まる」の意味の文。「凝る」は肩や背中など体の筋肉がかたくなる意味で、池の水には使わない。"}, {"text": "乾いた洗濯物の生地が凝って、ごわごわになった。", "explanation": "ここは「強張る」の意味の文。「凝る」は体の部分に使い、布地がこわばる場合には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bd28592-cbc0-45fd-b14a-bebd7286389c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39540, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "凝って", "is_correct": true, "explanation": "正解。「凝っていて」で、肩の筋肉がかたくなっている状態を表す。"}, {"text": "走って", "is_correct": false, "explanation": "「肩が走っていて」は主語と動詞が合わず、意味が通らない。"}, {"text": "叫んで", "is_correct": false, "explanation": "肩は叫ぶことができないので、文が成り立たない。"}, {"text": "泣いて", "is_correct": false, "explanation": "「肩が泣く」は日本語として通じず、腕が上がらない文脈とも合わない。"}], "explanations": {"凝って": "正解。「凝っていて」で、肩の筋肉がかたくなっている状態を表す。", "走って": "「肩が走っていて」は主語と動詞が合わず、意味が通らない。", "叫んで": "肩は叫ぶことができないので、文が成り立たない。", "泣いて": "「肩が泣く」は日本語として通じず、腕が上がらない文脈とも合わない。"}, "sentence_index": 6, "correct_answer": "凝って"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "冷凍庫から出した肉が凝っていた。", "explanation": "ここは「硬直」の意味の文。「凝る」は生きた体の筋肉がかたくなる意味で、冷凍肉には使わない。"}, {"text": "果物を煮詰めると、果汁が凝って甘くなる。", "explanation": "ここは「凝縮」の意味の文。「凝る」は体の部分がかたくなる意味で、果汁の濃縮には使わない。"}, {"text": "牛乳に酢を入れると、たんぱく質が凝る。", "explanation": "ここは「凝固」の意味の文。「凝る」は体の部分の状態に使い、たんぱく質の固まりには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bd28592-cbc0-45fd-b14a-bebd7286389c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39540, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "毎日長く車を運転すると、肩を凝ります。", "corrected_sentence": "毎日長く車を運転すると、肩が凝ります。", "error_description": "「肩を凝ります」は誤り。「凝る」は目的語を取らない動詞なので、主語の「肩」には「が」を使い「肩が凝ります」とする。（誤り：を → 正しい：が）", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "凝って", "is_correct": true, "explanation": "正解。て形の「凝って」は「〜ているので」に続き、文が成り立つ。"}, {"text": "凝る", "is_correct": false, "explanation": "辞書形は「〜ている」に直接続かないので、「凝るいるので」となり成り立たない。"}, {"text": "凝らない", "is_correct": false, "explanation": "ない形は「〜いるので」に続かず、この位置では文が崩れる。"}, {"text": "凝れば", "is_correct": false, "explanation": "ば形は条件を表すので、「凝れば、いるので」とは続かない。"}], "correct_form": "凝って", "base_form": "凝る", "form_label": "て形（〜ている）", "sentence_index": 1, "explanations": {"凝って": "正解。て形の「凝って」は「〜ているので」に続き、文が成り立つ。", "凝る": "辞書形は「〜ている」に直接続かないので、「凝るいるので」となり成り立たない。", "凝らない": "ない形は「〜いるので」に続かず、この位置では文が崩れる。", "凝れば": "ば形は条件を表すので、「凝れば、いるので」とは続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bd28592-cbc0-45fd-b14a-bebd7286389c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39540, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ずっとパソコンに向かっていたら、肩が凝るました。", "corrected_sentence": "ずっとパソコンに向かっていたら、肩が凝りました。", "error_description": "「凝るました」は誤り。「ます」は動詞の連用形（凝り）につけるので、辞書形の「凝る」にはつけられない。正しくは「凝りました」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "凝る", "is_correct": true, "explanation": "正解。辞書形の「凝る」は「〜ことが多い」と名詞化して続けられる。"}, {"text": "凝って", "is_correct": false, "explanation": "て形は「〜ことが」に続かないので、文が成り立たない。"}, {"text": "凝ろう", "is_correct": false, "explanation": "意向形は「凝ろうことが」となり不自然で、文の骨組みに合わない。"}, {"text": "凝れ", "is_correct": false, "explanation": "命令形は文を命令にしてしまい、「〜ことが多い」に続かない。"}], "correct_form": "凝る", "base_form": "凝る", "form_label": "辞書形（〜ことが）", "sentence_index": 7, "explanations": {"凝る": "正解。辞書形の「凝る」は「〜ことが多い」と名詞化して続けられる。", "凝って": "て形は「〜ことが」に続かないので、文が成り立たない。", "凝ろう": "意向形は「凝ろうことが」となり不自然で、文の骨組みに合わない。", "凝れ": "命令形は文を命令にしてしまい、「〜ことが多い」に続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bd28592-cbc0-45fd-b14a-bebd7286389c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
