INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39542, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "わるいことをして、もういやだとおもうこと。", "primary_collocate": null, "pronunciation": "こりる", "ipa": "koɾiɾɯ", "syllable_count": 3, "sentences": [{"text": "彼は何度も失敗したのに、まだ懲りていない。", "target_word": "懲りて", "complexity_tier": "T3", "furigana": "彼[かれ]は何度[なんど]も失敗[しっぱい]したのに、まだ懲[こ]りていない。", "sentence_source": "generated"}, {"text": "遅刻して先生に怒られたので、もう懲りました。", "target_word": "懲りました", "complexity_tier": "T3", "furigana": "遅刻[ちこく]して先生[せんせい]に怒[おこ]られたので、もう懲[こ]りました。", "sentence_source": "generated"}, {"text": "嘘をついて友達を失い、彼は懲りたようだ。", "target_word": "懲りた", "complexity_tier": "T3", "furigana": "嘘[うそ]をついて友達[ともだち]を失[うしな]い、彼[かれ]は懲[こ]りたようだ。", "sentence_source": "generated"}, {"text": "あんなに叱られても、弟は懲りずにまた悪さをした。", "target_word": "懲りず", "complexity_tier": "T3", "furigana": "あんなに叱[しか]られても、弟[おとうと]は懲[こ]りずにまた悪[わる]さをした。", "sentence_source": "generated"}, {"text": "夜更かしして風邪をひいたので、もう懲りた。", "target_word": "懲りた", "complexity_tier": "T3", "furigana": "夜更[よふ]かしして風邪[かぜ]をひいたので、もう懲[こ]りた。", "sentence_source": "generated"}, {"text": "一度痛い目にあえば、さすがに懲りるだろう。", "target_word": "懲りる", "complexity_tier": "T3", "furigana": "一度[いちど]痛[いた]い目[め]にあえば、さすがに懲[こ]りるだろう。", "sentence_source": "generated"}, {"text": "食べすぎて苦しんだ私は、懲りて腹八分にしている。", "target_word": "懲りて", "complexity_tier": "T3", "furigana": "食[た]べすぎて苦[くる]しんだ私[わたし]は、懲[こ]りて腹八分[はらはちぶ]にしている。", "sentence_source": "generated"}, {"text": "彼は借金で苦労したのに、全然懲りない人だ。", "target_word": "懲りない", "complexity_tier": "T3", "furigana": "彼[かれ]は借金[しゃっきん]で苦労[くろう]したのに、全然[ぜんぜん]懲[こ]りない人[ひと]だ。", "sentence_source": "generated"}, {"text": "宿題を忘れて困ったから、これで懲りたはずだ。", "target_word": "懲りた", "complexity_tier": "T3", "furigana": "宿題[しゅくだい]を忘[わす]れて困[こま]ったから、これで懲[こ]りたはずだ。", "sentence_source": "generated"}, {"text": "試験前に遊んで失敗し、娘はやっと懲りたようだ。", "target_word": "懲りた", "complexity_tier": "T3", "furigana": "試験前[しけんまえ]に遊[あそ]んで失敗[しっぱい]し、娘[むすめ]はやっと懲[こ]りたようだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "懲りない", "label": "negative"}, {"form": "懲りて", "label": "te-form"}, {"form": "懲りた", "label": "past"}, {"form": "懲りれば", "label": "conditional"}, {"form": "懲りずに", "label": "negative adverbial"}], "register": "neutral", "sense_fingerprint": "悪いことや失敗をして、もうしたくないと強く思う", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9917535d-1ee3-48f0-905e-62105b0c1b5b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39542, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "懲りて", "is_correct": true, "explanation": "「まだ〜ていない」の形で、経験から学んでいない状態を表す。"}, {"text": "懲りた", "is_correct": false, "explanation": "過去形では「まだ懲りたいない」となり、後ろの「いない」と続かない。"}, {"text": "懲りれば", "is_correct": false, "explanation": "条件形では文が途中で切れ、「いない」と続かない。"}, {"text": "懲りろ", "is_correct": false, "explanation": "命令形では「まだ懲りろいない」となり、文として成り立たない。"}], "explanations": {"懲りて": "「まだ〜ていない」の形で、経験から学んでいない状態を表す。", "懲りた": "過去形では「まだ懲りたいない」となり、後ろの「いない」と続かない。", "懲りれば": "条件形では文が途中で切れ、「いない」と続かない。", "懲りろ": "命令形では「まだ懲りろいない」となり、文として成り立たない。"}, "sentence_index": 0, "correct_answer": "懲りて"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "朝から座りっぱなしで、肩が懲りて痛い。", "explanation": "ここは〈凝る〉（肩がこる）の意味。懲りるは悪い経験で嫌になる意味なので、体がこわばる意味では使えない。"}, {"text": "新作ゲームに懲りて、一晩中やめられなかった。", "explanation": "ここは〈夢中になる〉の意味。懲りるは悪い経験の後で嫌になる意味なので、熱中する意味では合わない。"}, {"text": "いたずらした弟を、母は懲りて厳しく叱った。", "explanation": "ここは〈懲らしめる（罰を与える）〉の意味。懲りるは自分が嫌になる意味の自動詞で、人に罰を与える意味では使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3361c338-6e56-449e-8b1e-cdcf1bbca704') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39542, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "懲りて", "is_correct": true, "explanation": "「懲りて」で、経験を理由に腹八分にするという因果を表す。"}, {"text": "懲りなかった", "is_correct": false, "explanation": "過去の否定形では、現在の習慣「腹八分にしている」とつながる理由にならない。"}, {"text": "懲りろ", "is_correct": false, "explanation": "命令形では「、腹八分にしている」と続かず、文が成り立たない。"}, {"text": "懲りたくない", "is_correct": false, "explanation": "願望の否定で、「腹八分にしている」と続く因果が成り立たない。"}], "explanations": {"懲りて": "「懲りて」で、経験を理由に腹八分にするという因果を表す。", "懲りなかった": "過去の否定形では、現在の習慣「腹八分にしている」とつながる理由にならない。", "懲りろ": "命令形では「、腹八分にしている」と続かず、文が成り立たない。", "懲りたくない": "願望の否定で、「腹八分にしている」と続く因果が成り立たない。"}, "sentence_index": 6, "correct_answer": "懲りて"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "合格の知らせを聞いて、家族は懲りて大喜びした。", "explanation": "ここは〈喜ぶ〉の意味。懲りるは悪い経験の後に嫌になる意味なので、喜びの場面では使えない。"}, {"text": "映画のラストに感動して、懲りて泣いてしまった。", "explanation": "ここは〈感動する〉の意味。懲りるは嫌な経験で嫌になる意味なので、感動の場面には合わない。"}, {"text": "彼女に一目で懲りて、毎日手紙を書いた。", "explanation": "ここは〈恋をする〉の意味。懲りるは悪い経験で嫌になる意味なので、恋愛感情には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3361c338-6e56-449e-8b1e-cdcf1bbca704') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39542, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "借金で苦労したのに、彼はまだ懲りるていない。", "corrected_sentence": "借金で苦労したのに、彼はまだ懲りていない。", "error_description": "誤りは「懲りる」の活用。て形は「懲りて」で、「懲りるて」は文法的に成り立たない。正しくは「まだ懲りていない」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "懲りました", "is_correct": true, "explanation": "「もう〜ました」で、過去に経験して嫌になったことを丁寧に表す。"}, {"text": "懲りれば", "is_correct": false, "explanation": "条件形では文が途中で切れ、「もう」と続く完結した文にならない。"}, {"text": "懲りない", "is_correct": false, "explanation": "否定形では、怒られた後に懲りたという文脈と矛盾する。"}, {"text": "懲りられる", "is_correct": false, "explanation": "可能形で、「もう懲りられる」は経験後の結果を述べる文にならない。"}], "correct_form": "懲りました", "base_form": "懲りる", "form_label": "丁寧な過去形", "sentence_index": 1, "explanations": {"懲りました": "「もう〜ました」で、過去に経験して嫌になったことを丁寧に表す。", "懲りれば": "条件形では文が途中で切れ、「もう」と続く完結した文にならない。", "懲りない": "否定形では、怒られた後に懲りたという文脈と矛盾する。", "懲りられる": "可能形で、「もう懲りられる」は経験後の結果を述べる文にならない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3361c338-6e56-449e-8b1e-cdcf1bbca704') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39542, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼女は恋愛を懲りて、もう二度と付き合わない。", "corrected_sentence": "彼女は恋愛に懲りて、もう二度と付き合わない。", "error_description": "誤りは助詞。「懲りる」は「〜に懲りる」と使うので、「恋愛を」の「を」は誤りで、正しくは「恋愛に」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "懲りない", "is_correct": true, "explanation": "「全然懲りない人」の否定形で、後ろの名詞を修飾している。"}, {"text": "懲りずに", "is_correct": false, "explanation": "副詞形で、「人だ」と続く名詞修飾の形にならない。"}, {"text": "懲りなければ", "is_correct": false, "explanation": "条件形で、「人だ」と続く文として成り立たない。"}, {"text": "懲りないで", "is_correct": false, "explanation": "禁止・依頼の形で、「人だ」と続かない。"}], "correct_form": "懲りない", "base_form": "懲りる", "form_label": "否定形", "sentence_index": 7, "explanations": {"懲りない": "「全然懲りない人」の否定形で、後ろの名詞を修飾している。", "懲りずに": "副詞形で、「人だ」と続く名詞修飾の形にならない。", "懲りなければ": "条件形で、「人だ」と続く文として成り立たない。", "懲りないで": "禁止・依頼の形で、「人だ」と続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3361c338-6e56-449e-8b1e-cdcf1bbca704') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39543, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「満員電車に懲りて」の「に」で、懲りる対象を示す。"}, {"text": "を", "is_correct": false, "explanation": "「懲りる」は「を」を取らず、「満員電車を懲りて」は成り立たない。"}, {"text": "が", "is_correct": false, "explanation": "「満員電車が懲りて」は主語として不自然で、懲りる対象を示せない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表すため、「懲りて」の対象にはならない。"}], "correct_answer": "に", "explanations": {"に": "「満員電車に懲りて」の「に」で、懲りる対象を示す。", "を": "「懲りる」は「を」を取らず、「満員電車を懲りて」は成り立たない。", "が": "「満員電車が懲りて」は主語として不自然で、懲りる対象を示せない。", "へ": "「へ」は方向を表すため、「懲りて」の対象にはならない。"}, "error_tags": {"を": "目的語を取らない", "が": "主語として不自然", "へ": "方向を表す"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3361c338-6e56-449e-8b1e-cdcf1bbca704') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
