INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39543, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "経験したことから、もう同じことをしたくないと思うようになる。", "primary_collocate": null, "pronunciation": "こりる", "ipa": "koɾiɾɯ", "syllable_count": 3, "sentences": [{"text": "一度大失敗した彼は、もう株には懲りたと言っている。", "target_word": "懲りた", "complexity_tier": "T3", "furigana": "一度[いちど]大失敗[だいしっぱい]した彼[かれ]は、もう株[かぶ]には懲[こ]りたと言[い]っている。", "sentence_source": "generated"}, {"text": "満員電車に懲りて、今は早朝に出勤している。", "target_word": "懲りて", "complexity_tier": "T3", "furigana": "満員電車[まんいんでんしゃ]に懲[こ]りて、今[いま]は早朝[そうちょう]に出勤[しゅっきん]している。", "sentence_source": "generated"}, {"text": "台風で旅行が中止になり、夏の旅行には懲りた。", "target_word": "懲りた", "complexity_tier": "T3", "furigana": "台風[たいふう]で旅行[りょこう]が中止[ちゅうし]になり、夏[なつ]の旅行[りょこう]には懲[こ]りた。", "sentence_source": "generated"}, {"text": "あの店で高い料理を食べて懲りたので、二度と行かない。", "target_word": "懲りた", "complexity_tier": "T3", "furigana": "あの店[みせ]で高[たか]い料理[りょうり]を食[た]べて懲[こ]りたので、二度[にど]と行[い]かない。", "sentence_source": "generated"}, {"text": "彼女は恋愛で傷ついて、すっかり懲りてしまった。", "target_word": "懲りて", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は恋愛[れんあい]で傷[きず]ついて、すっかり懲[こ]りてしまった。", "sentence_source": "generated"}, {"text": "安い物を買って壊れたので、もう懲りました。", "target_word": "懲りました", "complexity_tier": "T3", "furigana": "安[やす]い物[もの]を買[か]って壊[こわ]れたので、もう懲[こ]りました。", "sentence_source": "generated"}, {"text": "私は雨の日の山登りに懲りて、天気を必ず調べる。", "target_word": "懲りて", "complexity_tier": "T3", "furigana": "私[わたし]は雨[あめ]の日[ひ]の山登[やまのぼ]りに懲[こ]りて、天気[てんき]を必[かなら]ず調[しら]べる。", "sentence_source": "generated"}, {"text": "失敗に懲りず、彼は新しい事業を始めた。", "target_word": "懲りず", "complexity_tier": "T3", "furigana": "失敗[しっぱい]に懲[こ]りず、彼[かれ]は新[あたら]しい事業[じぎょう]を始[はじ]めた。", "sentence_source": "generated"}, {"text": "痛い経験に懲りたから、同じミスはしません。", "target_word": "懲りた", "complexity_tier": "T3", "furigana": "痛[いた]い経験[けいけん]に懲[こ]りたから、同[おな]じミスはしません。", "sentence_source": "generated"}, {"text": "引っ越しの大変さに懲りて、もう当分動きたくない。", "target_word": "懲りて", "complexity_tier": "T3", "furigana": "引[ひ]っ越[こ]しの大変[たいへん]さに懲[こ]りて、もう当分[とうぶん]動[うご]きたくない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "懲りない", "label": "negative"}, {"form": "懲りて", "label": "te-form"}, {"form": "懲りた", "label": "past"}, {"form": "懲りれば", "label": "conditional"}, {"form": "懲りずに", "label": "negative adverbial"}], "register": "neutral", "sense_fingerprint": "つらい経験から、同じことを二度としたくないと思う", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9917535d-1ee3-48f0-905e-62105b0c1b5b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39543, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "懲りた", "is_correct": true, "explanation": "「もう〜と言っている」で、経験から懲りたという引用文になる。"}, {"text": "懲りて", "is_correct": false, "explanation": "て形では引用の「と言っている」に続かず、文が成り立たない。"}, {"text": "懲りれば", "is_correct": false, "explanation": "条件形では引用文にならず、「と言っている」が続かない。"}, {"text": "懲りず", "is_correct": false, "explanation": "「懲りずと言っている」となり、文として成り立たない。"}], "explanations": {"懲りた": "「もう〜と言っている」で、経験から懲りたという引用文になる。", "懲りて": "て形では引用の「と言っている」に続かず、文が成り立たない。", "懲りれば": "条件形では引用文にならず、「と言っている」が続かない。", "懲りず": "「懲りずと言っている」となり、文として成り立たない。"}, "sentence_index": 0, "correct_answer": "懲りた"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "一日中パソコンに向かって、肩が懲りてしまった。", "explanation": "ここは〈凝る〉（肩がこる）の意味。懲りるは悪い経験で嫌になる意味なので、体のこわばりには使えない。"}, {"text": "ラストシーンに感動して、懲りて泣いてしまった。", "explanation": "ここは〈感動する〉の意味。懲りるは嫌な経験の後で使う語なので、感動の場面では合わない。"}, {"text": "わがままな子を、祖母は懲りて何度も叱った。", "explanation": "ここは〈懲らしめる（罰を与える）〉の意味。懲りるは自分が嫌になる意味の自動詞で、人に罰を与える意味では使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3361c338-6e56-449e-8b1e-cdcf1bbca704') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39543, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "懲りて", "is_correct": true, "explanation": "「山登りに懲りて」で、経験を理由に天気を調べるという因果を表す。"}, {"text": "懲りなかった", "is_correct": false, "explanation": "過去の否定形では、「天気を必ず調べる」と続く理由にならない。"}, {"text": "懲りていた", "is_correct": false, "explanation": "「〜ていた」は過去の状態で、現在の習慣「必ず調べる」と時制が合わない。"}, {"text": "懲りたくない", "is_correct": false, "explanation": "願望の否定で、「天気を必ず調べる」との因果が成り立たない。"}], "explanations": {"懲りて": "「山登りに懲りて」で、経験を理由に天気を調べるという因果を表す。", "懲りなかった": "過去の否定形では、「天気を必ず調べる」と続く理由にならない。", "懲りていた": "「〜ていた」は過去の状態で、現在の習慣「必ず調べる」と時制が合わない。", "懲りたくない": "願望の否定で、「天気を必ず調べる」との因果が成り立たない。"}, "sentence_index": 6, "correct_answer": "懲りて"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "優勝の知らせに、みんなは懲りて踊り出した。", "explanation": "ここは〈喜ぶ〉の意味。懲りるは悪い経験で嫌になる意味なので、喜びの場面では使えない。"}, {"text": "週末は釣りに懲りて、一日中湖にいた。", "explanation": "ここは〈夢中になる〉の意味。懲りるは嫌な経験で距離を置く意味なので、熱中する意味では合わない。"}, {"text": "彼女に一目で懲りて、毎日手紙を書いた。", "explanation": "ここは〈恋をする〉の意味。懲りるは悪い経験の後に使うので、恋愛感情には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3361c338-6e56-449e-8b1e-cdcf1bbca704') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39543, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夜中の騒音を懲りて、彼は引っ越した。", "corrected_sentence": "夜中の騒音に懲りて、彼は引っ越した。", "error_description": "誤りは助詞。「懲りる」は「〜に懲りる」と使うので、「騒音を」の「を」は誤りで、正しくは「騒音に」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "懲りて", "is_correct": true, "explanation": "て形で、「満員電車に懲りて」と原因から結果の「早朝に出勤している」へつながる。"}, {"text": "懲りない", "is_correct": false, "explanation": "否定形では「、今は早朝に出勤している」と原因と結果がつながらない。"}, {"text": "懲りろ", "is_correct": false, "explanation": "命令形では「、今は早朝に出勤している」と続かず、文が成り立たない。"}, {"text": "懲りよう", "is_correct": false, "explanation": "意志形では原因と結果がつながらず、文の意味が通らない。"}], "correct_form": "懲りて", "base_form": "懲りる", "form_label": "て形", "sentence_index": 1, "explanations": {"懲りて": "て形で、「満員電車に懲りて」と原因から結果の「早朝に出勤している」へつながる。", "懲りない": "否定形では「、今は早朝に出勤している」と原因と結果がつながらない。", "懲りろ": "命令形では「、今は早朝に出勤している」と続かず、文が成り立たない。", "懲りよう": "意志形では原因と結果がつながらず、文の意味が通らない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3361c338-6e56-449e-8b1e-cdcf1bbca704') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39543, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "隣の騒音に懲りるて、彼は引っ越した。", "corrected_sentence": "隣の騒音に懲りて、彼は引っ越した。", "error_description": "誤りは活用。て形は「懲りて」で、「懲りるて」は文法的に成り立たない。正しくは「懲りて」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "懲りず", "is_correct": true, "explanation": "「失敗に懲りず」で、経験を生かさず続けるという連用形の否定で、後の文とつながる。"}, {"text": "懲りろ", "is_correct": false, "explanation": "命令形では「、彼は新しい事業を始めた」と続かず、文が成り立たない。"}, {"text": "懲りなければ", "is_correct": false, "explanation": "条件形では文が途中で切れ、主節の「彼は新しい事業を始めた」と結びつかない。"}, {"text": "懲りた", "is_correct": false, "explanation": "過去形では、懲りた結果と新事業を始めた流れが逆になり、文の意味が通らない。"}], "correct_form": "懲りず", "base_form": "懲りる", "form_label": "ず形（否定の連用形）", "sentence_index": 7, "explanations": {"懲りず": "「失敗に懲りず」で、経験を生かさず続けるという連用形の否定で、後の文とつながる。", "懲りろ": "命令形では「、彼は新しい事業を始めた」と続かず、文が成り立たない。", "懲りなければ": "条件形では文が途中で切れ、主節の「彼は新しい事業を始めた」と結びつかない。", "懲りた": "過去形では、懲りた結果と新事業を始めた流れが逆になり、文の意味が通らない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3361c338-6e56-449e-8b1e-cdcf1bbca704') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39544, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「東京の会社に移った」の「に」で、移動先を示す。"}, {"text": "を", "is_correct": false, "explanation": "「移る」は「を」を取らず、「東京の会社を移った」は成り立たない。"}, {"text": "が", "is_correct": false, "explanation": "「東京の会社が移った」は主語として不自然で、移動先を示せない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は相手を表すため、「東京の会社と移った」は文意に合わない。"}], "correct_answer": "に", "explanations": {"に": "「東京の会社に移った」の「に」で、移動先を示す。", "を": "「移る」は「を」を取らず、「東京の会社を移った」は成り立たない。", "が": "「東京の会社が移った」は主語として不自然で、移動先を示せない。", "と": "「と」は相手を表すため、「東京の会社と移った」は文意に合わない。"}, "error_tags": {"を": "目的語を取らない", "が": "主語として不自然", "と": "相手を表す"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3361c338-6e56-449e-8b1e-cdcf1bbca704') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39544, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「後ろの車両に移った」の「に」で、移動先を示す。"}, {"text": "の", "is_correct": false, "explanation": "「車両の移った」は成り立たず、移動先を示せない。"}, {"text": "で", "is_correct": false, "explanation": "「車両で移った」は手段の意味になり、移動先を示す文として合わない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を表すため、「車両より移った」は移動先の表現にならない。"}], "correct_answer": "に", "explanations": {"に": "「後ろの車両に移った」の「に」で、移動先を示す。", "の": "「車両の移った」は成り立たず、移動先を示せない。", "で": "「車両で移った」は手段の意味になり、移動先を示す文として合わない。", "より": "「より」は比較を表すため、「車両より移った」は移動先の表現にならない。"}, "error_tags": {"の": "所属を表す", "で": "手段を表す", "より": "比較を表す"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3361c338-6e56-449e-8b1e-cdcf1bbca704') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39544, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "あるものから、べつのものに、うつる。", "primary_collocate": null, "pronunciation": "うつる", "ipa": "ɯtsɯɾɯ", "syllable_count": 3, "sentences": [{"text": "私は窓側の席から前の席に移った。", "target_word": "移った", "complexity_tier": "T3", "furigana": "私[わたし]は窓側[まどがわ]の席[せき]から前[まえ]の席[せき]に移[うつ]った。", "sentence_source": "generated"}, {"text": "兄は大阪の会社から東京の会社に移った。", "target_word": "移った", "complexity_tier": "T3", "furigana": "兄[あに]は大阪[おおさか]の会社[かいしゃ]から東京[とうきょう]の会社[かいしゃ]に移[うつ]った。", "sentence_source": "generated"}, {"text": "来月、新しい家に移る予定です。", "target_word": "移る", "complexity_tier": "T3", "furigana": "来月[らいげつ]、新[あたら]しい家[いえ]に移[うつ]る予定[よてい]です。", "sentence_source": "generated"}, {"text": "暑いので、日かげに移って休みましょう。", "target_word": "移って", "complexity_tier": "T3", "furigana": "暑[あつ]いので、日[ひ]かげに移[うつ]って休[やす]みましょう。", "sentence_source": "generated"}, {"text": "彼はサッカー部から野球部に移りました。", "target_word": "移りました", "complexity_tier": "T3", "furigana": "彼[かれ]はサッカー部[ぶ]から野球部[やきゅうぶ]に移[うつ]りました。", "sentence_source": "generated"}, {"text": "会議が終わって、みんなは隣の部屋に移った。", "target_word": "移った", "complexity_tier": "T3", "furigana": "会議[かいぎ]が終[お]わって、みんなは隣[となり]の部屋[へや]に移[うつ]った。", "sentence_source": "generated"}, {"text": "祖父は静かな病院に移って、体調がよくなった。", "target_word": "移って", "complexity_tier": "T3", "furigana": "祖父[そふ]は静[しず]かな病院[びょういん]に移[うつ]って、体調[たいちょう]がよくなった。", "sentence_source": "generated"}, {"text": "電車が混んでいたので、後ろの車両に移った。", "target_word": "移った", "complexity_tier": "T3", "furigana": "電車[でんしゃ]が混[こ]んでいたので、後[うし]ろの車両[しゃりょう]に移[うつ]った。", "sentence_source": "generated"}, {"text": "大学を卒業して、彼は研究の仕事から教える仕事に移った。", "target_word": "移った", "complexity_tier": "T3", "furigana": "大学[だいがく]を卒業[そつぎょう]して、彼[かれ]は研究[けんきゅう]の仕事[しごと]から教[おし]える仕事[しごと]に移[うつ]った。", "sentence_source": "generated"}, {"text": "雨が強くなったので、パーティーは庭から室内に移りました。", "target_word": "移りました", "complexity_tier": "T3", "furigana": "雨[あめ]が強[つよ]くなったので、パーティーは庭[にわ]から室内[しつない]に移[うつ]りました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "移らない", "label": "negative"}, {"form": "移って", "label": "te-form"}, {"form": "移った", "label": "past"}, {"form": "移れば", "label": "conditional"}, {"form": "移り", "label": "masu-stem"}], "register": "neutral", "sense_fingerprint": "人が席・場所・所属などを、ある所から別の所へ変える", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9917535d-1ee3-48f0-905e-62105b0c1b5b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39544, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "移った", "is_correct": true, "explanation": "「前の席に移った」の過去形で、移動が完了したことを表す。"}, {"text": "移って", "is_correct": false, "explanation": "て形では文が終わらず、「。」で結べない。"}, {"text": "移れば", "is_correct": false, "explanation": "条件形では文が途中で切れ、完結した文にならない。"}, {"text": "移り", "is_correct": false, "explanation": "連用形では文末として成り立たない。"}], "explanations": {"移った": "「前の席に移った」の過去形で、移動が完了したことを表す。", "移って": "て形では文が終わらず、「。」で結べない。", "移れば": "条件形では文が途中で切れ、完結した文にならない。", "移り": "連用形では文末として成り立たない。"}, "sentence_index": 0, "correct_answer": "移った"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会員の数が千人から二千人に移った。", "explanation": "ここは〈増える〉の意味。移るは場所や対象が別のものへ変わる意味で、数量が増える意味では使えない。"}, {"text": "セーターを洗ったら、すっかり小さく移ってしまった。", "explanation": "ここは〈縮む〉の意味。移るは別のものへ移る意味なので、布の大きさが縮む意味は表せない。"}, {"text": "コップが床に落ちて、粉々に移った。", "explanation": "ここは〈壊れる〉の意味。移るは場所や対象が移る意味で、割れて壊れる意味には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3361c338-6e56-449e-8b1e-cdcf1bbca704') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39544, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "移って", "is_correct": true, "explanation": "「病院に移って」のて形で、移動と体調の変化をつなげる。"}, {"text": "移った", "is_correct": false, "explanation": "過去形では文が二つ並ぶだけで、「体調がよくなった」との因果がつながらない。"}, {"text": "移ろう", "is_correct": false, "explanation": "意志形では、移動の結果として体調がよくなったという文の意味と合わない。"}, {"text": "移れ", "is_correct": false, "explanation": "命令形では文が成り立たず、体調の変化の文とつながらない。"}], "explanations": {"移って": "「病院に移って」のて形で、移動と体調の変化をつなげる。", "移った": "過去形では文が二つ並ぶだけで、「体調がよくなった」との因果がつながらない。", "移ろう": "意志形では、移動の結果として体調がよくなったという文の意味と合わない。", "移れ": "命令形では文が成り立たず、体調の変化の文とつながらない。"}, "sentence_index": 6, "correct_answer": "移って"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "午後になって、天気が急に移った。", "explanation": "ここは〈変わる〉の意味。移るは別のものへ移る意味で、天気そのものが変わる意味では合わない。"}, {"text": "時計の針が十二時で移った。", "explanation": "ここは〈止まる〉の意味。移るは別のものへ移動する意味なので、動きが止まる意味では使えない。"}, {"text": "やかんのお湯が、すぐに移ってしまった。", "explanation": "ここは〈沸く〉の意味。移るは別のものへ移る意味で、液体が熱くなって沸く意味は表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3361c338-6e56-449e-8b1e-cdcf1bbca704') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39544, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "弟は窓側の席から前の席を移った。", "corrected_sentence": "弟は窓側の席から前の席に移った。", "error_description": "誤りは助詞。「移る」は「〜に移る」と使うので、「前の席を移った」の「を」は誤りで、正しくは「前の席に移った」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "移った", "is_correct": true, "explanation": "過去形で、「東京の会社に移った」と移動の完了を表す。"}, {"text": "移らない", "is_correct": false, "explanation": "否定形では「移らなかった」という反対の意味になり、文の内容に合わない。"}, {"text": "移れば", "is_correct": false, "explanation": "条件形では文が成り立たず、完結した文にならない。"}, {"text": "移り", "is_correct": false, "explanation": "連用形では文末として成り立たない。"}], "correct_form": "移った", "base_form": "移る", "form_label": "過去形", "sentence_index": 1, "explanations": {"移った": "過去形で、「東京の会社に移った」と移動の完了を表す。", "移らない": "否定形では「移らなかった」という反対の意味になり、文の内容に合わない。", "移れば": "条件形では文が成り立たず、完結した文にならない。", "移り": "連用形では文末として成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3361c338-6e56-449e-8b1e-cdcf1bbca704') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39544, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "父は静かな郊外に移るて、暮らしが楽になった。", "corrected_sentence": "父は静かな郊外に移って、暮らしが楽になった。", "error_description": "誤りは活用。て形は「移って」で、「移るて」は文法的に成り立たない。正しくは「移って」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "移った", "is_correct": true, "explanation": "過去形で、「後ろの車両に移った」と移動を終えたことを表す。"}, {"text": "移れる", "is_correct": false, "explanation": "可能形では「移ることができる」の意味になり、移動を終えた文の内容に合わない。"}, {"text": "移ろう", "is_correct": false, "explanation": "意志形では、「混んでいたので」という過去の文脈と合わない。"}, {"text": "移って", "is_correct": false, "explanation": "て形では文が終わらず、「。」で結べない。"}], "correct_form": "移った", "base_form": "移る", "form_label": "過去形", "sentence_index": 7, "explanations": {"移った": "過去形で、「後ろの車両に移った」と移動を終えたことを表す。", "移れる": "可能形では「移ることができる」の意味になり、移動を終えた文の内容に合わない。", "移ろう": "意志形では、「混んでいたので」という過去の文脈と合わない。", "移って": "て形では文が終わらず、「。」で結べない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3361c338-6e56-449e-8b1e-cdcf1bbca704') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39545, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「天気に移った」の「に」で、話題の行き先を示す。"}, {"text": "を", "is_correct": false, "explanation": "「移る」は「を」を取らず、「天気を移った」は成り立たない。"}, {"text": "が", "is_correct": false, "explanation": "「天気が移った」は主語として不自然で、話題の行き先を示せない。"}, {"text": "と", "is_correct": false, "explanation": "「天気と移った」は相手を示すことになり、話題の移り変わりの文として合わない。"}], "correct_answer": "に", "explanations": {"に": "「天気に移った」の「に」で、話題の行き先を示す。", "を": "「移る」は「を」を取らず、「天気を移った」は成り立たない。", "が": "「天気が移った」は主語として不自然で、話題の行き先を示せない。", "と": "「天気と移った」は相手を示すことになり、話題の移り変わりの文として合わない。"}, "error_tags": {"を": "目的語を取らない", "が": "主語として不自然", "と": "相手を表す"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3361c338-6e56-449e-8b1e-cdcf1bbca704') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39545, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「白いシャツに移ってしまった」の「に」で、移り先を示す。"}, {"text": "の", "is_correct": false, "explanation": "「シャツの移って」は成り立たず、移り先を示せない。"}, {"text": "で", "is_correct": false, "explanation": "「シャツで移って」は手段の意味になり、移り先を示せない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を表すため、「シャツより移って」は移り先の表現にならない。"}], "correct_answer": "に", "explanations": {"に": "「白いシャツに移ってしまった」の「に」で、移り先を示す。", "の": "「シャツの移って」は成り立たず、移り先を示せない。", "で": "「シャツで移って」は手段の意味になり、移り先を示せない。", "より": "「より」は比較を表すため、「シャツより移って」は移り先の表現にならない。"}, "error_tags": {"の": "所属を表す", "で": "手段を表す", "より": "比較を表す"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3361c338-6e56-449e-8b1e-cdcf1bbca704') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39545, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "物や事柄が、別の場所や状態に移動する。", "primary_collocate": null, "pronunciation": "うつる", "ipa": "ɯtsɯɾɯ", "syllable_count": 3, "sentences": [{"text": "隣の家から火が移って、倉庫も燃えた。", "target_word": "移って", "complexity_tier": "T3", "furigana": "隣[となり]の家[いえ]から火[ひ]が移[うつ]って、倉庫[そうこ]も燃[も]えた。", "sentence_source": "generated"}, {"text": "話題が政治から天気に移った。", "target_word": "移った", "complexity_tier": "T3", "furigana": "話題[わだい]が政治[せいじ]から天気[てんき]に移[うつ]った。", "sentence_source": "generated"}, {"text": "姉の風邪が私に移ってしまった。", "target_word": "移って", "complexity_tier": "T3", "furigana": "姉[あね]の風邪[かぜ]が私[わたし]に移[うつ]ってしまった。", "sentence_source": "generated"}, {"text": "季節は夏から秋に移り、涼しくなった。", "target_word": "移り", "complexity_tier": "T3", "furigana": "季節[きせつ]は夏[なつ]から秋[あき]に移[うつ]り、涼[すず]しくなった。", "sentence_source": "generated"}, {"text": "服にたばこのにおいが移った。", "target_word": "移った", "complexity_tier": "T3", "furigana": "服[ふく]にたばこのにおいが移[うつ]った。", "sentence_source": "generated"}, {"text": "時代が移ると、人々の考え方も変わる。", "target_word": "移る", "complexity_tier": "T3", "furigana": "時代[じだい]が移[うつ]ると、人々[ひとびと]の考[かんが]え方[かた]も変[か]わる。", "sentence_source": "generated"}, {"text": "注目は新しい商品に移っている。", "target_word": "移って", "complexity_tier": "T3", "furigana": "注目[ちゅうもく]は新[あたら]しい商品[しょうひん]に移[うつ]っている。", "sentence_source": "generated"}, {"text": "本のインクが白いシャツに移ってしまった。", "target_word": "移って", "complexity_tier": "T3", "furigana": "本[ほん]のインクが白[しろ]いシャツに移[うつ]ってしまった。", "sentence_source": "generated"}, {"text": "議論は、問題の原因から解決方法に移った。", "target_word": "移った", "complexity_tier": "T3", "furigana": "議論[ぎろん]は、問題[もんだい]の原因[げんいん]から解決方法[かいけつほうほう]に移[うつ]った。", "sentence_source": "generated"}, {"text": "彼の興味は、ゲームから音楽に移ったようだ。", "target_word": "移った", "complexity_tier": "T3", "furigana": "彼[かれ]の興味[きょうみ]は、ゲームから音楽[おんがく]に移[うつ]ったようだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "移らない", "label": "negative"}, {"form": "移って", "label": "te-form"}, {"form": "移った", "label": "past"}, {"form": "移れば", "label": "conditional"}, {"form": "移り", "label": "masu-stem"}], "register": "neutral", "sense_fingerprint": "火・病気・におい・話題・時などが、別のものや状態に及ぶ、または変わる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9917535d-1ee3-48f0-905e-62105b0c1b5b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39545, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "移って", "is_correct": true, "explanation": "「火が移って」のて形で、延焼の結果を後ろの文につなげる。"}, {"text": "移った", "is_correct": false, "explanation": "過去形では「倉庫も燃えた」と因果がつながらず、文が二つ並ぶだけになる。"}, {"text": "移ろう", "is_correct": false, "explanation": "意志形では文が成り立たず、延焼の結果を表せない。"}, {"text": "移れ", "is_correct": false, "explanation": "命令形では文の意味が通らず、延焼の文とつながらない。"}], "explanations": {"移って": "「火が移って」のて形で、延焼の結果を後ろの文につなげる。", "移った": "過去形では「倉庫も燃えた」と因果がつながらず、文が二つ並ぶだけになる。", "移ろう": "意志形では文が成り立たず、延焼の結果を表せない。", "移れ": "命令形では文の意味が通らず、延焼の文とつながらない。"}, "sentence_index": 0, "correct_answer": "移って"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夏の終わりに、気温が三十度に移った。", "explanation": "ここは〈上がる〉の意味。移るは別の場所や状態へ移る意味で、数値が高くなる意味では使えない。"}, {"text": "地震で机が大きく移った。", "explanation": "ここは〈揺れる〉の意味。移るは別の場所や状態に変わる意味なので、その場で震えて動く意味は表せない。"}, {"text": "コンクリートが一晩で固く移った。", "explanation": "ここは〈固まる〉の意味。移るは別の場所や状態に動く意味で、液体が固体になる意味には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3361c338-6e56-449e-8b1e-cdcf1bbca704') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39545, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "移って", "is_correct": true, "explanation": "「新しい商品に移っている」のて形で、「いる」と続けて状態を表す。"}, {"text": "移る", "is_correct": false, "explanation": "辞書形では「移るいる」となり、「いる」と続かない。"}, {"text": "移れば", "is_correct": false, "explanation": "条件形では文が途中で切れ、「いる」と続かない。"}, {"text": "移らない", "is_correct": false, "explanation": "否定形では「移らないいる」となり、文として成り立たない。"}], "explanations": {"移って": "「新しい商品に移っている」のて形で、「いる」と続けて状態を表す。", "移る": "辞書形では「移るいる」となり、「いる」と続かない。", "移れば": "条件形では文が途中で切れ、「いる」と続かない。", "移らない": "否定形では「移らないいる」となり、文として成り立たない。"}, "sentence_index": 6, "correct_answer": "移って"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夏の暑さで、牛乳がすっかり移ってしまった。", "explanation": "ここは〈腐る〉の意味。移るは別のものに及ぶ意味なので、食品が傷む意味では使えない。"}, {"text": "夕方には洗濯物がすっかり移ってしまった。", "explanation": "ここは〈乾く〉の意味。移るは別のものに及ぶ意味で、水分がなくなる意味には合わない。"}, {"text": "淹れたてのコーヒーが、もう移ってしまった。", "explanation": "ここは〈冷める〉の意味。移るは別のものに及ぶ意味で、温度が下がる意味では使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3361c338-6e56-449e-8b1e-cdcf1bbca704') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39545, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "木の葉に火が移るて、林が燃えた。", "corrected_sentence": "木の葉に火が移って、林が燃えた。", "error_description": "誤りは活用。て形は「移って」で、「移るて」は文法的に成り立たない。正しくは「移って」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "移った", "is_correct": true, "explanation": "過去形で、「天気に移った」と話題が変わったことを表す。"}, {"text": "移って", "is_correct": false, "explanation": "て形では文が途中で切れ、「。」で終わらない。"}, {"text": "移り", "is_correct": false, "explanation": "連用形では文末として成り立たない。"}, {"text": "移れば", "is_correct": false, "explanation": "条件形では文が続かず、完結した文にならない。"}], "correct_form": "移った", "base_form": "移る", "form_label": "過去形", "sentence_index": 1, "explanations": {"移った": "過去形で、「天気に移った」と話題が変わったことを表す。", "移って": "て形では文が途中で切れ、「。」で終わらない。", "移り": "連用形では文末として成り立たない。", "移れば": "条件形では文が続かず、完結した文にならない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3361c338-6e56-449e-8b1e-cdcf1bbca704') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39545, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼の関心は、テレビから読書を移ったようだ。", "corrected_sentence": "彼の関心は、テレビから読書に移ったようだ。", "error_description": "誤りは助詞。「移る」は「〜に移る」と使うので、「読書を移った」の「を」は誤りで、正しくは「読書に移った」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "移って", "is_correct": true, "explanation": "て形で、「白いシャツに移ってしまった」と結果を表す。"}, {"text": "移らない", "is_correct": false, "explanation": "否定形では「しまった」と続かず、移った事実に反する。"}, {"text": "移り", "is_correct": false, "explanation": "連用形では「しまった」と続かず、文が成り立たない。"}, {"text": "移れる", "is_correct": false, "explanation": "可能形では「しまった」の文の意味に合わない。"}], "correct_form": "移って", "base_form": "移る", "form_label": "て形", "sentence_index": 7, "explanations": {"移って": "て形で、「白いシャツに移ってしまった」と結果を表す。", "移らない": "否定形では「しまった」と続かず、移った事実に反する。", "移り": "連用形では「しまった」と続かず、文が成り立たない。", "移れる": "可能形では「しまった」の文の意味に合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3361c338-6e56-449e-8b1e-cdcf1bbca704') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
