INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39550, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。「白い花を三本買いました」で、買うの目的語を示す。"}, {"text": "が", "is_correct": false, "explanation": "買うは他動詞なので目的語に「が」は使えず、「白い花が三本買いました」は成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「白い花に三本買いました」では買う対象を示せず、文の意味が通らない。"}, {"text": "の", "is_correct": false, "explanation": "「白い花の三本買いました」では買うの目的語にならず、文が完結しない。"}], "correct_answer": "を", "explanations": {"を": "正解。「白い花を三本買いました」で、買うの目的語を示す。", "が": "買うは他動詞なので目的語に「が」は使えず、「白い花が三本買いました」は成り立たない。", "に": "「白い花に三本買いました」では買う対象を示せず、文の意味が通らない。", "の": "「白い花の三本買いました」では買うの目的語にならず、文が完結しない。"}, "error_tags": {"が": "主語（買うは他動詞）", "に": "方向・相手", "の": "連体修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c35033a2-3df4-477c-9b1a-3834224515ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39550, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "色がきれいで、いいにおいがする、植物の一部分です。", "primary_collocate": null, "pronunciation": "はな", "ipa": "hana", "syllable_count": 2, "sentences": [{"text": "庭にきれいな花が咲いています。", "target_word": "花", "complexity_tier": "T3", "furigana": "庭[にわ]にきれいな花[はな]が咲[さ]いています。", "sentence_source": "generated"}, {"text": "この花はいいにおいがするので、部屋に飾りました。", "target_word": "花", "complexity_tier": "T3", "furigana": "この花[はな]はいいにおいがするので、部屋[へや]に飾[かざ]りました。", "sentence_source": "generated"}, {"text": "母の日に、赤い花を母にあげました。", "target_word": "花", "complexity_tier": "T3", "furigana": "母[はは]の日[ひ]に、赤[あか]い花[はな]を母[はは]にあげました。", "sentence_source": "generated"}, {"text": "花の色が黄色なので、遠くからでもよく見えます。", "target_word": "花", "complexity_tier": "T3", "furigana": "花[はな]の色[いろ]が黄色[きいろ]なので、遠[とお]くからでもよく見[み]えます。", "sentence_source": "generated"}, {"text": "机の上に小さな花を置くと、部屋が明るくなります。", "target_word": "花", "complexity_tier": "T3", "furigana": "机[つくえ]の上[うえ]に小[ちい]さな花[はな]を置[お]くと、部屋[へや]が明[あか]るくなります。", "sentence_source": "generated"}, {"text": "春になると、公園にいろいろな花が咲いて、とてもにぎやかです。", "target_word": "花", "complexity_tier": "T3", "furigana": "春[はる]になると、公園[こうえん]にいろいろな花[はな]が咲[さ]いて、とてもにぎやかです。", "sentence_source": "generated"}, {"text": "水をあげるのを忘れたので、花がしおれてしまいました。", "target_word": "花", "complexity_tier": "T3", "furigana": "水[みず]をあげるのを忘[わす]れたので、花[はな]がしおれてしまいました。", "sentence_source": "generated"}, {"text": "駅の前の店で、白い花を三本買いました。", "target_word": "花", "complexity_tier": "T3", "furigana": "駅[えき]の前[まえ]の店[みせ]で、白[しろ]い花[はな]を三本[さんぼん]買[か]いました。", "sentence_source": "generated"}, {"text": "花のにおいをかぐと、気持ちが落ち着きます。", "target_word": "花", "complexity_tier": "T3", "furigana": "花[はな]のにおいをかぐと、気持[きも]ちが落[お]ち着[つ]きます。", "sentence_source": "generated"}, {"text": "この花は夜にだけ開くので、昼は見られません。", "target_word": "花", "complexity_tier": "T3", "furigana": "この花[はな]は夜[よる]にだけ開[ひら]くので、昼[ひる]は見[み]られません。", "sentence_source": "generated"}], "morphological_forms": [{"form": "花", "label": "基本形"}, {"form": "花々", "label": "重ね形"}], "register": "丁寧", "sense_fingerprint": "色やにおいを楽しむ、目に見える植物の部分としての花", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 6 above tier T1: contains vocabulary far above tier T1: しおれ (Zipf 2.31)','sentence 8 above tier T1: 3 words above tier T1 (max 2): におい (Zipf 3.98), かぐ (Zipf 3.5), 落ち着き (Zipf 3.87)']::text[], 'faaa67aa-cb63-45cf-9845-a7dc7a4f1e76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39550, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "花", "is_correct": true, "explanation": "正解。「花が咲く」で、植物の花を指す。"}, {"text": "葉", "is_correct": false, "explanation": "葉は咲くものではないので、「葉が咲いています」は意味が通らない。"}, {"text": "石", "is_correct": false, "explanation": "石は咲くものではないので、「石が咲いています」は意味が通らない。"}, {"text": "種", "is_correct": false, "explanation": "種は咲くものではないので、「種が咲いています」は成り立たない。"}], "explanations": {"花": "正解。「花が咲く」で、植物の花を指す。", "葉": "葉は咲くものではないので、「葉が咲いています」は意味が通らない。", "石": "石は咲くものではないので、「石が咲いています」は意味が通らない。", "種": "種は咲くものではないので、「種が咲いています」は成り立たない。"}, "sentence_index": 0, "correct_answer": "花"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この植物は、地面の下に花を伸ばして栄養を集めます。", "explanation": "ここは〈根〉の意味。根は地下に伸びて栄養を集めるが、花は地下に伸びないので合わない。"}, {"text": "この木は毎年、花が太くなります。", "explanation": "ここは〈幹〉の意味。幹は太くなって成長するが、花は太くならないので合わない。"}, {"text": "この畑の花は赤く色づいて、食べ頃になりました。", "explanation": "ここは〈実〉の意味。食べ頃になるのは実で、花は食べ頃にならないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c35033a2-3df4-477c-9b1a-3834224515ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39550, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "花", "is_correct": true, "explanation": "正解。「花がしおれてしまいました」で、植物の花が元気をなくす意味。"}, {"text": "机", "is_correct": false, "explanation": "机はしおれないので、文の意味が通らない。"}, {"text": "靴", "is_correct": false, "explanation": "靴はしおれないので、文の意味が通らない。"}, {"text": "紙", "is_correct": false, "explanation": "紙はしおれないので、文の意味が通らない。"}], "explanations": {"花": "正解。「花がしおれてしまいました」で、植物の花が元気をなくす意味。", "机": "机はしおれないので、文の意味が通らない。", "靴": "靴はしおれないので、文の意味が通らない。", "紙": "紙はしおれないので、文の意味が通らない。"}, "sentence_index": 6, "correct_answer": "花"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "花が詰まって、ティッシュが手放せません。", "explanation": "ここは〈鼻〉の意味。鼻なら詰まるが、植物の花は詰まらないので合わない。"}, {"text": "この花は夏に大きな日陰を作ります。", "explanation": "ここは〈木〉の意味。日陰を作るのは大きな木で、花は日陰を作らないので合わない。"}, {"text": "花は、踏まれてもすぐにまた生えてきます。", "explanation": "ここは〈草〉の意味。生えてくるのは草で、花は生えてくるものではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c35033a2-3df4-477c-9b1a-3834224515ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39550, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "昨日、花が三本買いました。", "corrected_sentence": "昨日、花を三本買いました。", "error_description": "「買う」の目的語には「を」を使う。「花が三本買いました」は誤りで、正しくは「花を三本買いました」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c35033a2-3df4-477c-9b1a-3834224515ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39550, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "窓辺に花が咲くています。", "corrected_sentence": "窓辺に花が咲いています。", "error_description": "「咲く」のて形は「咲いて」。「咲くています」は誤りで、正しくは「咲いています」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c35033a2-3df4-477c-9b1a-3834224515ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39551, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "正解。「花の蜜」で、花と蜜を結ぶ連体修飾の「の」。"}, {"text": "を", "is_correct": false, "explanation": "「花を蜜を集める」は目的語が二つ重なり、不自然で誤り。"}, {"text": "で", "is_correct": false, "explanation": "「花で蜜を集める」は場所・手段を示すが、蜜の出どころとして不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「花へ蜜を集める」は方向を表すが、花から蜜を集める意味にならない。"}], "correct_answer": "の", "explanations": {"の": "正解。「花の蜜」で、花と蜜を結ぶ連体修飾の「の」。", "を": "「花を蜜を集める」は目的語が二つ重なり、不自然で誤り。", "で": "「花で蜜を集める」は場所・手段を示すが、蜜の出どころとして不自然。", "へ": "「花へ蜜を集める」は方向を表すが、花から蜜を集める意味にならない。"}, "error_tags": {"を": "目的語（集める対象は蜜）", "で": "場所・手段", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c35033a2-3df4-477c-9b1a-3834224515ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39551, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "正解。「花の形」で、花と形を結ぶ連体修飾の「の」。"}, {"text": "で", "is_correct": false, "explanation": "「花で形は」は手段・場所として文が成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "「花を形は」では目的語が文の主題として続かず、意味が通らない。"}, {"text": "に", "is_correct": false, "explanation": "「花に形は」では位置や相手を示すことになり、花の形を表せない。"}], "correct_answer": "の", "explanations": {"の": "正解。「花の形」で、花と形を結ぶ連体修飾の「の」。", "で": "「花で形は」は手段・場所として文が成り立たない。", "を": "「花を形は」では目的語が文の主題として続かず、意味が通らない。", "に": "「花に形は」では位置や相手を示すことになり、花の形を表せない。"}, "error_tags": {"で": "手段・場所", "を": "目的語", "に": "位置"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c35033a2-3df4-477c-9b1a-3834224515ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39551, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "植物の一部で、種子を作るために咲く、美しい部分。", "primary_collocate": null, "pronunciation": "はな", "ipa": "hana", "syllable_count": 2, "sentences": [{"text": "花が咲いたあとに、植物は種を作ります。", "target_word": "花", "complexity_tier": "T3", "furigana": "花[はな]が咲[さ]いたあとに、植物[しょくぶつ]は種[たね]を作[つく]ります。", "sentence_source": "generated"}, {"text": "ハチが花の蜜を集めながら、植物の種作りを手伝っています。", "target_word": "花", "complexity_tier": "T3", "furigana": "ハチが花[はな]の蜜[みつ]を集[あつ]めながら、植物[しょくぶつ]の種作[たねづく]りを手伝[てつだ]っています。", "sentence_source": "generated"}, {"text": "植物は、種を作るために花を咲かせます。", "target_word": "花", "complexity_tier": "T3", "furigana": "植物[しょくぶつ]は、種[たね]を作[つく]るために花[はな]を咲[さ]かせます。", "sentence_source": "generated"}, {"text": "花の中心には、種になる小さな部分があります。", "target_word": "花", "complexity_tier": "T3", "furigana": "花[はな]の中心[ちゅうしん]には、種[たね]になる小[ちい]さな部分[ぶぶん]があります。", "sentence_source": "generated"}, {"text": "花が散ったあとに、小さな実ができました。", "target_word": "花", "complexity_tier": "T3", "furigana": "花[はな]が散[ち]ったあとに、小[ちい]さな実[み]ができました。", "sentence_source": "generated"}, {"text": "この植物は、夏の終わりに黄色い花を咲かせて、種を作ります。", "target_word": "花", "complexity_tier": "T3", "furigana": "この植物[しょくぶつ]は、夏[なつ]の終[お]わりに黄色[きいろ]い花[はな]を咲[さ]かせて、種[たね]を作[つく]ります。", "sentence_source": "generated"}, {"text": "花がなければ、植物は種を作ることができません。", "target_word": "花", "complexity_tier": "T3", "furigana": "花[はな]がなければ、植物[しょくぶつ]は種[たね]を作[つく]ることができません。", "sentence_source": "generated"}, {"text": "花の形は植物によってちがい、虫を引きつけやすい形のものもあります。", "target_word": "花", "complexity_tier": "T3", "furigana": "花[はな]の形[かたち]は植物[しょくぶつ]によってちがい、虫[むし]を引[ひ]きつけやすい形[かたち]のものもあります。", "sentence_source": "generated"}, {"text": "理科の授業で、アサガオの花を観察しました。", "target_word": "花", "complexity_tier": "T3", "furigana": "理科[りか]の授業[じゅぎょう]で、アサガオの花[はな]を観察[かんさつ]しました。", "sentence_source": "generated"}, {"text": "虫を引きつけるために、花は美しい色や形をしています。", "target_word": "花", "complexity_tier": "T3", "furigana": "虫[むし]を引[ひ]きつけるために、花[はな]は美[うつく]しい色[いろ]や形[かたち]をしています。", "sentence_source": "generated"}], "morphological_forms": [{"form": "花", "label": "基本形"}, {"form": "花々", "label": "重ね形"}], "register": "丁寧", "sense_fingerprint": "種子を作る働きをもつ、植物の器官としての花", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'faaa67aa-cb63-45cf-9845-a7dc7a4f1e76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39551, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "花", "is_correct": true, "explanation": "正解。「花が咲く」で、植物の花を指す。"}, {"text": "葉", "is_correct": false, "explanation": "葉は咲かないので、「葉が咲いたあとに」は不自然。"}, {"text": "木", "is_correct": false, "explanation": "木は「咲く」とは言わないので合わない。"}, {"text": "種", "is_correct": false, "explanation": "種は咲くものではないので、この文には入らない。"}], "explanations": {"花": "正解。「花が咲く」で、植物の花を指す。", "葉": "葉は咲かないので、「葉が咲いたあとに」は不自然。", "木": "木は「咲く」とは言わないので合わない。", "種": "種は咲くものではないので、この文には入らない。"}, "sentence_index": 0, "correct_answer": "花"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "春になって、畑の花が芽を出しました。", "explanation": "ここは〈種〉の意味。芽を出すのは種で、花は芽を出さないので合わない。"}, {"text": "この木の花は、夏の終わりに赤く熟します。", "explanation": "ここは〈実〉の意味。熟すのは実で、花は熟して食べ頃になるものではないので合わない。"}, {"text": "花が詰まって、息がしにくいです。", "explanation": "ここは〈鼻〉の意味。鼻なら詰まるが、植物の花は詰まらないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c35033a2-3df4-477c-9b1a-3834224515ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39551, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "花", "is_correct": true, "explanation": "正解。「花がなければ」で、植物の花を必要な条件として示す。"}, {"text": "石", "is_correct": false, "explanation": "石は植物の種作りの条件ではないので合わない。"}, {"text": "紙", "is_correct": false, "explanation": "紙は植物の種作りに関係しないので合わない。"}, {"text": "鉄", "is_correct": false, "explanation": "鉄は植物の条件として文脈に合わない。"}], "explanations": {"花": "正解。「花がなければ」で、植物の花を必要な条件として示す。", "石": "石は植物の種作りの条件ではないので合わない。", "紙": "紙は植物の種作りに関係しないので合わない。", "鉄": "鉄は植物の条件として文脈に合わない。"}, "sentence_index": 6, "correct_answer": "花"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "花は、夏になると一気に伸びます。", "explanation": "ここは〈草〉の意味。草は伸びるが、花は伸びるとは言わないので合わない。"}, {"text": "花を切って、薪にしました。", "explanation": "ここは〈木〉の意味。薪になるのは木で、花は薪にならないので合わない。"}, {"text": "夏になると、花がフェンスに絡みつきます。", "explanation": "ここは〈つる〉の意味。つるは絡みつくが、花は絡みつかないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c35033a2-3df4-477c-9b1a-3834224515ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39551, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ハチは花を蜜を集めます。", "corrected_sentence": "ハチは花から蜜を集めます。", "error_description": "蜜を集める起点は「から」。「花を蜜を」は目的語が重なって誤りで、正しくは「花から蜜を」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c35033a2-3df4-477c-9b1a-3834224515ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39551, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "花は春に咲くます。", "corrected_sentence": "花は春に咲きます。", "error_description": "「咲く」の丁寧形は「咲きます」。「咲くます」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c35033a2-3df4-477c-9b1a-3834224515ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39552, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "蚊が主語で、飛び回る動作の主体を示す。"}, {"text": "を", "is_correct": false, "explanation": "「飛び回る」は移動の動詞で、目的語の「を」は合わない。"}, {"text": "に", "is_correct": false, "explanation": "相手や位置を示す「に」では、動作の主体の蚊を表せない。"}, {"text": "で", "is_correct": false, "explanation": "場所や手段を示す「で」では、動作の主体の蚊を表せない。"}], "correct_answer": "が", "explanations": {"が": "蚊が主語で、飛び回る動作の主体を示す。", "を": "「飛び回る」は移動の動詞で、目的語の「を」は合わない。", "に": "相手や位置を示す「に」では、動作の主体の蚊を表せない。", "で": "場所や手段を示す「で」では、動作の主体の蚊を表せない。"}, "error_tags": {"が": "主格", "を": "対格", "に": "位置・相手", "で": "場所・手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3361c338-6e56-449e-8b1e-cdcf1bbca704') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39552, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "親鳥が主語で、飛び回る動作の主体を示す。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」では動作の主体を表せず、文が成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "連体の「の」では名詞をつなぐだけで、動詞の主語にならない。"}, {"text": "から", "is_correct": false, "explanation": "起点を示す「から」では、動作の主体を表せない。"}], "correct_answer": "が", "explanations": {"が": "親鳥が主語で、飛び回る動作の主体を示す。", "へ": "方向を示す「へ」では動作の主体を表せず、文が成り立たない。", "の": "連体の「の」では名詞をつなぐだけで、動詞の主語にならない。", "から": "起点を示す「から」では、動作の主体を表せない。"}, "error_tags": {"が": "主格", "へ": "方向", "の": "連体", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3361c338-6e56-449e-8b1e-cdcf1bbca704') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39552, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "虫や鳥が、あちこちに動きながら空をとぶこと。", "primary_collocate": null, "pronunciation": "とびまわる", "ipa": "tobimawaɾɯ", "syllable_count": 5, "sentences": [{"text": "庭で蜂が花の間を飛び回っている。", "target_word": "飛び回って", "complexity_tier": "T3", "furigana": "庭[にわ]で蜂[はち]が花[はな]の間[あいだ]を飛[と]び回[まわ]っている。", "sentence_source": "generated"}, {"text": "夜、部屋の中を蚊が飛び回って眠れなかった。", "target_word": "飛び回って", "complexity_tier": "T3", "furigana": "夜[よる]、部屋[へや]の中[なか]を蚊[か]が飛[と]び回[まわ]って眠[ねむ]れなかった。", "sentence_source": "generated"}, {"text": "小鳥が木の周りを飛び回っている。", "target_word": "飛び回って", "complexity_tier": "T3", "furigana": "小鳥[ことり]が木[き]の周[まわ]りを飛[と]び回[まわ]っている。", "sentence_source": "generated"}, {"text": "蝶が花畑を飛び回るのを、子どもたちが見ていた。", "target_word": "飛び回る", "complexity_tier": "T3", "furigana": "蝶[ちょう]が花畑[はなばたけ]を飛[と]び回[まわ]るのを、子[こ]どもたちが見[み]ていた。", "sentence_source": "generated"}, {"text": "夏の夕方、川のそばをトンボが飛び回る。", "target_word": "飛び回る", "complexity_tier": "T3", "furigana": "夏[なつ]の夕方[ゆうがた]、川[かわ]のそばをトンボが飛[と]び回[まわ]る。", "sentence_source": "generated"}, {"text": "ハエが食べ物の上を飛び回るので、ふたをした。", "target_word": "飛び回る", "complexity_tier": "T3", "furigana": "ハエが食[た]べ物[もの]の上[うえ]を飛[と]び回[まわ]るので、ふたをした。", "sentence_source": "generated"}, {"text": "すずめが朝から屋根の上を飛び回っていてうるさい。", "target_word": "飛び回って", "complexity_tier": "T3", "furigana": "すずめが朝[あさ]から屋根[やね]の上[うえ]を飛[と]び回[まわ]っていてうるさい。", "sentence_source": "generated"}, {"text": "巣の近くを親鳥が飛び回って、ひなを守っていた。", "target_word": "飛び回って", "complexity_tier": "T3", "furigana": "巣[す]の近[ちか]くを親鳥[おやどり]が飛[と]び回[まわ]って、ひなを守[まも]っていた。", "sentence_source": "generated"}, {"text": "ホタルが暗い川辺を飛び回り、とてもきれいだった。", "target_word": "飛び回り", "complexity_tier": "T3", "furigana": "ホタルが暗[くら]い川辺[かわべ]を飛[と]び回[まわ]り、とてもきれいだった。", "sentence_source": "generated"}, {"text": "蛾が電灯のまわりを飛び回っている。", "target_word": "飛び回って", "complexity_tier": "T3", "furigana": "蛾[が]が電灯[でんとう]のまわりを飛[と]び回[まわ]っている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "飛び回らない", "label": "negative"}, {"form": "飛び回って", "label": "te-form"}, {"form": "飛び回った", "label": "past"}, {"form": "飛び回れば", "label": "conditional"}, {"form": "飛び回り", "label": "masu-stem"}], "register": "neutral", "sense_fingerprint": "虫や鳥があちこちへ動きながら飛ぶ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9917535d-1ee3-48f0-905e-62105b0c1b5b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39552, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "飛び回って", "is_correct": true, "explanation": "「〜いる」に続くて形で、蜂が飛び続けている状態を表し、文に合う。"}, {"text": "飛び回れ", "is_correct": false, "explanation": "命令形なので「〜いる」に続かず、文が成り立たない。"}, {"text": "飛び回らせて", "is_correct": false, "explanation": "使役形になり、蜂を飛ばせるという意味になって主語の蜂と合わない。"}, {"text": "飛び回ろう", "is_correct": false, "explanation": "意志・勧誘の形で、「〜いる」の状態の描写と合わない。"}], "explanations": {"飛び回って": "「〜いる」に続くて形で、蜂が飛び続けている状態を表し、文に合う。", "飛び回れ": "命令形なので「〜いる」に続かず、文が成り立たない。", "飛び回らせて": "使役形になり、蜂を飛ばせるという意味になって主語の蜂と合わない。", "飛び回ろう": "意志・勧誘の形で、「〜いる」の状態の描写と合わない。"}, "sentence_index": 0, "correct_answer": "飛び回って"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "時計の針が文字盤の上を飛び回る。", "explanation": "ここは〈回転する〉の意味。時計の針は回転するもので、空中を飛ぶ意味の飛び回るは合わない。"}, {"text": "子犬が芝生の上を飛び回って、遊んでいる。", "explanation": "ここは〈跳ね回る〉の場面。飛び回るは空中を飛ぶ意味なので、地面を跳ねる子犬には合わない。"}, {"text": "赤ちゃんが床の上を飛び回っている。", "explanation": "ここは〈這い回る〉の場面。飛び回るは空を飛ぶ意味なので、手足で床を進む赤ちゃんには合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3361c338-6e56-449e-8b1e-cdcf1bbca704') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39552, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "飛び回って", "is_correct": true, "explanation": "て形で、後ろの「いてうるさい」とつながり、飛び続けている状態を表す。"}, {"text": "飛び回る", "is_correct": false, "explanation": "辞書形なので、後ろの「いて」とつながらず文が成り立たない。"}, {"text": "飛び回らない", "is_correct": false, "explanation": "否定形で、すずめが飛んでいる事実と逆になり文が合わない。"}, {"text": "飛び回れば", "is_correct": false, "explanation": "仮定形で、「いてうるさい」の文に続かない。"}], "explanations": {"飛び回って": "て形で、後ろの「いてうるさい」とつながり、飛び続けている状態を表す。", "飛び回る": "辞書形なので、後ろの「いて」とつながらず文が成り立たない。", "飛び回らない": "否定形で、すずめが飛んでいる事実と逆になり文が合わない。", "飛び回れば": "仮定形で、「いてうるさい」の文に続かない。"}, "sentence_index": 6, "correct_answer": "飛び回って"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "インクが白い紙の上を飛び回った。", "explanation": "ここは〈飛び散る〉の場面。飛び回るは生き物などが自分で動いて飛ぶ意味なので、インクには使わない。"}, {"text": "老人が公園の中を飛び回って、散歩していた。", "explanation": "ここは〈歩き回る〉の場面。飛び回るは空中を飛ぶ意味なので、歩く老人には合わない。"}, {"text": "子猫が座布団の上を飛び回っている。", "explanation": "ここは〈転げ回る〉の場面。飛び回るは空中を飛ぶ意味なので、転がって遊ぶ子猫には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3361c338-6e56-449e-8b1e-cdcf1bbca704') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39552, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ミツバチが庭の花の間を飛び回ったている。", "corrected_sentence": "ミツバチが庭の花の間を飛び回っている。", "error_description": "「飛び回ったている」は過去の「た」が余計。継続を表す〜ている形の「飛び回っている」が正しい。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "飛び回って", "is_correct": true, "explanation": "て形で、後ろの「眠れなかった」へ続けて原因を述べる形になる。"}, {"text": "飛び回らない", "is_correct": false, "explanation": "否定形で、蚊が飛んでいた事実と逆になり文が合わない。"}, {"text": "飛び回った", "is_correct": false, "explanation": "過去形で、後ろの「眠れなかった」と順序・つながりが合わない。"}, {"text": "飛び回る", "is_correct": false, "explanation": "辞書形のままでは後ろの「眠れなかった」へ続かず、文が成り立たない。"}], "correct_form": "飛び回って", "base_form": "飛び回る", "form_label": "て形", "sentence_index": 1, "explanations": {"飛び回って": "て形で、後ろの「眠れなかった」へ続けて原因を述べる形になる。", "飛び回らない": "否定形で、蚊が飛んでいた事実と逆になり文が合わない。", "飛び回った": "過去形で、後ろの「眠れなかった」と順序・つながりが合わない。", "飛び回る": "辞書形のままでは後ろの「眠れなかった」へ続かず、文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3361c338-6e56-449e-8b1e-cdcf1bbca704') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39552, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ツバメが川の上を飛び回るて、えさを探した。", "corrected_sentence": "ツバメが川の上を飛び回って、えさを探した。", "error_description": "て形の「飛び回って」を「飛び回るて」と誤っている。て形は語尾を「って」にする。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "飛び回って", "is_correct": true, "explanation": "て形で、後ろの「ひなを守っていた」へ続けて同時に行う動作を表す。"}, {"text": "飛び回る", "is_correct": false, "explanation": "辞書形で、後ろの「ひなを守っていた」と続けると文が崩れる。"}, {"text": "飛び回れ", "is_correct": false, "explanation": "命令形で、親鳥の行動を述べる文に合わない。"}, {"text": "飛び回ろう", "is_correct": false, "explanation": "意志の形で、実際に守っていた出来事の描写と合わない。"}], "correct_form": "飛び回って", "base_form": "飛び回る", "form_label": "て形", "sentence_index": 7, "explanations": {"飛び回って": "て形で、後ろの「ひなを守っていた」へ続けて同時に行う動作を表す。", "飛び回る": "辞書形で、後ろの「ひなを守っていた」と続けると文が崩れる。", "飛び回れ": "命令形で、親鳥の行動を述べる文に合わない。", "飛び回ろう": "意志の形で、実際に守っていた出来事の描写と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3361c338-6e56-449e-8b1e-cdcf1bbca704') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39553, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「上空を」で、ヘリコプターが飛び回る経路の空間を示す。"}, {"text": "が", "is_correct": false, "explanation": "「上空が」では上空が飛び回る主体になり、ヘリコプターの動きと合わない。"}, {"text": "に", "is_correct": false, "explanation": "「上空に」では飛び回る経路を示せず、「飛び回る」と結びつかない不自然な文になる。"}, {"text": "と", "is_correct": false, "explanation": "「上空と」では共同の相手になり、ヘリコプターが上空と一緒に動く意味になって合わない。"}], "correct_answer": "を", "explanations": {"を": "「上空を」で、ヘリコプターが飛び回る経路の空間を示す。", "が": "「上空が」では上空が飛び回る主体になり、ヘリコプターの動きと合わない。", "に": "「上空に」では飛び回る経路を示せず、「飛び回る」と結びつかない不自然な文になる。", "と": "「上空と」では共同の相手になり、ヘリコプターが上空と一緒に動く意味になって合わない。"}, "error_tags": {"を": "経路の格", "が": "主格", "に": "位置・相手", "と": "共同"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3361c338-6e56-449e-8b1e-cdcf1bbca704') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39553, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「山の上を」で、飛び回る経路を示す。"}, {"text": "が", "is_correct": false, "explanation": "「山の上が飛び回り」では山が動作の主体になり、文が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "共同の相手を示す「と」では、山の上と一緒に動く意味になり不自然。"}, {"text": "の", "is_correct": false, "explanation": "連体の「の」では「山の上の飛び回り」と名詞化され、動詞の目的語にならない。"}], "correct_answer": "を", "explanations": {"を": "「山の上を」で、飛び回る経路を示す。", "が": "「山の上が飛び回り」では山が動作の主体になり、文が成り立たない。", "と": "共同の相手を示す「と」では、山の上と一緒に動く意味になり不自然。", "の": "連体の「の」では「山の上の飛び回り」と名詞化され、動詞の目的語にならない。"}, "error_tags": {"を": "経路の格", "が": "主格", "と": "共同", "の": "連体"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3361c338-6e56-449e-8b1e-cdcf1bbca704') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39553, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "空中をあちこちに動き回って飛ぶこと。", "primary_collocate": null, "pronunciation": "とびまわる", "ipa": "tobimawaɾɯ", "syllable_count": 5, "sentences": [{"text": "ドローンが広場の上を飛び回っている。", "target_word": "飛び回って", "complexity_tier": "T3", "furigana": "ドローンが広場[ひろば]の上[うえ]を飛[と]び回[まわ]っている。", "sentence_source": "generated"}, {"text": "ヘリコプターが事故の現場の上空を飛び回っていた。", "target_word": "飛び回って", "complexity_tier": "T3", "furigana": "ヘリコプターが事故[じこ]の現場[げんば]の上空[じょうくう]を飛[と]び回[まわ]っていた。", "sentence_source": "generated"}, {"text": "コウモリが夕暮れの空を飛び回る。", "target_word": "飛び回る", "complexity_tier": "T3", "furigana": "コウモリが夕暮[ゆうぐ]れの空[そら]を飛[と]び回[まわ]る。", "sentence_source": "generated"}, {"text": "模型の飛行機が公園の空を飛び回って、子どもが喜んだ。", "target_word": "飛び回って", "complexity_tier": "T3", "furigana": "模型[もけい]の飛行機[ひこうき]が公園[こうえん]の空[そら]を飛[と]び回[まわ]って、子[こ]どもが喜[よろこ]んだ。", "sentence_source": "generated"}, {"text": "台風のあと、カラスが町の上空を飛び回っていた。", "target_word": "飛び回って", "complexity_tier": "T3", "furigana": "台風[たいふう]のあと、カラスが町[まち]の上空[じょうくう]を飛[と]び回[まわ]っていた。", "sentence_source": "generated"}, {"text": "花火大会の夜、ヘリが会場の上を飛び回った。", "target_word": "飛び回った", "complexity_tier": "T3", "furigana": "花火大会[はなびたいかい]の夜[よる]、ヘリが会場[かいじょう]の上[うえ]を飛[と]び回[まわ]った。", "sentence_source": "generated"}, {"text": "鳩が駅前の空を飛び回って、また広場におりた。", "target_word": "飛び回って", "complexity_tier": "T3", "furigana": "鳩[はと]が駅前[えきまえ]の空[そら]を飛[と]び回[まわ]って、また広場[ひろば]におりた。", "sentence_source": "generated"}, {"text": "大きな鷲が山の上を飛び回り、えものをさがしていた。", "target_word": "飛び回り", "complexity_tier": "T3", "furigana": "大[おお]きな鷲[わし]が山[やま]の上[うえ]を飛[と]び回[まわ]り、えものをさがしていた。", "sentence_source": "generated"}, {"text": "小型の飛行機が海の上を飛び回って写真をとった。", "target_word": "飛び回って", "complexity_tier": "T3", "furigana": "小型[こがた]の飛行機[ひこうき]が海[うみ]の上[うえ]を飛[と]び回[まわ]って写真[しゃしん]をとった。", "sentence_source": "generated"}, {"text": "ラジコンのヘリが体育館の中を飛び回った。", "target_word": "飛び回った", "complexity_tier": "T3", "furigana": "ラジコンのヘリが体育館[たいいくかん]の中[なか]を飛[と]び回[まわ]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "飛び回らない", "label": "negative"}, {"form": "飛び回って", "label": "te-form"}, {"form": "飛び回った", "label": "past"}, {"form": "飛び回れば", "label": "conditional"}, {"form": "飛び回り", "label": "masu-stem"}], "register": "neutral", "sense_fingerprint": "鳥・飛行機・ドローンなどが空中をあちこち動き回って飛ぶ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9917535d-1ee3-48f0-905e-62105b0c1b5b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39553, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "飛び回って", "is_correct": true, "explanation": "「〜いる」に続くて形で、ドローンが飛び続けている状態を表し、文に合う。"}, {"text": "飛び回れ", "is_correct": false, "explanation": "命令形なので「〜いる」に続かず、文が成り立たない。"}, {"text": "飛び回らせ", "is_correct": false, "explanation": "使役形になり、ドローンを飛ばせるという意味になって主語と合わない。"}, {"text": "飛び回る", "is_correct": false, "explanation": "辞書形なので「〜いる」の形とつながらず、文が成り立たない。"}], "explanations": {"飛び回って": "「〜いる」に続くて形で、ドローンが飛び続けている状態を表し、文に合う。", "飛び回れ": "命令形なので「〜いる」に続かず、文が成り立たない。", "飛び回らせ": "使役形になり、ドローンを飛ばせるという意味になって主語と合わない。", "飛び回る": "辞書形なので「〜いる」の形とつながらず、文が成り立たない。"}, "sentence_index": 0, "correct_answer": "飛び回って"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "コマが床の上を飛び回った。", "explanation": "ここは〈回転する〉の意味。コマは回って遊ぶもので、空中を飛ぶ意味の飛び回るは合わない。"}, {"text": "子犬が庭の芝生を飛び回っている。", "explanation": "ここは〈跳ね回る〉の場面。飛び回るは空中を飛ぶ意味なので、地面を跳ねる子犬には合わない。"}, {"text": "赤ちゃんが床の上を飛び回った。", "explanation": "ここは〈這い回る〉の場面。飛び回るは空を飛ぶ意味なので、手足で床を進む赤ちゃんには合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3361c338-6e56-449e-8b1e-cdcf1bbca704') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39553, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "飛び回って", "is_correct": true, "explanation": "て形で、空を飛び回ってから広場におりたという流れに合う。"}, {"text": "飛び込んで", "is_correct": false, "explanation": "「空に飛び込む」は意味が合わず、文の流れにならない。"}, {"text": "飛び降りて", "is_correct": false, "explanation": "上から下へ降りる意味になり、「空を」と合わない。"}, {"text": "飛び回れ", "is_correct": false, "explanation": "命令形なので、文の途中で「、また広場におりた」と続かず、文が成り立たない。"}], "explanations": {"飛び回って": "て形で、空を飛び回ってから広場におりたという流れに合う。", "飛び込んで": "「空に飛び込む」は意味が合わず、文の流れにならない。", "飛び降りて": "上から下へ降りる意味になり、「空を」と合わない。", "飛び回れ": "命令形なので、文の途中で「、また広場におりた」と続かず、文が成り立たない。"}, "sentence_index": 6, "correct_answer": "飛び回って"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ペンキが壁の上を飛び回った。", "explanation": "ここは〈飛び散る〉の場面。飛び回るは自分で動いて飛ぶ意味なので、ペンキには使わない。"}, {"text": "おじいさんが庭の中を飛び回って、散歩していた。", "explanation": "ここは〈歩き回る〉の場面。飛び回るは空中を飛ぶ意味なので、歩くおじいさんには合わない。"}, {"text": "子猫が座布団の上を飛び回っている。", "explanation": "ここは〈転げ回る〉の場面。飛び回るは空中を飛ぶ意味なので、転がって遊ぶ子猫には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3361c338-6e56-449e-8b1e-cdcf1bbca704') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39553, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ドローンが公園の上を飛び回りている。", "corrected_sentence": "ドローンが公園の上を飛び回っている。", "error_description": "「飛び回りている」は誤り。〜ている形は「飛び回っている」となる。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "飛び回って", "is_correct": true, "explanation": "て形で、後ろの「いた」へ続けて飛んでいた状態を表す。"}, {"text": "飛び回った", "is_correct": false, "explanation": "過去形で、「飛び回っていた」の継続の意味が出ず、文の流れに合わない。"}, {"text": "飛び回らない", "is_correct": false, "explanation": "否定形で、ヘリが飛んでいた事実と逆になり文が合わない。"}, {"text": "飛び回れば", "is_correct": false, "explanation": "仮定形で、実際にあった状況を述べる文とつながらない。"}], "correct_form": "飛び回って", "base_form": "飛び回る", "form_label": "て形", "sentence_index": 1, "explanations": {"飛び回って": "て形で、後ろの「いた」へ続けて飛んでいた状態を表す。", "飛び回った": "過去形で、「飛び回っていた」の継続の意味が出ず、文の流れに合わない。", "飛び回らない": "否定形で、ヘリが飛んでいた事実と逆になり文が合わない。", "飛び回れば": "仮定形で、実際にあった状況を述べる文とつながらない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3361c338-6e56-449e-8b1e-cdcf1bbca704') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39553, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ツバメが港の上を飛び回りて、また岸におりた。", "corrected_sentence": "ツバメが港の上を飛び回って、また岸におりた。", "error_description": "「飛び回りて」は誤り。て形は「飛び回って」となる。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "飛び回り", "is_correct": true, "explanation": "連用形で、後ろの「、えものをさがしていた」へ続けて動作を並べる形になる。"}, {"text": "飛び回る", "is_correct": false, "explanation": "辞書形で、後ろの「、えものをさがしていた」と続かない。"}, {"text": "飛び回れ", "is_correct": false, "explanation": "命令形で、鷲の行動を述べる文に合わない。"}, {"text": "飛び回ろう", "is_correct": false, "explanation": "意志の形で、実際の行動の描写と合わない。"}], "correct_form": "飛び回り", "base_form": "飛び回る", "form_label": "連用形（ます形）", "sentence_index": 7, "explanations": {"飛び回り": "連用形で、後ろの「、えものをさがしていた」へ続けて動作を並べる形になる。", "飛び回る": "辞書形で、後ろの「、えものをさがしていた」と続かない。", "飛び回れ": "命令形で、鷲の行動を述べる文に合わない。", "飛び回ろう": "意志の形で、実際の行動の描写と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3361c338-6e56-449e-8b1e-cdcf1bbca704') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39554, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "花粉は「運ぶ」の目的語なので、「を」で示す。"}, {"text": "に", "is_correct": false, "explanation": "「花粉に運ぶ」では運ぶ相手や方向になり、文が成り立たない。"}, {"text": "が", "is_correct": false, "explanation": "「花粉が運ぶ」では花粉が主語になり、運ぶ主体が文中にない。"}, {"text": "と", "is_correct": false, "explanation": "「花粉と運ぶ」では共同の相手になり、意味が合わない。"}], "correct_answer": "を", "explanations": {"を": "花粉は「運ぶ」の目的語なので、「を」で示す。", "に": "「花粉に運ぶ」では運ぶ相手や方向になり、文が成り立たない。", "が": "「花粉が運ぶ」では花粉が主語になり、運ぶ主体が文中にない。", "と": "「花粉と運ぶ」では共同の相手になり、意味が合わない。"}, "error_tags": {"を": "対格", "に": "位置・相手", "が": "主格", "と": "共同"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3361c338-6e56-449e-8b1e-cdcf1bbca704') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
